async function readUpstreamJson(resp, providerLabel) {
  const raw = await resp.text().catch(() => "");
  let data = null;
  try { data = raw ? JSON.parse(raw) : null; } catch { data = null; }
  if (!resp.ok) {
    const requestId = resp.headers?.get?.("x-request-id");
    const message =
      data?.error?.message ||
      data?.message ||
      raw ||
      `${providerLabel} failed with HTTP ${resp.status} (empty body)`;
    const err = new Error(requestId ? `${message} [request ${requestId}]` : message);
    err.status = resp.status;
    throw err;
  }
  if (!data) throw new Error(`${providerLabel} returned an empty or non-JSON response`);
  return data;
}

function openAIImageBufferFromResponse(data) {
  const b64 = data?.data?.[0]?.b64_json;
  if (!b64) throw new Error("OpenAI image response did not contain data[0].b64_json");
  return Buffer.from(b64, "base64");
}

function normalizeOpenAIQuality(value) {
  const v = String(value || "medium").toLowerCase();
  return ["low", "medium", "high", "auto"].includes(v) ? v : "medium";
}

function normalizeOpenAIOutputFormat(value) {
  const v = String(value || "png").toLowerCase();
  return ["png", "jpeg", "webp"].includes(v) ? v : "png";
}

async function callOpenAIImagesEdits({
  apiKey,
  model,
  prompt,
  size,
  quality,
  output_format,
  images,
  imageRoles,
  charmGeometryPolicy,
  backgroundPolicy,
}) {
  const form = new FormData();
  form.append("model", model);
  // Gemini receives explicit role labels as separate multimodal parts. OpenAI
  // receives a multipart edit request, so mirror the Charm Maker's special
  // role vocabularies inside the prompt. Default listing-edit behaviour is
  // unchanged.
  let promptText = String(prompt || "");
  if (imageRoles === "style_reference") {
    promptText = `${promptText.trim()}\n\n${IMAGE_ROLE_LABELS.style_reference.single}\n\n${IMAGE_ROLE_LABELS.style_reference.lock}`;
  } else if (imageRoles !== "none" &&
             (imageRoles === "line_art_style" || imageRoles === "customer_lineart" ||
              imageRoles === "lineart_to_charm" || imageRoles === "material_spec_to_charm" ||
              imageRoles === "colour_drawing_to_charm" || imageRoles === "gold_edit_markup")) {
    const roles = IMAGE_ROLE_LABELS[imageRoles];
    promptText = (images || []).length >= 2
      ? `${promptText.trim()}\n\n${roles.first}\n\n${roles.second}\n\n${roles.lock}`
      : `${promptText.trim()}\n\n${roles.single}\n\n${roles.lock}`;
  }
  // Backend-enforced final word: geometry + background policy text goes last
  // so it outranks everything, mirroring the Gemini part ordering.
  const policyText = charmPolicyFinalText({ geometryPolicy: charmGeometryPolicy, backgroundPolicy });
  if (policyText) promptText = `${promptText}\n\n${policyText}`;
  form.append("prompt", promptText);
  form.append("size", String(size || "2048x2048"));
  form.append("quality", normalizeOpenAIQuality(quality));
  form.append("output_format", normalizeOpenAIOutputFormat(output_format));
  form.append("n", "1");

  for (const [index, img] of (images || []).entries()) {
    const mime = String(img?.mime || "image/png");
    const filename = img?.filename || filenameForMime(`image${index}`, mime);
    form.append(
      "image[]",
      new Blob([Buffer.from(img?.buffer || Buffer.alloc(0))], { type: mime }),
      filename
    );
  }

  const resp = await studioFetchWithTimeout("https://api.openai.com/v1/images/edits", {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}` },
    body: form,
  }, STUDIO_UPSTREAM_TIMEOUT_MS, "OpenAI images/edits");
  return openAIImageBufferFromResponse(
    await readUpstreamJson(resp, "OpenAI images/edits")
  );
}

async function callOpenAIImagesGenerations({
  apiKey,
  model,
  prompt,
  size,
  quality,
  output_format,
}) {
  const resp = await studioFetchWithTimeout("https://api.openai.com/v1/images/generations", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model,
      prompt: String(prompt || ""),
      size: String(size || "2048x2048"),
      quality: normalizeOpenAIQuality(quality),
      output_format: normalizeOpenAIOutputFormat(output_format),
      n: 1,
    }),
 }, STUDIO_UPSTREAM_TIMEOUT_MS, "OpenAI images/generations");
  return openAIImageBufferFromResponse(
    await readUpstreamJson(resp, "OpenAI images/generations")
  );
}

/* ── NO CALL WAITS FOR EVER ──────────────────────────────────────────────
   A plain `await fetch` with no signal is a promise that can simply never
   settle: the upstream accepts the connection and goes quiet, the background
   function sits suspended until the platform kills it, and the one thing
   that never happens is the write that tells the customer anything.
   Measured in the wild: a render reached "rendering", the model call hung,
   and the version doc stayed frozen there while the browser's watcher waited
   out its entire timeout for a verdict nobody was ever going to write.

   So every upstream model call goes through this: an AbortController, a
   deadline, and an error that names the call and the deadline — which lands
   in the normal retry/catch paths, becomes a retry or a REFUNDED, WRITTEN
   failure, and cannot leave the document lying about what is happening. */
const STUDIO_UPSTREAM_TIMEOUT_MS = 100000;   /* one image generation */
/* ── THE FINISHED CHARM GETS LONGER THAN THE SHARED CEILING ───────────────
   The gold render moved to gemini-3-pro-image, which is the premium model
   for exactly the kind of work this is — eight small openings that have to
   land where a machine-drawn map puts them — and it thinks for longer than
   flash did. A measured flash render on v9 already spent ~121s between the
   "rendering" and "polishing" stage writes; the pro model will spend more,
   and at the shared 100s it would abort mid-thought and hand the customer a
   504 for a render that was working.

   180s, and it is a per-call value rather than a raise of the shared one:
   the Listing Generator, the Charm Maker and the batch paths are all still
   on flash and have no reason to wait longer for a failure. */
const STUDIO_RENDER_TIMEOUT_MS = 180000;     /* one gold charm, pro model  */
const STUDIO_JUDGE_TIMEOUT_MS = 60000;       /* one adjudication read */

/* ═══════════ WHAT A RUN'S VERDICT OCCUPIES ON THE VERSION DOCUMENT ═══════
   EVERY score field, in one list, because the alternative was two hand-kept
   copies of it and they drifted.

   A Firestore write is a merge and has no way to delete a key, so the start
   of a render nulls these out: between pressing Re-render and the new
   verdict landing the panel must show nothing rather than the last run's
   answer. That clearing list was written by hand in two places, and a field
   added to the WRITE and not to both copies of the CLEAR simply never got
   cleared again — it survived from run to run for ever.

   Which is what Paul saw on v9. The second render could not be scored at
   all, and the panel printed "No image could be scored" directly above "the
   check miscounted the map's engraved" and "Map contains: 8 openings · 3
   engraved fields" — the FIRST render's findings, still on the document,
   under the second render's warning. Three fields had been missing from the
   clear since they were introduced (renderScoreSpecOpenings,
   renderScoreSpecEngraved, renderScoreCorroborated) and two more joined
   them when the exam was made per-question.

   So there is one list now and both clears are generated from it. A new
   field is cleared by virtue of being named here, which is the only way
   this stays true. */
const STUDIO_SCORE_DOC_FIELDS = Object.freeze([
  "renderScore", "renderScoreMode", "renderScorePass", "renderScoreThreshold",
  "renderScoreChosen", "renderScoreCount", "renderScoreFloorFails",
  "renderScoreFabricated", "renderScoreWorst",
  "renderScoreGeometry", "renderScoreCutouts", "renderScoreEngraving",
  "renderScoreFidelity", "renderScoreTone", "renderScorePresentation",
  "renderScoreAttempts", "renderScoreSuspect", "renderScoreSuspectWhy",
  "renderScoreUniform", "renderScoreCaps", "renderScoreJudgeModel",
  "renderScoreReply", "renderScoreObservations",
  /* the answer sheet and how the judge did against it */
  "renderScoreSpecOpenings", "renderScoreSpecEngraved", "renderScoreCorroborated",
  "renderScoreExamWrong", "renderScoreUnmarked",
  /* why a run produced no verdict — as stale as any other finding once the
     next run starts, and the reason a re-render that DID score could still
     be wearing the last one's "the judge answered nothing" */
  "renderScoreUnscoredWhy",
  /* how many images were made, which the panel's heading reads */
  "renderAttempts", "renderAttempt",
  /* the cut check's failed verdicts — same lifetime, same staleness */
  "renderAttemptVerdicts",
]);
function studioClearedScore() {
  const out = {};
  for (const k of STUDIO_SCORE_DOC_FIELDS) out[k] = null;
  return out;
}
async function studioFetchWithTimeout(url, opts, ms, label) {
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), Math.max(1000, ms || STUDIO_UPSTREAM_TIMEOUT_MS));
  try {
    return await fetch(url, Object.assign({}, opts, { signal: ctl.signal }));
  } catch (e) {
    if (e && (e.name === "AbortError" || ctl.signal.aborted)) {
      const err = new Error(`${label || "upstream call"} timed out after ${Math.round((ms || STUDIO_UPSTREAM_TIMEOUT_MS) / 1000)}s`);
      err.status = 504;
      throw err;
    }
    throw e;
  } finally {
    clearTimeout(t);
  }
}

async function callImageModelEdits(options) {
  const config = resolveImageModel(options?.model);
  const apiKey = options?.apiKey || apiKeyForImageModel(config);
  // NOTE: only the Gemini path injects role labels — the OpenAI images/edits
  // endpoint receives the prompt and the images with no added framing — so
  // imageRoles is meaningful for Gemini only and harmless to pass either way.
  return config.provider === "openai"
    ? callOpenAIImagesEdits({ ...options, apiKey, model: config.id })
    : callGeminiImagesEdits({ ...options, apiKey, model: config.id });
}

async function callImageModelGenerations(options) {
  const config = resolveImageModel(options?.model);
  const apiKey = options?.apiKey || apiKeyForImageModel(config);
  return config.provider === "openai"
    ? callOpenAIImagesGenerations({ ...options, apiKey, model: config.id })
    : callGeminiImagesGenerations({ ...options, apiKey, model: config.id });
}

function sizeToAspectRatio(size = "2048x2048") {
  const m = /^(\d+)\s*x\s*(\d+)$/.exec(String(size || "").trim());
  if (!m) return "1:1";
  const w = Number(m[1]), h = Number(m[2]);
  if (!Number.isFinite(w) || !Number.isFinite(h) || w <= 0 || h <= 0) return "1:1";
  if (Math.abs(w - h) < 2) return "1:1";
  const gcd = (a,b)=> b ? gcd(b, a%b) : a;
  const g = gcd(w, h);
  return `${Math.round(w/g)}:${Math.round(h/g)}`;
}

function stripUndefined(obj) {
  if (!obj || typeof obj !== "object") return obj;
  const out = Array.isArray(obj) ? [] : {};
  for (const [k, v] of Object.entries(obj)) {
    if (v === undefined) continue;
    out[k] = stripUndefined(v);
  }
  return out;
}

