async function callGeminiGenerateContentImage({
  apiKey,
  model,
  prompt,
  size,
  images,
  imageRoles,
  charmGeometryPolicy,
  backgroundPolicy,
  imageSizeTier,
  /* ── ONE CALL MAY ASK FOR LONGER THAN THE SHARED CEILING ──────────────
     STUDIO_UPSTREAM_TIMEOUT_MS is 100s and was written for flash. A caller
     that passes nothing still gets exactly that, so every existing surface
     is unchanged; the gold render passes its own, because a pro image model
     legitimately spends longer than a flash one and a 504 at 100s would
     read to the customer as a broken render rather than a slow one. */
  timeoutMs,
}) {
  const geminiModel =
    String(model || DEFAULT_IMAGE_MODEL).trim() ||
    DEFAULT_IMAGE_MODEL;
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${geminiModel}:generateContent`;

  // ============================================================
  // 2K BY DEFAULT — every synchronous image generated by this
  // function (Redo button, Standard mode generate, Charm Maker,
  // run_set_async edits tasks, etc.) outputs at 2K, and the batch
  // path's own JSONL builder honours the tier it is handed, so
  // every image-producing surface that does not ask for something
  // else is unchanged.
  //
  // This was briefly a 1K hard-lock, which quietly halved the
  // Listing Generator, the Charm Maker and every batch run. Only
  // the Custom Charm Studio wanted 1K, and only for its FINAL
  // render — so 1K is now something a caller asks for, one call at
  // a time, never something the shared path imposes on everybody.
  // A caller that passes nothing gets 2K exactly as before, and an
  // unrecognised tier falls back to 2K rather than to whatever the
  // model's own default happens to be.
  // ============================================================
  const TIER_PX = { "1K": 1024, "2K": 2048, "4K": 4096 };
  const askedTier = String(imageSizeTier || "").trim().toUpperCase();
  const sizeKey = TIER_PX[askedTier] ? askedTier : "2K";

  // Existing WxH derivation, used for the post-process resize and
  // the in-prompt size hint. Falls back to the tier's own pixel
  // size when no size string was passed, so the hint always
  // matches the tier actually requested.
  const m = /^(\d+)\s*x\s*(\d+)$/.exec(String(size || "").trim());
  const wantW = m ? Number(m[1]) : TIER_PX[sizeKey];
  const wantH = m ? Number(m[2]) : TIER_PX[sizeKey];
  const wantAR = sizeToAspectRatio(size) || "1:1";

  // The generic closing line used to always end with "suitable for a product
  // photo" — a nudge toward studio-white ecommerce backgrounds that directly
  // fought the Charm Maker's solid-black policy. When a background policy is
  // declared, the closing line enforces it instead of contradicting it.
  const closingLine =
    String(backgroundPolicy || "").trim() === "solid_black"
      ? `The ENTIRE background must be pure solid black (#000000), edge to edge.`
      : `Return an image suitable for a product photo.`;

  const promptText =
    `${String(prompt || "").trim()}\n\n` +
    `OUTPUT (NON-NEGOTIABLE): Return a photorealistic ${wantAR} image. ` +
    `Exact size ${wantW}x${wantH}. ` +
    closingLine;

  const imageInputs = Array.isArray(images) ? images : [];
  // Unknown values fall back to "edit" so a typo can never silently unlock the
  // compositor's guarantees.
  /* ── "none" IS THE ONLY WAY TO SEND NO LABELS ────────────────────────
     Passing null or omitting imageRoles does NOT mean "no roles": the lookup
     below falls back to `edit`, whose IMAGE 2 label declares that image the
     design truth to reproduce. That fallback is deliberate — a typo must not
     silently unlock the compositor's guarantees — but it left no way to send
     a bare prompt. This is that way, and it is explicit at the call site. */
  const noRoles = String(imageRoles || "") === "none";
  const roleSet = IMAGE_ROLE_LABELS[imageRoles] || IMAGE_ROLE_LABELS.edit;

  const parts = [{ text: promptText }];
  for (const [index, img] of imageInputs.entries()) {
    // Explicit role labels prevent multi-image edit models from blending
    // the source template with the master charm or reversing their jobs.
    // Every two-image Listing Generator request uses this same ordering:
    // image 1 = destination/template, image 2 = master charm.
    if (!noRoles) {
      if (imageInputs.length >= 2) {
        parts.push({
          text:
            index === 0
              ? roleSet.first
              : index === 1
                ? roleSet.second
                : roleSet.extra(index + 1),
        });
      } else {
        parts.push({ text: roleSet.single });
      }
    }

    // Gemini will hard-crash if passed application/octet-stream.
    // Force a valid image MIME type so the API attempts to process the buffer.
    let safeMime = img?.mime || "image/png";
    if (safeMime.includes("octet-stream") || !safeMime.startsWith("image/")) {
      safeMime = "image/png"; 
    }

    parts.push({
      inline_data: {
        mime_type: safeMime,
        data: Buffer.from(img?.buffer || Buffer.alloc(0)).toString("base64"),
      },
    });
  }
  // The edit vocabulary only emits its lock for multi-image requests (a
  // single-image edit needs no disambiguation). The style_reference vocabulary
  // emits it always: with one reference image the "do not reproduce this
  // object" instruction is the entire point, and it must be last so it carries
  // the most weight.
  if (!noRoles && (imageInputs.length >= 2 || roleSet === IMAGE_ROLE_LABELS.style_reference)) {
    parts.push({ text: roleSet.lock });
  }

  // Backend-enforced FINAL word: charm geometry + background policy. Pushed
  // after every role label and lock so nothing above it — including reference
  // image traits — can override it. Empty (and absent) for all non-Charm-Maker
  // requests.
  const policyText = charmPolicyFinalText({ geometryPolicy: charmGeometryPolicy, backgroundPolicy });
  if (policyText) parts.push({ text: policyText });

  const body = stripUndefined({
    contents: [{ role: "user", parts }],
    generationConfig: {
      responseModalities: ["TEXT", "IMAGE"],
      // imageConfig.imageSize tells Gemini which tier to produce
      // natively — "2K" for a 2048×2048 image. Without it the model
      // uses its own default (~1024 area) and post-process upscaling
      // has to compensate, which loses fidelity. Same field/structure
      // the batch JSONL builder uses (see buildBatchJsonlLine).
      imageConfig: { imageSize: sizeKey },
    },
  });

  const resp = await studioFetchWithTimeout(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-goog-api-key": apiKey,
    },
    body: JSON.stringify(body),
  }, timeoutMs || STUDIO_UPSTREAM_TIMEOUT_MS, "Gemini image generation");

  const raw = await resp.text().catch(() => "");
  let data = null;
  try { data = raw ? JSON.parse(raw) : null; } catch { data = null; }

  if (!resp.ok) {
    const msg =
      data?.error?.message ||
      raw ||
      `Gemini generateContent failed with HTTP ${resp.status} (empty body)`;
    throw new Error(msg);
  }
  const partsOut = data?.candidates?.[0]?.content?.parts || [];

  const imgPart =
    partsOut.find((p) => p?.inline_data?.data) ||
    partsOut.find((p) => p?.inlineData?.data) ||
    null;

  const b64 = imgPart?.inline_data?.data || imgPart?.inlineData?.data;
  if (!b64) {
    const textOnly = partsOut
      .map((p) => p?.text)
      .filter(Boolean)
      .join("\n")
      .slice(0, 600);
    throw new Error(
      `Gemini response missing inline_data image payload. Text: ${
        textOnly || "(none)"
      }`
    );
  }

  let outBuf = Buffer.from(b64, "base64");

  // Normalize to PNG + requested size
  try {
    let sharp;
    try { sharp = require("sharp"); } catch(_) {}
    if (sharp) {
      const img = sharp(outBuf);
      const meta = await img.metadata();
      const needResize =
        wantW && wantH && (meta?.width !== wantW || meta?.height !== wantH);
      if (needResize) {
        outBuf = await img.resize(wantW, wantH, { fit: "cover" }).png().toBuffer();
      } else {
        outBuf = await img.png().toBuffer();
      }
    }
  } catch (_) {
    // If sharp fails or not present, still return raw bytes.
  }

  return outBuf;
}

function extractJsonObject(text) {
  const raw = String(text || "").trim();
  if (!raw) throw new Error("Charm concept planner returned no text");
  try { return JSON.parse(raw); } catch (_) {}
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) {
    try { return JSON.parse(fenced[1]); } catch (_) {}
  }
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");
  if (start >= 0 && end > start) {
    try { return JSON.parse(raw.slice(start, end + 1)); } catch (_) {}
  }
  throw new Error("Charm concept planner returned invalid JSON");
}

function shortPlannerText(value, max = 500) {
  return String(value == null ? "" : value)
    .replace(/[\u0000-\u001f\u007f]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, max);
}

function normalizeCharmConceptPlan(raw, requestedCount) {
  const referenceSubject = shortPlannerText(raw?.referenceSubject, 180);
  const buyerProfile = shortPlannerText(raw?.buyerProfile, 500);
  const purchaseSignals = Array.isArray(raw?.purchaseSignals)
    ? raw.purchaseSignals.map((v) => shortPlannerText(v, 180)).filter(Boolean).slice(0, 6)
    : [];
  const sourceConcepts = Array.isArray(raw?.concepts) ? raw.concepts : [];
  const concepts = [];
  const seen = new Set();

  for (const source of sourceConcepts) {
    const title = shortPlannerText(source?.title, 100);
    const subject = shortPlannerText(source?.subject, 240);
    const key = `${title}|${subject}`.toLowerCase();
    if (!title || !subject || seen.has(key)) continue;
    seen.add(key);
    concepts.push({
      rank: concepts.length + 1,
      title,
      subject,
      buyerConnection: shortPlannerText(source?.buyerConnection, 420),
      conversionRationale: shortPlannerText(source?.conversionRationale, 420),
      silhouetteBrief: shortPlannerText(source?.silhouetteBrief, 500),
      engravingBrief: shortPlannerText(source?.engravingBrief, 500),
      confidence: Math.round(clampNumber(source?.confidence, 0, 100, 70)),
    });
    if (concepts.length >= requestedCount) break;
  }

  if (!referenceSubject || concepts.length < requestedCount) {
    throw new Error(
      `Charm concept planner returned ${concepts.length}/${requestedCount} usable concepts`
    );
  }
  return {
    version: 1,
    referenceSubject,
    buyerProfile,
    purchaseSignals,
    concepts,
  };
}

async function planComplementaryCharmConcepts({ sourceStoragePath, count }) {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) throw new Error("Missing GEMINI_API_KEY env var");

  const requestedCount = Math.round(clampNumber(count, 1, 8, 1));
  const model = String(
    process.env.GEMINI_CHARM_CONCEPT_MODEL || DEFAULT_IMAGE_MODEL
  ).trim();
  const source = await storagePathToBuffer(sourceStoragePath);
  let safeMime = source.mime || "image/png";
  if (!safeMime.startsWith("image/") || safeMime.includes("octet-stream")) {
    safeMime = "image/png";
  }

  const planningPrompt = `CHARM PRODUCT CONCEPT PLANNER

The supplied image is a proven bestselling jewelry charm. Analyze it as market evidence, then choose ${requestedCount} NEW complementary charm concept${requestedCount === 1 ? "" : "s"} most likely to appeal to substantially the same buyer.

This is concept selection, not image editing. The new products must extend the bestseller's audience without replicating the existing SKU.

SELECTION LOGIC — rank concepts using all five factors:
1. Same-buyer affinity (40%): shared identity, hobby, emotion, gifting occasion, collecting behavior, or symbolic meaning.
2. Commercial/gift appeal (20%): evergreen, emotionally legible, easy to search for and easy to give.
3. Tiny-charm recognition (15%): instantly recognizable as an approximately 8–15 mm flat charm.
4. Manufacturability (15%): one-piece laser-cut sheet metal, robust outline, limited strategic engraving, no fragile floating parts.
5. Novelty versus the reference (10%): a genuinely different named subject and materially different silhouette.

ADJACENCY RULE:
- Stay one strong step from the reference, not merely in the same broad category.
- Example: for a cardinal bird, consider another highly collectible garden bird or a closely linked bird-lover symbol; do not make another cardinal, a re-posed cardinal, or a generic copy of the same bird.
- Prefer concrete, visually distinctive subjects over vague decorative variations.
- Each returned concept must be different from the reference and from every other returned concept.

ABSOLUTE EXCLUSIONS:
- Never select the exact subject/species/object shown in the reference.
- Never propose a mirrored, re-posed, re-scaled, simplified, embellished, baby, pair, family, or near-duplicate version of the same subject.
- No words, initials, dates, numbers, logos, copyrighted characters, or trademarked brand shapes.
- Do not claim access to outside sales data. Your confidence is an informed product-fit estimate based on the proven reference and the rubric above.

Return ONLY valid JSON in exactly this shape:
{
  "referenceSubject": "specific identification of the source charm",
  "buyerProfile": "concise description of who buys it and why",
  "purchaseSignals": ["signal 1", "signal 2", "signal 3"],
  "concepts": [
    {
      "title": "short operator-facing concept name",
      "subject": "precise new subject and pose for the image model",
      "buyerConnection": "why the same buyer would want this alongside the bestseller",
      "conversionRationale": "why this should work commercially",
      "silhouetteBrief": "distinctive one-piece outer contour, materially unlike the reference",
      "engravingBrief": "only the minimum internal engraving needed for recognition",
      "confidence": 0
    }
  ]
}

The concepts array must contain exactly ${requestedCount} items in descending commercial-confidence order.`;

  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;
  const resp = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-goog-api-key": apiKey,
    },
    body: JSON.stringify({
      contents: [{
        role: "user",
        parts: [
          { text: planningPrompt },
          { inline_data: { mime_type: safeMime, data: source.buffer.toString("base64") } },
        ],
      }],
      generationConfig: {
        responseModalities: ["TEXT"],
        temperature: 0.35,
      },
    }),
  });

  const raw = await resp.text().catch(() => "");
  let data = null;
  try { data = raw ? JSON.parse(raw) : null; } catch (_) {}
  if (!resp.ok) {
    throw new Error(
      data?.error?.message || raw || `Gemini charm concept planning failed with HTTP ${resp.status}`
    );
  }
  const text = (data?.candidates?.[0]?.content?.parts || [])
    .map((part) => part?.text)
    .filter(Boolean)
    .join("\n");
  return normalizeCharmConceptPlan(extractJsonObject(text), requestedCount);
}

 function newDownloadToken() {
   return globalThis.crypto?.randomUUID
     ? globalThis.crypto.randomUUID()
     : require("crypto").randomUUID();
 }

 function tokenDownloadURLFor(bucketName, storagePath, token) {
   const encoded = encodeURIComponent(storagePath).replace(/%2F/g, "%2F");
   return `https://firebasestorage.googleapis.com/v0/b/${bucketName}/o/${encoded}?alt=media&token=${token}`;
 }

async function uploadPngBufferToStorage({ outBuf, jobId, runId, slotIndex, outputBasePath }) {
  const bucket = admin.storage().bucket();
  const token = newDownloadToken();

  const effectiveRunId = runId || `lg1_${Date.now()}`;
  const effectiveSlot = typeof slotIndex === "number" ? slotIndex : null;

  let storagePath;
  if (outputBasePath) {
    const base = String(outputBasePath).trim();
    const isSet = /^listing-generator-1\/[^/]+\/Ready_To_List\/Set_\d+$/i.test(base);
    const isDeriv = /^listing-generator-1\/Charm_Maker\/Generated_Charm_Sets\/Deriv_\d+$/i.test(base); // ✅ Updated Regex
    if (!isSet && !isDeriv) {
      throw new Error("output_base_path not allowed");
    }
    storagePath = `${base}/Slot_${effectiveSlot + 1}.png`;
  } else {
    // fallback legacy
    storagePath = `listing-generator-1/generated/${effectiveRunId}/slot_${effectiveSlot + 1}.png`;
  }
  const file = bucket.file(storagePath);

  await file.save(outBuf, {
    resumable: false,
    contentType: "image/png",
    metadata: {
      metadata: {
        firebaseStorageDownloadTokens: token,
      },
    },
  });

  const bucketName = bucket.name;
  const downloadURL = tokenDownloadURLFor(bucketName, storagePath, token);

  return { storagePath, downloadURL, effectiveRunId, effectiveSlot };
}

async function uploadPngBufferToSetPath(outBuf, basePath, sIndex, fallbackJobId, fallbackRunId) {
  const bucket = admin.storage().bucket();
  const effectiveSlot = Number.isFinite(Number(sIndex)) && Number(sIndex) >= 0 ? Number(sIndex) : 0;

  if (basePath) {
    const base = assertAllowedOutputBase(basePath);
    const storagePath = `${base}/Slot_${effectiveSlot + 1}.png`;
    const file = bucket.file(storagePath);
     // IMPORTANT: Always attach firebaseStorageDownloadTokens so browser previews can load reliably.
     const token = newDownloadToken();

     await file.save(outBuf, {
       resumable: false,
       contentType: "image/png",
       metadata: {
         metadata: {
           firebaseStorageDownloadTokens: token,
         },
       },
     });

     const downloadURL = tokenDownloadURLFor(bucket.name, storagePath, token);
     return { storagePath, downloadURL, effectiveRunId: fallbackRunId || fallbackJobId || null, effectiveSlot };
  }

  return await uploadPngBufferToStorage({ outBuf, jobId: fallbackJobId, runId: fallbackRunId, slotIndex: effectiveSlot });
}

/**
 * Postprocess pipeline:
 * charm_postscale logic
 */
async function postScaleCharmComposite({
  passABuf,
  baseNoCharmBuf,
  scale,
  targetPx,
  shadowOpacity,
  shadowBlur,
  diffThreshold,
}) {
  let sharp;
  try {
    sharp = require("sharp");
  } catch (e) {
    throw new Error(
      "Missing dependency: sharp. Add it to your Netlify functions bundle (npm i sharp) to use kind=charm_postscale."
    );
  }

  const aMeta = await sharp(passABuf).metadata();
  const bMeta = await sharp(baseNoCharmBuf).metadata();
  if (!aMeta?.width || !aMeta?.height || !bMeta?.width || !bMeta?.height) {
    throw new Error("Could not read image metadata for postprocess.");
  }
  if (aMeta.width !== bMeta.width || aMeta.height !== bMeta.height) {
    throw new Error(
      `postprocess requires same dimensions. passA=${aMeta.width}x${aMeta.height}, base=${bMeta.width}x${bMeta.height}`
    );
  }

  const width = aMeta.width;
  const height = aMeta.height;

  // Decode raw RGBA
  const aRaw = await sharp(passABuf).ensureAlpha().raw().toBuffer();
  const bRaw = await sharp(baseNoCharmBuf).ensureAlpha().raw().toBuffer();

  const diffVals = new Uint8Array(width * height);
  for (let i = 0, p = 0; i < aRaw.length; i += 4, p++) {
    const dr = Math.abs(aRaw[i] - bRaw[i]);
    const dg = Math.abs(aRaw[i + 1] - bRaw[i + 1]);
    const db = Math.abs(aRaw[i + 2] - bRaw[i + 2]);
    diffVals[p] = Math.max(dr, dg, db);
  }

  async function buildMaskAndBBox(thr, feather) {
    const mask = Buffer.alloc(width * height);
    for (let p = 0; p < diffVals.length; p++) mask[p] = diffVals[p] > thr ? 255 : 0;

    const maskRaw = await sharp(mask, { raw: { width, height, channels: 1 } })
      .blur(feather)
      .threshold(18)
      .raw()
      .toBuffer();

    let minX = width, minY = height, maxX = -1, maxY = -1;
    let count = 0;

    for (let y = 0; y < height; y++) {
      const row = y * width;
      for (let x = 0; x < width; x++) {
        const v = maskRaw[row + x];
        if (v > 0) {
          count++;
          if (x < minX) minX = x;
          if (y < minY) minY = y;
          if (x > maxX) maxX = x;
          if (y > maxY) maxY = y;
        }
      }
    }

    const found = maxX >= 0;
    const bboxArea = found ? (maxX - minX + 1) * (maxY - minY + 1) : 0;
    const density = found && bboxArea > 0 ? count / bboxArea : 0; 
    return { found, maskRaw, minX, minY, maxX, maxY, count, bboxArea, density };
  }

  const baseThr = clampNumber(diffThreshold, 8, 120, 40);
  const feather = 1;

  const totalPx = width * height;
  const MAX_MASK_PX_RATIO = 0.035; 
  const MAX_BBOX_AREA_RATIO = 0.075; 
  const MAX_BBOX_W_RATIO = 0.35; 
  const MAX_BBOX_H_RATIO = 0.35; 
  const MIN_DENSITY = 0.035; 
  const CENTER_X_MIN = 0.12, CENTER_X_MAX = 0.88; 
  const CENTER_Y_MIN = 0.12, CENTER_Y_MAX = 0.88;

  let chosen = null;
  let best = null; 

  for (let thr = baseThr; thr <= 90; thr += 8) {
    const m = await buildMaskAndBBox(thr, feather);
    if (!m.found) continue;

    if (!best || m.bboxArea < best.bboxArea) best = { ...m, thr };

    const bboxW = (m.maxX - m.minX + 1);
    const bboxH = (m.maxY - m.minY + 1);
    const bboxWR = bboxW / width;
    const bboxHR = bboxH / height;
    const cx = (m.minX + m.maxX) / 2;
    const cy = (m.minY + m.maxY) / 2;
    const okCenter =
      (cx >= width * CENTER_X_MIN && cx <= width * CENTER_X_MAX) &&
      (cy >= height * CENTER_Y_MIN && cy <= height * CENTER_Y_MAX);

    const okMask = m.count <= totalPx * MAX_MASK_PX_RATIO;
    const okBox = m.bboxArea <= totalPx * MAX_BBOX_AREA_RATIO;
    const okW = bboxWR <= MAX_BBOX_W_RATIO;
    const okH = bboxHR <= MAX_BBOX_H_RATIO;
    const okDense = (m.density || 0) >= MIN_DENSITY;

    if (okMask && okBox && okW && okH && okDense && okCenter) {
      chosen = { ...m, thr };
      break;
    }
  }

  if (!chosen) chosen = best;
  if (!chosen || !chosen.found) return passABuf;

  if (chosen.bboxArea > totalPx * 0.25) {
    console.log("[postscale] bbox too large; skipping charm_postscale", {
      bboxArea: chosen.bboxArea,
      totalPx,
      thr: chosen.thr,
    });
    return passABuf;
  }

  let { maskRaw, minX, minY, maxX, maxY } = chosen;

  try {
    const DS = 4;
    const smallW = Math.max(1, Math.round(width / DS));
    const smallH = Math.max(1, Math.round(height / DS));

    const small = await sharp(maskRaw, { raw: { width, height, channels: 1 } })
      .resize(smallW, smallH, { kernel: "nearest" })
      .threshold(1)
      .raw()
      .toBuffer();

    const visited = new Uint8Array(smallW * smallH);
    let bestArea = 0;
    let best = null;

    const qx = new Int32Array(smallW * smallH);
    const qy = new Int32Array(smallW * smallH);

    for (let y = 0; y < smallH; y++) {
      for (let x = 0; x < smallW; x++) {
        const idx = y * smallW + x;
        if (visited[idx]) continue;
        if (small[idx] === 0) { visited[idx] = 1; continue; }

        visited[idx] = 1;
        let head = 0, tail = 0;
        qx[tail] = x; qy[tail] = y; tail++;

        let area = 0;
        let mnx = x, mny = y, mxx = x, mxy = y;

        while (head < tail) {
          const cx = qx[head];
          const cy = qy[head];
          head++;
          area++;
          if (cx < mnx) mnx = cx;
          if (cy < mny) mny = cy;
          if (cx > mxx) mxx = cx;
          if (cy > mxy) mxy = cy;

          const n1 = cx > 0 ? (cy * smallW + (cx - 1)) : -1;
          const n2 = cx + 1 < smallW ? (cy * smallW + (cx + 1)) : -1;
          const n3 = cy > 0 ? ((cy - 1) * smallW + cx) : -1;
          const n4 = cy + 1 < smallH ? ((cy + 1) * smallW + cx) : -1;

          if (n1 >= 0 && !visited[n1] && small[n1]) { visited[n1] = 1; qx[tail] = cx - 1; qy[tail] = cy; tail++; }
          if (n2 >= 0 && !visited[n2] && small[n2]) { visited[n2] = 1; qx[tail] = cx + 1; qy[tail] = cy; tail++; }
          if (n3 >= 0 && !visited[n3] && small[n3]) { visited[n3] = 1; qx[tail] = cx; qy[tail] = cy - 1; tail++; }
          if (n4 >= 0 && !visited[n4] && small[n4]) { visited[n4] = 1; qx[tail] = cx; qy[tail] = cy + 1; tail++; }
        }

        if (area < 12) continue;

        if (area > bestArea) {
          bestArea = area;
          best = { mnx, mny, mxx, mxy };
        }
      }
    }

    if (best) {
      const padSmall = 2;
      const sx1 = Math.max(0, best.mnx - padSmall);
      const sy1 = Math.max(0, best.mny - padSmall);
      const sx2 = Math.min(smallW - 1, best.mxx + padSmall);
      const sy2 = Math.min(smallH - 1, best.mxy + padSmall);

      minX = Math.max(0, Math.floor(sx1 * DS));
      minY = Math.max(0, Math.floor(sy1 * DS));
      maxX = Math.min(width - 1, Math.ceil((sx2 + 1) * DS) - 1);
      maxY = Math.min(height - 1, Math.ceil((sy2 + 1) * DS) - 1);
    }
  } catch (_) {
    // If refinement fails for any reason, keep the original bbox.
  }

  const pad = 6;
  const left = Math.max(0, minX - pad);
  const top = Math.max(0, minY - pad);
  const bboxW = Math.min(width - left, maxX - minX + 1 + pad * 2);
  const bboxH = Math.min(height - top, maxY - minY + 1 + pad * 2);

  const maskPng = await sharp(maskRaw, { raw: { width, height, channels: 1 } })
    .extract({ left, top, width: bboxW, height: bboxH })
    .blur(0.8)
    .png()
    .toBuffer();

  const charmCrop = await sharp(passABuf)
    .extract({ left, top, width: bboxW, height: bboxH })
    .removeAlpha()
    .joinChannel(maskPng)
    .png()
    .toBuffer();

  const tp = Number(targetPx);
  let outW, outH;
  if (Number.isFinite(tp)) {
    const targetH = Math.round(clampNumber(tp, 4, 96, 14));
    const aspect = bboxH > 0 ? (bboxW / bboxH) : 1;
    outH = Math.max(1, targetH);
    outW = Math.max(1, Math.round(outH * aspect));

    if (outW > width) {
      const k = width / outW;
      outW = Math.max(1, Math.floor(outW * k));
      outH = Math.max(1, Math.floor(outH * k));
    }
    if (outH > height) {
      const k = height / outH;
      outW = Math.max(1, Math.floor(outW * k));
      outH = Math.max(1, Math.floor(outH * k));
    }
  } else {
    const s = clampNumber(scale, 0.50, 0.70, 0.65);
    outW = Math.max(1, Math.round(bboxW * s));
    outH = Math.max(1, Math.round(bboxH * s));
  }

  const scaledCharm = await sharp(charmCrop)
    .resize(outW, outH, { kernel: "lanczos3" })
    .sharpen(0.6)
    .png()
    .toBuffer();

  try {
    const aStats = await sharp(scaledCharm).extractChannel(3).stats();
    if (!aStats?.channels?.[0] || aStats.channels[0].max === 0) return passABuf;
  } catch (_) {
    return passABuf;
  }

  const shBlur = clampNumber(shadowBlur, 0, 12, 2);
  const shOp = clampNumber(shadowOpacity, 0, 0.6, 0.28);

  const shadowAlphaRaw = await sharp(scaledCharm)
    .extractChannel(3)
    .blur(shBlur)
    .linear(shOp, 0)
    .raw()
    .toBuffer();

  const shadowLayer = await sharp({
    create: {
      width: outW,
      height: outH,
      channels: 3,
      background: { r: 0, g: 0, b: 0 },
    },
  })
    .joinChannel(shadowAlphaRaw, { raw: { width: outW, height: outH, channels: 1 } })
    .png()
    .toBuffer();

  const anchorX = left + Math.round(bboxW / 2);
  const newLeft = Math.max(0, Math.min(width - outW, Math.round(anchorX - outW / 2)));
  const newTop = Math.max(0, Math.min(height - outH, top));

  const finalBuf = await sharp(baseNoCharmBuf)
    .composite([
      { input: shadowLayer, left: newLeft, top: Math.min(height - outH, newTop + 1), blend: "multiply" },
      { input: scaledCharm, left: newLeft, top: newTop, blend: "over" },
    ])
    .png()
    .toBuffer();

  return finalBuf;
}

// ============================================================
// Gemini Batch API helpers (Listing Generator)
// Reference: https://ai.google.dev/gemini-api/docs/batch-api
//
// These helpers are strictly additive. The synchronous (non-batch)
// pipeline elsewhere in this file is untouched. Batch-related kinds
// (batch_submit, batch_status, batch_collect, batch_list, batch_cancel)
// live in their own block in exports.handler below.
// ============================================================

const BATCHES_COLL = "ListingGenerator1Batches";
// Server-side Charm Maker batch orchestrations (tab-independent pipeline).
const ORCH_COLL = "ListingGenerator1CharmOrchestrations";
const GEMINI_BASE = "https://generativelanguage.googleapis.com/v1beta";
const GEMINI_UPLOAD_BASE = "https://generativelanguage.googleapis.com/upload/v1beta";

// Build one JSONL request line for the Batch API. Encodes both reference
// images as inline_data (base64). responseModalities: ["IMAGE"] saves a
// few output tokens by skipping the model's default text preamble.
// imageConfig.imageSize: "2K" is the supported way to lock 2048x2048
// output per Google's image-generation docs.
function buildBatchJsonlLine(key, prompt, refMime, refBase64, charmMime, charmBase64, imageSize, opts) {
  const sizeKey = String(imageSize || "2K").toUpperCase();
  const safeRefMime = (refMime && refMime.startsWith("image/")) ? refMime : "image/png";
  const safeCharmMime = (charmMime && charmMime.startsWith("image/")) ? charmMime : "image/png";
  const o = opts || {};
  const imageRoles = String(o.imageRoles || "").trim();
  const backgroundPolicy = String(o.backgroundPolicy || "").trim();
  const geometryPolicy = String(o.geometryPolicy || "").trim();

  // Mirror the prompt augmentation Standard mode uses in
  // callGeminiGenerateContentImage(). Without this suffix, Gemini
  // may reframe or change the aspect ratio of the output, which in
  // turn causes the charm to appear at the wrong scale relative to
  // the reference image. Standard and Batch modes must produce the
  // same output for the same inputs.
  // Pixel-size hint: at 2K we tell the model 2048x2048; at 1K, 1024x1024.
  const sizeHint = sizeKey === "1K" ? "1024x1024"
                 : sizeKey === "2K" ? "2048x2048"
                 : sizeKey === "4K" ? "4096x4096"
                 : "2048x2048";
  // Same closing-line swap Standard mode performs: when the caller declares
  // a solid-black background, the generic "product photo" line (a white-
  // studio nudge) is replaced by the black-background mandate.
  const closingLine = backgroundPolicy === "solid_black"
    ? `The ENTIRE background must be pure solid black (#000000), edge to edge.`
    : `Return an image suitable for a product photo.`;
  const augmentedPrompt =
    `${String(prompt || "").trim()}\n\n` +
    `OUTPUT (NON-NEGOTIABLE): Return a photorealistic 1:1 image. ` +
    `Exact size ${sizeHint}. ` +
    closingLine;

  // Part assembly mirrors callGeminiGenerateContentImage's ordering for the
  // requested role vocabulary, so Standard and Batch produce the same output
  // for the same inputs.
  //   • default (listing compositor, two images): byte-identical to the
  //     original hardcoded "edit" labels.
  //   • "style_reference" (Charm Maker base charm, one image): reference is
  //     a material/craft sample, subject comes from the brief; the backend
  //     geometry/background override text goes last as the final word.
  let parts;
  if (imageRoles === "style_reference") {
    parts = [
      { text: augmentedPrompt },
      { text: IMAGE_ROLE_LABELS.style_reference.single },
      { inline_data: { mime_type: safeRefMime, data: refBase64 } },
      { text: IMAGE_ROLE_LABELS.style_reference.lock },
    ];
  } else {
    parts = [
      { text: augmentedPrompt },
      {
        text:
          "IMAGE 1 — LOCKED SOURCE TEMPLATE / DESTINATION CANVAS. Preserve its composition and all non-charm content.",
      },
      { inline_data: { mime_type: safeRefMime, data: refBase64 } },
      {
        text:
          "IMAGE 2 — MASTER CHARM / DESIGN TRUTH. Use its exact silhouette, integrated eyelet, cutouts, and engraving topology for the replacement charm only.",
      },
      { inline_data: { mime_type: safeCharmMime, data: charmBase64 } },
      {
        text:
          "FINAL IMAGE-ROLE LOCK: edit IMAGE 1 in place. IMAGE 2 supplies only the replacement charm design. Do not blend the images, redraw the whole template, or copy IMAGE 1's old charm details into the new charm.",
      },
    ];
  }

  const policyText = charmPolicyFinalText({ geometryPolicy, backgroundPolicy });
  if (policyText) parts.push({ text: policyText });

  return {
    key,
    request: {
      contents: [{
        role: "user",
        parts,
      }],
      generation_config: {
        // Match Standard mode's modalities exactly. The model may
        // adjust framing/scaling decisions when text output is
        // disallowed, which contributed to charm-size mismatches.
        responseModalities: ["TEXT", "IMAGE"],
        imageConfig: { imageSize: sizeKey },
      },
    },
  };
}

// Upload a JSONL file via the Files API using the resumable protocol
// (the only protocol Google documents for the Batch flow). Returns the
// `files/abc123` resource name.
async function uploadJsonlToGeminiFiles(apiKey, jsonlData, displayName) {
  // jsonlData may be a Buffer (preferred — avoids string→bytes
  // re-encoding inside fetch) or a string. We compute byte length
  // accordingly so the resumable headers are accurate either way.
  const isBuffer = Buffer.isBuffer(jsonlData);
  const bytes = isBuffer ? jsonlData.length : Buffer.byteLength(jsonlData, "utf8");

  const startResp = await fetch(`${GEMINI_UPLOAD_BASE}/files`, {
    method: "POST",
    headers: {
      "x-goog-api-key": apiKey,
      "X-Goog-Upload-Protocol": "resumable",
      "X-Goog-Upload-Command": "start",
      "X-Goog-Upload-Header-Content-Length": String(bytes),
      "X-Goog-Upload-Header-Content-Type": "application/jsonl",
      "Content-Type": "application/jsonl",
    },
    body: JSON.stringify({ file: { display_name: displayName || "lg1-batch" } }),
  });
  if (!startResp.ok) {
    const t = await startResp.text().catch(() => "");
    throw new Error(`Files API resumable-start failed: HTTP ${startResp.status} ${t.slice(0, 400)}`);
  }
  const uploadUrl = startResp.headers.get("x-goog-upload-url");
  if (!uploadUrl) throw new Error("Files API did not return x-goog-upload-url header");

  const uploadResp = await fetch(uploadUrl, {
    method: "POST",
    headers: {
      "Content-Length": String(bytes),
      "X-Goog-Upload-Offset": "0",
      "X-Goog-Upload-Command": "upload, finalize",
    },
    body: jsonlData,
  });
  if (!uploadResp.ok) {
    const t = await uploadResp.text().catch(() => "");
    throw new Error(`Files API upload-finalize failed: HTTP ${uploadResp.status} ${t.slice(0, 400)}`);
  }
  const data = await uploadResp.json().catch(() => ({}));
  const name = data?.file?.name;
  if (!name) throw new Error("Files API upload returned no file.name");
  return name;
}

async function createGeminiBatchJob(apiKey, model, fileName, displayName) {
  const url = `${GEMINI_BASE}/models/${model}:batchGenerateContent`;
  const body = {
    batch: {
      display_name: displayName || "lg1-batch",
      input_config: { file_name: fileName },
    },
  };
  const resp = await fetch(url, {
    method: "POST",
    headers: { "x-goog-api-key": apiKey, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  const text = await resp.text();
  if (!resp.ok) {
    throw new Error(`Batch create failed: HTTP ${resp.status} ${text.slice(0, 600)}`);
  }
  let parsed;
  try { parsed = JSON.parse(text); }
  catch { throw new Error(`Batch create returned non-JSON: ${text.slice(0, 200)}`); }
  // Returns a long-running operation; the actual batch name is at
  // .name (e.g., "batches/abc123") OR within .metadata. Per the docs,
  // the top-level .name is the operation/batch name we use for polling.
  const batchName = parsed?.name;
  if (!batchName) throw new Error(`Batch create returned no name: ${text.slice(0, 400)}`);
  return { batchName, raw: parsed };
}

async function getGeminiBatchJob(apiKey, batchName) {
  // batchName is "batches/abc123" — keep it as-is in the URL.
  const resp = await fetch(`${GEMINI_BASE}/${batchName}`, {
    method: "GET",
    headers: { "x-goog-api-key": apiKey, "Content-Type": "application/json" },
  });
  const text = await resp.text();
  if (!resp.ok) {
    throw new Error(`Batch get failed: HTTP ${resp.status} ${text.slice(0, 400)}`);
  }
  const parsed = JSON.parse(text);

  // Normalize state names. Google's batch API returns BATCH_STATE_*
  // strings; our code and Firestore documents use JOB_STATE_*. Map at
  // the source so all downstream logic compares against JOB_STATE_*.
  // Done in-place so state appears in both .metadata.state and .state.
  const norm = (s) => {
    if (!s || typeof s !== "string") return s;
    if (s.startsWith("BATCH_STATE_")) return "JOB_STATE_" + s.slice("BATCH_STATE_".length);
    return s;
  };
  if (parsed?.metadata?.state) parsed.metadata.state = norm(parsed.metadata.state);
  if (parsed?.state) parsed.state = norm(parsed.state);
  return parsed;
}

async function cancelGeminiBatchJob(apiKey, batchName) {
  const resp = await fetch(`${GEMINI_BASE}/${batchName}:cancel`, {
    method: "POST",
    headers: { "x-goog-api-key": apiKey, "Content-Type": "application/json" },
    body: "{}",
  });
  if (!resp.ok) {
    const t = await resp.text().catch(() => "");
    throw new Error(`Batch cancel failed: HTTP ${resp.status} ${t.slice(0, 200)}`);
  }
  return true;
}

// Stream the result JSONL line-by-line instead of loading the entire
// (potentially 2GB+) file into memory. Returns an async generator that
// yields each JSON-parsed line. Throws on non-OK HTTP. Empty/blank
// lines and parse errors are silently skipped (mirrors the older code).
async function* streamGeminiResultLines(apiKey, fileName) {
  const url = `https://generativelanguage.googleapis.com/download/v1beta/${fileName}:download?alt=media`;
  const resp = await fetch(url, {
    method: "GET",
    headers: { "x-goog-api-key": apiKey },
  });
  if (!resp.ok) {
    const t = await resp.text().catch(() => "");
    throw new Error(`Result file download failed: HTTP ${resp.status} ${t.slice(0, 400)}`);
  }
  if (!resp.body) {
    // Fallback for environments without ReadableStream support.
    const text = await resp.text();
    for (const raw of text.split("\n")) {
      const line = raw.trim();
      if (!line) continue;
      try { yield JSON.parse(line); } catch { /* skip */ }
    }
    return;
  }

  // The stream gives us Uint8Array chunks. We accumulate a small text
  // buffer and emit one parsed JSON object per newline. Crucially we
  // never hold more than the in-flight chunk + the trailing partial
  // line, so memory stays bounded regardless of file size.
  const decoder = new TextDecoder("utf-8");
  const reader = resp.body.getReader();
  let buf = "";
  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buf += decoder.decode(value, { stream: true });
    let nl;
    while ((nl = buf.indexOf("\n")) >= 0) {
      const line = buf.slice(0, nl).trim();
      buf = buf.slice(nl + 1);
      if (!line) continue;
      try { yield JSON.parse(line); } catch { /* skip malformed */ }
    }
  }
  buf += decoder.decode(); // flush any trailing bytes
  const tail = buf.trim();
  if (tail) {
    try { yield JSON.parse(tail); } catch { /* skip */ }
  }
}

// Run async tasks with bounded concurrency. Each task receives no
// arguments and returns a promise. Max in-flight = `limit`. Returns
// the array of results in input order. Used by batch_collect to
// upload result PNGs without holding all 600 image buffers in RAM
// at once.
async function runBoundedConcurrent(items, limit, worker) {
  const results = new Array(items.length);
  let nextIdx = 0;
  async function loop() {
    while (true) {
      const i = nextIdx++;
      if (i >= items.length) return;
      try {
        results[i] = await worker(items[i], i);
      } catch (e) {
        results[i] = { __error: e };
      }
    }
  }
  const runners = Array.from({ length: Math.min(limit, items.length) }, loop);
  await Promise.all(runners);
  return results;
}

// Sanitize a Gemini batch name "batches/abc123" → "abc123" for use as
// a Firestore doc id. Firestore disallows "/" in doc ids.
function batchDocIdFromName(batchName) {
  return String(batchName || "").replace(/^batches\//, "").replace(/[^\w-]/g, "_");
}


// ============================================================
// SERVER-SIDE CHARM MAKER ORCHESTRATION SUPPORT
// ------------------------------------------------------------
// The functions below are byte-for-byte MIRRORS of the Listing
// Generator's client-side builders (buildCharmDesignPrompt /
// buildCharmImageDescription / cleanCharmPlanText). They exist so
// the charm_batch_orchestrate flow can prepare sets entirely
// server-side, with no browser tab involved. IF YOU CHANGE THE
// PROMPT OR DESCRIPTION DOCTRINE IN THE HTML, CHANGE IT HERE TOO
// — otherwise Standard mode and server-orchestrated Batch mode
// will produce different designs.
// ============================================================
function cmCleanText(value, fallback = "") {
  return String(value == null ? fallback : value)
    .replace(/[\u0000-\u001f\u007f]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function buildCharmDesignPromptServer(concept, plan) {
        const chosen = concept || {};
        const context = plan || {};
        const signals = Array.isArray(context.purchaseSignals) && context.purchaseSignals.length
            ? context.purchaseSignals.join("; ")
            : "same-buyer affinity, collection appeal and giftability";
        return `MARKET-LED NEW CHARM DESIGN — NOT AN EDIT AND NOT A REPLICA

The supplied image is a proven bestselling charm. It is provided ONLY to communicate this workshop's metal colour, polish, engraving weight, flat laser-cut construction, integrated-bail craftsmanship, lighting and black-background treatment. Do not reproduce its object.

REFERENCE BESTSELLER SUBJECT: ${cmCleanText(context.referenceSubject, "shown in the supplied reference")}
INFERRED BUYER: ${cmCleanText(context.buyerProfile, "the same buyer who values the reference bestseller")}
PURCHASE SIGNALS: ${signals}

CHOSEN COMPLEMENTARY PRODUCT:
• CONCEPT: ${cmCleanText(chosen.title, "Buyer-aligned complementary charm")}
• NEW SUBJECT: ${cmCleanText(chosen.subject, "Choose a distinct adjacent subject with the strongest same-buyer appeal")}
• BUYER CONNECTION: ${cmCleanText(chosen.buyerConnection, "It belongs naturally in the same buyer's collection")}
• COMMERCIAL RATIONALE: ${cmCleanText(chosen.conversionRationale, "Evergreen, recognizable and giftable")}
• OUTER CONTOUR BRIEF: ${cmCleanText(chosen.silhouetteBrief, "Use a bold, recognizable one-piece silhouette unlike the reference")}
• ENGRAVING BRIEF: ${cmCleanText(chosen.engravingBrief, "Use only sparse recognition-critical surface engraving")}
• INTENTIONAL CUTOUT BRIEF: ${cmCleanText(chosen.cutoutBrief, "Use negative-space cutouts when they improve recognition and visual appeal; otherwise use none")}

NOVELTY LOCK — HIGHEST PRIORITY:
• Draw the NEW SUBJECT above. The reference subject itself is forbidden.
• The new design must have a materially different silhouette, pose and internal feature map from the reference.
• NEVER trace, mirror, re-pose, re-scale, simplify, embellish or lightly restyle the reference charm.
• NEVER create a baby, pair, family, alternate pose or cosmetic variation of the exact reference subject.
• HARD FAIL: a shopper would identify the result as the same SKU or same object as the reference.
• HARD FAIL: the new outline could be overlaid on the reference and broadly match.

HARD PHYSICAL CONSTRAINTS:
• ONE CONTINUOUS PIECE: the charm body and eyelet are cut together from one uninterrupted flat sheet. There are no separately attached metal components anywhere.
• INTENTIONAL CUTOUT FREEDOM: negative-space cutouts are an important design tool and are fully allowed. Use the INTENTIONAL CUTOUT BRIEF above. Cutouts may be small or large, numerous, openwork, filigree, outline-style, fully enclosed, or intentionally open to the outer contour.
• CUTOUT QUALITY: every intended cutout must have a deliberate recognizable shape and a clean, crisp laser-cut boundary. The remaining metal must form one structurally connected, manufacturable piece with no unsupported floating islands.
• ARTIFACT DISTINCTION: never create irregular black blotches, eroded/faded gaps, shadow-like voids, ragged missing patches or ambiguous areas without a crisp designed cut edge. These are rendering defects—not cutouts.
• UNIFORMLY FLAT SHEET METAL: every millimetre of the charm, including the complete eyelet area, lies in exactly one plane and has the same thin approximately 22-gauge sheet thickness.
• SHARP SQUARE-CUT 2D EDGES: crisp laser-cut perimeter and hole edges. No rounded, rolled, beveled, bulbous, tubular, domed, cast or inflated edges anywhere.
• FLAT SURFACE LIGHTING: high polish may create reflections across the flat face, but the reflections must never make the face or edges look curved, raised or sculpted.
• FRONT VIEW: perfectly front-facing orthographic view with 0% perspective tilt.
• ENGRAVING: sparse, strategic, shallow surface laser etching only. Preserve generous untouched metal areas.
• ENGRAVING TONE — GENTLE, CLOSE TO THE GOLD: render every engraved line in the same warm gold family as the polished face, only approximately 12–18% darker/warmer than the metal beside it — legible at preview size but soft, never a stark dark line against the gold.
• ENGRAVING COLOR LIMITS: never use white, cream or face-matching highlight colour for an engraving, but also never use black, charcoal, dark brown, heavy copper patina, heavy oxidation or deep shadow. Aim for a light warm tone only a few shades deeper than the surrounding gold — subtle, refined, still readable at preview size, never a dark outline.
• ENGRAVING/CUTOUT DISTINCTION: engravings are shallow surface marks; cutouts are true negative space with crisp laser-cut boundaries. Both are allowed and must remain visually unambiguous.
• NO TEXT: no letters, words, dates, numbers, logos or branded shapes.
• NO ATTACHED HARDWARE: no chains, clasps, jump rings, O-rings, split rings, wire loops, folded bails, soldered bails, hinges or connectors of any kind.

ONE INTEGRATED PROTRUDING CHARM HOOP — MANDATORY ON EVERY CHARM, ZERO SEPARATE RINGS:
• ABSOLUTE REQUIREMENT — NO EXCEPTIONS: every generated charm has exactly ONE small ring-shaped hanging hoop that PROTRUDES OUTWARD beyond the charm's outer silhouette at the top — the classic charm hoop. A charm rendered without this hoop is a total failure regardless of how good the rest looks.
• ONE PIECE: the hoop is laser-cut from the SAME flat sheet as the body in one continuous silhouette — the outline flows smoothly from the body, up and around the hoop, and back down. No joint, seam, hinge, fold, overlap, solder point or separate part anywhere.
• HOOP FORM: a small flat annulus — a rounded tab of sheet metal with one clean, round, front-facing hole through its center. It stays perfectly flat and sheet-thin like the rest of the charm: never a doughnut, torus, tube, wire ring, raised rim or edge-on ring, and never a narrow upright oval or slot.
• INTELLIGENT PLACEMENT — THINK BEFORE RENDERING: this charm will hang from this hoop under real-world gravity. Before rendering, locate the design's center of mass (where the visual weight of the metal actually is, accounting for asymmetry, cutouts and heavy/light regions). Place the hoop on the outer contour DIRECTLY ABOVE that center of mass so the charm hangs level and balanced — never tipping nose-up, nose-down or lopsided. For a side-profile animal that means above the back/shoulders, not the nose or tail; for an asymmetric object, shift the hoop toward the heavy side until the hang is level. Choose the placement that is BOTH physically balanced and most aesthetically pleasing for the subject.
• PROPORTION: small and elegant relative to the charm — roughly 10–18% of the charm's height, matching this workshop's reference charms.
• FORBIDDEN — PUNCHED-BODY ATTACHMENT: never use a hole punched inside the charm's body or artwork as the hanging point. The artwork stays intact; the hoop is additional silhouette rising above it.
• FORBIDDEN — SEPARATE HARDWARE: never add a second, separate ring threaded through the hoop; no jump rings, O-rings, split rings, folded/teardrop bails, connectors, clasps or chains. The integrated hoop is the only attachment.
• ZERO STACKED HARDWARE: exactly one hoop — never two hoops, never a hoop plus a punched hole, never a ring passing through the hoop.
• HARD FAIL: a charm with no visible protruding hoop at its top.
• HARD FAIL: a charm whose only attachment is a hole cut inside the main subject's body.
• HARD FAIL: a separate ring, bail or connector distinct from the charm's own sheet, anywhere in the image.
• HARD FAIL: the hoop rendered thick, tubular, domed, three-dimensional or shown edge-on.
• HARD FAIL: a hoop placed off the balance point so the charm would visibly hang tilted.

ABSOLUTE FLATNESS & FRONT-FACING LOCK (EQUAL PRIORITY TO THE HOOP RULE):
• The ENTIRE charm is rendered 100% FRONT-FACING in a perfectly flat orthographic view — as if the flat sheet was scanned face-on. 0% perspective, 0% rotation out of the picture plane.
• ZERO 3D: no depth, no visible thickness, no side walls, no top face, no vanishing lines, no foreshortening, no three-quarter or angled "product shot" viewpoint — even for subjects that are boxy in real life (a suitcase, a book, a house: draw its flat FRONT ELEVATION only).
• HARD FAIL: any part of the charm shown at an angle, in perspective, or with visible 3D volume or side surfaces.

BACKGROUND — ABSOLUTE:
• 100% PURE SOLID BLACK (#000000), edge to edge.
• No white, off-white, grey, studio sweep, gradient, texture or transparency anywhere in the background.
• Generate the image NATIVELY against pure black from the first render. Do not begin with white and remove it. Do not use masking, background removal, chroma keying, cutout compositing or transparent pixels.
• Before returning the image, inspect all four corners and every pixel outside the charm: they must already be uniform #000000.
• The isolated charm is centered with comfortable empty black margin and no cast shadow outside its silhouette.

AESTHETIC CONTINUITY:
Match only the reference's metal alloy/tone, polish, restrained engraving language, lighting quality and production realism. The product concept, subject, silhouette and feature placement come exclusively from the chosen complementary brief above.

FINAL PRE-RENDER CHECK — PERFORM THIS AFTER THE IMAGE IS COMPOSED:
1. Is there exactly ONE small ring-shaped hoop protruding above the charm's body, cut from the same continuous flat silhouette, positioned directly above the design's center of mass? If not, correct the interpretation before creating the single final image.
2. Confirm the hoop extends beyond the body's outline with one clean round hole through it, and that the artwork body itself has NO punched attachment hole anywhere.
3. Confirm there is ZERO separate metal hardware above, behind, in front of or threaded through the hoop. Touching or overlapping the body does not make a separate ring acceptable.
4. Confirm the entire charm is perfectly flat and 100% front-facing: no perspective, no 3D thickness, no angled view anywhere.
5. Repeat the rules before returning the image: EVERY charm has its one integrated protruding hoop. NO separate jump ring or bail. NO hole punched through the body. NO 3D or perspective. The charm with its single integrated hoop must be shown alone.`;
    }

function buildCharmImageDescriptionServer(concept, plan, variant) {
      const c = concept || {};
      const p = plan || {};
      const bits = [];
      const title = cmCleanText(c.title);
      const subject = cmCleanText(c.subject);
      if (variant === "earring") {
        bits.push(`Earring version${title ? ` of "${title}"` : ""}: ${subject || "flat laser-cut gold charm"} — hanging hoop removed for stud/earring assembly, design otherwise identical to the necklace charm.`);
      } else {
        bits.push(`${title ? `"${title}" — ` : ""}${subject || "flat laser-cut gold charm"} with integrated hanging hoop, for necklaces and charm jewelry.`);
      }
      const bc = cmCleanText(c.buyerConnection);
      if (bc) bits.push(bc);
      const cr = cmCleanText(c.conversionRationale);
      if (cr) bits.push(cr);
      const sil = cmCleanText(c.silhouetteBrief);
      if (sil) bits.push(`Silhouette: ${sil}`);
      const eng = cmCleanText(c.engravingBrief);
      if (eng) bits.push(`Engraving: ${eng}`);
      const refS = cmCleanText(p.referenceSubject);
      if (refS) bits.push(`Reference: ${refS}.`);
      const buyer = cmCleanText(p.buyerProfile);
      if (buyer) bits.push(`Target buyer: ${buyer}`);
      if (Array.isArray(p.purchaseSignals) && p.purchaseSignals.length) {
        bits.push(`Purchase drivers: ${p.purchaseSignals.map(cmCleanText).filter(Boolean).join("; ")}.`);
      }
      return bits.join("\n");
    }

function buildCharmEmbedMetadataServer(concept, plan, variant) {
  const c = concept || {};
  const p = plan || {};
  const description = buildCharmImageDescriptionServer(c, p, variant);
  if (!description) return null;
  let conceptJson = null;
  try {
    conceptJson = JSON.stringify({
      variant: variant || "necklace",
      title: cmCleanText(c.title) || null,
      subject: cmCleanText(c.subject) || null,
      buyerConnection: cmCleanText(c.buyerConnection) || null,
      conversionRationale: cmCleanText(c.conversionRationale) || null,
      silhouetteBrief: cmCleanText(c.silhouetteBrief) || null,
      engravingBrief: cmCleanText(c.engravingBrief) || null,
      referenceSubject: cmCleanText(p.referenceSubject) || null,
      buyerProfile: cmCleanText(p.buyerProfile) || null,
      purchaseSignals: Array.isArray(p.purchaseSignals)
        ? p.purchaseSignals.map((s) => cmCleanText(s)).filter(Boolean).slice(0, 6)
        : [],
    });
  } catch (_) {}
  const meta = { Description: description };
  const t = cmCleanText(c.title);
  if (t) meta.CharmTitle = t;
  if (conceptJson) meta.CharmConcept = conceptJson;
  return meta;
}


/* ============================================================================
   CUSTOM CHARM STUDIO — the customer-facing kinds (design guide §10.6)
   ----------------------------------------------------------------------------
     custom_charm_precheck   text-only vision pass on an uploaded image; costs
                             no credit, meters the upload allowance only on an
                             ACCEPTED image so a rejection is free
     custom_charm_generate   verify ID token -> atomic wallet debit -> compose
                             the prompt -> ONE image generation -> write the PNG
                             and the version doc. Credit auto-refunded on failure.
     custom_charm_refine     same, with the prior version as a second reference
     custom_session_status   thin read of a version doc, for browsers where
                             Firestore onSnapshot is blocked

   WHY THIS IS SAFE TO ADD HERE
     This file has no caller authentication of its own and answers
     Access-Control-Allow-Origin "*" — correct for an internal tool on a
     private subdomain, unacceptable for a customer endpoint. So every studio
     kind verifies a Firebase ID token itself, scopes every storage path to the
     caller's own uid, answers a storefront-locked origin instead of "*", and
     applies per-uid and per-IP hourly ceilings on top of the wallet. No
     existing kind's behaviour changes in any way.

   WHAT IT REUSES, VERBATIM
     buildCharmDesignPromptServer's HARD PHYSICAL CONSTRAINTS / HOOP /
     FLATNESS / BACKGROUND / FINAL PRE-RENDER CHECK blocks, the text-only
     auditCharmPromptPreflight, callImageModelEdits with the backend's final
     geometry + background override, embedPngTextMetadata, storagePathToBuffer,
     newDownloadToken and tokenDownloadURLFor. Only the INTENT HEADER differs:
     the Charm Maker's NOVELTY LOCK ("the reference subject is forbidden") is
     replaced by a customer FIDELITY block, because here the customer chose the
     reference and wants it honoured.

   ENV — nothing new. GEMINI_API_KEY, FIREBASE_* and FIREBASE_STORAGE_BUCKET
   already exist on this deployment.
   ========================================================================= */

const STUDIO_KINDS = new Set([
  "custom_charm_precheck",
  "custom_charm_generate",
  "custom_charm_refine",
  /* the studio composed the drawing itself — this only files it */
  "custom_charm_compose",
  "custom_charm_render",
  /* the catalogue photograph, turned into the line drawing the customer will
     actually edit — see handleStudioRefLineArt */
  "custom_charm_ref_lineart",
  /* ── THE ONE THE KICK FORWARDED TO NOBODY ─────────────────────────────
     geminiImageProxyKick.js has listed custom_charm_gold_edit in its
     ASYNC_KINDS since the arrow got its second job, and the storefront has
     been sending it. This file had no handler and did not list the kind, so
     every one of those requests reached handleStudioKind and fell through to
     `unknown_kind` — a 400 nobody could see, because an async kind is
     answered with the platform's own 202 before the proxy is ever consulted.
     The browser then watched the version document for a result that was
     never going to be written, and gave up at three minutes. That is the
     "the arrow just sits there" fault exactly. */
  "custom_charm_gold_edit",
  /* Fired on APPROVE, not on design: derives the greyscale map backwards
     from the approved gold charm, for the versions that never had a
     drawing to derive it forwards from. Costs no credit and nobody waits
     on it — see handleStudioSpecFromGold. */
  "custom_charm_spec_from_gold",
  /* "From our designs": the catalogue photograph becomes version 1's gold
     directly. No model, no credit — see handleStudioAdopt. */
  "custom_charm_adopt",
  /* custom_charm_prompt — read-only, returned the exact prompt a render
     would send — is REMOVED. It existed to feed the studio's prompt lab,
     which is gone; the render prompt is fixed and nothing needs to ask what
     it is. Also dropped from SYNC_KINDS in geminiImageProxyKick.js, which is
     the only door to this function. */
  "custom_session_status",
]);

const STUDIO_SESSIONS_COLL = "customSessions";
const STUDIO_RATE_COLL     = "Brites_Studio_RateLimits";
const STUDIO_CONFIG_DOC    = "config/customStudio";
/* ══════════ THE HOURLY CEILINGS ARE OFF ═══════════════════════════════════
   These were 25 generations an hour per account and 60 per IP. They were not
   a security control — nothing here is protected by them that is not already
   protected by the ID token check, the session-ownership check and the
   credit wallet — they were a spend guard on the image model, and they were
   costing the person who owns the studio a working afternoon.

   ZERO MEANS NO CEILING. The mechanism is left in place, in full, so turning
   one back on is a number rather than a rewrite, and it can be done WITHOUT
   A DEPLOY from either of two places:

     · Netlify environment: STUDIO_MAX_GENS_HOUR_UID / STUDIO_MAX_GENS_HOUR_IP
     · config/customStudio: maxGensHourUid / maxGensHourIp   (checked first,
       cached for a minute like the rest of that document)

   WHAT IS STILL ENFORCED, and deliberately so: every studio kind still
   requires a verified Firebase ID token, still refuses a session the caller
   does not own, and every call that reaches the image model still debits the
   credit wallet in an atomic transaction before the model is touched. The
   wallet is what stands between a stranger and the API key now. Anything
   with `wallet.unlimited === true` bypasses that too — which is why that flag
   belongs on staff accounts and nowhere else.
   ═══════════════════════════════════════════════════════════════════════ */
const STUDIO_MAX_GENS_HOUR_UID = Number(process.env.STUDIO_MAX_GENS_HOUR_UID) || 0;
const STUDIO_MAX_GENS_HOUR_IP  = Number(process.env.STUDIO_MAX_GENS_HOUR_IP)  || 0;
const STUDIO_MAX_INSTRUCTION   = 400;

/* Storefront-locked CORS. Deliberately NOT the "*" that json() returns. */
const STUDIO_ALLOWED_ORIGINS = [
  "https://britesjewelry.com",
  "https://www.britesjewelry.com",
  "https://brites-jewelry.myshopify.com",
];
function studioJson(statusCode, obj, origin) {
  const allow = STUDIO_ALLOWED_ORIGINS.includes(origin) ? origin : STUDIO_ALLOWED_ORIGINS[0];
  return {
    statusCode,
    headers: {
      "Content-Type": "application/json",
      "Access-Control-Allow-Origin": allow,
      "Access-Control-Allow-Headers": "Content-Type, Authorization",
      "Access-Control-Allow-Methods": "POST, OPTIONS",
      "Vary": "Origin",
      "Cache-Control": "no-store",
    },
    body: JSON.stringify(obj),
  };
}

/** Anonymous uids are first-class here: a guest's free allowance is a real
 *  wallet, so their token must be accepted exactly like a customer's. */
async function requireStudioUser(event) {
  const h = event?.headers || {};
  const raw = h.authorization || h.Authorization || "";
  const token = raw.startsWith("Bearer ") ? raw.slice(7).trim() : "";
  if (!token) { const e = new Error("sign_in_required"); e.status = 401; throw e; }
  try {
    const decoded = await admin.auth().verifyIdToken(token);
    return decoded.uid;
  } catch (_err) {
    const e = new Error("invalid_token"); e.status = 401; throw e;
  }
}

function studioClientIp(event) {
  const h = event?.headers || {};
  return String(
    h["x-nf-client-connection-ip"] ||
    String(h["x-forwarded-for"] || "").split(",")[0] ||
    "unknown"
  ).trim();
}

/* ═══════════ ⏸ GOLD CHARM VERIFICATION — TEMPORARILY PAUSED ══════════════
   ONE SWITCH. Set to false to bring the whole verification stack back
   exactly as it was; there is nothing else to undo.

       const STUDIO_VERIFICATION_PAUSED = false;

   WHAT TRUE DOES. It forces the two check modes to "off" at the single
   point each is read, so a render makes ONE image and returns it:
     • the adjudicator never runs — no judge call, no score, no re-render,
       and no renderScore* fields on the version document;
     • the cut check never runs — no punch, no verify, no cut-driven retry.
   The attempt loop's two retry conditions (cutWants / scoreWants) are both
   false on the first pass, so it breaks after attempt 1 and the customer is
   shown the first image generated.

   WHY IT IS A FLAG AND NOT AN EDIT TO THE CONFIG BELOW. renderCutCheck and
   renderAdjudicate keep their intended production values ("off" / "enforce")
   so the deployment's real settings are not lost in a temporary pause, and
   so un-pausing cannot silently restore the wrong ones. This flag also wins
   over config/customStudio, which means a stale override in Firestore cannot
   quietly switch a check back on while the pause is meant to be in force.

   THE STAFF READ-OUT IS PAUSED WITH IT, in britescustomstudio.js — the same
   flag name, the same one-line revert. See qaAllowed() there.

   NOT AFFECTED, deliberately: callImageWithRetry's transport-level retry on
   an overloaded provider. That is not a verification step — it is what makes
   a 503 not cost the customer a credit.                                    */
const STUDIO_VERIFICATION_PAUSED = true;

/* THE MOST IMAGES ONE RENDER MAY EVER COST. Every gate and every judge in
   the attempt loop is capped by this together, not each separately — see the
   ceiling in studioRenderAttempts. The storefront shows it as the "of 3" in
   its counter, so changing it here changes both. */
const STUDIO_MAX_RENDER_ATTEMPTS = 3;

const STUDIO_DEFAULT_CONFIG = {
  guestFreeCredits: 3,
  signupBonusCredits: 7,
  guestFreeUploads: 3,
  signupBonusUploads: 7,
  generateCost: 1,
  /* ── THE SECOND RENDERER IS GONE, NOT PARKED ──────────────────────────
     renderHighCost, renderHighModel and renderQualityTiers lived here. They
     priced and named a second image model (gpt-image-2) that the studio's
     Model toggle could route a render to for two credits.

     The toggle is removed from the storefront and handleStudioRender no
     longer reads body.quality at all, so there is no request that can reach
     that model and no price for it to charge. The keys are deleted rather
     than left defaulted-off: a key that only ever produces one outcome reads
     like a lever, and the next person to find it in Firestore would set it
     and watch nothing happen. Bringing the tier back is a deliberate edit in
     both files, which is the right size of decision for doubling a price. */
  /* ── 2K IN, 1K OUT ────────────────────────────────────────────────────
     The two studio steps are not the same job, so they do not share a tier,
     and NEITHER of them reaches outside the studio: the shared image call
     defaults to 2K for everybody and only moves when a caller asks.

     studioDrawingTier is the INPUT side. The production drawing is what the
     renderer is later handed, and it is also what code measures —
     studioPenWidth and the 2.5×-pen test that separates a cut-out from a cut
     edge both read the pen off the drawing itself, so halving the canvas
     halves the pen and leaves a hairline with fewer pixels to be judged on.
     It stays at 2K.

     studioRenderTier is the OUTPUT side — the finished metal charm the
     customer looks at. Nothing downstream measures it, so the extra tier buys
     presentation only, at real latency on every press. It is now PINNED at
     1024 and this key is inert; see studioRenderTier().

     Values are "1K" | "2K" | "4K"; anything else falls back to that step's
     OWN default, so a typo in one cannot silently change the other. No new
     environment variable — GEMINI_STUDIO_IMAGE_MODEL is still read if it is
     already set, below studioImageModel so Firestore stays the faster lever. */
  studioImageModel: "gemini-3-pro-image",
  /* the steps that do NOT run on studioImageModel. The first two are
     rewritten by code before anyone sees them; the third is the gold charm
     itself, which Paul moved onto the flash image model. Set any key to
     "gemini-3-pro-image" to put that one step back without a deploy.
     Deliberately NOT lifted by studioImageModel — see studioImageModelId. */
  studioLineArtModel: "gemini-3.1-flash-image",
  studioSpecModel: "gemini-3.1-flash-image",
  /* the gold charm: handleStudioRender AND handleStudioGoldEdit, one key so
     a rendered charm and an edited one can never come off different models */
  /* ── THE FINISHED GOLD CHARM RENDERS ON THE PRO IMAGE MODEL ───────────
     gemini-3-pro-image ("Nano Banana Pro"), checked against the published
     model list rather than inferred from another name — the rule beside
     DEFAULT_TEXT_MODEL, which exists because that constant was once a
     model that did not exist. Same request shape as the flash model, same
     imageConfig.imageSize tiers, so nothing about the call changes but the
     id. It is the render step's job that argues for it: reproducing a
     deterministic map's openings and engraved fields exactly is the
     "complex visual task with precise control" case, and it is what the
     adjudicator has been failing renders on.

     IT COSTS DOUBLE. $0.134 against $0.067 per 1K image at list price, and
     the studio renders 1K only. The adjudicator may spend up to
     renderScoreRetries extra images on top, so a worst-case gated render
     goes from about $0.20 to about $0.40 in model spend. generateCost —
     what the CUSTOMER is debited — is unchanged and is a separate decision.

     The gold edit resolves through this same key (see
     STUDIO_STEP_MODEL_KEYS), so it moves with the render, which is right:
     both produce the finished metal charm. The drawing steps, lineart and
     specgold, stay on flash — they feed the measurements, not the eye. */
  studioRenderModel: "gemini-3-pro-image",
  studioDrawingTier: "2K",
  studioRenderTier: "1K",
  /* THE MASK NEVER GOES TO THE MODEL SMALLER THAN THIS. It is built at the
     drawing's own resolution, so a drawing that arrived small (an older
     session, a reduced upload, a fallback that skipped the 2K tier) produced
     a small mask — and a small mask is a blurred instruction: the thin
     engraved strokes and the one-pen-wide cut edges are exactly the features
     that vanish first when a vision encoder downsamples. Upscaling happens
     AFTER detection, so nothing about which pixels are cut, engraved or
     polished changes; only the picture the model is handed gets bigger. */
  studioMaskMinPx: 2048,
  /* PRE-RENDER STRUCTURAL SPEC. When enabled, the coloured production drawing
     is deterministically resolved into a flat material map BEFORE any image
     model sees it: solid metal, engraved work and actual openings are each a
     distinct GREY (colour belongs to the finish reference, never to this map);
     openings are
     already white/background, and black/red work is already a darker tone of
     the same metal. The model therefore renders material and light instead of
     having to interpret manufacturing colours.

     IT IS NO LONGER A SWITCH FOR THE RENDER. It used to be safe to set false
     "only as an emergency fallback", because the legacy colour-coded path
     was waiting underneath. That path is gone: handleStudioRender ignores
     this key outright and always builds the map, because a render with no
     grey map now fails rather than falling back, and a config value that
     turned every render in the studio into a refunded failure would be the
     worst kind of lever. It still gates the mask built at DRAWING time
     (studioStoreVersionSpec), which is only a preview picture. */
  renderDeterministicSpec: true,
  /* "off" | "punch" | "observe" | "enforce" — see the cut check in
     handleStudioRender. "punch" is the one to reach for when the render keeps
     engraving a declared cut-out: it composites the openings the mask already
     knows about and judges nothing else.
     This is POST-render verification and remains deliberately separate from
     the deterministic PRE-render specification above. */
  /* ── THE CUT CHECK IS LIVE, WITH AUTOMATIC RE-RENDERS ─────────────────
     "punch" is the mode to run: the declared openings are composited in by
     code, which is the repairable failure and needs no model and no retry.
     The two verdicts code CANNOT repair — metal removed that should be solid,
     or a silhouette that drifted too far to map — trigger a fresh render,
     up to `renderRetries` extra attempts.
     Modes: "off" | "punch" | "observe" | "enforce". */
  /* ── NO PIXEL EDITING. THIS IS "off" AND SHOULD STAY THERE. ────────────
     "punch" fills declared openings with ONE flat colour sampled from the
     render's corners, at hard 1px edges, mapped through a bounding-box
     scaling. When the mapping is a few pixels out — and it routinely is —
     that flat shape spills over the metal and reads as a white sticker laid
     on the charm. Measured on a real render: 66% of the affected pixels were
     the single value (249,248,248). It cannot blend, so it can only be right
     or obviously wrong.

     Modes:
       "off"      nothing runs. What ships.
       "verify"   the check runs and a failed render is RE-RENDERED. No pixel
                  is ever touched. This is the mode to use if you want the
                  openings enforced.
       "observe"  the check runs and files its numbers; image untouched.
       "punch"    fills declared openings. Produces the sticker artefact.
       "enforce"  punch AND reject undeclared cuts. */
  /* renderInput ("mask" | "drawing") is REMOVED. It chose which image the
     renderer was shown, and the studio's Send toggle overrode it per press.
     There is one input now — the greyscale material spec (176/136/255), the
     STRUCTURE_MAP the fixed prompt describes — and handleStudioRender reads
     neither this key nor the request field. A drawing with no mask fails
     rather than falling back to the colour-coded production drawing. */
  renderCutCheck: "off",
  /* The naming pass. PARKED — the prompt no longer carries the census, so
     nothing read its output. The prompt is a fixed string now, so turning
     this back on cannot reach it at all without editing
     buildMaterialSpecToCharmPrompt by hand. */
  renderNameRegions: false,
  /* Extra attempts after a failed check. 0 restores the previous behaviour
     exactly. Retries are never charged: the debit happens once, before the
     first attempt. */
  renderRetries: 2,
  /* A retry must not outlive the browser — but the number this was set
     against is long gone, and so is the client it names. GEN_TIMEOUT_MS
     (180s) is the CONCEPT generator's clock; the render watcher was since
     rewritten to a silence window plus a hard cap (MK_RENDER_IDLE_MS,
     MK_RENDER_HARD_MS), and the cap is 480s.

     At 150s against a flash render measured at 35-80s this admitted a
     second attempt comfortably. Against gemini-3-pro-image it admits none:
     the loop starts a new attempt only if elapsed PLUS the previous
     attempt's measured duration still fits, and one pro attempt — image
     plus judge — lands near 140s on its own, so 140 + 140 > 150 and the
     adjudicator's retries would be dead on arrival. The verification work
     of the last few days would then be gating renders it could never ask
     to be redone.

     300s admits a second attempt and stops there: after two attempts at
     ~140s each the same test refuses a third (280 + 140 > 300), so a run
     settles around 280s against the client's 480s cap. That margin is the
     point — this budget must stay comfortably under MK_RENDER_HARD_MS, and
     the two are edited together or not at all. */
  renderRetryBudgetMs: 300000,

  /* ══════════ THE CUT-OUT COMPOSITE — A POST-PROCESS, NOT A PROMPT ═══════
     Measured across four renders of one charm: the greyscale map declared
     sixteen through-cuts covering 44.8% of the piece, and three of the four
     renders came back with exactly ONE of them. Google's image API documents
     no seed, no temperature and no mask parameter, so "cut where IMAGE 1 is
     white" is a request rather than a constraint and asking harder does not
     close it. What the model DOES reproduce reliably is the outer silhouette
     — to about a pixel and a half — which is exactly the case where you stop
     asking and composite.

     It runs once, after the winning render is chosen, and touches nothing
     upstream of itself: same prompt, same model, same attempt loop, same
     adjudicator, same cut check. Three settings, no deploy:
       "on"       what ships. Declared openings the render did not make are
                  composited into it; ones it already made are left exactly
                  as the model drew them.
       "observe"  it runs and files its numbers on the version doc, but the
                  image is returned untouched. This is how the numbers get
                  read against real traffic without a customer paying for it.
       "off"      it does not run at all. Byte-for-byte the behaviour before
                  it existed, and the reserve below is returned to the retry
                  loop.
     Every internal failure already returns the render unmodified, so "off"
     is a convenience rather than a safety net. */
  renderComposite: "on",
  /* ── THE SHAPE GATE ────────────────────────────────────────────────────
     "on" measures the silhouette overlap between each render and the
     greyscale map and re-rolls a render that is not the same charm; "off"
     measures nothing. It is deliberately NOT tied to STUDIO_VERIFICATION_
     PAUSED: that pause exists because the punch's FILL identification was
     still being corrected, and this gate reads no fills. It reads two outer
     silhouettes, which is the one thing every render in evidence reproduces
     well — 0.977 and 0.984 on good renders, 0.731 on the astronaut that drew
     itself standing. It costs no credit and no model call. */
  renderShapeGate: "on",
  /* ── AND WHETHER ITS ENGRAVING WAS TRACED OR FILLED ────────────────────
     "on" re-rolls a render whose engraving is materially thicker than
     anything its own map declares — an engraved OUTLINE rendered as a filled
     recess, which is the failure a count of engraved regions can never see
     because the regions are the same regions, only fatter. "observe"
     measures it and files the numbers without re-rolling; "off" skips it.

     It ships in "observe" on purpose: the thresholds behind it (SCO_ENG_*)
     are calibrated on ONE bad render, and a gate that re-rolls on a number
     nobody has watched yet spends the customer's clock on a guess. Watch
     renderEngraveOver on a week of renders, then set this to "on". */
  renderEngraveGate: "observe",
  /* ── HOW FAR A RENDER MAY BE STRETCHED ON ONE AXIS ─────────────────────
     Bounding-box anisotropy: (rb.w/mb.w) ÷ (rb.h/mb.h), never below 1. The
     composite REFUSES above this whatever the gate is set to — placing an
     opening into a charm this far out of proportion cannot be right, and
     doing nothing leaves the model's own cut-outs intact. See SCO_ASPECT_MAX
     for the three measurements this sits between. */
  renderAspectMax: 1.15,
  /* And whether the SHAPE GATE also re-rolls on it. "off" by default: the
     refusal above costs nothing and cannot damage a render, while a re-roll
     spends the clock, and three calibration pairs is not a population. Watch
     renderAspect on the version docs first. */
  renderAspectGate: "off",
  /* Below this the render is a different charm — a re-roll, never a cancelled
     composite; the composite's own floor lives in SCO_FIT_FAIL / SCO_FIT_IOU
     and is a boundary distance, for the reason set out there.

     0.90 came from two populations that looked well separated: no good render
     under 0.97, no bad one over 0.84. Ten pairs later they overlap — a good
     dragon reads 0.9053 and a heart drawn for a shield reads 0.9119 — because
     IoU is an AREA ratio and a coiled dragon is nearly all perimeter, so the
     same accuracy scores far worse on the customer's most intricate designs.
     0.80 keeps what IoU is genuinely good at, catching gross drift: it still
     rejects the wrong astronaut at 0.7308 and every mismatched dragon pair
     (0.7628-0.7983), while leaving the worst good render 0.10 of margin. The
     fine discrimination is the boundary distance's job, and it does separate
     — 1.72 good against 2.61 bad. */
  renderShapeMinIoU: 0.80,
  /* How many re-rolls a rejected render may buy, independent of the cut
     check's and the adjudicator's allowances — "this is not the customer's
     charm" is a different complaint from "this charm is not good enough",
     and neither should exhaust the other's budget. The wall clock still caps
     both, and with the adjudicator parked there is no judge call spending it,
     so two attempts fit comfortably inside the retry budget. Two, because a
     single re-roll of an independent draw only halves the chance of shipping
     a bad one; the gates are cheap and the failures are not. */
  renderShapeRetries: 2,
  /* Its share of the wall clock, reserved out of renderRetryBudgetMs BEFORE
     the retry loop spends it — see the note at the reservation. Measured at
     2.6-2.9s on an 824 px render and scaling with area; 30s is roughly three
     times what a 1600 px render needs, and the composite's own deadline
     makes an overrun a no-op rather than a late render. */
  renderCompositeBudgetMs: 30000,
  /* The RE-ROLL threshold the composite reports against. It no longer cancels
     anything: THE CANCEL TEST IS A DISTANCE, not an overlap, and it is not
     configurable — see SCO_FIT_FAIL.

     This one number used to do both jobs and that is what cost customers
     their cut-outs. Measured on a dragon: 0.8 degrees of tilt — a drift
     nobody would notice, boundary error moving 1.72 to 1.82 — dropped IoU
     from 0.9053 to 0.8925 and cancelled the whole composite, so all 27
     declared openings shipped as the model's engraving instead of as holes.
     "A whole bunch of scales are engraved instead of cut out" is that
     sentence, in a photograph. */
  renderCompositeMinIoU: 0.80,
  /* ── HOW EXACTLY THE OPENINGS FOLLOW THE MAP ───────────────────────────
     "on" (what ships) lets each cluster of openings take a small, bounded,
     evidence-backed correction against the render's own drawing, because the
     model does not transform the map — it redraws the charm, with its own
     slightly different internal proportions, and on the bow the corrections
     differ between regions by five pixels.

     "off" removes that stage: every opening lands exactly where the global
     silhouette fit puts it, which is the map's geometry and nothing else.
     That is the most literally repeatable placement available — the position
     of any one opening then cannot be influenced by what the model happened
     to draw anywhere else on the charm — at the cost of a few pixels against
     the render's own recesses where the interior really has drifted. */
  renderCompositeLocalFit: "on",

  /* ══════════ THE ADJUDICATOR — POST-RENDER SCORING ══════════════════════
     Reads the finished gold charm against the deterministic greyscale map
     with a vision model, scores six categories, and re-renders when the
     result is not good enough. See the adjudicator block above
     studioAdjudicateOnce for what it catches that the cut check cannot.

     THE WHOLE SUBSYSTEM REVERTS WITH THIS ONE VALUE, no deploy:
       "off"      nothing runs. Byte-for-byte the behaviour before it existed:
                  no judge call, no extra render, no fields on the version doc.
       "observe"  every render is scored and the numbers are filed, but the
                  image is returned untouched and nothing is ever re-rendered.
                  One cheap vision call per render, no extra image calls. This
                  is how the threshold gets set from real traffic.
       "enforce"  what ships. Score; if it fails, render again — up to
                  renderScoreRetries more times — and return the HIGHEST
                  SCORING attempt, never the last one.

     WHAT IT COSTS. In "enforce" a single credit can now buy up to three image
     calls and three judge calls instead of one image call. The customer is
     debited once, before the first attempt, and is never charged for a retry.
     renderRetryBudgetMs still caps the wall clock, so a slow first render
     simply ships as the best of however many attempts fitted. */
  renderAdjudicate: "enforce",
  /* The pass mark for the weighted total. A render is accepted only when it
     clears this AND no single category is below its floor.

     80, not 95. At 95 the total was the binding constraint on nearly every
     render: a charm a jeweller would ship scores in the high 80s, because
     the prompt calibrates 95 as "nothing to correct" and 85 as "clearly the
     right charm with one visible discrepancy". The workshop was re-rolling
     good charms to chase a mark the scale itself describes as perfection,
     spending two extra image calls to do it.

     The floors are what this leans on instead, and they are the better
     instrument: they ask "how bad is too bad in this one respect", which is
     the question that decides whether a charm is sellable. A v7 — cut-outs
     at 45 against a floor of 85 — still fails at any total threshold. */
  renderScoreThreshold: 80,
  /* Extra renders after a failing score. Never charged. */
  renderScoreRetries: 2,
  /* Both optional. A partial object overrides only the keys it names, so
     {"tone": 4} changes tone's weight and leaves the other five alone.
     Defaults live in STUDIO_SCORE_WEIGHTS / STUDIO_SCORE_FLOORS. */
  renderScoreWeights: null,
  renderScoreFloors: null,
};
let _studioCfg = null, _studioCfgAt = 0;
/* ── ONE PLACE THAT DECIDES WHAT THE STUDIO GENERATES WITH ────────────────
   Both studio image steps resolved their model inline, in two separate
   expressions that had to be kept in step by hand. They now come from here,
   so "what is the studio running on" has one answer and one place to change
   it. Order is deliberate: Firestore first (no deploy), then the existing env
   var if someone has already set it, then the built-in default. */
const STUDIO_IMAGE_MODEL_FALLBACK = "gemini-3-pro-image";
const STUDIO_DRAWING_TIER_FALLBACK = "2K";   // the input side
const STUDIO_RENDER_TIER_FALLBACK = "1K";    // the output side
const STUDIO_MASK_MIN_PX_FALLBACK = 2048;

/* ═══════════ HOW MANY DECLARED ZONES A DESIGN MAY HAVE ═══════════════════
   This was the literal 40, written out by hand at eight call sites with no
   comment at any of them, and nothing in the file ever said why. It was not
   a budget anyone had measured — the cut mask is a per-zone box fill over a
   bitmap, which costs microseconds a zone, and the prompt does not itemise
   engraved zones at all. What it DID do was silently drop a customer's 41st
   zone, and then a fallback was written to guess back what the truncation
   had thrown away — which punched a charm's entire body out as a hole. Two
   bugs, both descended from an unexplained constant.

   So the list is not truncated any more. A design with 400 zones renders all
   400. The number below is a runaway guard — a payload this size is a bug in
   the caller, not a customer's design — and it is deliberately far above any
   real design so that it never quietly shapes one.

   AND IF IT EVER DOES BITE, IT SAYS SO. Silent truncation is what made the
   original 40 so expensive: the map was wrong and nothing anywhere reported
   a reason. studioZoneList logs loudly and stamps the count it dropped. */
const STUDIO_ZONE_LIMIT = 2000;
function studioZoneList(zones, where) {
  const all = Array.isArray(zones) ? zones : [];
  if (all.length <= STUDIO_ZONE_LIMIT) return all;
  console.error(`[studio] ZONE LIST TRUNCATED at ${where}: ${all.length} zones ` +
                `exceeds STUDIO_ZONE_LIMIT ${STUDIO_ZONE_LIMIT}. This is a caller ` +
                `bug — the map for this design will be missing declared areas.`);
  return all.slice(0, STUDIO_ZONE_LIMIT);
}

/* ── NOT EVERY STEP EARNS THE EXPENSIVE MODEL ─────────────────────────────
   One knob for five steps meant the two steps whose output is REWRITTEN BY
   CODE before anyone sees it were paying the same rate as the charm the
   customer actually looks at:

     lineart   the catalogue trace is thinned, re-measured and smoothed by
               studioThinLineArt before it becomes the reference — most of
               the pro model's extra fidelity is planed off deterministically.
               The flash image model at the same 2K drawing tier keeps the
               fidelity that survives that pass.
     specgold  the from-gold greyscale map is the FALLBACK path: since mk24
               the drawing pipeline builds this map deterministically and the
               deriver yields to it, so this should rarely run at all — and
               when it does, its output is a three-tone map, not a picture.

   Each has its own Firestore key (studioLineArtModel / studioSpecModel) so
   either can be put back on the pro model without a deploy. The keys resolve
   BEFORE the shared chain on purpose: the global studioImageModel /
   GEMINI_STUDIO_IMAGE_MODEL lever keeps meaning "the model the studio
   generates with", and turning it up must not silently drag the planed
   steps up with it.

   ── THE GOLD CHARM HAS ITS OWN KEY TOO ──────────────────────────────────
   render and goldedit produce the SAME artefact — the photoreal metal charm
   the customer buys — and Paul moved that artefact onto the flash image
   model. They share one key, studioRenderModel, so the two can never drift
   apart and hand the customer a different-looking charm depending on which
   button was pressed.

   generate is deliberately NOT in this group. Its output is the production
   drawing, which is the render's INPUT and the thing studioPenWidth, the
   2.5x-pen cut test and studioMaterialSpec all measure — a downgrade there
   is a downgrade to every measurement downstream of it, which is a separate
   decision from what the finished charm is rendered with. It stays on the
   shared studioImageModel knob. */
const STUDIO_STEP_MODEL_KEYS = Object.freeze({
  lineart: "studioLineArtModel",
  specgold: "studioSpecModel",
  render: "studioRenderModel",
  goldedit: "studioRenderModel",
});
const STUDIO_STEP_MODEL_FALLBACK = Object.freeze({
  lineart: "gemini-3.1-flash-image",
  specgold: "gemini-3.1-flash-image",
  /* the finished metal charm — "Nano Banana Pro", a stable listed ID,
     verified against the published model list rather than inferred from
     another name. Reached only when config/customStudio cannot be read at
     all; it matches STUDIO_CFG_DEFAULTS.studioRenderModel deliberately, so
     an unreachable Firestore does not quietly change which model draws the
     charm the customer is paying for. */
  render: "gemini-3-pro-image",
  goldedit: "gemini-3-pro-image",
});

function studioImageModelId(cfg, step) {
  const key = step && STUDIO_STEP_MODEL_KEYS[step];
  if (key) {
    const own = cfg && cfg[key];
    return String(own || STUDIO_STEP_MODEL_FALLBACK[step]).trim();
  }
  return String(
    (cfg && cfg.studioImageModel) ||
    process.env.GEMINI_STUDIO_IMAGE_MODEL ||
    STUDIO_IMAGE_MODEL_FALLBACK
  ).trim();
}

/* An unrecognised value falls back to this step's OWN default rather than to
   a shared one — a typo in the render key must not silently drop the drawing,
   and a typo in the drawing key must not silently inflate every render. */
function studioTier(value, fallback) {
  const t = String(value || "").trim().toUpperCase();
  return t === "1K" || t === "2K" || t === "4K" ? t : fallback;
}

/* the production drawing — the render's input, and what the pixel plan measures */
function studioDrawingTier(cfg) {
  return studioTier(cfg && cfg.studioDrawingTier, STUDIO_DRAWING_TIER_FALLBACK);
}

/* ── THE FINISHED METAL CHARM IS 1024, FULL STOP ──────────────────────────
   Presentation only — nothing downstream measures it, so the tier buys the
   customer nothing but a bigger file and a slower render. Paul's ruling is
   1024 ONLY, so this no longer reads config: studioRenderTier was already
   "1K" by default and a Firestore value could still inflate it, which is
   the one thing "only" rules out. The key is deliberately dead rather than
   deleted — an existing studioRenderTier:"2K" in anyone's config document
   now does nothing instead of silently costing more, and putting the knob
   back is a one-line deploy.

   NOT clamped anywhere shared. studioDrawingTier stays 2K — that is the
   render's INPUT, the thing studioPenWidth and the 2.5x-pen cut test
   measure — and every non-studio caller (Listing Generator, Charm Maker,
   batch) still resolves its own tier through callGeminiGenerateContentImage
   exactly as before, defaulting to 2K when it passes nothing. */
function studioRenderTier(_cfg) {
  return STUDIO_RENDER_TIER_FALLBACK;
}

/* the mask's minimum long edge; 0 or a junk value disables the floor */
function studioMaskMinPx(cfg) {
  const n = Number(cfg && cfg.studioMaskMinPx);
  return Number.isFinite(n) && n >= 256 && n <= 8192 ? Math.round(n) : STUDIO_MASK_MIN_PX_FALLBACK;
}

function studioImageSizeString(tier) {
  return tier === "1K" ? "1024x1024" : tier === "4K" ? "4096x4096" : "2048x2048";
}

async function studioConfig() {
  if (_studioCfg && Date.now() - _studioCfgAt < 60000) return _studioCfg;
  try {
    const snap = await getDb().doc(STUDIO_CONFIG_DOC).get();
    _studioCfg = Object.assign({}, STUDIO_DEFAULT_CONFIG, snap.exists ? snap.data() : {});
  } catch (_e) {
    _studioCfg = Object.assign({}, STUDIO_DEFAULT_CONFIG);
  }
  _studioCfgAt = Date.now();
  return _studioCfg;
}

/** Hourly ceiling on top of the wallet, so a stolen ID token cannot burn the
 *  Gemini budget in one go. */
/* ── RATE CEILING, WITH AN EXEMPTION ──────────────────────────────────────
   Checks the hourly ceilings unless the account is unlimited, in which case
   the counter is not read and not incremented — a testing session must not
   silently fill the window for the account's own later use.

   Reads the user doc once and only when a uid is supplied. A failure to read
   it is treated as "not unlimited", so the ceiling still applies: the safe
   direction for a limiter is to stay on. */
async function studioUnlimitedUid(uid) {
  if (!uid) return false;
  try {
    const snap = await getDb().doc(`users/${uid}`).get();
    if (!snap.exists) {
      console.log(`[studio] gate: users/${uid} does not exist — ceiling applies`);
      return false;
    }
    const w = snap.data()?.wallet;
    const un = walletIsUnlimited(w);
    if (!un) {
      /* The commonest cause of "I set unlimited and it still limits me" is the
         value being the STRING "true", or the field sitting on the user doc
         rather than inside `wallet`. Say which, rather than just refusing. */
      const raw = w && Object.prototype.hasOwnProperty.call(w, "unlimited")
        ? `wallet.unlimited=${JSON.stringify(w.unlimited)} (${typeof w.unlimited}) — must be boolean true`
        : (w ? "wallet exists but has no `unlimited` field" : "no `wallet` map on the user doc");
      console.log(`[studio] gate: uid ${uid} NOT unlimited — ${raw}`);
    }
    return un;
  } catch (e) {
    console.error("[studio] unlimited check failed, ceiling stays on:", e?.message || e);
    return false;
  }
}

/* Says WHICH ceiling refused, and whether the exemption was even consulted.
   A limiter that returns a bare 429 with no reason is how an afternoon gets
   spent blaming the upstream provider. */
/* Whatever the ceilings are RIGHT NOW. config/customStudio wins over the
   environment so a ceiling can be raised, lowered or switched off from the
   Firebase console while the storefront is live; the document is already
   cached for a minute, so asking costs nothing. */
async function studioCeilings() {
  let cfg = null;
  try { cfg = await studioConfig(); } catch (_e) { cfg = null; }
  const pick = (k, fallback) => {
    const v = cfg && cfg[k] != null ? Number(cfg[k]) : fallback;
    return Number.isFinite(v) && v > 0 ? v : 0;
  };
  return {
    uid: pick("maxGensHourUid", STUDIO_MAX_GENS_HOUR_UID),
    ip:  pick("maxGensHourIp",  STUDIO_MAX_GENS_HOUR_IP),
  };
}

async function studioGateOk(uid, event) {
  const ceil = await studioCeilings();
  /* No ceiling configured is the shipped default — see the note beside
     STUDIO_MAX_GENS_HOUR_UID. Nothing is read and nothing is counted, so an
     account that is not being limited does not pay a Firestore transaction
     per generation either. */
  if (!ceil.uid && !ceil.ip) return true;
  if (await studioUnlimitedUid(uid)) {
    console.log(`[studio] gate: uid ${uid} is unlimited — ceilings skipped`);
    return true;
  }
  const ip = studioClientIp(event);
  const okUid = await studioBudgetOk("gen", uid, ceil.uid);
  if (!okUid) {
    console.log(`[studio] gate: BLOCKED by the per-account ceiling ` +
                `(${ceil.uid}/hour, drawings and renders share it, ` +
                `window resets an hour after its first request) uid=${uid}`);
    return false;
  }
  const okIp = await studioBudgetOk("genip", ip, ceil.ip);
  if (!okIp) {
    console.log(`[studio] gate: BLOCKED by the per-IP ceiling ` +
                `(${ceil.ip}/hour) ip=${ip}`);
    return false;
  }
  return true;
}

async function studioBudgetOk(key, id, max) {
  /* THE OFF SWITCH, IN ONE PLACE. A ceiling of zero is no ceiling: nothing is
     read, nothing is written, nothing is counted. Every caller passes its
     limit through here, so switching one off can never leave a counter
     ticking somewhere that a later change turns back into a refusal. */
  if (!(Number(max) > 0)) return true;
  const db = getDb();
  const hash = require("crypto").createHash("sha256").update(String(id)).digest("hex").slice(0, 32);
  const ref = db.doc(`${STUDIO_RATE_COLL}/${key}_${hash}`);
  const now = Date.now();
  try {
    return await db.runTransaction(async (tx) => {
      const snap = await tx.get(ref);
      const d = snap.exists ? snap.data() : {};
      const windowStart = d.windowStart && now - d.windowStart < 3600e3 ? d.windowStart : now;
      const count = windowStart === d.windowStart ? (d.count || 0) : 0;
      if (count >= max) return false;
      tx.set(ref, { windowStart, count: count + 1, updatedAt: now }, { merge: true });
      return true;
    });
  } catch (_e) {
    return true;   // never let the limiter itself take the studio down
  }
}

/* ── wallet ──────────────────────────────────────────────────────────────
   The client's credit meter is cosmetic. THIS is the quota: an atomic
   transaction that runs BEFORE Gemini is called, and a refund if the
   generation fails. */
/* ── UNLIMITED ACCOUNTS ────────────────────────────────────────────────────
 * `users/{uid}.wallet.unlimited === true` exempts an account from the credit
 * meter AND from the hourly rate ceilings. Generations and renders still run
 * and still log to the ledger; only the balance and the counter are left
 * alone.
 *
 * The ceilings (25 gens/hour per uid, 60 per IP, drawings and renders sharing
 * one counter) exist so a public storefront cannot be used to drive the
 * Gemini key as fast as somebody can click. That is right for a shopper and
 * wrong for whoever is developing the studio, who can exhaust an hour's
 * budget in twenty-five minutes of testing and then be locked out for the
 * rest of the window — the counter resets an hour after its FIRST request,
 * not on a sliding hour, so there is no partial recovery.
 *
 * It lives on the USER document rather than in config/customStudio because
 * that config doc is readable by any signed-in visitor (see firestore.rules),
 * and a public list of staff uids is a needless thing to publish. The user doc
 * is readable only by its owner, unwritable from any browser, and is ALREADY
 * loaded inside this transaction — so the check costs nothing.
 *
 * Set it in the Firebase console; no deploy, no code change, and it survives
 * every future top-up because nothing else writes that field.
 * ===================================================================== */
function walletIsUnlimited(w) {
  return !!(w && w.unlimited === true);
}

async function studioDebit(uid, cost, sessionId) {
  const db = getDb();
  const ref = db.doc(`users/${uid}`);
  await db.runTransaction(async (tx) => {
    const snap = await tx.get(ref);
    const w = (snap.exists && snap.data().wallet) || {};

    /* Unlimited: no balance check, no decrement — but still ledgered, so the
       real cost of testing stays visible instead of becoming invisible. */
    if (walletIsUnlimited(w)) {
      tx.create(ref.collection("walletLedger").doc(), {
        delta: 0, reason: "generate_unlimited", ref: sessionId || null,
        at: admin.firestore.FieldValue.serverTimestamp(),
      });
      return;
    }

    const credits = Number(w.credits) || 0;
    if (credits < cost) { const e = new Error("out_of_credits"); e.status = 402; throw e; }
    tx.set(ref, {
      wallet: Object.assign({}, w, {
        credits: credits - cost,
        lifetimeSpent: (Number(w.lifetimeSpent) || 0) + cost,
      }),
      updatedAt: Date.now(),
    }, { merge: true });
    tx.create(ref.collection("walletLedger").doc(), {
      delta: -cost, reason: "generate", ref: sessionId || null,
      at: admin.firestore.FieldValue.serverTimestamp(),
    });
  });
}
async function studioRefund(uid, cost, sessionId) {
  try {
    const db = getDb();
    const ref = db.doc(`users/${uid}`);
    await db.runTransaction(async (tx) => {
      const snap = await tx.get(ref);
      const w = (snap.exists && snap.data().wallet) || {};
      /* Nothing was taken, so nothing is given back — refunding an unlimited
         account would quietly inflate a balance that is never spent. */
      if (walletIsUnlimited(w)) return;
      tx.set(ref, {
        wallet: Object.assign({}, w, {
          credits: (Number(w.credits) || 0) + cost,
          lifetimeSpent: Math.max(0, (Number(w.lifetimeSpent) || 0) - cost),
        }),
        updatedAt: Date.now(),
      }, { merge: true });
      tx.create(ref.collection("walletLedger").doc(), {
        delta: cost, reason: "failure_refund", ref: sessionId || null,
        at: admin.firestore.FieldValue.serverTimestamp(),
      });
    });
  } catch (e) {
    console.error("[studio] refund failed:", e?.message || e);
  }
}
/** Uploads are metered separately from generation, and ONLY on an accepted
 *  image, so a rejected photo costs the customer nothing. */
async function studioMeterUpload(uid, cfg) {
  const db = getDb();
  const ref = db.doc(`users/${uid}`);
  const user = await admin.auth().getUser(uid).catch(() => null);
  const signedIn = !!(user && user.email);
  let allowed = true;
  await db.runTransaction(async (tx) => {
    const snap = await tx.get(ref);
    const w = (snap.exists && snap.data().wallet) || {};
    const used = Number(w.uploadsUsed) || 0;
    const cap = cfg.guestFreeUploads
              + (signedIn ? cfg.signupBonusUploads : 0)
              + (Number(w.purchasedAllowance) || 0);
    if (used >= cap) { allowed = false; return; }
    tx.set(ref, { wallet: Object.assign({}, w, { uploadsUsed: used + 1 }), updatedAt: Date.now() }, { merge: true });
  });
  return allowed;
}

/* ── the prompt ──────────────────────────────────────────────────────────
   buildCharmDesignPromptServer is the workshop's own doctrine and the single
   source of truth for what a Brites charm physically is. We slice its
   constraint blocks out VERBATIM and wrap them in a customer intent header,
   so the two can never drift: edit the doctrine there and the studio inherits
   it on the next deploy. */
function studioCleanText(text) {
  return String(text == null ? "" : text)
    .replace(/[\x00-\x1f\x7f]+/g, " ")
    .replace(/```+/g, " ")
    .replace(/\b(ignore|disregard|forget)\b[^.]{0,40}\b(previous|above|prior|system)\b[^.]*/gi, " ")
    .replace(/\s+/g, " ")
    .replace(/^[\s.,;:!?)\]}>-]+/, "")
    .trim()
    .slice(0, STUDIO_MAX_INSTRUCTION);
}

/** Everything from HARD PHYSICAL CONSTRAINTS onward, with the Charm Maker's
 *  AESTHETIC CONTINUITY paragraph swapped for the studio's — that one block
 *  says the subject comes from the complementary brief and NOT from the
 *  reference, which is precisely backwards here. */
function studioConstraintBlocks() {
  let full = "";
  try {
    full = String(buildCharmDesignPromptServer({}, {}) || "");
  } catch (_e) {
    full = "";
  }
  const start = full.indexOf("HARD PHYSICAL CONSTRAINTS:");
  const aesthetic = full.indexOf("AESTHETIC CONTINUITY:");
  const finalCheck = full.indexOf("FINAL PRE-RENDER CHECK");
  if (start < 0 || finalCheck < 0) return "";       // doctrine moved — see below

  const physical = aesthetic > start && aesthetic < finalCheck
    ? full.slice(start, aesthetic)
    : full.slice(start, finalCheck);

  const studioAesthetic =
`AESTHETIC CONTINUITY:
Match this workshop's metal alloy and tone, polish, restrained engraving language, lighting quality, production realism and black-background treatment. The SUBJECT comes from the customer's reference image and their written instructions — honour it. Everything about HOW it is made comes from the rules above.

`;
  return physical + studioAesthetic + full.slice(finalCheck);
}

/* Failsafe: if buildCharmDesignPromptServer is ever restructured so the slice
   markers move, the studio must not silently generate unconstrained charms.
   This is the minimum doctrine, used only in that case. */
/* ═══════════ THE FILL LAW ════════════════════════════════════════════════
 * The customer's fill is not decoration and never was — it is the one
 * instruction in the studio that changes what the workshop DOES to the
 * piece. The drawing tool now offers exactly three answers and no others,
 * so this block can be absolute rather than advisory. It is inserted
 * verbatim into every prompt that consumes a customer drawing: the B/W
 * generation and the metal render alike. Both must obey it identically, or
 * the customer's own preview would disagree with the charm they receive.
 * ===================================================================== */
/* The same three instructions, said again as a LIST. A colour inside a
 * compressed JPEG is a thing to be interpreted; a line of text reading
 * "CUT OUT — top centre" is not. Sent alongside the picture, never instead
 * of it, so the two corroborate each other. */
function zoneBlock(zones, which) {
  /* a zone with no geometry is not a zone: it printed as "at the centre
     (about 0% × 0%)" and still incremented a count the model was told to
     obey. Nothing client-side can send one, but nothing server-side checked. */
  const z = (Array.isArray(zones) ? zones : []).filter((q) =>
    q && (q.intent === "cutout" || q.intent === "engrave" || q.intent === "none") &&
    Number(q.w) > 0.004 && Number(q.h) > 0.004);
  if (!z.length) return "";
  const cut = z.filter((q) => q.intent === "cutout");
  const eng = z.filter((q) => q.intent === "engrave");
  const out = z.filter((q) => q.intent === "none");
  const src = which === "reference" ? "THE REFERENCE IMAGE"
            : which === "drawing" ? "THE PRODUCTION DRAWING" : "the mark-up";
  /* ── NOT ONE DIGIT IN THIS LIST. EVER. ────────────────────────────────
     This block has now injected content onto a finished charm twice, and
     both times the vector was the same: a token that only exists to
     structure the list. First it was layer names — "logo 4", "Engraved ·
     Cherry3D Logo.png" — which came back set in type around the rim. The
     names were removed and replaced with index numbers, and the model drew
     the NUMBERS instead, each one placed at the very position its line
     described: a charm with 3 at the top, 4 on the left, 14 at the bottom.
     An image model treats every distinctive token in an instruction block
     as a candidate for the canvas, so the only safe list is one made of
     nothing but ordinary words. No indices, no percentages, no counts in
     figures. Sizes are said in words; counts are said in words; areas are
     told apart by where they are, which is all they ever needed. */
  const sizeWord = (q) => {
    if (q.ring) return "a ring-shaped band around the drawing";
    const span = Math.max(Number(q.w) || 0, Number(q.h) || 0);
    if (span > 0.75) return "spanning nearly the whole drawing";
    if (span > 0.45) return "large";
    if (span > 0.2)  return "medium-sized";
    if (span > 0.08) return "small";
    return "tiny";
  };
  const W = ["no","one","two","three","four","five","six","seven","eight",
             "nine","ten","eleven","twelve"];
  const cw = (n) => n < W.length ? W[n] : "more than twelve";
  const say = (q) => `  – at ${q.where || "the centre"}: ${sizeWord(q)}` +
    (q.ring ? " (its central hole is NOT part of it)" : "");
  return `
THE CUSTOMER'S OWN COUNT OF WHAT EACH AREA IS, taken from the controls they
used in the studio rather than read off the pixels. This list and ${src}
agree; if you ever think they do not, THIS LIST WINS:
${cut.length ? `• CUT CLEAN THROUGH — ${cw(cut.length)} area${cut.length === 1 ? "" : "s"}:\n${cut.map(say).join("\n")}` : "• CUT CLEAN THROUGH: none"}
${out.length ? `• OUTLINE ONLY (boundary worked, interior left as polished metal) — ${cw(out.length)} area${out.length === 1 ? "" : "s"}:\n${out.map(say).join("\n")}` : "• OUTLINE ONLY: none"}
• ENGRAVED SOLID: every remaining BLACK area of ${src} — ${cw(eng.length)} of
  them. They are not itemised because the picture already shows each one;
  engrave every one of them exactly where and as the picture shows it.
  BLACK, not merely dark: a blue area is dark too, and it is a hole.
AN OUTLINE-ONLY INSTRUCTION IS ABOUT ONE SHAPE'S OWN BOUNDARY AND INTERIOR —
NOTHING ELSE. It never blanks, erases, thins or un-engraves anything outside
that shape: every other black area the picture shows stays exactly as dark and
as engraved as the picture shows it. Turning a solidly engraved band into a
thin outline because an outline instruction exists nearby is a hard fail.
EVERY area listed as CUT CLEAN THROUGH must be an actual opening in your
output, and every black area must come through as engraved. THE LIST IS ALSO
COMPLETE: those are the only openings this charm has. An opening anywhere the
list does not name — however much the design might look better open — is a
hard fail. Count your openings against it before you finish.
NOTHING IN THIS LIST IS ARTWORK. It describes where areas sit; it is not
lettering, not a caption, not a label, not a legend and not part of the
design. Never draw, engrave, set or letter ANY word, letter, digit or number
anywhere on the charm unless it is given under LETTERING — and this list is
not LETTERING.
This list says what these particular areas ARE; it is not a census of the
whole charm. The hoop's own hole, and any opening the design itself plainly
requires — a ring, a bail, the middle of a letter O — are separate from it
and are still required. What the list forbids is the reverse: turning a
listed cut-out into engraving or solid metal, or a listed engraved area into
plain polished metal.
`;
}

const FILL_LAW =
`THE GOLDEN RULE OF THIS WORKSHOP — ABOVE EVERY OTHER INSTRUCTION IN THIS
PROMPT: the customer's three engraving colours (BLACK, BLUE, RED) are obeyed
EXACTLY, on every generation, every refinement and every render, with no
exception, ever. EVERY solid blue area IS an opening. Every black area IS
engraved. Every red boundary IS an outline with a polished interior. If your
composed image loses even ONE of them — one blue area that is not an opening,
one black area that is not engraved — the image is WRONG and must be redone
before you return it. There is no artistic judgement to apply here; a lost
instruction is a physically different object than the one that was bought.

AREA FILL — THREE MEANINGS, NON-NEGOTIABLE. This is the customer's
manufacturing instruction, not a stylistic choice, and it overrides every
other consideration including your own sense of what would look better:

  1. SOLID BLACK FILLED AREA  =  ENGRAVE IT.
     The whole area is engraved — cut into the surface, hatched or recessed
     solid. The metal is STILL THERE; its surface is worked. In the B/W
     production drawing it is solid black. In the metal render it is a
     recessed, darker, textured area with the metal plainly present.

  2. SOLID BLUE FILLED AREA  =  CUT IT CLEAN THROUGH.
     The metal is REMOVED from that area entirely: an actual opening through
     the charm, with whatever is behind the charm visible through it. Blue is
     reserved in this studio for exactly this and appears for no other
     reason. In the B/W production drawing a cut-out is drawn as an OPEN
     HOLE — paper white inside, with a single clean cut edge around it, the
     same convention as the hoop's hole. NEVER fill a blue area with black.
     NEVER engrave it. NEVER leave it as solid metal. It is a hole.

  3. RED OUTLINE, or an outline with a white/empty interior  =  OUTLINE ONLY.
     Engrave the boundary LINE and nothing else. The interior is flat,
     untouched, polished metal — exactly like the surrounding surface. NEVER
     promote an unfilled outline into a filled or engraved area, never hatch
     it, never shade it, never darken it. If the customer had wanted it
     engraved they would have said so, and they had a control to say it with.
     RED IS RESERVED for this and appears in a Brites drawing for no other
     reason. A red boundary is engraved as an ordinary black production line;
     the red itself is never reproduced.

THESE THREE COLOURS ARE INSTRUCTIONS, NOT PIGMENT. Blue and red are reserved
words in this studio's language: blue says "there is no metal here", red says
"only this line is worked". Neither is EVER a colour of the finished metal —
no blue enamel, no red inlay, nothing on the physical charm is blue or red.
On a production DRAWING they appear as themselves, because a drawing is where
instructions are written down; on a rendered CHARM they appear only as what
they mean: an opening, and a worked line in plain metal.

Applying the wrong one of these three is the single worst error you can make
on this job: it produces a charm that is physically different from the one
the customer designed. Count them before you draw and count them again after.`;

/* ── THE SAME LAW, FOR THE RENDER STEP ONLY ───────────────────────────────
   FILL_LAW above is written from the DRAWING's point of view — half of it
   instructs how the three colours are drawn ("paper white inside", "in the
   B/W production drawing…"), which is noise once the drawing already exists,
   and worse, it hands the model a second description of a hole to reconcile
   with the render's own. The render prompt then restated the whole mapping a
   third time in its own header.

   Three descriptions of one rule are not three times the emphasis; they are a
   reconciliation problem, and a model resolves those by picking. So the render
   says it ONCE, in the only vocabulary that applies to a photograph of metal,
   and leads with the distinction that actually fails: a hole and an engraving
   must not look alike. This block is SHORTER than the three it replaces. */
const FILL_LAW_RENDER =
`THE GOLDEN RULE OF THIS WORKSHOP — ABOVE EVERY OTHER INSTRUCTION HERE.
The drawing's three instruction colours are manufacturing orders, not pigment.
The finished charm obeys all three exactly, and shows none of them.

  BLUE area in the drawing → A HOLE. The metal is gone. You see the ground the
  charm rests on straight through it, exactly as through the hoop's hole.
  Never metal, never enamel, never engraving, never a dark patch.

  BLACK area in the drawing → ENGRAVED metal. The metal is still there and
  only its surface is worked. Never a hole.

  RED boundary in the drawing → ONLY THAT LINE is engraved. Its interior is
  flat polished metal, identical to the surface around it. Never fill it.

  WHITE inside the charm → untouched polished metal, INCLUDING a white shape
  fully enclosed by an outline. An enclosed white shape is solid sheet with a
  worked line around it, never an opening. Only blue declares an opening.

A HOLE AND AN ENGRAVING MUST NEVER LOOK ALIKE. This is the distinction the
whole charm depends on. A hole shows the ground through it and is bounded by a
cut edge. An engraving shows worked gold, barely different from the polish
beside it. If a viewer could not tell instantly which of the two they were
looking at, the render has failed — and that failure is almost always an
engraving rendered dark enough to read as an opening.

Applying the wrong one of the three produces a charm physically different from
the one the customer bought. Count the holes before you finish, then count them
again.`;

const STUDIO_FALLBACK_CONSTRAINTS =
`HARD PHYSICAL CONSTRAINTS:
• ONE CONTINUOUS PIECE cut from a single uniformly flat, thin (~22-gauge) sheet. No separate parts, no floating islands.
• SHARP SQUARE-CUT 2D EDGES. No rounded, domed, tubular, cast or inflated edges.
• EXACTLY ONE INTEGRATED PROTRUDING HOOP at the top, cut from the same sheet as a flat annulus with one clean round hole, placed directly above the design's center of mass so the charm hangs level. Never a hole punched inside the body. No jump rings, split rings, bails, chains or any separate hardware.
• ENGRAVING: sparse, very shallow, superficial surface etching — a delicate skim of the surface, never a deep carve. Its tone sits only a few shades from the surrounding gold: quiet, low-contrast, never black or white.
• NO TEXT of any kind. NO ATTACHED HARDWARE. NO 3D, no perspective, no visible thickness — a perfectly front-facing flat orthographic view.
• BACKGROUND: 100% pure solid black (#000000), edge to edge, generated natively, no gradient, no transparency, no cast shadow.

AESTHETIC CONTINUITY:
Match this workshop's metal tone, polish, engraving language and lighting. The SUBJECT comes from the customer's reference image and their written instructions — honour it.

FINAL PRE-RENDER CHECK — perform after the image is composed:
1. Exactly ONE protruding hoop above the body, from the same continuous silhouette, above the center of mass?
2. No attachment hole punched through the artwork, and no separate ring anywhere?
3. Entirely flat and 100% front-facing — no perspective, no 3D thickness?
4. Pure #000000 in every pixel outside the charm?
If any answer is no, correct the design before rendering.`;

/* ── the studio's OUTPUT CONTRACT for the design step ─────────────────────
   Adapted from the Charm Maker's promptStrBW, with one inversion: there the
   drawing DESCRIBES an existing gold charm, here the drawing IS the design.
   The ink rules are identical either way — black maps 1:1 to engraved metal —
   because this drawing later becomes the render step's structural truth, and
   the whole point of designing in B/W is that nothing about the engraving is
   ambiguous. */
const STUDIO_LINEART_CONTRACT =
`THE THREE INSTRUCTION COLOURS (THEY MEAN THE SAME IN YOUR INPUT AND YOUR OUTPUT):
This studio's production drawings are colour-coded. Exactly three colours may
carry meaning, and they are manufacturing instructions, never decoration:
• SOLID BLACK area → ENGRAVED metal.
• SOLID BLUE (a bright cyan-blue, close to #00b4ff) area → CUT CLEAN
  THROUGH: a real opening in the sheet. In your drawing that opening is
  filled SOLID BLUE so the instruction is visible at a glance.
• RED (close to #e00000) boundary line → OUTLINE ONLY: that boundary is a
  worked line and the area it encloses is flat polished metal, left WHITE.
Whatever colour an instruction arrives in — on the reference, the sketch or
the mark-up — it leaves in the SAME colour on your drawing. Losing an
instruction colour, moving it, or inventing one nobody gave is a hard fail.

COLOUR-CODED PRODUCTION LINE ART — THE OUTPUT CONTRACT (NON-NEGOTIABLE):
• The output is a flat 2D VECTOR-STYLE production drawing on a solid pure WHITE (#FFFFFF) background, drawn in BLACK ink plus the two instruction colours above and nothing else. Absolutely no transparency, no other colours, no greys, no shading, no gradients, no 3D extrusion, no perspective, no photorealism, no metal rendering.
• It depicts ONE charm: a single continuous silhouette that could be laser-cut from one flat sheet. No separate parts, no floating islands, no props, no scene.
• EXACTLY ONE small ring-shaped hanging hoop protrudes above the silhouette at the top, drawn as part of the same continuous outline — a flat annulus with one clean round hole — directly above the design's center of mass, so the finished charm hangs level. Never a separate jump ring, bail or chain.
• The charm's outer perimeter is ONE clean solid BLUE outline approximately 2px thick — the same instruction blue as the holes, because the silhouette IS a cut: it is where the charm is cut out of the sheet. A blue perimeter LINE is the cut edge; only a blue FILLED AREA is an opening.
• ENGRAVING INK RULE (CRITICAL — BLACK MAPS 1:1 TO ENGRAVED METAL, WHITE TO POLISHED METAL):
    1. STROKE ENGRAVING (the common case): an engraved line — straight, curved, or forming the OUTLINE of a shape such as a cloud, heart, wing, leaf or star — is ONE solid black stroke of appropriate weight. Never two thin parallel outlines standing in for one wide stroke.
    2. INTERIOR STAYS WHITE: when a stroke forms a CLOSED outline, the area it encloses is polished metal and stays pure WHITE. An outlined cloud is an outlined cloud, never a solid black cloud.
    3. SOLID-REGION ENGRAVING (rare): fill an area solid black ONLY when that ENTIRE area is meant to be engraved metal.
    4. THE FINGERTIP TEST: for every inked area — would a fingertip feel it as recessed engraving? If the interior would feel like the same polished surface as the rest of the charm, it stays white with a black outline stroke.
    5. CUTOUTS/HOLES — TWO KINDS, DRAWN DIFFERENTLY, HARD RULE:
       (a) the CUSTOMER'S DECLARED CUT-OUT AREAS in the design are filled SOLID BLUE inside their cut outline — blue area = no metal here.
       (b) STRUCTURAL CUTS — the hanging hoop's hole and the charm's outer silhouette — are drawn as BLUE LINES ONLY: the hoop's hole is pure WHITE inside ONE clean BLUE circular cut line, never filled solid blue and never black; the outer perimeter is one clean BLUE line. A blue LINE is a cut edge; only a blue FILLED AREA is an opening in the design.
    6. OUTLINE-ONLY AREAS: an area the customer marked outline-only has its boundary drawn as ONE clean RED line of ordinary production weight, interior pure white. Red is this drawing's word for "work the line, leave the inside alone".
• RECOGNITION AT CHARM SCALE: sparse, recognition-critical engraving only — the few lines that make the subject read at 12 mm.
• WORDS AND DIGITS: the only text of any kind in your drawing is text visibly present in the customer's own reference/mark-up or given as LETTERING. Never invent, copy or letter anything from these instructions — no numbers, no counts, no percentages, no labels, no filenames. Instructions are read, never drawn.
HARD FAIL: any shading, grey tone, black background, or any colour other than black, the instruction blue and the instruction red.
HARD FAIL: an outlined shape rendered as a filled solid when its interior is polished metal.
HARD FAIL: a cut-through opening left white or drawn black instead of filled blue, or a blue/red instruction dropped, recoloured or moved.
FINAL CHECK BEFORE RENDERING THE ONE IMAGE: one continuous silhouette with its perimeter drawn as one blue line; one integrated protruding hoop above the center of mass, its hole WHITE inside one blue cut line — never solid blue; every black mark is genuinely engraved metal; every declared opening a solid blue AREA — count the blue areas the input declares and count them again in your drawing, they must match; every outline-only boundary red with a white interior; pure white background edge to edge.`;

/* Where on the drawing a normalized point sits, in words the model can bind
   to what it sees — a note's meaning depends on WHERE it is pinned. */
function markupRegion(x, y) {
  const col = x < 0.34 ? "left" : x > 0.66 ? "right" : "centre";
  const row = y < 0.34 ? "top" : y > 0.66 ? "bottom" : "middle";
  return row === "middle" && col === "centre" ? "the centre" : `the ${row} ${col}`;
}

function buildCustomerLineArtPrompt({ instructions, thread, refine, markupNotes, markupZones, markupMode, refMode, refZones }) {
  const clean = studioCleanText(instructions);
  const log = (Array.isArray(thread) ? thread : [])
    .filter((m) => m && m.text)
    .slice(-24)
    .map((m, i) => `${i + 1}. ${m.role === "studio" ? "STUDIO" : "CUSTOMER"}: ${studioCleanText(m.text)}`)
    .filter((line) => line.split(": ").slice(1).join(": ").length > 0)
    .join("\n");

  const header =
`CUSTOMER-DIRECTED CHARM DESIGN — B/W PRODUCTION DRAWING. TRANSLATE, DON'T INVENT.

The supplied image is the customer's chosen reference. Design their charm from
it and draw the design as flat B/W production line art, then apply ONLY the
customer's requested changes:

CUSTOMER INSTRUCTIONS: ${clean || "(no change requested — translate the reference faithfully)"}
REFERENCE HANDLING: keep the recognizable subject and proportions; changes
beyond the instructions are forbidden.

• OUTER CONTOUR BRIEF: follow the reference subject's own recognizable silhouette, simplified into one bold, clean, manufacturable outline.
• ENGRAVING BRIEF: use only sparse, recognition-critical engraving strokes — the few lines that make the subject read at charm size.
• INTENTIONAL CUTOUT BRIEF: use negative-space cutouts where they improve recognition or visual appeal; otherwise use none.`;

  const parts = [header];
  if (log) {
    parts.push(
`CUSTOMER DIRECTION LOG — the full conversation so far, oldest first.
Honour all of it; the last line is the newest request:
${log}`);
  }
  if (refine) {
    parts.push(
`REFINEMENT PASS: the second image is the customer's current drawing of this
charm. Keep it and change ONLY what the newest instruction asks for.`);
  }
  /* ── THE SKETCH CONTRACT ─────────────────────────────────────────────────
     Set only when the reference image is the customer's OWN hand drawing from
     the studio's sketchpad, with the mode they chose there. Exact means the
     sketch IS the design, wanted as drawn; interpreted means it is a brief
     for the real thing. */
  if (!refine && (refMode === "exact" || refMode === "interpret")) {
    parts.push(refMode === "exact"
? `THE REFERENCE IMAGE IS THE CUSTOMER'S OWN HAND-DRAWN DESIGN — EXACT MODE:
The customer chose "exactly as drawn". Your job is faithful VECTORIZATION,
not redesign: reproduce the sketch's geometry, composition, positions and
proportions exactly, converted to clean production line weight. Straighten
only the hand's jitter; change NOTHING else.
• LINE COUNT IS SACRED: one drawn line becomes one production line — never
  doubled, never given an inner or outer parallel, a rim, a border or a halo.
• LINE colour carries no meaning — the sketchpad offers coloured lines only so
  the customer can tell their own objects apart, and every line is an engraved
  line whatever its colour.
• AREA FILL CARRIES THE WHOLE MEANING, and there are exactly three:
  SOLID BLACK area = ENGRAVE that area. SOLID BLUE area = CUT IT CLEAN
  THROUGH — a real opening, drawn in your output as that area filled SOLID
  BLUE, never black, never engraved, never plain white. RED BOUNDARY, or no
  fill at all, = outline only: draw that boundary as one clean RED line and
  leave its interior white as flat polished metal. The instruction colours
  pass straight through: blue in, blue out; red in, red out. Applying the
  wrong one produces a physically different charm; it is the worst error
  available on this job.
• TEXT in the sketch is reproduced at exactly the drawn position and size, in
  one clean sans-serif face — never moved, rescaled, reflowed or restyled.
• Add nothing the sketch does not show; remove nothing it does.
BEFORE RENDERING, CHECK: laid over the sketch, does every element of your
output sit on top of its counterpart at the same size? If not, redo it.`
: `THE REFERENCE IMAGE IS THE CUSTOMER'S OWN HAND-DRAWN DESIGN — INTERPRETED:
A freehand PEN line's colour carries no meaning — it only tells the
customer's own objects apart, and every such line is an engraved line. An
AREA is the opposite: its colour is a manufacturing instruction with exactly
three values. SOLID BLACK area = engrave it. SOLID BLUE area = CUT IT CLEAN
THROUGH — a real opening, shown in your output as that area filled SOLID
BLUE, never as black and never as engraving. A RED BOUNDARY, or no fill at
all = outline only, its interior left as flat polished metal and its boundary
drawn as one clean RED line. The instruction colours pass straight through:
blue in, blue out; red in, red out.
Read the sketch for what it DEPICTS and draw that subject properly in this
studio's production line language — clean, manufacturable, symmetric where
the real subject is symmetric — while keeping the sketch's composition: each
element at the position and relative scale the customer gave it. Honour any
text: the same words, at the same place and relative size, in one clean
sans-serif face.`);
  }
  /* ── AND THE LAW ITSELF, IN FULL, ON EVERY PATH THAT HAS A PLAN ─────────
     This used to be two mutually exclusive branches — "the reference is a
     sketch" and "this is a refinement" — which between them missed the two
     commonest journeys in the studio: a FIRST generation from an uploaded
     picture, and a first generation from a catalogue charm. Those produced a
     prompt with no fill law in it at all, so the one instruction that
     changes the physical object was decided by whatever the model felt like.
     The plan now arrives for all four kinds of reference (the studio reads
     it off the picture when nobody has drawn one), so the law travels
     wherever the plan does.

     Not when a MARK-UP is in the request: the mark-up block below carries
     the same law with the mark-up's own — more recent, more specific — list
     beside it, and stating the law twice with two different censuses of the
     same charm is an invitation to split the difference. */
  const hasRefPlan = Array.isArray(refZones) && refZones.length > 0;
  const markupInPlay = markupMode !== undefined && markupMode !== null;
  if (!markupInPlay && (refMode === "exact" || refMode === "interpret" || refine || hasRefPlan)) {
    parts.push(FILL_LAW);
    const rz = zoneBlock(refZones, "reference");
    if (rz) parts.push(rz);
  }
  /* ── THE MARKUP CONTRACT ─────────────────────────────────────────────────
     The customer drew on the previous drawing with a mouse or a fingertip.
     Two modes, chosen by the customer in the markup studio:

       interpret (default) — every mark is a GESTURE to be read for intent.
         A hand can only approximate; the studio's job is to understand what
         the shape MEANS and draw the real thing properly.
       exact — the customer means their geometry literally; reproduce it,
         cleaned only to production line weight.

     Notes travel with their anchor points so the model can bind each
     instruction to the region it is pinned on — "make this bigger" says
     nothing without the where. Note numbers match the numbered labels baked
     into the composite image. */
  const allNotes = (Array.isArray(markupNotes) ? markupNotes : [])
    .map((n) => {
      if (n && typeof n === "object") {
        const t = studioCleanText(n.text);
        if (!t) return null;
        const x = Number(n.x), y = Number(n.y);
        const where = Number.isFinite(x) && Number.isFinite(y) ? markupRegion(x, y) : null;
        const h = Number(n.h);
        return { text: t, where, kind: n.kind === "lettering" ? "lettering" : "note",
                 h: Number.isFinite(h) && h > 0 && h < 1 ? h : null };
      }
      const t = studioCleanText(n);                     // legacy: bare strings
      return t ? { text: t, where: null, kind: "note" } : null;
    })
    .filter(Boolean).slice(0, 16);
  /* Two different things arrive as text, and confusing them ruins a charm:
     a NOTE is an instruction ABOUT the drawing and must never be drawn; a
     LETTERING item is a word the customer placed ON the charm and must be
     engraved. The drawing studio tags them apart at source. */
  const notes    = allNotes.filter((n) => n.kind !== "lettering").slice(0, 12);
  const lettering = allNotes.filter((n) => n.kind === "lettering").slice(0, 6);
  if (markupMode !== undefined && markupMode !== null) {
    const exact = String(markupMode) === "exact";
    const noteLines = notes.map((n, i) =>
      `${i + 1}. ${n.where ? `(pinned at ${n.where} of the drawing) ` : ""}"${n.text}"`).join("\n");
    const letterLines = lettering.map((n) =>
      `• "${n.text}"${n.where ? ` — placed at ${n.where} of the charm` : ""}${n.h ? `, cap height ≈ ${Math.round(n.h * 100)}% of the drawing's height — reproduce at THIS size, at THIS position, exactly as shown in the markup image` : ""}`).join("\n");
    /* the vocabulary the drawing studio can now produce, in both modes */
    const GRAMMAR =
`${FILL_LAW}
${zoneBlock(markupZones)}
WHAT THE CUSTOMER'S TOOLS MEAN:
• A FREEHAND PEN LINE's colour carries no meaning. The studio lets the
  customer draw in more than one colour purely so they can tell their own
  marks apart, and every such line is the same instruction as a black one:
  engrave it. This says nothing about AREAS — a closed shape's black, blue or
  red is governed by the law above, and a RED BOUNDARY around an empty area
  is that law's third value, not a coloured pen stroke.
• A RING (a shape with a hole in it) = a genuine cut-out — metal removed, so
  the background shows through.
• An ARROW = "this, here": read what it points AT, and treat the note nearest
  its tail as the instruction for the thing at its head.
• A rectangle or circle with a small loop on top = the charm plus its BAIL,
  the loop it hangs from.
• A dashed leader line from a label to a spot = the same as a pinned note.
${lettering.length ? `
LETTERING THE CUSTOMER PLACED ON THE CHARM — these words are part of the
charm and MUST be engraved, in the studio's ONE lettering face (a clean
sans-serif — never a serif, script or decorative face), at exactly the
position and size shown in the markup image, cut deep enough to read at
charm scale. The customer placed and sized these words deliberately; moving,
rescaling or restyling them is a defect:
${letterLines}` : ""}`;
    parts.push(exact
? `CUSTOMER MARKUP — EXACT MODE (the customer chose literal):
The final image is the customer's own hand-drawn markup ON TOP of the current
drawing. The coloured ink and the note bubbles themselves must never appear in
your output — but in THIS mode the drawn geometry is meant literally:
• A drawn SHAPE is reproduced faithfully — same geometry, position and
  proportions — converted to this drawing's own black production ink at proper
  line weight.
• A ring or highlight around existing linework still means "change this area";
  a scribble or strike THROUGH existing linework still means "remove this".

THE PRIME RULE OF EXACT MODE — CHANGE ONLY WHAT WAS MARKED:
Everything the customer did NOT mark is reproduced IDENTICALLY from the
current drawing — same lines, same weights, same positions, same proportions,
same fills and non-fills. An unrequested "improvement" is a DEFECT, not a
courtesy. In particular:
• NEVER double a line. A single outline stays ONE line — no inner or outer
  parallel lines, no rims, no borders, no halos added to any shape, marked
  or unmarked.
• NEVER restyle, thicken, thin, move or resize anything that was not marked.
• An outlined shape with NO fill stays an outline with NO fill — do not fill,
  hatch or blacken it, and do not outline a filled shape.
• LETTERING added by the customer is engraved at EXACTLY the position and
  size shown in the markup image — same spot, same cap height, one single
  clean sans-serif face. Do not move it, rescale it, reflow it or restyle it.
BEFORE RENDERING, CHECK: does every unmarked region of your output match the
current drawing stroke for stroke? If anything unmarked changed, that is
wrong — redo it.

${GRAMMAR}
${notes.length ? `PINNED NOTES — each anchored to the spot its words are about; honour every one in its own region:
${noteLines}` : ""}`
: `CUSTOMER MARKUP — HOW TO READ IT (INTERPRETED, the default):
The final image is the customer's own hand-drawn markup ON TOP of the current
drawing. It is DIRECTION, not artwork: the customer's gesture ink — pen
strokes, highlights, rings, arrows — and the note bubbles themselves must
never appear in your output. The one exception is the three INSTRUCTION
colours: a solid blue AREA, a red BOUNDARY and a solid black AREA are the
fill law speaking, not gestures, and they pass through to your drawing as
exactly what they are.

READ EVERY MARK FOR INTENT, NEVER FOR ITS LITERAL GEOMETRY — it was drawn by
hand with a mouse or fingertip, so its shape is an APPROXIMATION:
1. CLASSIFY each mark first:
   • a ring or highlight AROUND existing linework = "change this area";
   • a scribble or strike THROUGH existing linework = "remove this";
   • a drawn SHAPE in open space, or attached to the silhouette = "ADD
     something like this, here".
2. For every added shape, NAME the real object the sketch approximates. Use
   the pinned notes — especially the note nearest the sketch — and the
   conversation to decide: a rough two-lobed arc at the shoulder with a note
   saying "wings" is a WING, not a wobbly arc.
3. Then draw THAT object properly: clean, manufacturable, symmetric where its
   real counterpart is symmetric, in this drawing's own line language,
   integrated into the charm's continuous silhouette — at the sketch's
   position and roughly its scale.
4. HARD FAIL: output linework that traces, echoes or resembles the customer's
   hand-drawn path. Their wobble is input error, not design.

${GRAMMAR}
${notes.length ? `
PINNED NOTES — each anchored to the spot its words are about, numbered to
match the labels in the markup image. A note applies to the marks and the
region it is pinned on:
${noteLines}
` : ""}
BEFORE RENDERING, ANSWER INTERNALLY: (a) which areas did the customer mark?
(b) what is each mark asking — change, remove, or add? (c) what real object
does each sketched shape stand for, given the note pinned nearest to it?
(d) what does this charm look like with those intents executed cleanly, as if
the workshop's own designer had made the changes? Render THAT.`);
  }
  parts.push(STUDIO_LINEART_CONTRACT);
  return parts.join("\n\n");
}

/* ── the render step's prompt: the Charm Maker's conversion, reversed ───── */
/* ── THE CONSTRAINTS, MINUS THE BACKGROUND ────────────────────────────────
   studioConstraintBlocks() is the Charm Maker's doctrine, and the Charm Maker
   shoots on black — it carries a whole "BACKGROUND — ABSOLUTE:" section
   ("100% PURE SOLID BLACK edge to edge", "no cast shadow outside its
   silhouette", "do not begin with white and remove it"). Correct there; the
   exact opposite of what the studio render needs, which is a white ground and
   a real contact shadow.

   The filter is SECTION-aware, not line-aware: a line-by-line pass caught the
   bullets naming #000000 and left the neighbours in the same section — "no
   white, off-white, grey, studio sweep… anywhere in the background" and "no
   cast shadow" — which are the two that would have hurt most. Whole sections
   whose heading names the background go; the remaining sweep catches strays
   elsewhere. Every physical constraint is untouched, and this is a filter
   rather than a fork so the doctrine still lives in one place. */
function renderConstraintBlocks() {
  const src = String(studioConstraintBlocks() || STUDIO_FALLBACK_CONSTRAINTS);
  const isHeading = (line) => /^[A-Z][A-Z0-9 ,&/'’()—–-]{4,}:\s*$/.test(line.trim());
  const out = [];
  let skipping = false;
  for (const line of src.split("\n")) {
    if (isHeading(line)) skipping = /BACKGROUND/i.test(line);
    if (skipping) continue;
    if (/#000000/.test(line)) continue;
    if (/^\s*[•\-]\s*BACKGROUND\b/i.test(line)) continue;
    if (/\bno cast shadow\b|\bempty black margin\b|\bagainst pure black\b/i.test(line)) continue;
    out.push(line);
  }
  return out
    .join("\n")
    .replace(/,?\s*(?:and\s+)?black-background treatment/gi, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function buildLineArtToCharmPrompt({ metal, zones }) {
  const m = studioCleanText(metal) || "gold";
  const label = ({
    silver: "polished sterling silver",
    gold: "polished 14k gold",
    rose: "polished 14k rose gold",
    solid10: "polished 10k solid gold",
    solid14: "polished 14k solid gold",
  })[m] || ("polished " + m);

  /* Presentation — ground, shadow, engraving tone — is stated ONCE, in
     STUDIO_RENDER_FINISH at the end. The header used to preview it here in
     different words, and every one of those words had to be reconciled with
     the block that claimed to supersede them. */
  const header =
`APPROVED PRODUCTION DRAWING → FINISHED CHARM

Render ONE finished charm as a photorealistic flat ${label} charm. IMAGE 1 is the approved production drawing and is the only structural truth.

1:1 STRUCTURAL LOCK — HIGHEST PRIORITY
• Reproduce the drawing exactly. Do not redesign, beautify, simplify, add, remove, move or reinterpret anything.
• The outer silhouette, integrated top hoop, every hole, every engraved area, every outline-only region, every letterform and every proportion must match the drawing 1:1.
• The finished charm contains NO instruction colours: not one blue pixel, not one red pixel.

MATERIAL
• ${label}. The metal changes tone only, never form.
• One thin flat sheet, front-facing: no perspective, no visible thickness.
• The hoop's hole and every hole the drawing declares are real openings.

${FILL_LAW_RENDER}
${zoneBlock(zones, "drawing")}`;

  return header + "\n\n" + renderConstraintBlocks() +
         "\n\n" + STUDIO_RENDER_FINISH;
}

/* Normal render path after the deterministic material-spec pass. This is
   intentionally SHORTER than buildLineArtToCharmPrompt(): BLUE/RED/BLACK have
   already been resolved by code, so repeating the colour law here would put
   interpretation back into the very stage we just made deterministic. */
/* ── THREE IMAGES, THREE JOBS, NO OVERLAP ─────────────────────────────────
   IMAGE 1 says WHERE METAL EXISTS: light-grey metal, white empty.
   IMAGE 2 says HOW EXISTING METAL IS WORKED: dark engraved, light polished.
   IMAGE 3 says HOW GOLD BEHAVES: polish, specularity, edge character,
   lighting and shadow. It supplies no subject geometry.

   THE ALLOY IS NOW NAMED EVEN WHEN THE SAMPLE IS ATTACHED, and that reverses
   a deliberate earlier decision, so here is why. The old rule was "one colour
   authority, never two": with the sample attached the metal went unnamed and
   the sample owned colour outright. That is airtight reasoning about prompt
   conflict and it produced a real defect — the customer's metal choice
   reached nothing. Whatever alloy the stored sample happens to be is the
   alloy every customer receives, silver and rose alike.

   The split that fixes it is not "two opinions about colour", it is one
   opinion each about two different things: the WORDS own which alloy it is,
   the SAMPLE owns how that alloy behaves under light. Those cannot contradict
   each other because they answer different questions, and the sample is told
   in as many words that its own colour is not the subject. Replacing the
   stored sample with a correctly-coloured one is then an improvement rather
   than a prerequisite.                                                    */
/* ── THE SAME PROMPT, FOR THE COLOUR-CODED DRAWING ───────────────────────
   Identical skeleton to the greyscale builder below — itself a mirror of the
   Listing Generator's promptStrBW — with the mapping swapped for the studio's
   own fill law: black engraves, blue cuts, red outlines, white is polished.

   One case the greyscale map does not need. BLUE IS USED TWO WAYS in these
   drawings: a blue FILLED AREA is an opening, but a blue LINE is a cut EDGE —
   the outer silhouette and the hoop's ring are drawn as blue strokes with
   white inside. Reading those as openings would cut the charm's own body
   away, so it gets its own numbered case. Red is likewise always a line and
   never an area. Both are recorded failure modes in this pipeline, not
   hypotheticals.                                                           */
/* ── NO LONGER CALLED FROM ANYWHERE ───────────────────────────────────────
   This was the fallback prompt: it went out with the colour-coded production
   drawing whenever the deterministic grey-mask pass could not produce a spec,
   and it was also what the Send toggle's "Colour drawing" option selected.

   Both routes are closed. handleStudioRender now throws mask_unavailable
   rather than falling back — a prompt describing blue and red inks, sent
   with an image the customer paid a credit to have rendered, is a worse
   outcome than a refunded failure — and the toggle is off the storefront.

   Kept, not deleted, for one reason: it is the complete written statement of
   the studio's colour fill law (blue area cuts, blue line is an edge, red
   outlines, black engraves), which the drawing side of the pipeline still
   implements. It is documentation now. Nothing calls it.                  */
function buildColourDrawingToCharmPrompt({ metal, hasReference }) {
  const m = studioCleanText(metal) || "gold";
  const bare = ({
    silver: "sterling silver",
    gold: "14k gold",
    rose: "14k rose gold",
    solid10: "10k solid gold",
    solid14: "14k solid gold",
  })[m] || m;

  const second = hasReference
    ? `\n    The SECOND image is strictly a MATERIAL REFERENCE. You must NEVER copy, merge, or include the subject matter or object shown in the second image. \n`
    : "";
  const ignoreSecond = hasReference
    ? `\n    • IGNORE SECOND IMAGE SUBJECT: Do NOT add or draw the object from the SECOND image. Use the second image ONLY to understand the metal's colour, polish and lighting.`
    : "";

  return `CRITICAL INSTRUCTION: You are performing a 1:1 structural replication of the FIRST image, converting it into a photorealistic ${bare} charm.
${second}
    TASK: Generate a photograph of a real metal charm based STRICTLY on the object shown in the FIRST image. The final image must be the EXACT SAME object as the FIRST image.

    HARD CONSTRAINTS (NON-NEGOTIABLE):
    • 100% STRUCTURAL MATCH: Keep all outer perimeters, overall shape, and proportions 100% identical to the FIRST image.${ignoreSecond}
    • FILL LAW (CRITICAL — THE FIRST IMAGE'S INKS ARE INSTRUCTIONS, NOT COLOURS TO COPY):
        The FIRST image is a production drawing. Its inks tell you what to do with the metal; none of them is the colour of the finished charm. Take no colour from it. Before rendering any region, classify it:
        1. WHITE INSIDE THE CHARM — POLISHED METAL (the most common case): plain unworked sheet. Render it as bright, smooth, reflective ${bare}.
        2. BLACK FILLED AREA — ENGRAVED METAL: the sheet is unbroken and the metal is still there; only its surface has been worked. Render it as the SAME alloy in the SAME colour, told apart by finish alone — satin against mirror, the way a brushed band reads against a polished one on a single ring. NEVER render it as a different metal, a separate inlay, enamel, or a printed disc.
        3. BLUE FILLED AREA — CUT CLEAN THROUGH: the metal is ABSENT. You see the background straight through the charm, bounded by a thin bright inner cut edge where the sheet's thickness catches the light, with a small soft shadow just inside. That edge and that shadow are what prove it is open.
        4. BLUE LINE — A CUT EDGE, NOT AN OPENING: a blue STROKE with white on the inside is the boundary the metal is cut along, not a hole. The charm's outer silhouette and the hoop's ring are drawn this way. Render solid metal right up to that line and stop. Cutting away everything a blue line encloses would remove the charm itself.
        5. RED LINE — AN OUTLINE ONLY: it marks a boundary. The area it encloses is unchanged polished metal, exactly as in case 1. Never fill it, never engrave it, never cut it.
        6. THE FINGERTIP TEST: for every region ask — would a fingertip find smooth polished metal, find metal whose surface is textured but continuous, or pass straight through and touch nothing? Smooth → case 1. Textured but continuous → case 2. Nothing there → case 3.
        HARD FAIL: a blue filled area rendered as engraving, shading or a darker patch instead of an actual opening.
        HARD FAIL: a black area, a red area, or the inside of a blue LINE rendered as an opening. Metal the drawing says is there must be there.
    • MATERIAL: The whole charm is one alloy: ${bare}. Thin flat sheet metal with crisp cut edges, not a thick moulded token, and the top hoop is part of the same sheet rather than an attached jump ring.
    • BACKGROUND: A plain pure WHITE studio background with one soft contact shadow beneath the charm. Every opening cut through the metal appears in that shadow as a corresponding gap of clean white.
    • NO INVENTION: Do not add, remove, move, resize or reinterpret any geometry, and add no gemstones, borders, engraving or lettering the FIRST image does not show.`;
}

/* ── THE RENDER PROMPT. ONE TEXT, NO SUBSTITUTIONS. ───────────────────────
   This is the prompt Paul arrived at in the studio's prompt lab and asked to
   be made the default. It is stored VERBATIM — no metal name interpolated,
   no census appended, no reference-image clause switched in or out — because
   every one of those was a way for the text that shipped to differ from the
   text that was tested.

   WHY IT IS LITERALLY "14K GOLD". state.metal is fixed to "gold" for the
   whole design step; the metal pills are a checkout control and never reach
   a render. So the alloy in this prompt is not a placeholder that lost its
   variable — it is the only alloy the renderer is ever asked for. If a metal
   choice is ever added to the design step, this function is where it goes,
   and it should be a deliberate edit rather than a template that quietly
   rewrote a tested prompt.

   The parameters are kept in the signature so the two call sites do not have
   to change shape, and are deliberately unused.

   WHAT THIS REPLACED: a mirror of the Listing Generator's line-art prompt,
   inverted — same skeleton, a numbered classification of mid grey / dark
   grey / white, a fingertip test and two HARD FAILs. The failure it kept
   producing was the one the TOPOLOGY LOCK below is built around: a grey
   region that looked like it ought to be a hole — an eye, an inner counter,
   a shape paired with a real cut-out — rendered as an opening. This text
   resolves that by freezing the cut-out mask before anything is drawn and
   forbidding it to be inferred from meaning or appearance.

   The region census is still computed and still filed on the version doc; it
   is not appended here, and appending it would change the tested text.    */
/* ── THE ONE SENTENCE THAT ASSUMES WE MADE THE HOOP ────────────────────────
   Everything this workshop draws from scratch hangs from an integrated hoop
   — a flat annulus cut from the same sheet — and the MATERIAL line below
   says so, which is right for a charm the studio designed.

   It is wrong for a charm that came out of our own repository. Those are
   finished pieces with their own hanging hardware already on them, and it is
   frequently a REAL jump ring: round wire, attached, unmistakably not cut
   from the sheet. Telling the renderer that "the top hoop is part of the
   same sheet rather than an attached jump ring" asks it to contradict the
   photograph — to flatten a wire ring into an annulus, or to fuse it into
   the body — on the one pipeline where the hoop is not ours to design.

   So the sentence is swapped, and ONLY when the caller says this charm came
   from the repository. Everything else about the prompt is byte-identical,
   the swap is confined to this builder, and no other pipeline reaches it:
   the Charm Maker's own doctrine lives in studioConstraintBlocks() and is
   not consulted here, buildLineArtToCharmPrompt is a different builder for a
   path this render does not take, and the flag arrives per request rather
   than from config. The regression suite asserts each of those separately. */
const STUDIO_HOOP_INTEGRATED =
  "and the top hoop is part of the same sheet rather than an attached jump ring";
const STUDIO_HOOP_AS_FOUND =
  "and its hanging hardware is ALREADY PART OF THE PIECE in IMAGE 1 — " +
  "reproduce it exactly as it appears there, whether it is a flat integrated " +
  "hoop or a separate round jump ring. Do not add a hoop, do not remove one, " +
  "do not re-form one into the other, and do not add a second ring, bail or chain";

/* ── THE OUTLINE FAILURE, AND WHY IT NEEDED ITS OWN BLOCK ─────────────────
   Measured on an astronaut charm. The map drew a figure floating: tilted,
   one arm raised into a fist, the legs bent and tucked. The render came back
   as a textbook standing astronaut — upright, arms down, feet apart. Correct
   subject, correct alloy, correct finish, correct hoop, and the wrong shape.

   The numbers say it is not drift and not a bad fit. The two silhouettes
   share a bounding box to within a few per cent and their principal axes
   differ by 3.6°, so nothing was rotated or rescaled; the render simply
   carries 27.5% MORE metal inside that same box, and its solidity — the
   share of its own convex hull it fills — went from 0.819 to 0.875. The
   model did not move the outline. It FILLED IN the negative space: the gap
   under the raised arm, the gap between the bent legs. Best-fit silhouette
   IoU 0.731 against the 0.977-0.984 a good render scores.

   Nothing in the prompt defended against that. TOPOLOGY LOCK is entirely
   about FILL — which greys stay metal, which whites go empty — and it was
   obeyed. FILL-PRIORITY says IMAGE 1's fill "overrides every outline and all
   familiar meaning", which reads as a rule about interiors, and the only
   sentence covering the boundary was one clause of NO INVENTION at the very
   end. So the model was told to treat the map as pixels, recognised an
   astronaut anyway, and drew the astronaut it knows.

   This block names that failure, says it is a failure even when the result
   looks better, and gives it its own verification step. It ADDS; it changes
   no existing sentence, and removing the one interpolation below reverts it.

   It also names IMAGE 3. Three images are sent — topology, structure and the
   gold sample — and the prompt described two, leaving the third with no
   declared role at all. The Charm Maker's prompt has carried an explicit
   image-role lock for exactly this reason since the day a style reference's
   subject turned up in an output.                                          */
/* ── SHORTER, NOT LONGER ──────────────────────────────────────────────────
   Two whole blocks were added to this prompt in one week — a silhouette lock
   and an output-frame lock — each written after a specific bad render, each
   several hundred words, and the renders got stranger rather than steadier.
   That is the expected direction, and it is worth writing down so nobody
   adds a third block the next time one goes wrong.

   AN IMAGE MODEL IS NOT AN INSTRUCTION FOLLOWER WITH A LONGER ATTENTION
   SPAN. Three things go wrong as this text grows:
     · Salience is a budget. Twenty rules do not each get the weight one rule
       gets; the fill law, which is the only thing that must never be missed,
       competes with a paragraph about captions.
     · A negation names its subject. "Do not draw IMAGE 1" puts IMAGE 1 in
       the frame's vocabulary — and the render that prompted the frame lock
       came back with the words "IMAGE 1" lettered into the picture. Every
       extra mention raises the odds of the thing it forbids.
     · The API documents no seed and no temperature, so each render is an
       independent draw. Wording moves the distribution; it cannot truncate
       the tail. The tail is what the customer is complaining about.

   So the rules that survive here are the ones that shape the CENTRAL case,
   said once, positively, in as few words as carry them. The tail is not
   argued with — it is measured and re-rolled, deterministically, by the
   gates in studioCompositeOpenings. Every failure that produced a paragraph
   above now has a number instead:
     wrong shape        silhouette IoU        0.98 good / 0.75 bad
     contact sheet      stray content         0.01 good / 0.61 bad
     two-tone metal     off-alloy share       0.01 good / 0.39 bad
   A number does not dilute anything else in the prompt, cannot be argued
   with by a sampler, and costs nothing per render.

   THE RULE FOR EDITING THIS: if a bad render suggests new prompt text, first
   ask whether the same failure can be measured. If it can, measure it. Text
   is for the rules that decide what a good charm IS; the gates are for
   catching when the model did not make one.                                */
function buildMaterialSpecToCharmPrompt(opts) {
  /* strict true in the builder as well as at the call site: a truthy string
     arriving from somewhere unexpected must not quietly drop the hoop rule
     for a charm the studio drew itself */
  const hoop = (opts && opts.builtInHoop === true) ? STUDIO_HOOP_AS_FOUND : STUDIO_HOOP_INTEGRATED;
  /* ── SEVEN BLOCKS INTO FOUR, WITH EVERY INSTRUCTION STILL IN IT ───────────
     Nothing was decided to be unnecessary. What came out was RESTATEMENT, and
     restatement is what dilutes: sixteen distinct rules were being carried by
     twenty-three sentences, so the fill law — the one rule that must never be
     missed — was competing for salience with two paraphrases of itself.

     Three ideas were each said three times and are now said once:
       · "not a recognizable object" / "overrides all familiar meaning" /
         "if you recognise what it depicts" — one idea, kept in the form that
         tells the model what to DO about it.
       · the legend's WHITE = EMPTY / "every grey stays opaque, only white is
         empty" / "OUTPUT CUT-OUT MASK = IMAGE 1 WHITE MASK, exactly" — the
         equation was a third phrasing of the clause above it, not a stronger
         one, and an equation invites arithmetic rather than looking.
       · NO INVENTION's "do not add, remove, move, resize or reinterpret any
         geometry, and add nothing IMAGE 1 does not already contain" against
         "exclusive authority" and "traced, not interpreted" — the verbs are
         kept, the block they sat in is not.

     Two headings also went, and headings are not free: each one announces a
     new topic and spends attention on the announcement. Four blocks — what it
     is, trace it, what it is made of, what the picture looks like — is the
     whole instruction set with no section that exists only to be a section.

     The count, for the next person tempted to add a paragraph: 1,652 chars to
     1,346, and all sixteen rules verifiable one by one against the old text.
     See SHORTER, NOT LONGER above for why that direction is the right one.

     ONE RULE ADDED SINCE, AND THE FIRST ATTEMPT AT IT BROKE THE CUTTING.
     A swallow came back with its head, flank and tail band sunk as broad
     recesses because the model read each closed engraved OUTLINE as the edge
     of a pocket to hollow out — 17.6% of the map engraved against 32.9% of
     the render, at three times the map's own stroke thickness. Nothing here
     forbade it: every other line about engraving is about its TONE.

     THE FIRST FIX WAS WORSE THAN THE FAULT. To pay for the new paragraph out
     of the block's own length, a clause was deleted from TRACE as "duplicate"
     — "every grey region stays opaque gold and only the white regions are
     empty". It is not duplicate. The ladder line above it is a LEGEND, a
     glossary entry that names the tone; that clause was the only IMPERATIVE
     in the whole prompt telling the renderer that white is cut through.
     Deleting it, lowercasing "WHITE = EMPTY", and putting an ALL-CAPS
     engraving headline in the slot where it had been left a prompt whose
     single loudest instruction was about engraving and which no longer asked
     for a hole anywhere. Three renders in a row came back with every opening
     solid, and the compositor cut all of them — which is also why their
     alignment became the next complaint.

     SO THE BLOCK IS THE ORIGINAL, VERBATIM, plus one clause inside MATERIAL
     where engraving was already being discussed. Not a headline, not a
     paragraph, and not in front of anything: 1,277 chars to 1,441, every
     original sentence present unchanged, one ALL-CAPS heading as before, and
     both mentions of white-as-empty back where they were.

     THE LESSON, FOR THE NEXT PERSON SHORTENING THIS: SHORTER, NOT LONGER is
     about padding, not about rules, and a sentence is not duplicate because
     another sentence contains the same word. Diff the imperatives, not the
     vocabulary. The enforcement for the engraving rule is scoEngraveFill,
     because a rule in a prompt is a request; see the note there.

     AND THEN THE CUT CLAUSE WAS STRENGTHENED ON PURPOSE, against Google's
     own published guidance for this model family. Three rules from it apply
     here and the old clause broke all three:

       · NAME THE OPERATION WITH A VERB. The guide's first rule is to open
         with a strong verb naming the primary operation. "Cut" appeared
         NOWHERE in this prompt as a verb — only as the noun "through-cut"
         and the adjective "crisp cut edges". The one operation the renderer
         kept failing at was the one operation never asked for.
       · SAY WHAT IS THERE, NOT WHAT IS ABSENT. "empty street", not "no
         cars". "Only the white regions are empty" is a restriction, and it
         asks for an absence — the hardest thing to render. It is now an
         instruction to cut, and what fills the hole is named: the white
         ground behind the charm, and a bright bevel on the sheet's edge.
         That is the guide's own cut-out pattern, which works by describing
         what is VISIBLE through the opening rather than the opening itself.
       · A LEGEND IS NOT AN INSTRUCTION. "WHITE = EMPTY" is a glossary
         entry, and the guide is explicit that a list of keywords is not
         enough on its own. It stays, because it is compact and the other
         two tones are served by it, and the white case now has a narrative
         sentence behind it as well.

     The clause was strengthened IN PLACE — same paragraph, same position —
     because the last edit's damage came as much from moving and re-ranking
     instructions as from deleting one. 1,277 chars to 1,748; the length
     discipline above is about padding, and none of this is padding.

     HOW TO TELL WHETHER IT WORKED, without waiting for a customer:
     renderModelCutShare on the version doc is the share of declared
     openings the model cut itself. 1.0 is a clean render; 0.0 means every
     hole in the picture was cut by code. The three renders that prompted
     this were 0.0. There is a console warning on that case too. */
  return `PRIMARY OPERATION — MATERIAL TRANSFER ONLY

Transform IMAGE 1 into a photorealistic 14K gold charm. It is a pixel-level manufacturing map and the exclusive authority for the silhouette, every through-cut and every worked surface: WHITE = EMPTY; LIGHT GREY = smooth unengraved metal; DARK GREY = shallow recessed engraving.

TRACE, DO NOT INTERPRET: every grey region stays opaque gold, and every white region enclosed by grey is CUT clean through the sheet — a real opening, with the white ground behind the charm showing through it and a bright bevel where the sheet's own thickness catches the light. Cut every one of them, whatever their size or number, and never stand one in with engraving, shading, tinted metal or filled gold. Every notch, concavity, asymmetry and tilt of the outer boundary is the design. If you recognise what IMAGE 1 depicts, draw the map you were given rather than the tidier, more symmetrical version you remember, and add, remove, move or resize nothing — a better-looking charm with a different outline is a failed render.

MATERIAL: ONE alloy across the whole piece — 14K gold, thin flat sheet with crisp cut edges, not a thick moulded token, ${hoop}. An engraved area is the SAME gold as the polish beside it, only slightly darker and warmer — its brightness is 0.85 of the polished metal beside it, and never below 0.75; IMAGE 1's greys are a classification code and must never reach the output as colour. Engrave the dark grey pixels themselves and no more: a dark grey line is a line, and the light grey it encloses stays polished rather than becoming a sunken field.

FRAME: one charm, alone and centred, on a plain pure WHITE ground with a single soft contact shadow beneath it. The attached images are read, never drawn: no copy of them, and no lettering, appears anywhere in the picture.`;
}

/* ═══════════ HOW THE CUSTOMER'S CHARM IS PRESENTED ═══════════════════════
   Two things were wrong with it, and both are the kind of wrong that makes
   a real object look like a picture of one.

   THE ENGRAVING WAS TOO DARK. Engraving does not change what metal IS; it
   changes how the surface catches light. A recess in polished gold reads as
   a slightly deeper, warmer, more coppery gold — not as brown, not as
   bronze, and never as a separate material inlaid into the piece. It was
   coming back nearly black in places and heavily grained, which reads as
   fake at a glance because no jeweller's laser leaves that.

   AND IT SAT ON BLACK. A charm floating on pure black with no shadow is a
   cut-out; it tells the customer nothing about the object's weight, its
   thickness, or — crucially — where the holes are. A real shadow does, and
   the holes in the shadow are the proof that the cut-outs are cut. */
const STUDIO_RENDER_FINISH =
`PRESENTATION — THIS SUPERSEDES EVERY EARLIER INSTRUCTION ABOUT THE
BACKGROUND, THE SHADOW AND THE ENGRAVING TONE. Where anything above
disagrees with this block, THIS BLOCK WINS.

BACKGROUND AND SHADOW:
• The charm rests on a clean, seamless, pure WHITE studio ground plane — not
  black, not grey, not a gradient, not a vignette, not a reflection. Plain
  white, edge to edge.
• It casts ONE real, physically plausible contact shadow onto that plane:
  soft-edged, short, close under the piece, slightly darker and tighter
  where the metal meets the ground and diffusing outward. A single soft key
  light from the upper left, so the shadow falls gently to the lower right.
  THE SHADOW IS REQUIRED. A charm sitting on white with no shadow reads as a
  cut-out pasted onto a blank page, not as a photographed object, and is an
  incomplete image.
• AN OPENING IS A PHYSICAL EVENT, NOT A DARKER PATCH. You see the white ground
  straight through it, bounded by a thin bright inner cut edge where the
  sheet's thickness catches the light, with a small soft shadow just inside.
  That edge and that shadow are what prove it is open. Filled, tinted,
  recessed, sculpted or merely shaded is the worst failure in this render.
• THE SHADOW IS A TRUE SILHOUETTE OF THE CHARM AND OF NOTHING ELSE. Every
  opening cut through the metal — the hoop's hole and every cut-out in the
  design — appears in the shadow as a corresponding gap of clean white.
  Light passes through a hole; a shadow with the hole missing is the single
  clearest sign of a render that has not understood the object. Count the
  openings in the charm and count them again in the shadow.
• No drop shadow effect, no glow, no outline, no floor line, no horizon, no
  props, no hand, no chain, no packaging.

ENGRAVED SURFACES — THE ONE THING THIS RENDER GETS WRONG MOST OFTEN IS
ENGRAVING RENDERED TOO DARK. Every line below is a CEILING, not a target:
• An engraved area is the SAME GOLD as the polish beside it. What changes is
  the FINISH, not the colour — satin where the rest is mirror, like brushed
  and polished bands on one ring. The polished metal stays bright and
  specular; the contrast between the two comes from finish and the gentlest
  tonal shift, never from a change of colour.
• Converted to greyscale, an engraved area sits no more than about one-eighth
  darker than the polished metal touching it, and that is a CEILING — closer is always better,
  further apart is always wrong. Brown, bronze, copper, grey, charcoal or black
  is wrong, and so is any recess that reads as a dark shape, a separate inlay
  or a second alloy rather than as the same worked gold.
• If the engraving is the first thing the eye lands on, or if it could be
  mistaken for a hole, it is far too dark. Err lighter every time.
• DEPTH IS SUPERFICIAL. A shallow, delicate skim of the surface — never a
  deep carve, a trench, a chisel cut, or anything with visible walls or
  strong internal shadow.
• EVEN EVERYWHERE. Every engraved area the same tone and the same depth as
  every other. Blotches, patches, or gradients within one area are wrong.
• TEXTURE BARELY THERE. A faint, fine, even micro-texture — the trace of a
  laser, visible only on inspection. Coarse grain, heavy hatching, stippling,
  brushed streaks or any woven look is wrong, and is the main thing that
  makes a render look artificial. When in doubt, less.

FINAL CHECK ON THIS BLOCK: white ground; one soft contact shadow; every
opening present as white inside that shadow; every declared opening a real
hole rather than metal; and every engraved area so close in tone to the
polish that no one could mistake it for a hole — shallow, even everywhere,
texture barely there.`;

function buildCustomerCharmPrompt({ instructions, thread, metal, refine }) {
  const clean = studioCleanText(instructions);
  const log = (Array.isArray(thread) ? thread : [])
    .filter((m) => m && m.text)
    .slice(-24)
    .map((m, i) => `${i + 1}. ${m.role === "studio" ? "STUDIO" : "CUSTOMER"}: ${studioCleanText(m.text)}`)
    .filter((line) => line.split(": ").slice(1).join(": ").length > 0)
    .join("\n");

  const header =
`CUSTOMER-DIRECTED CHARM DESIGN — TRANSLATE, DON'T INVENT

The supplied image is the customer's chosen reference. Translate its subject
faithfully into this workshop's flat laser-cut charm language, then apply ONLY
the customer's requested changes:

CUSTOMER INSTRUCTIONS: ${clean || "(no change requested — translate the reference faithfully)"}
REFERENCE HANDLING: keep the recognizable subject and proportions; changes
beyond the instructions are forbidden.

• OUTER CONTOUR BRIEF: follow the reference subject's own recognizable silhouette, simplified into one bold, clean, manufacturable outline.
• ENGRAVING BRIEF: use only sparse, recognition-critical surface engraving — the few lines that make the subject read at charm size.
• INTENTIONAL CUTOUT BRIEF: use negative-space cutouts where they improve recognition or visual appeal; otherwise use none.`;

  const parts = [header];
  if (log) {
    parts.push(
`CUSTOMER DIRECTION LOG — the full conversation so far, oldest first.
Honour all of it; the last line is the newest request:
${log}`);
  }
  if (refine) {
    parts.push(
`REFINEMENT PASS: the second image is the customer's current version of this
charm. Keep it and change ONLY what the newest instruction asks for.`);
  }
  if (metal) {
    parts.push(`METAL: render in ${studioCleanText(metal)}. Metal choice affects tone only — never form.`);
  }
  parts.push(studioConstraintBlocks() || STUDIO_FALLBACK_CONSTRAINTS);
  return parts.join("\n\n");
}

/* ── the intake check ────────────────────────────────────────────────────
   Text only, no image output, no credit. The rejection reason is customer
   copy, so it is written in the studio's voice — and the word "AI" appears
   nowhere in it (design guide §9.7). */
const STUDIO_PRECHECK_PROMPT =
`You are the intake check for a handmade jewellery workshop that cuts flat metal charms.
Judge the attached photograph against these questions and answer with JSON only.

1. Is there ONE clear, identifiable main subject?
2. Can that subject be reduced to a flat silhouette with an integrated hanging hoop and still be recognisable?
3. Is it free of identifiable people and faces?
4. Is it free of minors, nudity and sexual content?
5. Is it free of obvious third-party trademarks, logos and licensed characters?
6. Is it sharp and well-lit enough to read the subject's outline?

Answer with exactly this shape and nothing else:
{"usable": true|false, "reason": "<one warm sentence, max 22 words, addressed to the customer, explaining what to try instead>", "subject": "<2-4 words>"}

Rules for "reason": only fill it when usable is false. Never mention models,
generation, prompts or automated checking. Never use the word "AI". Suggest a
concrete alternative, e.g. "A single pet in clear daylight works beautifully —
try a photo where the whole outline is visible."`;

async function studioVisionVerdict(img) {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) throw new Error("Missing GEMINI_API_KEY env var");
  const model = String(
    process.env.GEMINI_STUDIO_PRECHECK_MODEL ||
    process.env.GEMINI_CHARM_PREFLIGHT_MODEL ||
    DEFAULT_TEXT_MODEL
  ).trim();
  let mime = img?.mime || "image/jpeg";
  if (!String(mime).startsWith("image/")) mime = "image/jpeg";

  const resp = await fetch(`${GEMINI_BASE}/models/${model}:generateContent`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "x-goog-api-key": apiKey },
    body: JSON.stringify({
      contents: [{
        role: "user",
        parts: [
          { text: STUDIO_PRECHECK_PROMPT },
          { inline_data: { mime_type: mime, data: Buffer.from(img.buffer).toString("base64") } },
        ],
      }],
      generationConfig: { temperature: 0, responseMimeType: "application/json" },
    }),
  });
  const data = await readUpstreamJson(resp, "gemini");
  const text = (data?.candidates?.[0]?.content?.parts || [])
    .map((p) => p?.text || "").join("").trim();
  const parsed = extractJsonObject(text);
  if (!parsed) return { usable: false, reason: "" };
  return parsed;
}

/* ═══════════ THE ADJUDICATOR ═════════════════════════════════════════════
   Everything before this point tries to make the render come out right. This
   is the first thing that CHECKS whether it did, and it exists because the
   failure it catches cannot be caught any other way.

   The cut check beside it is geometric: it measures pixels against the
   drawing and can say "this declared opening came back solid". It cannot say
   "this render is a two-panel diptych with a caption", or "there is a second
   charm", or "the engraving is bronze", because none of those are
   registration failures — they are the render answering a different question
   entirely, and the pixels it produces are internally consistent. Those are
   the ones that reach a customer looking obviously wrong, and only something
   that can LOOK at both pictures can tell.

   So: the deterministic greyscale map and the finished gold charm go to a
   vision model together, with the same fill law the render prompt was given,
   and it scores the realisation in six named categories. The score decides
   whether the render ships or gets rolled again.

   TWO WAYS TO FAIL, deliberately. A weighted total catches the render that
   is slightly wrong everywhere. Per-category floors catch the render that is
   excellent everywhere except in the one way that makes it unusable — a
   diptych scores well on geometry, engraving and tone, and its average would
   sail past any single threshold. `fidelity` is what kills it.

   IT CAN NEVER FAIL A RENDER. A judge that errors, times out or answers
   nonsense returns null, and null means "accepted": the customer has already
   paid, and a charm nobody scored is infinitely better than no charm. The
   worst this can do is spend more model calls than it needed to.

   OFF IN ONE VALUE: config/customStudio → renderAdjudicate: "off". See the
   note beside that key for what each mode does.
   ═══════════════════════════════════════════════════════════════════════ */
const STUDIO_SCORE_KEYS = ["geometry", "cutouts", "engraving", "fidelity", "tone", "presentation"];

/* WHAT MATTERS MOST, AS NUMBERS. Geometry and cut-outs are the shape of the
   object the customer is buying and together carry over half the score;
   fidelity is third because an invented detail is a lie about the product.
   Tone and presentation are real but recoverable — a slightly dark engraving
   is a worse photograph of the right charm, not the wrong charm. */
const STUDIO_SCORE_WEIGHTS = Object.freeze({
  geometry: 28, cutouts: 24, engraving: 18, fidelity: 16, tone: 8, presentation: 6,
});
/* THE FLOORS ARE NOT THE WEIGHTS. A floor asks a different question: not
   "how much does this contribute" but "how bad is too bad, whatever else is
   right". Fidelity's floor is high because there is no acceptable amount of
   fabricated detail; tone's is low because engraving a shade dark is a
   disappointment and not a defect.

   ── SET AGAINST THE PASS MARK, WHICH IS NOW 80 ──────────────────────────
   Geometry and cut-outs came down from 90 and 85, engraving from 80 to 75.
   They were written when the mark was 95 and were calibrated to it, so
   leaving them where they were while the mark dropped would have moved the
   whole decision onto the floors without anybody choosing that: a charm
   totalling 89 was still rejected on a geometry of 88, and the lower mark
   would have changed nothing except the number printed on the panel.

   The scale the judge is given is what these are pinned to. Its own words:
   95 is "a jeweller comparing the two would find nothing to correct", 85 is
   "clearly the right charm with one visible discrepancy", 60 is
   "recognisably related but wrong in a way a customer would notice". A
   floor is the "customer would notice" line, not the "jeweller would
   correct" line — the second is a standard for a re-roll, and re-rolls cost
   two more image calls and a slower page for a charm that was sellable.

   FIDELITY DOES NOT MOVE. It is not a quality scale: the prompt makes any
   invented element score 20 or below and anything that is not one single
   charm 10 or below, so this floor is a switch, and there is no amount of a
   second charm or a caption that ships. Tone and presentation do not move
   either — they were already set below the mark and mean what they meant. */
const STUDIO_SCORE_FLOORS = Object.freeze({
  geometry: 80, cutouts: 80, engraving: 75, fidelity: 90, tone: 70, presentation: 70,
});

/* The judge is shown the SAME fill law the renderer was given — the exact
   three tones out of studioMaterialSpec — so it is checking the contract
   that was actually issued rather than a paraphrase of it. If the render
   prompt's vocabulary ever changes, this changes with it. */
/* ── THE JUDGE HAS TO BE TOLD THE SAME THING THE RENDERER WAS ────────────
   The render prompt's hoop sentence is swapped per request on `builtInHoop`,
   and this prompt's geometry rule was not: it told the judge to "penalise a
   hoop that has become a separate attached jump ring rather than part of the
   same sheet" on EVERY render. On a repository charm whose real jump ring
   the renderer had just been told to reproduce as found, a faithful render
   was therefore marked down for being faithful — and with renderAdjudicate
   shipping as "enforce" and renderScoreRetries at 2, it could buy two more
   renders to make the charm less correct.

   Same flag, same strict true, same shape as the render prompt: one clause,
   two spellings, everything either side byte-identical. */
const STUDIO_ADJ_HOOP_INTEGRATED =
  "and a hoop that has become a separate attached jump ring rather than part " +
  "of the same sheet";
const STUDIO_ADJ_HOOP_AS_FOUND =
  "and any change to the hanging hardware, which is already part of this piece " +
  "and must be reproduced as it appears rather than re-formed into a flat " +
  "integrated hoop";
/* ── WHAT IS ADDED WHEN THE FIRST ASK CAME BACK MALFORMED ────────────────
   Appended only on the second ask, and it says what was wrong rather than
   repeating the format for its own sake: a model that produced prose, or an
   object missing a score, has already read the format once and needs to be
   told which part of it it broke. Nothing about the CHARM changes — the
   judgement being asked for is identical, so a repaired answer is the same
   verdict correctly shaped, not a second opinion. */
const STUDIO_ADJ_REPAIR = {
  no_object:
    "\n\nYOUR PREVIOUS REPLY CONTAINED NO JSON OBJECT. Answer again with the " +
    "JSON object described above and nothing else — no prose before it, no " +
    "explanation after it, no code fence.",
  unparsable:
    "\n\nYOUR PREVIOUS REPLY WAS NOT VALID JSON. Answer again with the JSON " +
    "object described above and nothing else. Check that every string is " +
    "quoted, every brace is closed, and there is no trailing comma.",
  incomplete:
    "\n\nYOUR PREVIOUS REPLY WAS MISSING ONE OR MORE OF THE SIX SCORES. All " +
    "six of \"geometry\", \"cutouts\", \"engraving\", \"fidelity\", \"tone\" and " +
    "\"presentation\" must be present and must each be a number from 0 to 100. " +
    "An answer missing one is discarded whole.",
};
function buildStudioAdjudicatePrompt(opts) {
  const hoop = (opts && opts.builtInHoop === true)
    ? STUDIO_ADJ_HOOP_AS_FOUND : STUDIO_ADJ_HOOP_INTEGRATED;
  const base = STUDIO_ADJUDICATE_PROMPT.replace("${HOOP_RULE}", hoop);
  const repair = opts && opts.repair ? STUDIO_ADJ_REPAIR[opts.repair] : "";
  return repair ? base + repair : base;
}
const STUDIO_ADJUDICATE_PROMPT =
`You are the final quality check in a workshop that laser-cuts flat 14K gold charms.

You are given two pictures of the SAME charm.

IMAGE A — STRUCTURE_MAP. A deterministic greyscale manufacturing map produced by
code, not by a model. It is THE SPECIFICATION. Its three tones are exact:
• WHITE (255) — NOT METAL. Either outside the charm, or a through-cut opening:
  a hole with the background visible straight through it.
• LIGHT GREY (176) — SOLID METAL, polished smooth, unengraved.
• DARK GREY (136) — SOLID METAL, shallow engraved recess. Still the same gold,
  only worked.

IMAGE B — the rendered photograph of the finished 14K gold charm. Judge it.

Score each category from 0 to 100 for how faithfully IMAGE B realises IMAGE A.
Calibrate strictly: 95 means a jeweller comparing the two would find nothing to
correct. 85 means clearly the right charm with one visible discrepancy. 60 means
recognisably related but wrong in a way a customer would notice. Below 40 means
the render did not follow the map.

1. "geometry" — outer silhouette and proportion. Does the outline of the metal
in B match the outline of all non-white area in A: the same shape, the same
aspect ratio, the hanging hoop in the same place and the same relative size,
every feature where the map puts it? Penalise drift, added or removed lobes, a
changed aspect ratio, \${HOOP_RULE}.

2. "cutouts" — the WHITE-inside-the-charm rule, and the one most often broken.
Every white region enclosed by metal in A must be a real hole in B, with the
background visible through it and a bright cut edge where the sheet's thickness
catches the light. Penalise heavily any opening rendered instead as engraving,
as a dark patch, as a recess, as tinted or shaded metal, or filled solid.
Penalise just as heavily any hole in B that is NOT white in A — metal removed
that should be solid. Count the openings in A, then count them in B.

3. "engraving" — DARK GREY coverage and placement. Every dark region in A must
be visibly engraved in B at full coverage, including regions that touch the
outer edge or cover most of the charm. Every light-grey region must be smooth
polished metal. Penalise engraving that stops short of its region, spreads
beyond it, appears where A is light grey, or is missing altogether.

4. "fidelity" — NO INVENTION. Does B contain anything at all that is not in A?
This is the most serious failure here even when everything else is perfect.
Look for: a second charm, a duplicate, a mirrored or split panel, a diptych,
side-by-side or before-and-after halves, any label, caption, watermark, letter
or number, a chain, a hand, a prop, packaging, a border, a frame, gemstones,
added ornament, engraved lines the map does not contain, or a second background.
Any one of those makes this score 20 or below. If the picture is anything other
than ONE single charm photographed once, this score is 10 or below.

5. "tone" — material and engraving colour. The whole charm is ONE alloy: warm
yellow 14K gold. An engraved area is THE SAME GOLD and differs only in finish —
satin against mirror — sitting, in greyscale, at most about a fifth darker than
the polished metal beside it. Penalise engraving rendered brown, bronze, copper,
grey, charcoal or black; any recess dark enough to be mistaken for a hole; any
second metal, inlay, enamel, paint or patina; silver, rose or white gold; and
heavy grain, coarse hatching or a woven texture.

6. "presentation" — a plain pure white seamless ground and ONE soft contact
shadow beneath the charm, with every opening appearing in that shadow as a gap
of clean white. Penalise a black, grey, gradient or textured ground; no shadow;
a drop-shadow effect, glow or outline; a floor line or horizon; and a shadow
with the holes missing.

FIRST COUNT, THEN SCORE. Before any score, fill in "observations" by actually
looking at the two pictures. These are facts, not opinions, and the workshop
checks your scores against them — a score that contradicts your own
observations is discarded. Count the enclosed white regions inside the charm
in IMAGE A, then count the real holes in IMAGE B, and say how many separate
charms are visible in IMAGE B.

COUNT THE WAY THE WORKSHOP COUNTS, because your count is marked against a
machine count of IMAGE A made with these exact rules:
• SEPARATE means not touching. Two regions joined by even a thin channel of
  the same tone are ONE region; two regions divided by metal are TWO. A
  cluster of engraved lines that touch one another is ONE engraved region.
• Small still counts. A droplet, a slot, a gap between two shapes — if it is
  an enclosed patch of white you can plainly see, it is an opening. Do not
  fold small openings into a neighbour or skip them as detail.
• Only white ENCLOSED by metal is an opening. White outside the silhouette is
  the backdrop, never an opening — but white reaching INTO the charm through
  a mouth in the outline is still backdrop, not a hole.
Trace the charm once, region by region, and count as you go; do not estimate
the total from a glance.

Answer with EXACTLY this JSON and nothing else:
{"observations":{"charmsVisible":1,"openingsInSpec":0,"openingsInRender":0,
  "engravedRegionsInSpec":0,"engravedRegionsInRender":0,
  "groundIsWhite":true,"shadowPresent":true,
  "describeRender":"what IMAGE B actually shows, 8-20 words"},
 "geometry":0,"cutouts":0,"engraving":0,"fidelity":0,"tone":0,"presentation":0,
 "fabricated":["each invented element, 2-6 words; empty array if none"],
 "worst":"the single biggest discrepancy, at most 18 words"}

Judge only what you can see, and do not be generous. A score of 100 asserts
that a jeweller could find NOTHING to change; almost no render earns it, and
one that contradicts your observations will be thrown out. If the two pictures
match well but not perfectly, the honest answer is in the 80s or low 90s.`;

/* One vision call. Never throws — a judge that cannot answer must not be able
   to cost a customer their charm. */
async function studioAdjudicateOnce(specBuf, goldBuf, cfg, opts) {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) return { raw: null, model: "", text: "", why: "no_api_key" };
  /* ── WHICH MODEL IS DOING THE JUDGING ─────────────────────────────────
     This mattered more than it looks. The chain used to end at
     DEFAULT_IMAGE_MODEL — an image GENERATION model. Asking one of those
     for a JSON critique is the wrong tool, and it is exactly the sort of
     thing that answers with a filled-in template rather than a judgement;
     it ends at DEFAULT_JUDGE_MODEL now — the pro model, because this is
     the one reading job whose answers are marked against a machine count
     and thrown out when they miss. config/customStudio still wins so the
     model can be changed without a deploy, and whichever one answered is
     written onto the version document, so "what judged this render" is
     never a guess again. The -image warning below stays: the default can
     no longer trip it, but an override still can — and it tests the same
     spelling the audit distrusts, previews included, so an override can
     never be distrusted silently with nothing in the log. */
  const model = String(
    (cfg && cfg.renderScoreModel) ||
    process.env.GEMINI_STUDIO_JUDGE_MODEL ||
    process.env.GEMINI_STUDIO_PRECHECK_MODEL ||
    DEFAULT_JUDGE_MODEL
  ).trim();
  if (/-image(-preview)?$/.test(model)) {
    console.warn(`[studio] adjudicator is pointed at "${model}", an image-generation ` +
                 `model. Set renderScoreModel on config/customStudio (or ` +
                 `GEMINI_STUDIO_JUDGE_MODEL) to a text model, or its verdicts are ` +
                 `not worth acting on.`);
  }
  try {
    const resp = await studioFetchWithTimeout(`${GEMINI_BASE}/models/${model}:generateContent`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-goog-api-key": apiKey },
      body: JSON.stringify({
        contents: [{
          role: "user",
          parts: [
            { text: buildStudioAdjudicatePrompt(opts) },
            { text: "IMAGE A — STRUCTURE_MAP (the specification):" },
            { inline_data: { mime_type: "image/png", data: Buffer.from(specBuf).toString("base64") } },
            { text: "IMAGE B — the rendered 14K gold charm (judge this):" },
            { inline_data: { mime_type: "image/png", data: Buffer.from(goldBuf).toString("base64") } },
          ],
        }],
        generationConfig: { temperature: 0, responseMimeType: "application/json" },
      }),
    }, STUDIO_JUDGE_TIMEOUT_MS, "render adjudicator");
    const data = await readUpstreamJson(resp, "gemini");
    const text = (data?.candidates?.[0]?.content?.parts || [])
      .map((p) => p?.text || "").join("").trim();
    /* THE REPLY IS KEPT, WHATEVER IT IS. When the scores looked wrong there
       was no way to tell a model that had judged badly from one that had not
       judged at all, because the only thing anybody could see was the six
       numbers that came out the far end. The raw text is filed on the
       version document now, truncated, so that question is one look away. */
    let raw = null;
    try { raw = extractJsonObject(text); }
    catch (e) { return { raw: null, model, text, why: "unparsable" }; }
    /* ── A CALL THAT SUCCEEDED IS NOT AN ANSWER THAT ARRIVED ─────────────
       extractJsonObject either throws or returns whatever JSON.parse gave
       it — and `null`, `0` and `false` are all valid JSON. A reply of the
       four characters "null" therefore came back here as {raw:null,
       why:""}: no reason, no retry, and the caller reported it as the
       vague "unusable answer" that told nobody anything. If there is no
       object, say so where the retry logic can see it. */
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
      return { raw: null, model, text, why: "no_object" };
    }
    return { raw, model, text, why: "" };
  } catch (e) {
    console.error("[studio] adjudicator call failed:", e?.message || e);
    return { raw: null, model, text: "", why: String(e?.message || e).slice(0, 120) };
  }
}

/* Turns the model's six numbers into a decision. Kept separate from the call
   so the arithmetic can be tested without a network. */
function studioScoreVerdict(raw, cfg) {
  if (!raw || typeof raw !== "object") return null;
  const num = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? Math.max(0, Math.min(100, Math.round(n))) : null;
  };
  const cats = {};
  for (const k of STUDIO_SCORE_KEYS) {
    const v = num(raw[k]);
    if (v === null) return null;            /* an incomplete answer is no answer */
    cats[k] = v;
  }
  const weights = Object.assign({}, STUDIO_SCORE_WEIGHTS, (cfg && cfg.renderScoreWeights) || {});
  const floors  = Object.assign({}, STUDIO_SCORE_FLOORS,  (cfg && cfg.renderScoreFloors)  || {});
  let sum = 0, wsum = 0;
  for (const k of STUDIO_SCORE_KEYS) {
    const w = Number(weights[k]);
    if (!Number.isFinite(w) || w <= 0) continue;
    sum += cats[k] * w; wsum += w;
  }
  const total = wsum ? Math.round(sum / wsum) : 0;
  /* The fallback here and STUDIO_CFG_DEFAULTS.renderScoreThreshold are the
     same number for a reason: this one is reached when studioConfig() could
     not be read at all, and a stricter mark on the day Firestore is
     unreachable would reject renders that pass on every other day. */
  const thresholdRaw = Number(cfg && cfg.renderScoreThreshold);
  const threshold = Number.isFinite(thresholdRaw) && thresholdRaw > 0 && thresholdRaw <= 100
    ? thresholdRaw : 80;
  /* BOTH TESTS, NOT EITHER. The total catches "slightly wrong everywhere";
     the floors catch "excellent except for the one thing that ruins it". */
  const floorFails = STUDIO_SCORE_KEYS.filter((k) => {
    const f = Number(floors[k]);
    return Number.isFinite(f) && f > 0 && cats[k] < f;
  });
  const fabricated = Array.isArray(raw.fabricated)
    ? raw.fabricated.map((s) => String(s || "").slice(0, 60)).filter(Boolean).slice(0, 8)
    : [];
  return {
    cats, total, threshold,
    pass: total >= threshold && floorFails.length === 0,
    floorFails,
    fabricated,
    worst: String(raw.worst || "").slice(0, 160),
  };
}

/* ═══════════ CHECKING THE JUDGE ══════════════════════════════════════════
   A vision model asked "is this good?" will tell you it is good. The first
   thing this subsystem produced in the wild was 100 across all six
   categories, on a render nobody believed was perfect — and a scorer that
   cannot fail is worse than no scorer, because it costs a call per render
   and licenses whatever comes back.

   So the model is no longer asked only for opinions. It is asked to COUNT
   first — how many openings are in the map, how many holes are in the
   render, how many charms it can see — and those counts are facts that its
   own scores can be checked against. A judge that says the render has two
   holes where the map has three, and then scores cut-outs 100, has
   contradicted itself; the score is capped at something the observation can
   support and the cap is recorded.

   This cannot make a bad judge good. What it does is make a bad judge
   VISIBLE — an answer with no observations at all is marked suspect and, in
   enforce mode, is treated as no answer rather than as a pass.

   ── AND THEN IT WAS NOT ENOUGH ─────────────────────────────────────────
   Reported from the wild: 98/100/100/100/98/100 on a render the customer
   could see was wrong, wearing no warning at all. Every safeguard above was
   working exactly as written, and all three of them missed it:

   • The caps compared the model's TWO OWN NUMBERS TO EACH OTHER. "openings
     1 -> 1" satisfies every one of them, and a model filling in a template
     writes the same number twice by construction. Self-consistency is free.
   • Worse, those invented counts set hasCounts, and hasCounts was what
     switched OFF the uniform-perfect suspicion. The fabrication was not
     merely missed; it was the thing that bought the verdict its clean bill.
   • And the template test demanded six IDENTICAL numbers. Two categories
     jittered by two points walked straight through it.

   The repair is to stop asking the judge to be its own witness. IMAGE A is
   not a photograph and not a model's output — it is a three-tone PNG this
   code generated, so how many openings and engraved fields it contains is a
   measurable fact, and studioSpecTruth measures it. The judge's first two
   answers become an EXAM with an answer sheet: a judge that miscounts the
   specification it was handed did not read it, whatever its six numbers say
   about the render. The render-side counts are then compared against that
   same truth rather than against the judge's own claim, which is what turns
   "the render lost a hole" from an opinion into a measurement. */
const STUDIO_SCORE_CAPS = Object.freeze({
  multipleCharms:   { cat: "fidelity",     to: 10 },
  fabricatedListed: { cat: "fidelity",     to: 20 },
  openingsMismatch: { cat: "cutouts",      to: 55 },
  engravingMismatch:{ cat: "engraving",    to: 65 },
  groundNotWhite:   { cat: "presentation", to: 40 },
  noShadow:         { cat: "presentation", to: 60 },
  /* ── measured against the map, not against the judge's own arithmetic ──
     A judge that cannot count the SPECIFICATION has disqualified itself from
     scoring the category that specification defines; these two caps are
     lower than the self-consistency ones above because a wrong answer about
     IMAGE A is worse evidence than a disagreement about IMAGE B. */
  specOpeningsWrong:  { cat: "cutouts",   to: 40 },
  specEngravingWrong: { cat: "engraving", to: 50 },
  /* ── AND THESE TWO SAY NOTHING ABOUT THE CHARM ────────────────────────
     A wrong answer about IMAGE A is a fact about the JUDGE. Left in the
     score it becomes a fact about the render: the cap drops the category
     under its floor, the render fails, and the workshop spends a retry
     making a charm less wrong in a way nobody actually observed. So the
     two spec caps are recorded and then LIFTED OUT — see `unmarked` — and
     the category they name is scored by nobody rather than scored badly. */
  /* the render genuinely disagrees with the map — the real defect, finally
     measurable, because one side of the comparison is now a fact */
  renderOpeningsWrong:  { cat: "cutouts",   to: 45 },
  renderEngravingWrong: { cat: "engraving", to: 55 },
});

/* ═══════════ WHICH OF THE MAP'S COUNTS ARE FAIR TO BE MARKED ON ═════════
   The exam only means anything if a competent answerer could pass it. Four
   live runs say the engraved count is not such a question and the openings
   count is:

     v7  jug        map 8 openings → judge said 8 ✓   map 3 engraved → 1  ✗
     v8  jug        map 8 openings → judge said 8 ✓   map 3 engraved → 30 ✗
     v9  jug        openings ✓                        engraved ✗
     v1  butterfly  map 1 opening  → judge said 1 ✓   map 15 engraved → 7 ✗

   Four out of four on openings, nought out of four on engraved, and the
   engraved misses are not near-misses — 1 and 30 against a truth of 3.

   That is not a judge that cannot count. It is two things counting
   DIFFERENT OBJECTS. studioLabel is 4-connected over the exact 136-grey, so
   a butterfly's wing detailing is fifteen separate components to this code
   and one engraved pattern to anything with eyes; strokes that meet at a
   corner are two regions to the machine and one to the viewer. Openings do
   not have that problem: a through-cut is a white island with a hard edge,
   and both counters agree about what one is.

   So the engraved count is COLLECTED AND SHOWN and never marked. It stays
   in the prompt because it costs nothing, it goes on the panel because a
   reader may want it, and if the two counters are ever brought into
   agreement — 8-connectivity, or merging regions closer together than the
   pen is wide — putting the question back is one line here.

   What is NOT lost: engraving is still scored 0-100 by the judge's own
   category 3, which asks whether every dark region is engraved at full
   coverage and nothing else is, and still carries a floor. It is measured
   the way tone and presentation are measured — by eye, against the map —
   rather than by a count the two sides define differently.

   This is why the butterfly kept shipping unverified while the jug did not:
   with engraved marked and openings at 1, the only question the judge could
   pass was the uninformative one, so every render of that charm failed the
   exam on the unanswerable half. Nothing was wrong with the render, the
   judge, or the charm. */
const STUDIO_EXAM_QUESTIONS = Object.freeze([
  /* [ the judge's field, the truth key, the cap when it is wrong ] */
  Object.freeze(["openingsInSpec", "openings", "specOpeningsWrong"]),
]);
/* The comparison the customer actually cares about — the map's count against
   what the judge can see in the photograph — and it is restricted to the
   same question for the same reason. One side of it is a machine count, so
   it is only a measurement where both sides count the same object. */
const STUDIO_RENDER_COUNT_CHECKS = Object.freeze([
  Object.freeze(["openingsInRender", "openings", "renderOpeningsWrong"]),
]);
/* How far the render's engraved count may fall below the judge's own count
   of the map before it reads as engraving gone missing rather than as the
   noise of counting a pattern twice. */
const STUDIO_ENGRAVED_SHORTFALL = 0.25;

/* ── WHAT THE MAP ACTUALLY CONTAINS ───────────────────────────────────────
   Measured from the BUFFER that was sent to the judge, not from the masks
   studioMaterialSpec happens to be holding: a reused map arrives with no
   masks at all, and the buffer is the only thing that is certainly what the
   judge was looking at. Never throws — an unmeasurable map means no exam,
   which leaves the judge exactly as trusted as it was before this existed. */
const STUDIO_TRUTH_MIN_FRAC = 0.004;   /* the census's own floor, so the two agree */

async function studioSpecTruth(sharp, specBuf) {
  if (!sharp || !specBuf) return null;
  try {
    const { data, info } = await sharp(specBuf).removeAlpha().raw()
      .toBuffer({ resolveWithObject: true });
    const w = info.width, h = info.height, n = w * h, ch = info.channels;
    if (!n) return null;
    const POLISHED = STUDIO_MASK_POLISHED[0], ENGRAVED = STUDIO_MASK_ENGRAVED[0];
    /* the same tolerance studioRefineMask classifies with. The refined map is
       anti-aliased, and a boundary pixel sitting halfway between two tones
       belongs to neither region's count. */
    const near = (v, t) => Math.abs(v - t) <= 24;
    const metal = new Uint8Array(n), engraved = new Uint8Array(n), white = new Uint8Array(n);
    for (let i = 0; i < n; i++) {
      const v = data[i * ch];
      if (near(v, ENGRAVED)) { metal[i] = 1; engraved[i] = 1; }
      else if (near(v, POLISHED)) metal[i] = 1;
      else if (v >= 255 - 24) white[i] = 1;
      /* everything else is an anti-aliased boundary pixel and belongs to no
         region — see the hole mask below for why saying so matters */
    }
    /* THE CHARM'S BODY INCLUDES ITS HOLES. Flooding from the border through
       everything that is not metal leaves the silhouette; white inside that
       silhouette is an opening, white outside it is the studio backdrop. That
       distinction is the entire cut-out category. */
    const face = studioOuterFace(metal, w, h);
    let facePx = 0;
    for (let i = 0; i < n; i++) if (face[i]) facePx++;
    if (!facePx) return null;
    /* ── AN OPENING IS WHITE, NOT MERELY "NOT METAL" ──────────────────────
       This read `face[i] && !metal[i]`, and the tolerance above could leave a
       gap: the map is anti-aliased, so the seam between a polished region and
       an engraved one runs through the midpoint of the two tones — inside the
       silhouette, and if that midpoint matches neither tone it is NOT METAL.
       Every such seam was then a hole. They arrive as a thin ring around each
       engraved field, and on a charm with a large one that ring can clear the
       census floor and be filed as a ninth opening the map does not contain —
       an answer sheet with a wrong answer on it, marking a judge that read the
       map correctly as having failed. The judge is told "only white ENCLOSED
       by metal is an opening"; this now measures the same thing it asks for.

       NOTE ON THE CURRENT LADDER: at 136/176 the ±24 windows OVERLAP (152..160)
       and ENGRAVED is tested first, so a seam pixel classifies as engraved
       rather than as neither and this class of phantom opening cannot arise at
       all. The guard is kept because it is correct either way and because the
       ladder is a tunable — widen the gap again and the gap-in-tolerance
       returns. */
    const holes = new Uint8Array(n);
    for (let i = 0; i < n; i++) if (face[i] && white[i]) holes[i] = 1;
    const tally = (mask) =>
      studioCensusRegions(mask, w, h, facePx, STUDIO_TRUTH_MIN_FRAC, 1).total;
    return { openings: tally(holes), engraved: tally(engraved), facePx, w, h };
  } catch (e) {
    console.error("[studio] could not measure the spec map:", e?.message || e);
    return null;
  }
}

function studioScoreAudit(raw, scored, cfg, extra) {
  if (!scored) return scored;
  const obs = raw && typeof raw.observations === "object" && raw.observations ? raw.observations : null;
  const truth = (extra && extra.truth && Number.isFinite(Number(extra.truth.openings)))
    ? extra.truth : null;
  const judgeModel = String((extra && extra.model) || "");
  const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : null);
  /* kept before anything is capped — the template test below is a question
     about the answer the model gave, not about the answer after this
     function has finished punishing it */
  const rawCats = STUDIO_SCORE_KEYS.map((k) => scored.cats[k]);
  const caps = [];
  /* EVERY CONTRADICTION IS RECORDED, not only the one that happened to move
     the number furthest. Two rules can hit the same category — "you misread
     the map" and "the render is short a hole" are different findings — and
     when the first has already pulled the score below the second's ceiling,
     dropping the second from the list loses the more interesting half of the
     diagnosis. The score itself is still only ever lowered. */
  const cap = (rule) => {
    const c = STUDIO_SCORE_CAPS[rule];
    if (!c) return;
    if (scored.cats[c.cat] > c.to) scored.cats[c.cat] = c.to;
    if (caps.indexOf(rule) < 0) caps.push(rule);
  };

  if (obs) {
    const charms = num(obs.charmsVisible);
    if (charms !== null && charms !== 1) cap("multipleCharms");
    const oa = num(obs.openingsInSpec), ob = num(obs.openingsInRender);
    if (oa !== null && ob !== null && oa !== ob) cap("openingsMismatch");
    /* ── THE JUDGE'S OWN TWO ENGRAVED NUMBERS, COMPARED PROPORTIONALLY ──
       Exact inequality was the wrong test the moment the counts got large.
       A judge that reported 30 engraved regions in the map and 31 in the
       render was saying the engraving is all there; the old `ea !== eb`
       read that one-region difference as a defect and capped engraving at
       65. What this test is actually for is engraving that went MISSING, so
       that is what it asks: a material shortfall in the render against the
       judge's own reading of the map. Both numbers come from the same eye,
       so the ratio survives the miscounting that the absolute values do
       not. */
    const ea = num(obs.engravedRegionsInSpec), eb = num(obs.engravedRegionsInRender);
    if (ea !== null && eb !== null && ea > 0 &&
        eb < ea - Math.max(0, Math.floor(ea * STUDIO_ENGRAVED_SHORTFALL))) {
      cap("engravingMismatch");
    }
    if (obs.groundIsWhite === false) cap("groundNotWhite");
    if (obs.shadowPresent === false) cap("noShadow");
  }
  if (scored.fabricated.length) cap("fabricatedListed");

  /* ── THE EXAM, MARKED AGAINST THE ANSWER SHEET ───────────────────────
     The two questions about IMAGE A have right answers, and this is where
     the judge finds that out. `graded` is what it was asked and could be
     marked on; `matched` is what it got right; `wrong` is what it did not.
     A judge with an empty `graded` refused the only checkable question on
     the paper, which is its own kind of answer. */
  const graded = [], matched = [], wrong = [], wrongRules = [], unmarked = [];
  if (obs && truth) {
    for (const [field, key, rule] of STUDIO_EXAM_QUESTIONS) {
      const said = num(obs[field]);
      if (said === null) continue;
      graded.push(key);
      if (said === Number(truth[key])) matched.push(key);
      else {
        wrong.push(key);
        /* RECORDED, NOT SCORED. The rule goes on the caps list so the panel
           can say which question was missed, and the category it names is
           added to `unmarked` so the recompute below leaves it out of the
           total and out of the floors entirely. A judge that misread the
           map's engraved fields has not told us the engraving is bad; it
           has told us it cannot be believed about engraving. */
        wrongRules.push(rule);
        if (caps.indexOf(rule) < 0) caps.push(rule);
        const c = STUDIO_SCORE_CAPS[rule];
        if (c && unmarked.indexOf(c.cat) < 0) unmarked.push(c.cat);
      }
    }
    /* AND THE RENDER, AGAINST THE MAP RATHER THAN AGAINST ITS OWN CLAIM.
       This is the comparison the customer actually cares about: the map has
       three openings, the judge can see two in the photograph, so a hole is
       missing — a fact that survives the judge having also misread the map,
       because only one side of it comes from the judge. */
    for (const [field, key, rule] of STUDIO_RENDER_COUNT_CHECKS) {
      const said = num(obs[field]);
      if (said !== null && said !== Number(truth[key])) cap(rule);
    }
  }

  /* WHAT A NON-ANSWER LOOKS LIKE. Not "it scored highly" — a genuinely good
     render should score highly. It is an answer with no evidence behind it:
     no observations at all, or a set of numbers with the shape of a template
     being filled in rather than two pictures being compared. */
  /* THE MODEL'S OWN SIX, NOT THE CAPPED ONES. This read scored.cats, which
     the caps above have already pulled down — so any cap firing at all
     widened the spread and switched the template test off. That is exactly
     backwards: a contradiction is a reason to look harder at the shape of
     the answer, not to stop looking. The test asks what the MODEL wrote. */
  const vals = rawCats.slice();
  const lo = Math.min.apply(null, vals), hi = Math.max.apply(null, vals);
  /* NOT "identical" — NEAR-identical, which is what actually arrived. Six
     unrelated criteria landing within three points of each other at the very
     top of the scale is the template shape; demanding they be exactly equal
     let 98/100/100/100/98/100 through untouched. */
  const nearPerfect = lo >= 97 && (hi - lo) <= 3;
  /* ── A COUNT IS ONLY EVIDENCE WHEN IT COULD HAVE BEEN WRONG ──────────
     The old test accepted the mere PRESENCE of a count as corroboration,
     which is how invented numbers came to vouch for the scores they were
     invented alongside. Two things have to be true now. The count must have
     been marked correct against the map — and it must be a count worth
     getting right: nearly every charm has exactly one opening, its hanging
     hole, so a judge that writes "1" has told us nothing it could not have
     guessed from the shape of the question. A 3 that matches a 3 is a judge
     that looked, and there is no cheap way to fake it. */
  const corroborated = matched.some((k) => Number(truth[k]) >= 2);
  const reasons = [];
  if (!obs) reasons.push("no_observations");
  else if (!String(obs.describeRender || "").trim()) reasons.push("no_description");
  /* ── A WRONG ANSWER DISQUALIFIES A QUESTION, NOT THE WHOLE PAPER ─────
     This used to read `if (wrong.length) reasons.push("miscounted_spec")`,
     and that single line is what made the check useless on the render that
     needed it most.

     Reported from the wild, v7: the map held 8 openings and 3 engraved
     fields. The judge counted the map's openings and got 8 — exactly right,
     on the one question there is no cheap way to fake — then counted 3
     openings in the render and described what it saw as "the central jug is
     a large cutout". Five openings had merged into one. That finding is a
     MEASUREMENT: the render side comes from the judge, the map side comes
     from studioSpecTruth, and it is the whole reason this subsystem exists.
     It capped cutouts at 45, under a floor of 85, and the render should have
     been rejected and re-rolled with the loss named.

     It was not. The same judge had said the map held 1 engraved field where
     the machine counted 3, `wrong.length` was 1, the entire verdict was
     marked suspect, and `trusted` in studioRenderAttempts turned the whole
     thing off. The check found the defect and then disqualified itself over
     an unrelated sub-question, and the customer got the broken charm with a
     banner explaining that the check could not be trusted.

     The engraved question is also the harder half by some distance, and not
     symmetrically so. studioLabel is 4-CONNECTED: engraved strokes that meet
     only at a corner are two regions to the machine and one wave to anything
     with eyes, and the prompt's own rule — "SEPARATE means not touching" —
     reads the other way. A wave engraving is exactly that case. So the
     question the old line hung the entire verdict on is the one it is most
     reasonable to get wrong.

     The paper is now marked question by question. The whole verdict falls
     only when the judge shows it did not read the map AT ALL — every graded
     answer wrong. One right and one wrong is a judge that looked: it keeps
     the category it proved itself on, and loses the other to `unmarked`.

     HALF CREDIT HAS TO BE EARNED, THOUGH. The question it got right must be
     one it could not have guessed: nearly every charm has exactly one
     opening, its hanging hole, so "1" against a truth of 1 proves nothing —
     the same `corroborated` bar the uniform-perfect test uses. A judge that
     missed a question and passed only an uninformative one has shown no
     evidence it read the map, and the whole verdict falls as before. */
  if (graded.length && (!matched.length || (wrong.length && !corroborated))) {
    reasons.push("miscounted_spec");
  } else if (truth && obs && !graded.length) reasons.push("uncounted_spec");
  if (nearPerfect && !corroborated) reasons.push("uniform_perfect");
  /* ── THE WRONG TOOL, NAMED WHERE SOMEBODY WILL SEE IT ────────────────
     Until mk29 every model chain in this file ended at DEFAULT_IMAGE_MODEL,
     so a deployment that never set renderScoreModel had its renders judged
     by an image GENERATOR — precisely the thing that answers with a
     filled-in template. The judge's chain ends at DEFAULT_TEXT_MODEL now,
     so only an explicit override can put an image model here again — and
     when one does, it is a reason for distrust and the studio's own panel
     says so, rather than a console.warn nobody reads while the verdict
     gates renders. An image model that counted the map correctly has proved
     it looked, so corroboration still excuses it: this is a rule about
     evidence, not about names. */
  if (/-image(-preview)?$/.test(judgeModel) && !corroborated) reasons.push("image_model_judge");
  /* ── A DEAD VERDICT IS RECORDED AS THE JUDGE EARNED IT ────────────────
     Unmarking exists so a HALF-credible verdict can still gate on its
     credible half. When the paper failed outright there is no credible
     half: nothing is lifted out, the two spec caps land on the score as
     they always did, and the number filed beside "not trusted" is the
     judge's mark rather than a total flattered by the questions it got
     wrong being quietly dropped. */
  if (reasons.indexOf("miscounted_spec") >= 0) {
    unmarked.length = 0;
    for (const rule of wrongRules) cap(rule);
  }
  scored.uniform = nearPerfect;
  scored.corroborated = corroborated;
  scored.suspect = reasons.length > 0;
  scored.suspectWhy = reasons;
  scored.caps = caps;
  /* which of the map's two questions it got wrong, and which categories are
     therefore scored by nobody. Both are filed on the version document: a
     verdict that gated a render on half the paper has to be able to say
     which half, or the panel is back to six numbers with nothing behind
     them. */
  scored.examWrong = wrong;
  scored.unmarked = unmarked;
  scored.truth = truth
    ? { openings: Number(truth.openings), engraved: Number(truth.engraved) } : null;
  scored.observations = obs ? {
    charmsVisible: num(obs.charmsVisible),
    openingsInSpec: num(obs.openingsInSpec),
    openingsInRender: num(obs.openingsInRender),
    engravedRegionsInSpec: num(obs.engravedRegionsInSpec),
    engravedRegionsInRender: num(obs.engravedRegionsInRender),
    groundIsWhite: obs.groundIsWhite === true ? true : obs.groundIsWhite === false ? false : null,
    shadowPresent: obs.shadowPresent === true ? true : obs.shadowPresent === false ? false : null,
    describeRender: String(obs.describeRender || "").slice(0, 200),
  } : null;

  /* the caps may have moved the total and the floors, so both are recomputed
     from the corrected numbers rather than from what the model claimed */
  if (caps.length || unmarked.length) {
    /* the SAME weights and floors the first pass used, overrides included —
       recomputing against the built-in defaults would quietly undo a
       config/customStudio override the moment a cap fired */
    const weights = Object.assign({}, STUDIO_SCORE_WEIGHTS, (cfg && cfg.renderScoreWeights) || {});
    const floors  = Object.assign({}, STUDIO_SCORE_FLOORS,  (cfg && cfg.renderScoreFloors)  || {});
    /* ── AN UNMARKED CATEGORY IS LEFT OUT, NOT SCORED ZERO ───────────────
       The weighted mean is taken over the categories that still have a
       credible number, so removing one RENORMALISES rather than dragging
       the total down by its weight. Scoring it low instead would fail the
       render for the judge's mistake — which is the failure this whole
       change exists to remove — and scoring it 100 would let a judge buy a
       pass by misreading the map. Neither: it is not counted. */
    const counted = STUDIO_SCORE_KEYS.filter((k) => unmarked.indexOf(k) < 0);
    let sum = 0, wsum = 0;
    for (const k of counted) {
      const w = Number(weights[k]);
      if (!Number.isFinite(w) || w <= 0) continue;
      sum += scored.cats[k] * w; wsum += w;
    }
    scored.total = wsum ? Math.round(sum / wsum) : 0;
    scored.floorFails = counted.filter((k) => {
      const f = Number(floors[k]);
      return Number.isFinite(f) && f > 0 && scored.cats[k] < f;
    });
    scored.pass = scored.total >= scored.threshold && scored.floorFails.length === 0;
  }
  return scored;
}

/* ── WHAT THE NEXT ATTEMPT IS TOLD AFTER A WRONG SHAPE ────────────────────
   The measurement is a single number and the note must not pretend otherwise:
   it does not know WHICH part of the outline moved, only that the outline as
   a whole is not the map's. So it names the failure mode rather than a
   region — and the failure mode is specific enough to act on, because it is
   always the same one. The model did not mis-trace the boundary; it stopped
   tracing and drew the object it recognised.

   No measurement is quoted at the model. A number it cannot verify invites it
   to reason about the number instead of looking at the picture, and "IoU
   0.73" means nothing in a drawing instruction.                            */
/* ── AND THE CORRECTION NOTES OBEY THE SAME RULE ──────────────────────────
   A retry note is appended to the prompt, so a six-bullet note is the same
   dilution the prompt itself was just cut back for — and it arrives at the
   worst moment, on the attempt that already went wrong. Each of these says
   one thing, names the failure so the model knows what to change, and stops.
   The gate, not the wording, is what guarantees the outcome.               */
/* ── HOW BAD IS THIS ONE, ACROSS EVERYTHING MEASURED ──────────────────────
   Only ever used to pick between attempts that have ALL failed. Each term is
   the amount by which the attempt overshot that check's own limit, expressed
   as a multiple of the limit so four different units become comparable. Zero
   means the check passed; the sum is what the least-bad attempt minimises.

   The four are deliberately unweighted. A render that is a little wrong in
   every respect is about as unsellable as one that is very wrong in one, and
   there is no evidence to justify pretending otherwise. */
function shapeBadness(s, minIoU) {
  if (!s) return Infinity;
  const over = (v, lim) => (v == null || !(v > lim) ? 0 : (v - lim) / (lim || 1));
  const iouShort = s.iou == null || s.iou >= minIoU ? 0 : (minIoU - s.iou) / minIoU;
  return iouShort +
    over(s.outline && s.outline.mean, STUDIO_OUTLINE_MEAN_LIMIT) +
    over(s.furniture && s.furniture.biggest, STUDIO_FURN_LIMIT) +
    over(s.alloy && s.alloy.offAlloy, STUDIO_ALLOY_LIMIT);
}
/* the same limits the compositor applies, named here so the ranking and the
   gate can never drift apart.

   THE TAIL WAS DROPPED because it could not order its own evidence: two good
   dragons scored 3.16 and 17.98 on the p95 while the heart that passed for a
   shield scored 9.83, so the worst reading of the eight belonged to a render
   the customer liked. A ranking term that points the wrong way makes the
   least-bad attempt the wrong attempt, so it is gone and the mean — which
   does separate, 0.40/0.57/0.73/1.72 good against 2.64/2.94/5.43/6.06 bad —
   carries the outline on its own at the limit it was calibrated for. */
const STUDIO_OUTLINE_MEAN_LIMIT = 2.2;
const STUDIO_FURN_LIMIT = 0.06;
const STUDIO_ALLOY_LIMIT = 0.12;

function studioFrameRetryNote(attemptNo) {
  return [
    "CORRECTION — the previous attempt returned a page, not a photograph: the frame held other content beside the charm — panels, inset copies of the reference images, borders or lettering.",
    "The attached images are instructions to read, never subjects to draw. Output ONE charm alone, centred on plain white ground with its own soft contact shadow, and nothing else anywhere in the frame.",
    attemptNo >= 2 ? "This has already been asked for once. The photograph only." : "",
  ].filter(Boolean).join("\n");
}

function studioAlloyRetryNote(attemptNo) {
  return [
    "CORRECTION — the previous attempt rendered the charm in TWO metals: part of it came back as flat grey or gunmetal instead of gold.",
    "The whole piece is one alloy. An engraved area is the same 14K gold as the polish beside it, only slightly darker and warmer — never a grey, a silver, a black or a separate inlaid material. IMAGE 2's greys classify the surface; they are not colours to copy.",
    attemptNo >= 2 ? "This has already been asked for once. One alloy, edge to edge." : "",
  ].filter(Boolean).join("\n");
}

/* The correction for a filled outline. Three sentences, and the middle one
   is the whole instruction: the failure is not "too much engraving", it is a
   line treated as the edge of a pocket, and a note that says the first does
   not correct the second. */
function studioEngraveRetryNote(attemptNo) {
  return [
    "CORRECTION — the previous attempt ENGRAVED AREAS THAT IMAGE 1 SHOWS AS POLISHED. Its engraved marks came back far thicker than the marks on the map.",
    "Engrave the dark grey pixels of IMAGE 1 and nothing else. A dark grey line is a LINE: the light grey it encloses — a head, a body, a wing panel — stays smooth polished metal, not a sunken field. Only fill an area with engraving where IMAGE 1 fills that whole area dark grey.",
    attemptNo >= 2 ? "This has already been asked for once. Match the map's marks stroke for stroke." : "",
  ].filter(Boolean).join("\n");
}

/* Too dark a recess, corrected with the number rather than an adjective.
   "Slightly darker" is what the prompt already says and what this render
   already believed it was doing; a ratio is the one form of the instruction
   that cannot be satisfied by a render at half the brightness. */
function studioEngraveToneRetryNote(shape, attemptNo) {
  const r = shape && shape.engrave && shape.engrave.toneRatio;
  return [
    "CORRECTION — the previous attempt cut its ENGRAVING FAR TOO DARK. Its recesses came back as dark brown shapes rather than as worked gold.",
    (r ? `Measured on that attempt, an engraved area sat at ${r} of the brightness of the polished metal beside it. ` : "") +
      `It must sit at about ${STUDIO_ENGRAVE_RATIO} — the same gold, a little darker and warmer, told apart from the polish by FINISH rather than by colour. Never darker than ${SCO_ENG_TONE_MIN} of the polish, and never brown, bronze, grey or black.`,
    attemptNo >= 2 ? "This has already been asked for once. Err lighter: a recess nobody notices is right, one that reads as a hole is wrong." : "",
  ].filter(Boolean).join("\n");
}

/* A charm redrawn at the wrong proportions, told as a proportion rather than
   as "the shape is wrong" — the outline IS right, which is why every other
   check passed it; what moved is the ratio between its width and its height. */
function studioAspectRetryNote(shape, attemptNo) {
  const k = shape && shape.aspect;
  return [
    "CORRECTION — the previous attempt drew the charm at the WRONG PROPORTIONS. Its outline was right and its width-to-height ratio was not: the piece came back stretched on one axis.",
    (k ? `Measured against IMAGE 1, it was off by a factor of ${k}. ` : "") +
      "Reproduce IMAGE 1's width and height in the SAME ratio it has. Do not stretch, squash, or refit the charm to the frame — its proportions are part of the design, and every engraved line and every opening sits where it does because of them.",
    attemptNo >= 2 ? "This has already been asked for once. Measure the map's width against its height and match it." : "",
  ].filter(Boolean).join("\n");
}

function studioShapeRetryNote(shape, attemptNo, builtInHoop) {
  return [
    "CORRECTION — the previous attempt drew the WRONG SHAPE. Its outline was measured against IMAGE 1 and does not match: the subject was right, the shape was not.",
    "Trace IMAGE 1's outline exactly as given — same lean, same asymmetry, same position of every part, and every gap of white between two parts still open. Do not straighten, centre, mirror or otherwise improve it; a better-looking charm with a different outline is a failed render.",
    "Reproduce its scale and centring in the frame too, and " +
      (builtInHoop === true ? "its hanging hardware exactly as it appears there." : "its integrated top hoop."),
    attemptNo >= 2 ? "This has already been asked for once. Trace the boundary literally." : "",
  ].filter(Boolean).join("\n");
}

/* What the next attempt is told. Naming the failure is the whole value of
   having judged it — a bare re-roll is just another sample from the same
   distribution. */
function studioScoreRetryNote(scored, attemptNo) {
  /* an unmarked category's number is the judge's, not the charm's — naming it
     as the weakest area would send the retry after a fault nobody observed */
  const gradedKeys = STUDIO_SCORE_KEYS.filter((k) => (scored.unmarked || []).indexOf(k) < 0);
  const worstCat = (gradedKeys.length ? gradedKeys : STUDIO_SCORE_KEYS)
    .slice()
    .sort((a, b) => scored.cats[a] - scored.cats[b])[0];
  const lines = [
    `RETRY ${attemptNo} — THE PREVIOUS ATTEMPT WAS REJECTED BY THE WORKSHOP'S OWN CHECK.`,
    `It scored ${scored.total} against a required ${scored.threshold}.`,
  ];
  /* ── THE ONE THING HERE THAT IS NOT AN OPINION ───────────────────────
     The map's counts are machine-measured and the render's counts came from
     something that just looked at the render. Where they disagree, say so in
     numbers before saying anything about scores: "8 openings became 3" is an
     instruction a renderer can act on, and "cutouts: 45/100" is not. On the
     v7 jug this is the difference between a targeted retry and a re-roll. */
  const t = scored.truth, o = scored.observations;
  const unmarked = scored.unmarked || [];
  if (t && o) {
    if (o.openingsInRender != null && Number(o.openingsInRender) !== Number(t.openings) &&
        unmarked.indexOf("cutouts") < 0) {
      lines.push(`COUNT: the map specifies ${t.openings} separate through-cut opening(s) ` +
                 `and only ${o.openingsInRender} were visible as real holes in your last ` +
                 `attempt. Openings that merged into one larger cut-out, or were filled ` +
                 `with metal, are the defect. Cut every white region enclosed by metal in ` +
                 `IMAGE 1 as its own hole, separated by the metal the map puts between them.`);
    }
    if (o.engravedRegionsInRender != null && Number(o.engravedRegionsInRender) !== Number(t.engraved) &&
        unmarked.indexOf("engraving") < 0) {
      lines.push(`COUNT: the map specifies ${t.engraved} separate engraved field(s) and ` +
                 `${o.engravedRegionsInRender} were visible in your last attempt. Engrave ` +
                 `every dark-grey region of IMAGE 2 at full coverage and nothing else.`);
    }
  }
  if (scored.floorFails.length) {
    lines.push(`Unacceptable in: ${scored.floorFails.join(", ")}.`);
  }
  lines.push(`Weakest area: ${worstCat} (${scored.cats[worstCat]}/100).`);
  if (scored.worst) lines.push(`What was wrong: ${scored.worst}`);
  if (scored.fabricated.length) {
    lines.push(`THE PREVIOUS ATTEMPT INVENTED DETAIL THAT IS NOT IN THE MAPS: ` +
               `${scored.fabricated.join("; ")}. Render ONE charm and nothing else — ` +
               `no second panel, no duplicate, no caption, no border, no props.`);
  }
  lines.push(`Correct exactly this and change nothing that was already right. ` +
             `IMAGE 1 remains the only authority for the silhouette and every ` +
             `through-cut; IMAGE 2 remains the only authority for what is engraved.`);
  return lines.join("\n");
}

/* ═══════════ THE ATTEMPT LOOP ════════════════════════════════════════════
   Lifted out of handleStudioRender so it can be exercised without a model, a
   bucket or a Firestore. Everything it needs arrives as an argument and
   nothing it does touches global state, which is the only reason the two
   things most worth being sure of — that the BEST attempt ships rather than
   the last one, and that neither judge can spend more attempts than it was
   given — can be proven rather than asserted.

   TWO JUDGES, TWO ALLOWANCES, ONE CLOCK.
     · the cut check (geometric, repairs what it can) may ask for up to
       `maxRetries` more attempts
     · the adjudicator (looks at the picture, scores it) may ask for up to
       `scoreRetries` more
     · `retryBudgetMs` overrules both, because the browser's watcher gives up
       at 180s and a render the customer was told had failed is worse than an
       imperfect one. A new attempt only STARTS if the time already spent plus
       the previous attempt's measured duration still fits — so a slow first
       render never buys a doomed second one.
   ═══════════════════════════════════════════════════════════════════════ */
async function studioRenderAttempts(opts) {
  const {
    renderOnce, basePrompt, cutMode, maxRetries, retryable, punchFn,
    adjMode, scoreRetries, judgeFn, retryBudgetMs, onRetry, onStage,
    shapeFn, shapeRetries, shapeMinIoU,
  } = opts;
  const now = opts.now || (() => Date.now());
  const startedAt = opts.startedAt != null ? opts.startedAt : now();
  const adjudicating = adjMode === "observe" || adjMode === "enforce";
  const log = opts.log || ((...a) => console.log(...a));

  let outBuf = null, punch = null, attempts = 0, lastMs = 0, nextNote = "";
  /* the verdict belonging to the most recent attempt — null when that one
     could not be judged. Kept because the render that ships is the last one
     unless the swap below moves it, and the panel must describe THAT one. */
  let lastScored = null;
  /* ── ONE ROW PER IMAGE MADE, NOT PER IMAGE JUDGED ─────────────────────
     scoreLog only ever held attempts the judge answered on, and the panel's
     table is built from it — so a run that made two images and could only
     score one printed "2 images generated" above a table with one row, and
     the second image left no trace anywhere the customer could see. Whether
     an attempt was judged is a fact about the JUDGE; that an image was made
     is a fact about the run, and the run's own record has to carry it.

     attemptLog has an entry for every iteration of this loop, judged or
     not, and it is what the version document's table is built from now.
     scoreLog stays exactly what it was — the scored subset, which is what
     scoreBest and renderScoreCount mean — so nothing that reads it changes. */
  const failedVerdicts = [], scoreLog = [], attemptLog = [];
  let scoreBest = null;
  /* ── THE THIRD JUDGE, AND THE ONLY FREE ONE ───────────────────────────
     The shape gate asks one question — is this the same charm the map
     describes? — by measuring the silhouette overlap between the render and
     the greyscale map. No model, no credit, no wording: two segmentations
     and a three-degree-of-freedom fit, about a second of arithmetic.

     It exists because of a failure neither other judge catches. An astronaut
     map drawn floating, tilted, one fist raised and the legs tucked, came
     back as a textbook standing astronaut — right subject, right alloy,
     right finish, right hoop, wrong shape. Silhouette IoU 0.731 where a good
     render scores 0.977. The cut check would call that "unaligned" and
     decline; the compositor calls it drift and stands down; and with both
     parked the render shipped. A number that says "this is not the customer's
     charm" is worth a re-roll on its own.

     BEST-BY-OVERLAP, NOT LAST. If every attempt drifts, the closest one
     ships — same doctrine as the adjudicator's, for the same reason: trying
     harder must never hand the customer a worse charm. */
  let shapeBest = null, lastShape = null;
  const shaping = typeof shapeFn === "function" && shapeRetries != null;

  while (true) {
    attempts++;
    const promptText = nextNote ? basePrompt + "\n\n" + nextNote : basePrompt;
    if (attempts > 1 && onRetry) await onRetry(attempts);
    const t0 = now();
    outBuf = await renderOnce(promptText);
    nextNote = "";

    /* THE CHECKS CANNOT BE ALLOWED TO COST THE CHARM. Both callbacks are
       WRITTEN never to throw — and mk28 proved that a promise is not a
       property: one out-of-scope identifier inside judgeFn's closure threw
       ReferenceError past every internal try/catch, the loop trusted it,
       and a paid render died with "log is not defined". So the loop holds
       the doctrine itself now: a punch that crashes degrades to an
       unpunched render with the failure named in its report, and a judge
       that crashes is a judge that answered nothing. */
    if (cutMode === "off") punch = null;
    else {
      try { punch = await punchFn(outBuf); }
      catch (e) {
        console.error("[studio] cut check crashed — shipping unpunched:", e?.message || e);
        punch = { buf: outBuf, report: { verified: false,
          reason: "punch_crashed: " + String(e?.message || e).slice(0, 120),
          declaredCuts: 0, punchedPx: 0, alignment: 0, openFrac: 0,
          regionsOk: 0, regionsBad: 0, worst: "" } };
      }
    }

    /* ── THE DOCUMENT HAS TO MOVE BEFORE THE JUDGE RUNS ──────────────────
       The storefront's watcher gives up when the version document has been
       SILENT too long, and between "rendering" and "polishing" there was no
       write at all — so one attempt's silence was the image call PLUS the
       cut check PLUS the judge, added together. A measured flash run on v9
       spent 121s in that gap; with a pro image model at a 180s ceiling and
       a 60s judge behind it, the sum comfortably clears any idle window
       worth having, and the customer would be told a working render had
       stalled.

       So the image landing is reported the moment it lands. The silence is
       now bounded by the LONGER of the two calls rather than their sum, the
       two clocks can be reasoned about separately, and the progress bar
       gains a step that is true: the charm exists and is being checked. */
    if (onStage) await onStage("engraving", attempts);

    /* THE SHAPE GATE. Same doctrine as the other two callbacks: it is written
       never to throw, and the loop assumes nothing. A gate that cannot answer
       is a gate that raises no objection — it must never be the reason a paid
       render is lost. */
    lastShape = null;
    if (shaping) {
      try { lastShape = await shapeFn(outBuf); }
      catch (e) {
        console.error("[studio] shape gate crashed — raising no objection:", e?.message || e);
        lastShape = null;
      }
      if (lastShape && lastShape.iou != null) {
        log(`[studio] render gate attempt ${attempts}: IoU ${lastShape.iou}/${shapeMinIoU}, ` +
            `stray ${lastShape.furniture ? lastShape.furniture.biggest : "?"}, ` +
            `off-alloy ${lastShape.alloy ? lastShape.alloy.offAlloy : "?"}, ` +
            `outline ${lastShape.outline ? lastShape.outline.mean + "%/" + lastShape.outline.p95 + "%" : "?"} — ` +
            `${lastShape.ok ? "accepted" : "REJECTED: " + lastShape.why} (${lastShape.ms}ms)`);
        /* ── RANKED ON EVERYTHING MEASURED, NOT ON ONE NUMBER ────────────
           When every attempt fails, one of them still has to ship, and the
           choice was made on silhouette IoU alone — one of four things now
           measured. A render can be geometrically excellent and come back in
           the wrong metal entirely; ranked on IoU it wins, and the customer
           gets a white dragon because it was the roundest failure.

           Each check is scored as how far past its own limit the attempt
           went, so the numbers are comparable, and the least-bad on the sum
           is the one that ships. Nothing here changes which attempts PASS —
           a passing render never reaches this. */
        lastShape.badness = shapeBadness(lastShape, shapeMinIoU);
        if (!shapeBest || lastShape.badness < shapeBest.badness) {
          shapeBest = { buf: outBuf, iou: lastShape.iou, badness: lastShape.badness,
                        why: lastShape.why, attempt: attempts };
        }
      }
    }

    /* THE JUDGE. A null answer means "accepted" — see the adjudicator block
       above. The buffer judged is the one the model produced; the punch,
       when it runs at all, only fills declared openings. */
    let scored = null;
    lastScored = null;
    if (adjudicating) {
      const j0 = now();
      /* the attempt number goes IN so the reason a judge failed can come back
         out attributed to the right image — a bare `judgeFailWhy` on the
         handler is overwritten by the next failure and cannot say which
         attempt it belonged to */
      try { scored = await judgeFn(outBuf, attempts); }
      catch (e) {
        console.error("[studio] adjudicator crashed — accepting unscored:", e?.message || e);
        scored = null;
      }
      if (scored) {
        scored.attempt = attempts;
        scored.ms = now() - j0;
        lastScored = scored;
        scoreLog.push(scored);
        /* ── TRUST FIRST, THEN THE SCORE ──────────────────────────────
           Strictly greater, so an equal later score does not displace an
           earlier one — the first render to reach a given quality wins.
           But a TRUSTED verdict outranks an untrusted one whatever the two
           numbers say, because an untrusted number is not a rating and
           cannot be compared with one. Without that, a distrusted 95 became
           `scoreBest`, the swap below refused to ship a suspect winner, and
           a trusted 90 that was sitting right there never got its turn.
           Now that an untrusted verdict can spend a retry, that race is
           reachable rather than theoretical. */
        const better = !scoreBest ||
          (!scored.suspect && scoreBest.scored.suspect) ||
          (!!scored.suspect === !!scoreBest.scored.suspect &&
           scored.total > scoreBest.scored.total);
        if (better) scoreBest = { buf: outBuf, punch, scored };
        log(`[studio] adjudicator attempt ${attempts}: ${scored.total}/${scored.threshold}` +
            ` ${STUDIO_SCORE_KEYS.map((k) => k[0] + scored.cats[k]).join(" ")}` +
            (scored.floorFails.length ? ` FLOOR:${scored.floorFails.join(",")}` : "") +
            (scored.caps && scored.caps.length ? ` CAPPED:${scored.caps.join(",")}` : "") +
            (scored.unmarked && scored.unmarked.length
              ? ` NOTMARKED:${scored.unmarked.join(",")}` : "") +
            (scored.fabricated.length ? ` INVENTED:${scored.fabricated.join("|")}` : "") +
            (scored.suspect ? ` SUSPECT:${(scored.suspectWhy || []).join(",")}` : "") +
            ` [${scored.model || "?"}] (${scored.ms}ms)`);
        if (scored.suspect) {
          log(`[studio] adjudicator answer NOT TRUSTED — it is not gating this ` +
              `render. Reply was: ${String(scored.reply || "").slice(0, 300)}`);
        } else if (scored.unmarked && scored.unmarked.length) {
          /* the half-credit case, said out loud: this verdict IS gating the
             render, on the categories the judge proved it could read */
          log(`[studio] adjudicator misread the map's ` +
              `${(scored.examWrong || []).join(", ")} — ` +
              `${scored.unmarked.join(", ")} left unmarked; the rest of the ` +
              `verdict still gates this render`);
        }
      } else {
        log(`[studio] adjudicator attempt ${attempts}: no verdict — accepting`);
      }
    }
    /* the budget must account for the judge too, or three scored attempts
       overrun a limit that was measured for three bare renders */
    lastMs = now() - t0;

    /* EVERY IMAGE MADE GETS A ROW, whatever happened to it after. `judged`
       is the honest distinction the panel needs: an unjudged attempt has no
       scores rather than bad ones, and printing a zero for it would read as
       the worst render of the run when it is the unmeasured one. */
    attemptLog.push({
      n: attempts,
      ms: lastMs,
      judged: !!scored,
      /* what the geometric check made of this image, which is a fact about
         the image even when no model would grade it */
      cut: punch && punch.report
        ? (punch.report.verified ? "ok" : String(punch.report.reason || "")) : "",
      /* the geometric fact about this image, on every row, whether or not
         anything asked for a retry because of it */
      iou: lastShape && lastShape.iou != null ? lastShape.iou : null,
    });

    /* ── A DISTRUSTED VERDICT MAY OBJECT. IT MAY NOT APPROVE. ───────────
       "Suspect" used to mean the verdict decided nothing at all — it could
       neither pass a render nor spend a retry. That was built to stop a
       template-filler rubber-stamping everything, and for passing it is
       exactly right. For failing it is exactly wrong, and the asymmetry is
       the whole point:

         · a verdict that wrongly PASSES ships a bad charm to a customer
         · a verdict that wrongly FAILS spends one more render

       Those are not comparable costs, so they must not share a rule. The
       camera charm is what made it plain: the map holds two openings, the
       judge read one — which disqualifies it from vouching for anything —
       and then reported one opening in the render and said the centre ring
       had come out as two thin lines. The render really had lost a hole.
       Every safeguard fired correctly, the verdict was binned as untrusted,
       and the flawed charm shipped anyway with a banner about the check.

       So trust now gates the PASS only. A suspect verdict that wants to
       reject is allowed to buy a retry — but one, not the full allowance,
       because a judge that cannot count the map is a poor guide to how many
       more attempts are worth paying for. A trusted verdict spends the full
       renderScoreRetries as before. */
    const trusted = !!scored && !scored.suspect;
    const cutWants = !!punch && retryable(punch.report) && attempts <= maxRetries;
    /* the pass is the thing trust buys: an untrusted verdict can never be
       the reason a render is accepted, which is unchanged */
    const scoreAllowance = trusted ? scoreRetries : Math.min(1, scoreRetries);
    const scoreWants = adjMode === "enforce" && !!scored && !scored.pass &&
                       attempts <= scoreAllowance;
    if (scoreWants && !trusted) {
      log(`[studio] adjudicator attempt ${attempts} is NOT TRUSTED, but it is ` +
          `objecting rather than approving — spending one retry on it`);
    }
    /* the gate spends its own allowance, independent of the other two, because
       "this is a different charm" is a different complaint from "this charm is
       not good enough" and neither should exhaust the other's budget */
    const shapeWants = shaping && !!lastShape && lastShape.iou != null &&
                       !lastShape.ok && attempts <= shapeRetries;
    if (!cutWants && !shapeWants && !scoreWants) break;
    /* ── THREE IMAGES, EVER ───────────────────────────────────────────────
       Three judges can each ask for another attempt and each carries its own
       allowance, so the worst case was the sum of three budgets rather than
       any one of them. One ceiling over all of them: the original render and
       at most two re-rolls. It is the number the storefront's counter shows
       as the denominator, so the two must not be able to disagree. */
    if (attempts >= STUDIO_MAX_RENDER_ATTEMPTS) {
      log(`[studio] attempt ceiling reached (${attempts}/${STUDIO_MAX_RENDER_ATTEMPTS})` +
          ` — shipping the best attempt so far`);
      break;
    }

    if (cutWants) failedVerdicts.push(punch.report.reason);
    if (shapeWants) failedVerdicts.push(lastShape.why || "wrong_shape");
    const spent = now() - startedAt;
    if (retryBudgetMs && spent + lastMs > retryBudgetMs) {
      log(`[studio] retry budget reached (${spent}ms + ${lastMs}ms > ${retryBudgetMs}ms)` +
          (scoreWants ? " — shipping the best attempt so far" : ""));
      break;
    }
    /* MOST SPECIFIC COMPLAINT WINS THE WORDING. The cut check names a region;
       the shape gate names the outline; the score names a category. Telling a
       model three things at once is how a correction note stops correcting
       anything. */
    nextNote = cutWants ? studioRetryNote(punch.report, attempts, opts.builtInHoop)
             : shapeWants ? (lastShape.why === "frame_furniture" ? studioFrameRetryNote(attempts)
                            : lastShape.why === "two_tone_metal" ? studioAlloyRetryNote(attempts)
                            : lastShape.why === "engraving_filled" ? studioEngraveRetryNote(attempts)
                            : lastShape.why === "engraving_too_dark" ? studioEngraveToneRetryNote(lastShape, attempts)
                            : lastShape.why === "aspect_drift" ? studioAspectRetryNote(lastShape, attempts)
                            : lastShape.why === "outline_mismatch"
                              ? studioShapeRetryNote(lastShape, attempts, opts.builtInHoop)
                            : studioShapeRetryNote(lastShape, attempts, opts.builtInHoop))
             : studioScoreRetryNote(scored, attempts);
    log(`[studio] render retry ${attempts}/` +
        (cutWants ? maxRetries : shapeWants ? shapeRetries : scoreAllowance) + ` after ` +
        (cutWants ? punch.report.reason
                  : shapeWants ? `${lastShape.why} (IoU ${lastShape.iou}, stray ` +
                                 `${lastShape.furniture ? lastShape.furniture.biggest : "?"}, off-alloy ` +
                                 `${lastShape.alloy ? lastShape.alloy.offAlloy : "?"})`
                  : `score ${scored.total}`));
  }

  /* ── IF EVERY ATTEMPT DRIFTED, THE CLOSEST ONE SHIPS ──────────────────
     Only when the adjudicator did not pick a winner of its own, so the two
     selections can never contradict each other. When it did, its choice
     stands: a scored verdict looks at the whole picture and this number does
     not. */
  if (shaping && !scoreBest && shapeBest && lastShape && !lastShape.ok &&
      shapeBest.badness < (lastShape.badness == null ? Infinity : lastShape.badness)) {
    log(`[studio] every attempt failed — shipping attempt ${shapeBest.attempt} ` +
        `(${shapeBest.why}, badness ${shapeBest.badness.toFixed(2)}) rather than the ` +
        `last one (badness ${(lastShape.badness || 0).toFixed(2)})`);
    outBuf = shapeBest.buf;
    lastShape = { iou: shapeBest.iou, ok: false, why: shapeBest.why,
                  badness: shapeBest.badness, ms: 0, swapped: true };
  }

  /* ── THE BEST ONE SHIPS, NOT THE LAST ONE ───────────────────────────────
     A third attempt can easily score below the second. Returning whatever
     came out of the final iteration would mean the customer sometimes gets a
     worse charm BECAUSE the studio tried harder, which is the one outcome
     this subsystem must not produce. In "observe" nothing is swapped: that
     mode's whole promise is that the image is returned untouched.

     AN UNSCORED ATTEMPT IS NOT A CANDIDATE. If the judge fails on the last
     attempt but scored an earlier one, the earlier one ships even though its
     score was poor — "the highest rated" can only mean the highest of the
     ones that were actually rated, and an unmeasured render is not evidence
     of anything. When NO attempt could be scored, scoreBest is null, nothing
     is swapped, and the last render ships exactly as it would have with the
     whole subsystem off. */
  /* ── AND THE PANEL REPORTS THE ONE THAT SHIPPED ────────────────────────
     `shipped` is the buffer, the punch and the VERDICT THAT BELONGS TO IT,
     resolved in one place so the readout cannot describe a different image
     from the one the customer received. The record was built from scoreBest
     whether or not the swap happened, so a run whose attempts were all
     distrusted — now reachable, because a distrusted verdict can spend a
     retry — printed "showing #1" over the second render's picture. The
     numbers were real and belonged to the wrong image, which is the worst
     kind of wrong a readout can be. */
  let shipped = { buf: outBuf, punch, scored: lastScored };
  if (adjMode === "enforce" && scoreBest && !scoreBest.scored.suspect && scoreBest.buf !== outBuf) {
    log(`[studio] adjudicator: shipping attempt ${scoreBest.scored.attempt} ` +
        `(${scoreBest.scored.total}) over the last one`);
    shipped = scoreBest;
    outBuf = scoreBest.buf;
    punch = scoreBest.punch;
  }
  return { outBuf, punch, attempts, failedVerdicts, scoreLog, attemptLog,
           scoreBest, shipped, shape: lastShape, shapeBest };
}

/* ── version doc: what drives the client's staged progress bar ───────────
   The storefront subscribes to customSessions/{sid}/versions/{n} and narrates
   `stage` back to the customer as it moves. Every write is best-effort — a
   Firestore hiccup must never fail a generation the customer already paid for. */
async function studioStage(vRef, patch) {
  try { await vRef.set(patch, { merge: true }); } catch (_e) {}
}

async function handleStudioPrecheck({ body, event, origin }) {
  const uid = await requireStudioUser(event);
  const cfg = await studioConfig();
  const p = String(body?.input_storage_path || "").trim();
  if (!p.startsWith(`custom-studio/${uid}/`)) {
    return studioJson(403, { ok: false, error: "forbidden" }, origin);
  }
  /* Shares the per-account ceiling, which ships switched off — see the note
     beside STUDIO_MAX_GENS_HOUR_UID. With no ceiling configured this reads
     nothing and counts nothing. */
  const pcCeil = (await studioCeilings()).uid;
  if (pcCeil && !(await studioUnlimitedUid(uid)) &&
      !(await studioBudgetOk("pc", uid, pcCeil))) {
    return studioJson(429, { ok: false, error: "rate_limited" }, origin);
  }

  const img = await storagePathToBuffer(p);
  let verdict;
  try {
    verdict = await studioVisionVerdict(img);
  } catch (err) {
    // Never block a customer because the checker was unavailable — the
    // generation applies the same doctrine again, server-side. The upload is
    // still metered, so a checker outage can't turn the allowance off.
    console.error("[studio] precheck unavailable:", err?.message || err);
    if (!(await studioMeterUpload(uid, cfg))) {
      return studioJson(402, { ok: false, error: "no_uploads_left" }, origin);
    }
    return studioJson(200, { ok: true, usable: true, degraded: true, reason: "" }, origin);
  }

  if (verdict.usable) {
    if (!(await studioMeterUpload(uid, cfg))) {
      return studioJson(402, { ok: false, error: "no_uploads_left" }, origin);
    }
  }
  return studioJson(200, {
    ok: true,
    usable: !!verdict.usable,
    verdict: verdict.usable ? "ok" : "rejected",
    subject: verdict.subject || null,
    reason: verdict.usable
      ? ""
      : (verdict.reason || "That image won't translate into a charm — try one with a single, clearly outlined subject."),
  }, origin);
}

/* A refusal decided before any work starts still has to reach the shopper, and
   from a background invocation the HTTP response cannot. This puts it on the
   version doc, which the studio is already watching. Best-effort by design:
   failing to report a failure must not become a second failure. */
/* Shopify's img_url filter returns a PROTOCOL-RELATIVE url — "//host/path",
   no scheme. A browser resolves that against the page it is on and it works
   everywhere on the storefront, which is why it rides all the way through the
   feed templates and into the saved session without anyone noticing. There is
   no page here. Node's fetch() has nothing to resolve against and rejects it
   outright with "Failed to parse URL from //…", killing the generation before
   a single pixel is drawn. One line, and it also repairs every session already
   saved with a bare "//" reference. */
function studioAbsoluteUrl(u) {
  const s = String(u || "").trim();
  if (s.startsWith("//")) return "https:" + s;
  if (s.startsWith("/"))  return "https://britesjewelry.com" + s;
  return s;
}

async function studioFailVersion(vRef, n, error) {
  try {
    await vRef.set({
      n: Number(n) || null,
      status: "failed", stage: "failed", error: String(error).slice(0, 300),
      failedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });
  } catch (e) {
    console.error("[studio] could not record failure:", e?.message || e);
  }
}

async function handleStudioGenerate({ kind, body, event, origin }) {
  const uid = await requireStudioUser(event);
  const cfg = await studioConfig();
  const cost = Number(cfg.generateCost) || 1;
  const db = getDb();

  const sessionId = String(body?.sessionId || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 60);
  if (!sessionId) return studioJson(400, { ok: false, error: "missing_session" }, origin);

  /* Ownership is checked FIRST, ahead of the rate limits, and the order is
     deliberate. Everything after this point is allowed to write a failure into
     the caller's own version doc — and it has to, because this function is
     invoked in the background: Netlify answers the browser with its own 202
     and the JSON we return here is read by nobody. A refusal that only exists
     as an HTTP status is a refusal the shopper never sees; they just watch a
     progress bar until the client's timeout gives up, with no reason given.
     Writing it to the version doc puts it on the same channel as every other
     outcome — the onSnapshot listener the studio is already holding open. */
  const sRef = db.collection(STUDIO_SESSIONS_COLL).doc(sessionId);
  const sSnap = await sRef.get();
  if (!sSnap.exists || sSnap.data().uid !== uid) {
    /* NOT reported to the version doc: this caller does not own this session,
       so writing into it would be handing them a channel into someone else's
       design. The HTTP 403 is the whole answer. */
    return studioJson(403, { ok: false, error: "forbidden" }, origin);
  }
  const session = sSnap.data();

  const n = Number(body?.versionNumber) || (Number(session.currentVersion) || 0) + 1;
  const vRef = sRef.collection("versions").doc(String(n));

  if (!(await studioGateOk(uid, event))) {
    await studioFailVersion(vRef, n, "rate_limited");
    return studioJson(429, { ok: false, error: "rate_limited" }, origin);
  }

  // 1) atomic debit, BEFORE any upstream call
  try {
    await studioDebit(uid, cost, sessionId);
  } catch (err) {
    if (err?.status === 402) {
      await studioFailVersion(vRef, n, "out_of_credits");
      return studioJson(402, { ok: false, error: "out_of_credits" }, origin);
    }
    throw err;
  }
  const instructions = studioCleanText(body?.instructions);
  const metal = studioCleanText(body?.metal || session.metal || "gold");
  const isRefine = kind === "custom_charm_refine" && n > 1;

  await studioStage(vRef, {
    n, status: "queued", stage: "queued",
    instructions, refineText: studioCleanText(body?.refineText), metal,
    createdAt: admin.firestore.FieldValue.serverTimestamp(),
  });

  try {
    await studioStage(vRef, { status: "generating", stage: "planning" });

    // The reference: an uploaded object, or the chosen product's image fetched
    // SERVER-side rather than trusting a client-supplied URL.
    const ref = session.reference || {};
    let refImg = null;
    if (ref.type === "upload" && ref.path) {
      if (!String(ref.path).startsWith(`custom-studio/${uid}/`)) {
        throw new Error("reference outside your own storage");
      }
      refImg = await storagePathToBuffer(ref.path);
    } else if (ref.type === "catalog" && ref.item && ref.item.image) {
      const r = await fetch(studioAbsoluteUrl(ref.item.image));
      if (!r.ok) throw new Error(`reference image fetch ${r.status}`);
      refImg = {
        mime: r.headers.get("content-type") || "image/jpeg",
        buffer: Buffer.from(await r.arrayBuffer()),
      };
    }
    if (!refImg) throw new Error("no reference image on this session");

    const images = [
      { buffer: refImg.buffer, mime: refImg.mime, filename: filenameForMime("reference", refImg.mime) },
    ];
    let hasPrev = false;
    if (isRefine) {
      try {
        const prev = await storagePathToBuffer(
          `custom-studio/${uid}/uploads/designs/${sessionId}/v${n - 1}.png`
        );
        images.push({ buffer: prev.buffer, mime: prev.mime, filename: filenameForMime("previous", prev.mime) });
        hasPrev = true;
      } catch (_e) {
        // first refine after a restore, or the prior version is gone — the
        // direction log alone carries the context
      }
    }

    /* The customer's own markup of the previous drawing — circles, highlights
       and text bubbles composited client-side onto the drawing they refer to.
       It rides the request body (a background invocation caps the payload at
       256 KB, so the client ships a tightly compressed JPEG) and enters the
       generation as DIRECTION, never as subject: the role label and the lock
       both forbid its ink from appearing in the output. Only meaningful on a
       refine, and only when the previous drawing made it into the request —
       markup with no drawing under it would point at nothing. */
    let markupNotes = [];
    let markupZones = [];                      // the engraving instruction, as data
    let markupMode = null;                     // set ONLY when a markup image is accepted
    if (isRefine && hasPrev && typeof body?.markupImage === "string") {
      const mm = /^data:image\/(png|jpeg);base64,([A-Za-z0-9+/=]+)$/.exec(body.markupImage.trim());
      if (mm) {
        const buf = Buffer.from(mm[2], "base64");
        if (buf.length > 0 && buf.length <= 1.5 * 1024 * 1024) {
          images.push({ buffer: buf, mime: "image/" + mm[1], filename: "markup." + (mm[1] === "png" ? "png" : "jpg") });
          markupNotes = Array.isArray(body.markupNotes) ? body.markupNotes : [];
          markupZones = Array.isArray(body.markupZones) ? body.markupZones : [];
          markupMode = String(body.markupMode) === "exact" ? "exact" : "interpret";
        }
      }
    }

    // Same pipeline the Charm Maker runs: a text-only prompt audit, then
    // exactly ONE image generation with the backend's final geometry and
    // background override appended after every role label.
    /* The design step draws in B/W. No geometry or background policy is
       passed DELIBERATELY: both append photoreal-metal / black-background
       overrides that would outrank the line-art contract — the exact same
       reason the Charm Maker's own B/W call passes neither. The contract
       carries the geometry rules in drawing terms instead. */
    const refMode = body?.refMode === "exact" ? "exact"
                  : body?.refMode === "interpret" ? "interpret" : null;
    /* the fill law, as data, for a reference the customer drew themselves */
    const refZones = studioZoneList(body?.refZones, "refLineArt");
    const basePrompt = buildCustomerLineArtPrompt({
      instructions, thread: body?.thread, refine: isRefine, markupNotes, markupZones, markupMode,
      refMode, refZones,
    });
    let effectivePrompt = basePrompt;
    try {
      const audited = await auditCharmPromptPreflight({
        prompt: basePrompt,
        backgroundPolicy: null,
        geometryPolicy: null,
        editIntent: null,
        imageCount: images.length,
        imageRoles: "customer_lineart",
      });
      if (audited) effectivePrompt = audited;
    } catch (_e) { /* best effort — never blocks a paid generation */ }
    /* THE LAW IS NOT NEGOTIABLE, INCLUDING BY OUR OWN AUDITOR. The prompt
       goes through a preflight model asked to smooth out contradictions,
       which may return as little as a third of what it was handed.
       Everything else here can survive being rephrased; this cannot, because
       what it governs is whether there is a hole in somebody's jewellery.
       So it is re-stated verbatim afterwards if the audit dropped it. */
    if ((refMode || isRefine || markupMode || refZones.length) &&
        effectivePrompt.indexOf("AREA FILL — THREE MEANINGS") < 0) {
      /* THE MARK-UP'S LIST WINS. It is the more specific account of the two
         and it is the one the customer is looking at; preferring the
         reference's list here re-stated an older census of the same charm
         underneath the newer one. */
      effectivePrompt += "\n\n" + FILL_LAW +
        (zoneBlock(markupZones) || zoneBlock(refZones, "reference") || "");
    }

    await studioStage(vRef, { stage: "generating" });

    const studioModelConfig = resolveImageModel(studioImageModelId(cfg));
    /* NOT named studioTier: that is a module-level function, and a const of
       the same name inside this scope would shadow it — silently here, and as
       a TDZ throw the moment anything above this line reached for it. */
    const drawingTier = studioDrawingTier(cfg);
    let outBuf = await callImageModelEdits({
      apiKey: apiKeyForImageModel(studioModelConfig),
      model: studioModelConfig.id,
      prompt: effectivePrompt,
      size: studioImageSizeString(drawingTier),
      imageSizeTier: drawingTier,
      quality: "high",
      output_format: "png",
      images,
      imageRoles: "customer_lineart",
      charmGeometryPolicy: null,
      backgroundPolicy: null,
    });

    await studioStage(vRef, { stage: "polishing" });

    // The design description travels inside the PNG, so it survives download,
    // the production queue and the customer's own copy.
    outBuf = embedPngTextMetadata(outBuf, {
      Description: `Custom Charm Studio production drawing — ${instructions || "customer reference"}. Version ${n}.`,
      CharmTitle: `Custom charm drawing v${n}`,
    });

    // NOTE the "uploads" segment: templates/cart.liquid and
    // snippets/ajax-cart-template.liquid render a clickable thumbnail for any
    // cart line property whose value contains "uploads" plus an image
    // extension, so the customer sees their design as a picture in the cart.
    const storagePath = `custom-studio/${uid}/uploads/designs/${sessionId}/v${n}.png`;
    const bucket = getBucket();
    const token = newDownloadToken();
    await bucket.file(storagePath).save(outBuf, {
      resumable: false,
      contentType: "image/png",
      metadata: { metadata: { firebaseStorageDownloadTokens: token, uid, sessionId, version: String(n) } },
    });
    const downloadURL = tokenDownloadURLFor(bucket.name, storagePath, token);

    /* Build the Greyscale Mask now, so the customer sees both pictures before
       paying for a render. Never allowed to fail this step. */
    let specURL = "", specPath = "", specReuse = null;
    try {
      const sp = await studioStoreSpecForVersion({
        uid, sessionId, n, metal,
        drawingBuffer: outBuf, zones: [],
      });
      if (sp) {
        specURL = sp.specURL; specPath = sp.specPath;
        /* THE MAP THE RENDER WILL REUSE. Filed under the render's own field
           names and with its fingerprint, so the first press of Re-render
           recognises this map instead of rebuilding it to identical bytes. */
        specReuse = {
          renderSpecURL: sp.specURL, renderSpecPath: sp.specPath,
          renderSpecKey: sp.specKey, renderSpecMode: "deterministic-material",
          renderSpecFacePx: sp.facePx, renderSpecHolePx: sp.holePx,
          renderSpecWorkPx: sp.workPx,
        };
      }
    } catch (e) { console.error("[studio] greyscale mask at generation skipped:", e?.message || e); }

    await studioStage(vRef, Object.assign({
      status: "done", stage: "done", storagePath, downloadURL,
      specURL, specPath,
      prompt: String(effectivePrompt).slice(0, 4000),
      model: studioModelConfig.id,
      doneAt: admin.firestore.FieldValue.serverTimestamp(),
    }, specReuse || {}));
    try {
      await sRef.set({
        currentVersion: n,
        updatedAtServer: admin.firestore.FieldValue.serverTimestamp(),
      }, { merge: true });
    } catch (_e) {}

    return studioJson(200, { ok: true, n, storagePath, downloadURL }, origin);
  } catch (err) {
    // A failed generation must never cost a credit.
    await studioRefund(uid, cost, sessionId);
    await studioStage(vRef, {
      status: "failed", stage: "failed",
      error: String(err?.message || err).slice(0, 300),
    });
    console.error("[studio] generate failed:", err?.message || err);
    return studioJson(500, { ok: false, error: "generation_failed" }, origin);
  }
}


/* ═══════════ DECLARED CUT-OUTS, PUNCHED DETERMINISTICALLY ════════════════
   The studio KNOWS every hole before a render is ever requested: the customer
   declared it and the production drawing carries it in blue. Asking a
   generative model to re-derive that from a coloured region is the one
   probabilistic step in an otherwise deterministic pipeline, and it fails in
   both directions — a declared hole rendered as engraving, and metal cut away
   that nobody declared. So the model is no longer asked. It renders metal;
   the openings are cut here, in arithmetic.

   THE ONLY HARD PART is telling a blue AREA from a blue LINE: the perimeter
   and the hoop are drawn in the same instruction blue, and punching those
   would delete the face of the charm. They separate by LOCAL THICKNESS
   against the drawing's own pen width, which is scale-free. Measured on a
   real studio drawing: three genuine fills at 1.9–3.2x the pen, four lines
   (silhouette, hoop, two strokes) at 0.6–1.0x. A gap that wide is a rule,
   not a tuned threshold.
   ===================================================================== */
let _sharpMod = null, _sharpTried = false;
function studioSharp() {
  if (_sharpTried) return _sharpMod;
  _sharpTried = true;
  /* NEVER LOAD-BEARING. Sharp is a native module and this repo has watched it
     fail to package before. If it is not there the render still ships — it is
     simply recorded as unverified, which is strictly better than a charm the
     customer cannot buy. */
  try { _sharpMod = require("sharp"); }
  catch (err) {
    console.error("[studio] sharp unavailable — cut-out punch disabled:", err?.message || err);
    _sharpMod = null;
  }
  return _sharpMod;
}

const studioIsBluePixel = (px, p) => {
  const r = px[p], g = px[p + 1], b = px[p + 2];
  /* Same tolerant classifier as the browser's reserved-blue reader. It is
     deliberately about hue dominance, not an exact hex value, so antialiasing
     around a one-pixel edge does not erase the instruction. */
  return b - (r > g ? r : g) > 28 && b > 120;
};
const studioIsRedPixel = (px, p) => {
  const r = px[p], g = px[p + 1], b = px[p + 2];
  const lum = 0.299 * r + 0.587 * g + 0.114 * b;
  return r - (g > b ? g : b) > 45 && r > 105 && lum < 220;
};

function studioBlueMask(px, n, stride) {
  const m = new Uint8Array(n);
  for (let i = 0, p = 0; i < n; i++, p += stride) {
    if (studioIsBluePixel(px, p)) m[i] = 1;
  }
  return m;
}

function studioRedMask(px, n, stride) {
  const m = new Uint8Array(n);
  for (let i = 0, p = 0; i < n; i++, p += stride) {
    if (studioIsRedPixel(px, p)) m[i] = 1;
  }
  return m;
}

/* 4-connected components, iterative — recursion blows the stack on a 2K image
   long before it finds anything interesting. */
function studioLabel(mask, w, h) {
  const labels = new Int32Array(w * h);
  const stack = new Int32Array(w * h);
  let count = 0;
  for (let s = 0; s < w * h; s++) {
    if (!mask[s] || labels[s]) continue;
    count++;
    let top = 0;
    stack[top++] = s; labels[s] = count;
    while (top) {
      const i = stack[--top], x = i % w, y = (i / w) | 0;
      if (x > 0     && mask[i - 1] && !labels[i - 1]) { labels[i - 1] = count; stack[top++] = i - 1; }
      if (x < w - 1 && mask[i + 1] && !labels[i + 1]) { labels[i + 1] = count; stack[top++] = i + 1; }
      if (y > 0     && mask[i - w] && !labels[i - w]) { labels[i - w] = count; stack[top++] = i - w; }
      if (y < h - 1 && mask[i + w] && !labels[i + w]) { labels[i + w] = count; stack[top++] = i + w; }
    }
  }
  return { labels, count };
}

function studioLargestComponent(mask, w, h) {
  const { labels, count } = studioLabel(mask, w, h);
  if (!count) return mask;
  const size = new Float64Array(count + 1);
  for (let i = 0; i < w * h; i++) if (labels[i]) size[labels[i]]++;
  let best = 1;
  for (let L = 2; L <= count; L++) if (size[L] > size[best]) best = L;
  const out = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) if (labels[i] === best) out[i] = 1;
  return out;
}

function studioDilate(mask, w, h, r) {
  let a = mask;
  for (let k = 0; k < r; k++) {
    const b = new Uint8Array(w * h);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (a[i] || (x && a[i - 1]) || (x < w - 1 && a[i + 1]) ||
            (y && a[i - w]) || (y < h - 1 && a[i + w])) b[i] = 1;
      }
    }
    a = b;
  }
  return a;
}

/* 3-4 chamfer distance, two passes. Divided by three it is within a few
   percent of Euclidean — far more precision than a RATIO needs. */
function studioChamfer(mask, w, h) {
  const d = new Float32Array(w * h);
  for (let i = 0; i < w * h; i++) d[i] = mask[i] ? 1e9 : 0;
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const i = y * w + x; if (!mask[i]) continue;
    let v = d[i];
    if (y > 0)              v = Math.min(v, d[i - w] + 3);
    if (y > 0 && x > 0)     v = Math.min(v, d[i - w - 1] + 4);
    if (y > 0 && x < w - 1) v = Math.min(v, d[i - w + 1] + 4);
    if (x > 0)              v = Math.min(v, d[i - 1] + 3);
    d[i] = v;
  }
  for (let y = h - 1; y >= 0; y--) for (let x = w - 1; x >= 0; x--) {
    const i = y * w + x; if (!mask[i]) continue;
    let v = d[i];
    if (y < h - 1)              v = Math.min(v, d[i + w] + 3);
    if (y < h - 1 && x < w - 1) v = Math.min(v, d[i + w + 1] + 4);
    if (y < h - 1 && x > 0)     v = Math.min(v, d[i + w - 1] + 4);
    if (x < w - 1)              v = Math.min(v, d[i + 1] + 3);
    d[i] = v;
  }
  for (let i = 0; i < w * h; i++) d[i] /= 3;
  return d;
}

/* ── THE PEN, MEASURED ON EVERY MARK ──────────────────────────────────────
   This used to take the pen from the LONGEST component of the colour being
   tested, on the reasoning that the longest blue thing is the silhouette and a
   silhouette is one pen wide. That held only while the silhouette was drawn in
   blue. On a drawing whose perimeter is BLACK there is no blue line to
   calibrate against, so the longest blue component is a FILL — the estimate
   came back five times too thick and every genuine cut-out was dismissed as a
   line. Measured on a real drawing: three fills at 7.7-11.0px against a "pen"
   of 11.0, so the detector found nothing at all.

   The pen is now the MEDIAN thickness of every inked pixel in the drawing,
   whatever its colour. Line work always dominates a production drawing by
   pixel count, so the median lands on the pen and is unmoved by how many fills
   there are or what colour anything is: it measured 2.0px on both a
   blue-silhouette drawing and a black-silhouette one. */
function studioPenWidth(px, w, h, scope) {
  const n = w * h;
  const ink = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    if (scope && !scope[i]) continue;
    const p = i * 3;
    if (studioIsBluePixel(px, p) || studioIsRedPixel(px, p) || studioIsBlack(px, p)) ink[i] = 1;
  }
  const d = studioChamfer(ink, w, h);
  const v = [];
  for (let i = 0; i < n; i++) if (ink[i]) v.push(d[i]);
  if (!v.length) return 1;
  v.sort((a, b) => a - b);
  return Math.max(1, v[v.length >> 1]);
}

function studioCutRegions(mask, w, h, minRatio, penIn) {
  /* Primary discriminator: local thickness against the drawing's pen.
     Secondary discriminator: component fill density. The density path exists
     for exactly the failure a thick engraved border exposed: the global pen
     estimate can be biased upward by a large black band, while a genuine blue
     fill is still visibly a filled blob. A blue perimeter remains extremely
     sparse inside its own bounding box, so density separates the two without
     asking a model or using a magic absolute pixel width. */
  const ratio0 = minRatio || 2.5;
  const { labels, count } = studioLabel(mask, w, h);
  const cut = new Uint8Array(w * h);
  if (!count) return { cut, areas: 0, lines: 0, pen: 0, cutPx: 0 };
  const dist = studioChamfer(mask, w, h);
  const size = new Float64Array(count + 1), maxd = new Float64Array(count + 1);
  const x0 = new Int32Array(count + 1); x0.fill(w);
  const y0 = new Int32Array(count + 1); y0.fill(h);
  const x1 = new Int32Array(count + 1); x1.fill(-1);
  const y1 = new Int32Array(count + 1); y1.fill(-1);
  for (let i = 0; i < w * h; i++) {
    const L = labels[i]; if (!L) continue;
    const x = i % w, y = (i / w) | 0;
    size[L]++; if (dist[i] > maxd[L]) maxd[L] = dist[i];
    if (x < x0[L]) x0[L] = x; if (x > x1[L]) x1[L] = x;
    if (y < y0[L]) y0[L] = y; if (y > y1[L]) y1[L] = y;
  }
  const pen = penIn || 1;
  const minPx = Math.max(24, Math.round(w * h * 0.00002));
  const keep = new Uint8Array(count + 1);
  let areas = 0, lines = 0, cutPx = 0;
  for (let L = 1; L <= count; L++) {
    const bw = x1[L] - x0[L] + 1, bh = y1[L] - y0[L] + 1;
    const density = size[L] / Math.max(1, bw * bh);
    const thickEnough = maxd[L] / pen >= ratio0;
    const denseFill = density >= 0.24 && Math.min(bw, bh) >= Math.max(4, pen * 1.8);
    if ((thickEnough || denseFill) && size[L] >= minPx) { keep[L] = 1; areas++; }
    else lines++;
  }
  for (let i = 0; i < w * h; i++) if (labels[i] && keep[labels[i]]) { cut[i] = 1; cutPx++; }
  return { cut, areas, lines, pen, cutPx };
}

/* Everything the frame cannot reach across background. Enclosed background is
   NOT reached, so this is the charm's outer boundary with its holes filled —
   which is exactly what makes a drawing and a photograph comparable. */
function studioOuterFace(isWall, w, h) {
  const n = w * h;
  const outside = new Uint8Array(n), stack = new Int32Array(n);
  let top = 0;
  const push = (i) => { if (!outside[i] && !isWall[i]) { outside[i] = 1; stack[top++] = i; } };
  for (let x = 0; x < w; x++) { push(x); push((h - 1) * w + x); }
  for (let y = 0; y < h; y++) { push(y * w); push(y * w + w - 1); }
  while (top) {
    const i = stack[--top], x = i % w, y = (i / w) | 0;
    if (x > 0) push(i - 1);
    if (x < w - 1) push(i + 1);
    if (y > 0) push(i - w);
    if (y < h - 1) push(i + w);
  }
  const face = new Uint8Array(n);
  for (let i = 0; i < n; i++) face[i] = outside[i] ? 0 : 1;
  /* one continuous piece, by doctrine — so stray marks outside the charm
     (a label, a speck) cannot distort the bounding box the whole registration
     depends on */
  return studioLargestComponent(face, w, h);
}

function studioBBox(mask, w, h) {
  let x0 = w, y0 = h, x1 = -1, y1 = -1;
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    if (!mask[y * w + x]) continue;
    if (x < x0) x0 = x; if (x > x1) x1 = x;
    if (y < y0) y0 = y; if (y > y1) y1 = y;
  }
  if (x1 < 0) return null;
  return { x0, y0, x1, y1, w: x1 - x0 + 1, h: y1 - y0 + 1 };
}

/* ── MANUFACTURING-COLOUR ROI ─────────────────────────────────────────────
   UI chrome must never become charm geometry. The production drawing already
   carries reserved manufacturing colours, so BLUE/RED are the authoritative
   locator for the drawing itself. We first find their bounding box, pad it,
   and then allow structural analysis ONLY inside that ROI. Grey frames,
   labels, card borders and screenshot furniture outside the ROI become
   mathematically incapable of enclosing the charm. */
function studioManufacturingROI(px, w, h) {
  const n = w * h;
  const signal = new Uint8Array(n);
  let count = 0;
  for (let i = 0; i < n; i++) {
    const p = i * 3;
    if (studioIsBluePixel(px, p) || studioIsRedPixel(px, p)) { signal[i] = 1; count++; }
  }
  const signalBox = studioBBox(signal, w, h);
  /* The studio's production contract requires a BLUE outer perimeter, so on
     current drawings this is the strongest possible locator. Old/imported
     drawings without enough reserved-colour pixels fall back to the previous
     full-canvas analysis rather than being guessed at. */
  const minSignalPx = Math.max(24, Math.round(n * 0.00001));
  if (!signalBox || count < minSignalPx) return { mask: null, box: null, signalBox: null, signalPx: count, mode: "legacy-full-canvas" };

  const span = Math.max(signalBox.w, signalBox.h);
  const pad = Math.max(10, Math.round(span * 0.065));
  const box = {
    x0: Math.max(0, signalBox.x0 - pad),
    y0: Math.max(0, signalBox.y0 - pad),
    x1: Math.min(w - 1, signalBox.x1 + pad),
    y1: Math.min(h - 1, signalBox.y1 + pad),
  };
  box.w = box.x1 - box.x0 + 1; box.h = box.y1 - box.y0 + 1;
  const mask = new Uint8Array(n);
  for (let y = box.y0; y <= box.y1; y++) {
    const row = y * w;
    for (let x = box.x0; x <= box.x1; x++) mask[row + x] = 1;
  }
  return { mask, box, signalBox, signalPx: count, mode: "manufacturing-colour-roi" };
}

function studioRestrictMask(mask, scope) {
  if (!scope) return mask;
  const out = new Uint8Array(mask.length);
  for (let i = 0; i < mask.length; i++) if (scope[i] && mask[i]) out[i] = 1;
  return out;
}

function studioFaceLooksSane(faceBox, signalBox) {
  if (!faceBox || !signalBox) return false;
  /* The reserved-colour box already contains the blue outer cut perimeter and
     hoop on current production drawings. A detected face much larger than it
     is therefore a frame/UI enclosure, not the charm. */
  const maxW = signalBox.w * 1.30 + 12;
  const maxH = signalBox.h * 1.30 + 12;
  const minW = Math.max(4, signalBox.w * 0.45);
  const minH = Math.max(4, signalBox.h * 0.45);
  return faceBox.w <= maxW && faceBox.h <= maxH && faceBox.w >= minW && faceBox.h >= minH;
}


function studioPadBox(box, w, h, padX, padY) {
  if (!box) return null;
  const px = Math.max(0, padX | 0), py = Math.max(0, padY | 0);
  const x0 = Math.max(0, box.x0 - px), y0 = Math.max(0, box.y0 - py);
  const x1 = Math.min(w - 1, box.x1 + px), y1 = Math.min(h - 1, box.y1 + py);
  return { x0, y0, x1, y1, w: x1 - x0 + 1, h: y1 - y0 + 1 };
}

function studioBoxArea(box) {
  return box ? Math.max(0, box.w | 0) * Math.max(0, box.h | 0) : 0;
}

function studioMaskInsideBox(mask, box, w, h) {
  const out = new Uint8Array(w * h);
  if (!mask || !box) return out;
  for (let y = box.y0; y <= box.y1; y++) {
    let i = y * w + box.x0;
    for (let x = box.x0; x <= box.x1; x++, i++) if (mask[i]) out[i] = 1;
  }
  return out;
}

function studioRoiFromManufacturingColours({ px, w, h, n, pen, blue, red, black }) {
  const all = new Uint8Array(n);
  for (let i = 0; i < n; i++) if (blue[i] || red[i] || black[i]) all[i] = 1;

  /* Blue is the most trustworthy structural signal because the workshop
     grammar reserves it for cut edges and openings, including the outer
     silhouette. If blue exists, let it define the first pass ROI. */
  let coreBox = studioBBox(blue, w, h);
  if (!coreBox) {
    const biggest = studioLargestComponent(all, w, h);
    coreBox = studioBBox(biggest, w, h);
  }
  if (!coreBox) return { box: null, mask: new Uint8Array(n) };

  /* The outer cut line is authoritative but narrow; internal black/red work
     and a detached-looking hoop need breathing room. Pad from both pen width
     and overall scale, then expand once to include any manufacturing-colour
     pixel that falls into the padded window. */
  const pad = Math.max(8, Math.round(Math.max(coreBox.w, coreBox.h) * 0.06), Math.round((Number(pen) || 2) * 6));
  let roiBox = studioPadBox(coreBox, w, h, pad, pad);
  for (let i = 0; i < n; i++) {
    if (!all[i]) continue;
    const x = i % w, y = (i / w) | 0;
    if (x < roiBox.x0 || x > roiBox.x1 || y < roiBox.y0 || y > roiBox.y1) continue;
    if (x < coreBox.x0) coreBox.x0 = x; if (x > coreBox.x1) coreBox.x1 = x;
    if (y < coreBox.y0) coreBox.y0 = y; if (y > coreBox.y1) coreBox.y1 = y;
  }
  coreBox.w = coreBox.x1 - coreBox.x0 + 1; coreBox.h = coreBox.y1 - coreBox.y0 + 1;
  roiBox = studioPadBox(coreBox, w, h, pad, pad);

  const mask = new Uint8Array(n);
  for (let y = roiBox.y0; y <= roiBox.y1; y++) {
    const row = y * w;
    for (let x = roiBox.x0; x <= roiBox.x1; x++) mask[row + x] = 1;
  }
  return { box: roiBox, mask };
}

/* Sample into an N x N grid normalised to the mask's own bounding box, so two
   pictures of the same charm at different scales become comparable. */
function studioNormalise(mask, w, h, box, N) {
  const g = new Uint8Array(N * N);
  for (let j = 0; j < N; j++) {
    const sy = box.y0 + Math.min(box.h - 1, Math.floor((j + 0.5) * box.h / N));
    for (let i = 0; i < N; i++) {
      const sx = box.x0 + Math.min(box.w - 1, Math.floor((i + 0.5) * box.w / N));
      g[j * N + i] = mask[sy * w + sx];
    }
  }
  return g;
}

function studioIoU(a, b, n) {
  let inter = 0, uni = 0;
  for (let i = 0; i < n; i++) { const x = a[i], y = b[i]; if (x && y) inter++; if (x || y) uni++; }
  return uni ? inter / uni : 0;
}

const STUDIO_BG_MIN = 230;
const studioIsBg = (px, p) => px[p] > STUDIO_BG_MIN && px[p + 1] > STUDIO_BG_MIN && px[p + 2] > STUDIO_BG_MIN;

async function studioRawAt(sharp, buf, side) {
  const { data, info } = await sharp(buf)
    .resize(side, side, { fit: "inside" })
    .removeAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });
  return { px: data, w: info.width, h: info.height };
}


/* ── THE FOURTH INSTRUCTION: SOLID METAL, SAID OUT LOUD ────────────────────
   White meant two different things. Inside the charm it meant "untouched
   polished metal"; outside it meant "paper". And since the render moved to a
   white ground, a HOLE renders white too — so an enclosed white region ringed
   by a thin outline and a real opening became the same picture, and the model
   was left inferring which from context. It inferred wrong on two legs.

   Absence is the weakest signal you can hand a vision encoder, so metal stops
   being an absence. Every interior pixel that is not an instruction and not a
   declared hole is flooded with this tint before the drawing goes to the
   model. White then means exactly one thing: not metal.

   Green because it is the one hue the vocabulary does not use — measured
   against the other four classes its nearest neighbour is dE 103, where the
   closest existing pair (cut blue vs paper) is 58. The customer never sees
   it: this is applied to the RENDER'S INPUT only, never to the drawing filed
   in Storage or shown in the studio. */
const STUDIO_METAL_TINT = [0x4d, 0xff, 0x4d];

const studioIsBlack = (px, p) => px[p] < 90 && px[p + 1] < 90 && px[p + 2] < 90;

/* every region the drawing declares, at the drawing's own resolution, with
   sample points kept so the same regions can be interrogated in the render */
async function studioDrawingPlan(sharp, drawingBuf) {
  const { data: px, info } = await sharp(drawingBuf).removeAlpha().raw()
    .toBuffer({ resolveWithObject: true });
  const w = info.width, h = info.height, n = w * h;

  const roi = studioManufacturingROI(px, w, h);
  const scope = roi.mask;
  const ink = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    if (scope && !scope[i]) continue;
    if (!studioIsBg(px, i * 3)) ink[i] = 1;
  }

  let face = studioOuterFace(studioDilate(ink, w, h, 2), w, h);
  let faceBox = studioBBox(face, w, h);
  let roiGuard = "not-needed";

  if (roi.signalBox && !studioFaceLooksSane(faceBox, roi.signalBox)) {
    /* Sanity recovery: rebuild the wall from manufacturing colours + black
       only. This strips antialiased grey/card furniture even if it somehow
       entered the padded ROI. */
    const strictInk = new Uint8Array(n);
    for (let i = 0; i < n; i++) {
      if (scope && !scope[i]) continue;
      const p = i * 3;
      if (studioIsBluePixel(px, p) || studioIsRedPixel(px, p) || studioIsBlack(px, p)) strictInk[i] = 1;
    }
    const strictFace = studioOuterFace(studioDilate(strictInk, w, h, 2), w, h);
    const strictBox = studioBBox(strictFace, w, h);
    if (studioFaceLooksSane(strictBox, roi.signalBox)) {
      face = strictFace; faceBox = strictBox; roiGuard = "strict-recovered";
    } else {
      /* Unsafe topology is better sent down the legacy path than materialised
         as a giant rectangular sheet. Null faceBox makes material-spec creation
         decline cleanly. */
      face = new Uint8Array(n); faceBox = null; roiGuard = "rejected-oversize-face";
    }
  }

  const pen = studioPenWidth(px, w, h, scope);
  let blue = studioBlueMask(px, n, 3);
  blue = studioRestrictMask(blue, scope);
  const { cut } = studioCutRegions(blue, w, h, 2.5, pen);

  /* black FILLS are engraving and must stay closed; black LINES are outlines
     and are not regions at all — the same thickness test that separates a
     cut-out from a cut edge separates them. */
  const black = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    if (scope && !scope[i]) continue;
    if (studioIsBlack(px, i * 3)) black[i] = 1;
  }
  const { cut: blackAreas } = studioCutRegions(black, w, h, 2.5, pen);

  /* interior metal: inside the charm, not ink, not a declared hole. Ink is
     dilated so a region's own outline cannot leak it into its neighbour. */
  const inkWall = studioDilate(ink, w, h, 2);
  const metal = new Uint8Array(n);
  for (let i = 0; i < n; i++) if (face[i] && !inkWall[i] && !cut[i]) metal[i] = 1;

  const minPx = Math.max(200, Math.round(n * 0.0004));
  const regions = [];
  const collect = (mask, kind) => {
    const { labels, count } = studioLabel(mask, w, h);
    const size = new Float64Array(count + 1);
    for (let i = 0; i < n; i++) if (labels[i]) size[labels[i]]++;
    const pts = new Map();
    const step = 3;
    for (let y = 0; y < h; y += step) for (let x = 0; x < w; x += step) {
      const i = y * w + x, L = labels[i];
      if (!L || size[L] < minPx) continue;
      if (!pts.has(L)) pts.set(L, []);
      pts.get(L).push(i);
    }
    for (const [L, list] of pts) if (list.length >= 12) regions.push({ kind, px: size[L], pts: list });
  };
  collect(cut, "open");
  collect(blackAreas, "closed");
  collect(metal, "closed");
  return { px, w, h, n, ink, face, faceBox, blue, cut, pen, regions,
           roiMode: roi.mode, roiBox: roi.box, roiSignalBox: roi.signalBox,
           roiSignalPx: roi.signalPx, roiGuard };
}

/* ── DETERMINISTIC MATERIAL SPECIFICATION ────────────────────────────────
   The production drawing is useful to a person because three reserved colours
   explain three manufacturing operations. It is a poor final input to an
   image model because the model still has to DECIDE what each colour means.

   This pass removes that decision. Before the renderer is called, the drawing
   is converted into a flat proof of the finished topology:
     · actual sheet metal is already shown in the requested metal family;
     · black and red work is already shown as worked metal of that same family;
     · blue filled areas are already absent;
     · white holes enclosed by a blue boundary (most importantly the hoop hole)
       are already absent;
     · blue cut/perimeter lines themselves are NOT reproduced as decoration.

   The customer never sees this image. It exists only between the deterministic
   drawing and the probabilistic material renderer. The renderer no longer
   interprets BLUE/RED/BLACK at all — it photorealises geometry that is already
   resolved. No second model call, no extra customer instruction, no new cost.
   ====================================================================== */
function studioBlueBoundedWhiteHoles(plan) {
  const { px, w, h, n, face, blue } = plan;
  const white = new Uint8Array(n);
  for (let i = 0; i < n; i++) if (face[i] && studioIsBg(px, i * 3)) white[i] = 1;
  const { labels, count } = studioLabel(white, w, h);
  if (!count) return new Uint8Array(n);

  /* A structural hoop is two nested BLUE cut lines: the outer contour cuts
     the hoop from the sheet and the inner contour cuts its opening. The white
     band between them is METAL, not a hole. The previous blue-vote test saw
     blue on both sides of that band and therefore classified the entire hoop
     body as empty. Track the distinct blue contours touching each white
     region so a band between two contours remains solid; the white centre,
     which touches only the inner contour, is still cut out. */
  const blueComponents = studioLabel(blue || studioBlueMask(px, n, 3), w, h).labels;

  const size = new Float64Array(count + 1);
  for (let i = 0; i < n; i++) if (labels[i]) size[labels[i]]++;
  let largest = 1;
  for (let L = 2; L <= count; L++) if (size[L] > size[largest]) largest = L;

  /* One pass over the sheet, not one pass PER component. A 2K drawing can
     contain hundreds of tiny enclosed white islands; O(regions × pixels)
     would turn a deterministic pre-pass into the slowest part of the render. */
  const blueVotes = new Float64Array(count + 1);
  const redVotes = new Float64Array(count + 1);
  const blackVotes = new Float64Array(count + 1);
  const firstBlueComponent = new Int32Array(count + 1);
  const secondBlueComponent = new Int32Array(count + 1);
  const noteBlueComponent = (L, B) => {
    if (!B || firstBlueComponent[L] === B || secondBlueComponent[L] === B) return;
    if (!firstBlueComponent[L]) firstBlueComponent[L] = B;
    else if (!secondBlueComponent[L]) secondBlueComponent[L] = B;
  };
  const at = (x, y) => y * w + x;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = at(x, y), L = labels[i];
      if (!L || L === largest) continue;
      const boundary = (x === 0 || labels[i - 1] !== L) ||
                       (x === w - 1 || labels[i + 1] !== L) ||
                       (y === 0 || labels[i - w] !== L) ||
                       (y === h - 1 || labels[i + w] !== L);
      if (!boundary) continue;
      /* Two pixels reaches through antialiasing without reaching across a
         normal studio line into unrelated artwork. We count the actual ink
         colours around the component; a true hole is overwhelmingly blue,
         while a polished enclosed shape is overwhelmingly red or black. */
      for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) {
        if (Math.abs(dx) + Math.abs(dy) > 2) continue;
        const xx = x + dx, yy = y + dy;
        if (xx < 0 || yy < 0 || xx >= w || yy >= h) continue;
        const q = at(xx, yy);
        if (labels[q] === L) continue;
        const p = q * 3;
        if (studioIsBluePixel(px, p)) {
          blueVotes[L]++;
          noteBlueComponent(L, blueComponents[q]);
        }
        else if (studioIsRedPixel(px, p)) redVotes[L]++;
        else if (studioIsBlack(px, p)) blackVotes[L]++;
      }
    }
  }

  const holeLabel = new Uint8Array(count + 1);
  const minPx = Math.max(20, Math.round(n * 0.00001));
  for (let L = 1; L <= count; L++) {
    /* The largest white component is the polished face itself. It is bounded
       by the charm's blue outer cut line and must NEVER be mistaken for one
       enormous hole. */
    if (L === largest || size[L] < minPx) continue;
    const blue = blueVotes[L], red = redVotes[L], black = blackVotes[L];
    const votes = blue + red + black;
    const betweenTwoBlueContours = !!secondBlueComponent[L];
    if (!betweenTwoBlueContours && votes >= 8 && blue / votes >= 0.72 && blue > (red + black) * 2) {
      holeLabel[L] = 1;
    }
  }

  const holes = new Uint8Array(n);
  for (let i = 0; i < n; i++) if (labels[i] && holeLabel[labels[i]]) holes[i] = 1;
  return holes;
}

function studioEnlargeTopHoopHole(plan, holes) {
  const { w, h, n, face, faceBox } = plan;
  if (!faceBox) return;
  const { labels, count } = studioLabel(holes, w, h);
  if (!count) return;

  const size = new Float64Array(count + 1);
  const x0 = new Int32Array(count + 1); x0.fill(w);
  const y0 = new Int32Array(count + 1); y0.fill(h);
  const x1 = new Int32Array(count + 1); x1.fill(-1);
  const y1 = new Int32Array(count + 1); y1.fill(-1);
  for (let i = 0; i < n; i++) {
    const L = labels[i];
    if (!L) continue;
    const x = i % w, y = (i / w) | 0;
    size[L]++;
    if (x < x0[L]) x0[L] = x; if (x > x1[L]) x1[L] = x;
    if (y < y0[L]) y0[L] = y; if (y > y1[L]) y1[L] = y;
  }

  /* The integrated hoop opening is the uppermost compact, near-round hole in
     the protruding top band. Grow only that final resolved opening, after the
     blue cut line and white centre have been combined, so its inner diameter
     increases slightly without moving the outer hoop or any design cut-out. */
  const topEdgeLimit = faceBox.y0 + faceBox.h * 0.18;
  const centreLimit = faceBox.y0 + faceBox.h * 0.25;
  const minDiameter = Math.max(4, faceBox.w * 0.02);
  const maxDiameter = faceBox.w * 0.18;
  let hoopLabel = 0;
  for (let L = 1; L <= count; L++) {
    const bw = x1[L] - x0[L] + 1, bh = y1[L] - y0[L] + 1;
    const diameter = Math.min(bw, bh);
    const ratio = bw / Math.max(1, bh);
    const density = size[L] / Math.max(1, bw * bh);
    const cy = (y0[L] + y1[L]) * 0.5;
    if (y0[L] > topEdgeLimit || cy > centreLimit ||
        diameter < minDiameter || diameter > maxDiameter ||
        ratio < 0.55 || ratio > 1.8 || density < 0.45) continue;
    if (!hoopLabel || y0[L] < y0[hoopLabel] ||
        (y0[L] === y0[hoopLabel] && size[L] > size[hoopLabel])) hoopLabel = L;
  }
  if (!hoopLabel) return;

  const hoopHole = new Uint8Array(n);
  for (let i = 0; i < n; i++) if (labels[i] === hoopLabel) hoopHole[i] = 1;
  const diameter = Math.min(x1[hoopLabel] - x0[hoopLabel] + 1,
                            y1[hoopLabel] - y0[hoopLabel] + 1);
  const grow = Math.max(1, Math.min(3, Math.ceil(diameter * 0.025)));
  const enlarged = studioDilate(hoopHole, w, h, grow);
  for (let i = 0; i < n; i++) if (face[i] && enlarged[i]) holes[i] = 1;
}

function studioSpecCutMask(plan, zones) {
  const { w, h, n, blue, cut } = plan;
  const out = new Uint8Array(n);

  /* Structured cut-out zones are the customer's own manufacturing data. They
     do not replace the exact pixels; they tell us WHICH blue pixels are an
     area when a global line-thickness estimate is ambiguous. This keeps the
     exact contour from the drawing while the decision 'line or hole?' comes
     from deterministic data, not from an image model. */
  const cuts = (Array.isArray(zones) ? zones : []).filter((z) =>
    z && z.intent === "cutout" && Number(z.w) > 0.004 && Number(z.h) > 0.004);
  /* When the structured list exists it is the authority. In particular, a
     filled blue area can physically touch the blue outer perimeter; component
     analysis then sees one connected blue object and could otherwise erase the
     whole silhouette. Zones let us take only the exact blue pixels inside the
     declared area. With no structured list (old/uploaded references), fall
     back to the image-only fill detector. */
  if (!cuts.length) {
    for (let i = 0; i < n; i++) if (cut[i]) out[i] = 1;
  }
  for (const z of cuts) {
    const padX = Math.max(2, Math.round(w * 0.008));
    const padY = Math.max(2, Math.round(h * 0.008));
    const x0 = Math.max(0, Math.floor(Number(z.x) * w) - padX);
    const y0 = Math.max(0, Math.floor(Number(z.y) * h) - padY);
    const x1 = Math.min(w, Math.ceil((Number(z.x) + Number(z.w)) * w) + padX);
    const y1 = Math.min(h, Math.ceil((Number(z.y) + Number(z.h)) * h) + padY);
    for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) {
      const i = y * w + x;
      if (blue[i]) out[i] = 1;
    }
  }
  /* ── THERE IS NO FALLBACK HERE, AND THAT IS THE POINT ──────────────────
     A fallback lived here that punched blue components the image "proved"
     were filled blobs, whether or not a zone claimed them. It was added to
     rescue a cut-out that had fallen off a TRUNCATED zone list, and the
     truncation it was rescuing is gone (see STUDIO_ZONE_LIMIT), so the thing
     it existed for cannot happen any more.

     It also could not have worked. Measured on a moon-and-star charm, the
     blue CRESCENT BODY is one filled blob of 105,673px, density 0.34, local
     thickness 7.0 — indistinguishable, by any measure taken on that
     component alone, from a declared cut-out of the same shape. It IS
     declared metal. Density punched it; thickness punched it; the charm came
     back with its whole body opened out as a through-cut. Opening 33.3% of a
     face where the customer declared 4.8% is not a rescue.

     The lesson is the general one, so it is written here rather than in a
     commit message: whether a region is a HOLE or is METAL is not a property
     of its pixels. It is a fact the customer supplied. A picture cannot
     recover it, and code that tries will be wrong in exactly the cases that
     matter most — the big, obvious, load-bearing ones. The declared list is
     the authority. When it is silent about a region, the answer is that the
     region is not a hole, not that we should go looking for one.

     If a cut-out is ever missing from a map again, it is missing from the
     LIST, and the list is what gets fixed. */
  return out;
}

/* ── THE MASK IS GREYSCALE, ON PURPOSE ────────────────────────────────────
   IMAGE 1 answers exactly one question: which pixels are cut clean through,
   which are engraved, and which are plain polished metal. Nothing else about
   it is meant to be read.

   It used to be painted in the CUSTOMER'S metal — gold face, darker gold
   engraving, and a different pair of hues per metal. That made it a second
   opinion about colour, competing with the finish reference (IMAGE 2) and
   with the metal named in the prompt: three sources, and on a non-gold order
   two of them disagreed with the third. Same failure family as the earlier
   black-background and "B/W line art" finds — an input DESCRIBED wrongly
   defeats every rule written downstream of it.

   So the three states are three greys, far apart in luminance and with zero
   saturation, which is also the clearest possible signal that this image is a
   map and not a photograph. Colour now has exactly one owner: IMAGE 2.

   Luminance ladder: hole 255 → polished 176 → engraved 136. The 40-level
   engraving gap remains distinct after vision downsampling while no longer
   visually commanding an excessively dark gold finish.                   */
const STUDIO_MASK_POLISHED = [176, 176, 176];
const STUDIO_MASK_ENGRAVED = [136, 136, 136];

/* exact squared euclidean distance transform, Felzenszwalb & Huttenlocher */
function studioEdt1d(f, n) {
  const d = new Float64Array(n), v = new Int32Array(n), z = new Float64Array(n + 1);
  let k = 0; v[0] = 0; z[0] = -Infinity; z[1] = Infinity;
  for (let q = 1; q < n; q++) {
    let s = ((f[q] + q * q) - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
    while (s <= z[k]) { k--; s = ((f[q] + q * q) - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]); }
    k++; v[k] = q; z[k] = s; z[k + 1] = Infinity;
  }
  k = 0;
  for (let q = 0; q < n; q++) {
    while (z[k + 1] < q) k++;
    d[q] = (q - v[k]) * (q - v[k]) + f[v[k]];
  }
  return d;
}

function studioEdt2d(mask, w, h) {           // distance to nearest ZERO pixel
  const INF = 1e12;
  const f = new Float64Array(Math.max(w, h));
  const dist = new Float64Array(w * h);
  for (let i = 0; i < w * h; i++) dist[i] = mask[i] ? INF : 0;
  for (let x = 0; x < w; x++) {
    for (let y = 0; y < h; y++) f[y] = dist[y * w + x];
    const d = studioEdt1d(f, h);
    for (let y = 0; y < h; y++) dist[y * w + x] = d[y];
  }
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) f[x] = dist[y * w + x];
    const d = studioEdt1d(f, w);
    for (let x = 0; x < w; x++) dist[y * w + x] = Math.sqrt(d[x]);
  }
  return dist;
}

/* negative inside the shape, positive outside, in source pixels */
function studioSignedField(mask, w, h) {
  const inv = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) inv[i] = mask[i] ? 0 : 1;
  /* edt2d returns the distance to the nearest ZERO of what it is handed.
     Handed the mask, that is the distance to the nearest OUTSIDE pixel — the
     right number for a pixel that is inside. Handed the inverse, it is the
     distance to the nearest INSIDE pixel — the right number for a pixel that
     is outside. Getting these the wrong way round inverts the field and fills
     the whole frame, which is exactly what it did the first time. */
  const dToOutside = studioEdt2d(mask, w, h);
  const dToInside = studioEdt2d(inv, w, h);
  const sdf = new Float32Array(w * h);
  for (let i = 0; i < w * h; i++) {
    sdf[i] = mask[i] ? -(dToOutside[i] - 0.5) : (dToInside[i] - 0.5);
  }
  return sdf;
}

function studioBilinearField(sdf, w, h, tw, th) {
  const out = new Float32Array(tw * th);
  const sx = w / tw, sy = h / th;
  for (let y = 0; y < th; y++) {
    const fy = Math.min(h - 1, Math.max(0, (y + 0.5) * sy - 0.5));
    const y0 = Math.floor(fy), y1 = Math.min(h - 1, y0 + 1), wy = fy - y0;
    for (let x = 0; x < tw; x++) {
      const fx = Math.min(w - 1, Math.max(0, (x + 0.5) * sx - 0.5));
      const x0 = Math.floor(fx), x1 = Math.min(w - 1, x0 + 1), wx = fx - x0;
      const a = sdf[y0 * w + x0], b = sdf[y0 * w + x1];
      const c = sdf[y1 * w + x0], d = sdf[y1 * w + x1];
      out[y * tw + x] = (a * (1 - wx) + b * wx) * (1 - wy) + (c * (1 - wx) + d * wx) * wy;
    }
  }
  return out;
}

/* separable gaussian on a float field. Blurring a DISTANCE FIELD is not the
   same as blurring a picture: it is curvature flow on the boundary, so the
   high-frequency stair steps flatten out while the shape itself is kept. The
   sigma is tied to the SOURCE pixel size, because that is the wavelength of
   the staircase we are removing — anything much larger starts rounding real
   corners. */
function studioGaussField(field, w, h, sigma) {
  const r = Math.max(1, Math.ceil(sigma * 3));
  const k = new Float32Array(2 * r + 1);
  let sum = 0;
  for (let i = -r; i <= r; i++) { const v = Math.exp(-(i * i) / (2 * sigma * sigma)); k[i + r] = v; sum += v; }
  for (let i = 0; i < k.length; i++) k[i] /= sum;
  const tmp = new Float32Array(w * h), out = new Float32Array(w * h);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    let acc = 0;
    for (let i = -r; i <= r; i++) {
      const xx = Math.min(w - 1, Math.max(0, x + i));
      acc += field[y * w + xx] * k[i + r];
    }
    tmp[y * w + x] = acc;
  }
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    let acc = 0;
    for (let i = -r; i <= r; i++) {
      const yy = Math.min(h - 1, Math.max(0, y + i));
      acc += tmp[yy * w + x] * k[i + r];
    }
    out[y * w + x] = acc;
  }
  return out;
}

/* drop islands smaller than minPx — these are threshold speckle, never design */
function studioDespeckleMask(mask, w, h, minPx) {
  const lab = new Int32Array(w * h).fill(-1);
  const stack = new Int32Array(w * h);
  let comp = 0;
  for (let s = 0; s < w * h; s++) {
    if (!mask[s] || lab[s] >= 0) continue;
    let sp = 0, size = 0; stack[sp++] = s; lab[s] = comp;
    const members = [];
    while (sp) {
      const i = stack[--sp]; members.push(i); size++;
      const x = i % w, y = (i / w) | 0;
      if (x > 0 && mask[i - 1] && lab[i - 1] < 0) { lab[i - 1] = comp; stack[sp++] = i - 1; }
      if (x < w - 1 && mask[i + 1] && lab[i + 1] < 0) { lab[i + 1] = comp; stack[sp++] = i + 1; }
      if (y > 0 && mask[i - w] && lab[i - w] < 0) { lab[i - w] = comp; stack[sp++] = i - w; }
      if (y < h - 1 && mask[i + w] && lab[i + w] < 0) { lab[i + w] = comp; stack[sp++] = i + w; }
    }
    if (size < minPx) for (const i of members) mask[i] = 0;
    comp++;
  }
  return mask;
}


/* ── THE MASK IS RESAMPLED, NOT MAGNIFIED ─────────────────────────────────
   Classifying the drawing pixel by pixel leaves a staircase along every
   curve — the drawing's own anti-aliasing hard-thresholded onto the pixel
   grid — plus stray single-pixel marks and pinholes. Nearest-neighbour
   upscaling then turned each of those artefacts into a visible block.

   So each class is rebuilt from its own signed distance field: de-speckled in
   both polarities, converted to a field, resampled, smoothed by a sigma tied
   to the SOURCE pixel size, and thresholded back at zero. Thresholding is
   what keeps exactly three tones and hard edges; doing it after the resample
   is what makes those edges follow the real curve.

   NOTHING IS RECLASSIFIED. Which regions are cut, engraved or polished was
   decided by studioMaterialSpec at the drawing's own resolution and is not
   revisited — this only decides where each region's boundary falls at the
   higher resolution. Deterministic throughout: exact EDT, exact bilinear,
   fixed kernel, fixed threshold; the same drawing yields the same bytes. */
async function studioRefineMask(sharp, maskBuf, targetLong) {
  const POLISHED = STUDIO_MASK_POLISHED[0], ENGRAVED = STUDIO_MASK_ENGRAVED[0], ABSENT = 255;
  const { data, info } = await sharp(maskBuf).removeAlpha().raw().toBuffer({ resolveWithObject: true });
  const w = info.width, h = info.height, n = w * h, ch = info.channels;
  const near = (v, t) => Math.abs(v - t) <= 24;

  const A = new Uint8Array(n), B = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    const v = data[i * ch];
    if (near(v, ENGRAVED)) B[i] = 1;
    else if (near(v, POLISHED)) A[i] = 1;
  }

  const speck = Math.max(6, Math.round(n * 0.00004));
  const fillHoles = (mask) => {
    const inv = new Uint8Array(n);
    for (let i = 0; i < n; i++) inv[i] = mask[i] ? 0 : 1;
    studioDespeckleMask(inv, w, h, speck);
    for (let i = 0; i < n; i++) if (!inv[i]) mask[i] = 1;
  };
  studioDespeckleMask(A, w, h, speck); fillHoles(A);
  studioDespeckleMask(B, w, h, speck); fillHoles(B);

  const scale = Math.max(1, targetLong / Math.max(w, h));
  const tw = Math.round(w * scale), th = Math.round(h * scale);
  const sigma = Math.max(0.8, scale * 0.85);

  const upA = studioGaussField(studioBilinearField(studioSignedField(A, w, h), w, h, tw, th), tw, th, sigma);
  const upB = studioGaussField(studioBilinearField(studioSignedField(B, w, h), w, h, tw, th), tw, th, sigma);

  const rgb = Buffer.alloc(tw * th * 3, ABSENT);
  for (let i = 0; i < tw * th; i++) {
    const p = i * 3;
    if (upB[i] < 0) { rgb[p] = rgb[p + 1] = rgb[p + 2] = ENGRAVED; }
    else if (upA[i] < 0) { rgb[p] = rgb[p + 1] = rgb[p + 2] = POLISHED; }
  }
  const buf = await sharp(rgb, { raw: { width: tw, height: th, channels: 3 } }).png().toBuffer();
  return { buf, w: tw, h: th };
}

/* ── TOPOLOGY WITHOUT SEMANTICS ─────────────────────────────────────────
   The three-tone material map still resembles the customer's subject. That
   lets a learned symbol prior overrule a light-grey fill and turn a familiar
   enclosed shape into a hole. Collapse both metal tones to one light-grey mass
   before Gemini sees topology: the model can no longer pair, mirror or
   reinterpret an internal smooth-metal island. The greyscale map is sent
   separately and remains the sole surface-treatment instruction. */
async function studioTopologyMask(sharp, materialSpecBuf) {
  if (!sharp || !materialSpecBuf?.length) return null;
  const { data, info } = await sharp(materialSpecBuf).removeAlpha().raw()
    .toBuffer({ resolveWithObject: true });
  const w = info.width, h = info.height, n = w * h, ch = info.channels;
  const out = Buffer.alloc(n * 3, 255);
  const TOPOLOGY_METAL = STUDIO_MASK_POLISHED[0];
  let metalPx = 0;
  for (let i = 0; i < n; i++) {
    const p = i * ch;
    /* Material-spec pixels are exact 136, 176 or 255. The small margin keeps
       this safe if a future PNG decoder introduces a near-white edge value. */
    if (Math.max(data[p], data[p + 1], data[p + 2]) < 240) {
      const q = i * 3;
      out[q] = out[q + 1] = out[q + 2] = TOPOLOGY_METAL;
      metalPx++;
    }
  }
  const buf = await sharp(out, { raw: { width: w, height: h, channels: 3 } })
    .png().toBuffer();
  return { buf, w, h, metalPx, emptyPx: n - metalPx };
}

/* ── NAME EVERY REGION, DON'T JUST STATE THE LAW ──────────────────────────
   The three-tone law was stated abstractly and the renderer applied it
   abstractly: it saw a light shape, a dark shape and a white shape and
   painted a charm that resembled them, treating two differently-declared
   shapes inside one field as the same thing.

   This block says, per region, WHAT IS THERE — computed from the resolved
   map, never from the model's reading of it. It is the same information the
   map already carries, spoken once in the vocabulary the renderer answers
   to, which is the one thing the abstract statement of the law never did.

   Two deliberate restrictions, both learned the hard way:
     · NO BOUNDING BOXES. A region is named by where its centre sits, never
       by a rectangle — a box around a thin shape is a claim about every
       pixel it encloses, and that is how a whole field gets wiped.
     · NO DIGITS. Counts are spelled as words. The render step forbids text
       on the charm, and a numeral in the prompt is a numeral the renderer
       can decide to engrave.
   ====================================================================== */
const STUDIO_CENSUS_WORDS = ["none", "one", "two", "three", "four", "five",
                             "six", "seven", "eight", "nine", "ten"];

function studioCensusCount(n) {
  return n <= 10 ? STUDIO_CENSUS_WORDS[n] : "many";
}

function studioCensusWhere(u, v) {
  const col = u < 0.34 ? "left" : u > 0.66 ? "right" : "centre";
  const row = v < 0.34 ? "upper" : v > 0.66 ? "lower" : "middle";
  if (col === "centre" && row === "middle") return "at the centre of the charm";
  if (col === "centre") return `${row} centre of the charm`;
  if (row === "middle") return `middle ${col} of the charm`;
  return `${row} ${col} of the charm`;
}

function studioCensusSize(frac) {
  if (frac >= 0.25) return "a large field";
  if (frac >= 0.08) return "a broad area";
  if (frac >= 0.02) return "a modest shape";
  return "a small shape";
}

/* Components of a mask, largest first, with a centroid and an area share.
   Sub-threshold specks are dropped: naming a stray dot as an opening is how a
   renderer gets told to punch a hole nobody asked for. */
function studioCensusRegions(mask, w, h, facePx, minFrac, cap) {
  const { labels, count } = studioLabel(mask, w, h);
  if (!count) return { total: 0, list: [] };
  const area = new Float64Array(count + 1);
  const sx = new Float64Array(count + 1), sy = new Float64Array(count + 1);
  for (let i = 0; i < labels.length; i++) {
    const L = labels[i];
    if (!L) continue;
    area[L]++; sx[L] += i % w; sy[L] += (i / w) | 0;
  }
  const out = [];
  for (let L = 1; L <= count; L++) {
    if (area[L] / facePx < minFrac) continue;
    out.push({ px: area[L], cx: sx[L] / area[L], cy: sy[L] / area[L] });
  }
  out.sort((a, b) => b.px - a.px);
  /* `total` is the TRUE count and `list` is capped. Reporting the capped
     length as the count would be a false statement in a block that tells the
     renderer to count — a charm with eight openings would be instructed to
     produce five, and the three it dropped are metal it would fill back in. */
  return { total: out.length, list: out.slice(0, cap) };
}

/* `spec` is the return of studioMaterialSpec, so the words and the picture are
   built from the SAME masks. Reading plan.regions instead would undercount:
   its "open" list is blue FILLED areas only, while the spec image also removes
   blue-BOUNDED white holes — the hoop hole among them. A census that names one
   opening beside a map showing two is worse than no census at all. */
/* ── THE SHAPE THAT WAS NEVER MENTIONED ───────────────────────────────────
   A metal shape sitting INSIDE an engraved field is the case the census kept
   silent about. Openings were named, engraved fields were named, and
   everything else fell under one blanket line — "everything else inside the
   silhouette is plain polished metal". On the knife-and-fork charm that
   blanket line is the only thing standing between the renderer and cutting
   the knife, while the fork right beside it, of similar size and in the same
   field, is named explicitly as an opening.

   These islands are found the cheap way: the metal mask's LARGEST component
   is the charm's body, and any other component above the floor is a shape
   surrounded by worked metal. No adjacency walk, no geometry. */
function studioMetalIslands(plan, spec) {
  if (!spec || !spec.holeMask || !spec.workMask) return [];
  const { w, h, n, face } = plan;
  const metal = new Uint8Array(n);
  for (let i = 0; i < n; i++) if (face[i] && !spec.holeMask[i] && !spec.workMask[i]) metal[i] = 1;
  const { labels, count } = studioLabel(metal, w, h);
  if (count < 2) return [];
  const area = new Float64Array(count + 1);
  const sx = new Float64Array(count + 1), sy = new Float64Array(count + 1);
  for (let i = 0; i < n; i++) {
    const L = labels[i];
    if (!L) continue;
    area[L]++; sx[L] += i % w; sy[L] += (i / w) | 0;
  }
  let body = 1;
  for (let L = 2; L <= count; L++) if (area[L] > area[body]) body = L;

  /* ── SURROUNDED, NOT MERELY SEPARATE ──────────────────────────────────
     "Any metal component that is not the body" is too loose: a hoop ring
     segment, or a sliver left by an antialiased edge, satisfies it and gets
     announced to the renderer as a solid shape standing in an engraved
     field. On the real knife-and-fork mask that produced three islands where
     there is one.

     So a candidate must actually be enclosed by worked metal: of the pixels
     touching it from outside, most must be engraved. The knife's border is
     the engraved disc on every side; a hoop fragment's border is background
     and cut edge, and is dropped. */
  const enclosedByWork = (L) => {
    let touch = 0, worked = 0;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (labels[i] !== L) continue;
        for (const j of [x > 0 ? i - 1 : -1, x < w - 1 ? i + 1 : -1,
                         y > 0 ? i - w : -1, y < h - 1 ? i + w : -1]) {
          if (j < 0 || labels[j] === L) continue;
          touch++;
          if (spec.workMask[j]) worked++;
        }
      }
    }
    return touch >= 8 && worked / touch >= 0.6;
  };

  const out = [];
  for (let L = 1; L <= count; L++) {
    if (L === body) continue;
    if (area[L] / spec.facePx < 0.004) continue;
    if (!enclosedByWork(L)) continue;
    out.push({ px: area[L], cx: sx[L] / area[L], cy: sy[L] / area[L] });
  }
  return out.sort((a, b) => b.px - a.px).slice(0, 5);
}

/* ── NAMING, NOT CLASSIFYING ──────────────────────────────────────────────
   A vision model is asked ONE question about the mask: what is each region a
   picture of. It is never asked, and is never believed about, whether a
   region is cut, engraved or solid — those come from the pixels and are
   already settled before this runs. Only the noun is taken; everything else
   in the reply is discarded.

   This matters because the whole failure being addressed is a model deciding
   a shape's class for itself. Letting a second model do the same thing one
   step earlier would move the fault, not remove it. So the reply is filtered:
   a name is rejected outright if it contains a class word.

   Degrades to no names at all. Positions and areas still describe every
   region, which is what the census did before this existed. */
const STUDIO_NAME_BANNED = /\b(cut|cutout|cut-out|hole|opening|open|engrav\w*|etch\w*|solid|metal|polish\w*|raised|recess\w*|void|negative|space|background|shape|region|area)\b/i;

function studioCleanRegionName(raw) {
  const s = studioCleanText(raw).toLowerCase().replace(/[^a-z \-]/g, "").trim();
  if (!s || s.length > 24) return "";
  if (s.split(/\s+/).length > 3) return "";
  if (STUDIO_NAME_BANNED.test(s)) return "";
  return s;
}

async function studioNameRegions(maskBuf, items) {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey || !maskBuf || !items.length) return {};
  const model = String(
    process.env.GEMINI_STUDIO_PRECHECK_MODEL ||
    process.env.GEMINI_CHARM_PREFLIGHT_MODEL ||
    DEFAULT_TEXT_MODEL
  ).trim();

  const list = items.map((it, k) =>
    `${k}: centre at ${Math.round(it.u * 100)}% across, ${Math.round(it.v * 100)}% down; ` +
    `covers about ${(it.frac * 100).toFixed(1)}% of the charm`).join("\n");

  const instruction =
`You are looking at a greyscale manufacturing map of one flat jewellery charm.

Your ONLY job is to say what each listed region DEPICTS — the everyday noun for
the object or motif drawn there. One to three words. A common noun.

You are NOT being asked whether anything is cut, engraved, raised or solid.
That is already decided and you must not comment on it. Never use the words
cut, hole, opening, engraved, solid, metal, polished, shape, region or area.
If you cannot tell what a region depicts, return an empty string for it.

REGIONS (coordinates are relative to the charm, not the image):
${list}

Return ONLY valid JSON in exactly this shape:
{"names":[{"i":0,"name":"..."}]}`;

  const resp = await fetch(`${GEMINI_BASE}/models/${model}:generateContent`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "x-goog-api-key": apiKey },
    body: JSON.stringify({
      contents: [{
        role: "user",
        parts: [
          { text: instruction },
          { inline_data: { mime_type: "image/png", data: Buffer.from(maskBuf).toString("base64") } },
        ],
      }],
      generationConfig: { temperature: 0, responseMimeType: "application/json" },
    }),
  });
  const data = await readUpstreamJson(resp, "gemini");
  const text = (data?.candidates?.[0]?.content?.parts || []).map((p) => p?.text || "").join("").trim();
  const parsed = extractJsonObject(text);
  const out = {};
  for (const row of (parsed?.names || [])) {
    const i = Number(row?.i);
    if (!Number.isInteger(i) || i < 0 || i >= items.length) continue;
    const name = studioCleanRegionName(row?.name);
    if (name) out[i] = name;
  }
  return out;
}

function studioCensusItems(plan, spec) {
  if (!plan || !plan.faceBox || !spec || !spec.facePx) return null;
  const box = plan.faceBox;
  if (!(box.w > 0) || !(box.h > 0)) return null;
  const { w, h } = plan, facePx = spec.facePx;
  const empty = { total: 0, list: [] };
  const open = spec.holeMask
    ? studioCensusRegions(spec.holeMask, w, h, facePx, 0.004, 5) : empty;
  const worked = spec.workMask
    ? studioCensusRegions(spec.workMask, w, h, facePx, 0.004, 5) : empty;
  const islands = studioMetalIslands(plan, spec);
  if (!open.total && !worked.total && !islands.length) return null;
  const decorate = (r) => Object.assign({}, r, {
    u: (r.cx - box.x0) / box.w, v: (r.cy - box.y0) / box.h, frac: r.px / facePx });
  return {
    open: { total: open.total, list: open.list.map(decorate) },
    worked: { total: worked.total, list: worked.list.map(decorate) },
    islands: islands.map(decorate),
  };
}

/* `names` is optional and is keyed by the index each region has in the flat
   order open -> worked -> islands. Absent names simply leave the measured
   description, which is what shipped before naming existed. */
function studioSpecCensus(plan, spec, names) {
  const items = studioCensusItems(plan, spec);
  if (!items) return "";
  const nm = names || {};
  let k = 0;
  const describe = (r) => {
    const name = nm[k++];
    const where = `${studioCensusSize(r.frac)} ${studioCensusWhere(r.u, r.v)}`;
    return name ? `the ${name} — ${where}` : where;
  };
  const partial = (r) => r.total > r.list.length ? "  The largest are:" : "  They are:";

  const lines = [];
  lines.push(`OPENINGS — ${studioCensusCount(items.open.total)} in this charm.`);
  if (items.open.total) {
    lines.push(partial(items.open));
    for (const r of items.open.list) lines.push(`  · ${describe(r)}: METAL IS ABSENT HERE.`);
    lines.push("  Each one is cut clean through the sheet. The ground the charm rests on is visible through it, bounded by a thin bright cut edge, with a small shadow inside the opening. It is never filled, tinted, recessed, engraved or shaded over.");
  }
  lines.push(`ENGRAVED FIELDS — ${studioCensusCount(items.worked.total)} in this charm.`);
  if (items.worked.total) {
    lines.push(partial(items.worked));
    for (const r of items.worked.list) lines.push(`  · ${describe(r)}: METAL IS STILL THERE, ITS SURFACE WORKED.`);
    lines.push("  Solid metal throughout, only the surface finish differs. Never open, never a separate material, never a different alloy.");
  }
  /* ── THE LINE THE KNIFE NEEDED ────────────────────────────────────────
     A plain shape standing inside an engraved field, beside an opening of
     similar size, is the exact confusion this render keeps losing. It used
     to be covered only by the blanket "everything else" sentence below. */
  if (items.islands.length) {
    lines.push(`SOLID SHAPES STANDING INSIDE AN ENGRAVED FIELD — ${studioCensusCount(items.islands.length)}.`);
    for (const r of items.islands) lines.push(`  · ${describe(r)}: SOLID METAL, NOT AN OPENING.`);
    lines.push("  These are the hardest thing in this charm to get right. Each is unbroken sheet with the engraved field worked around it, so it reads as bright polished metal standing clear of the darker worked surface. One of them sits beside an opening of similar size and shape: THEY ARE NOT THE SAME. You cannot see the ground through these. Cutting one of them out produces a charm the customer did not buy.");
  }
  lines.push("EVERYTHING ELSE INSIDE THE SILHOUETTE IS PLAIN POLISHED METAL, identical in colour to the rest of the charm.");
  lines.push("An opening and an engraved field are the two things this render most often confuses. Count the openings above, then count them again in your finished image.");

  return "RESOLVED REGIONS — THIS IS WHAT IMAGE 1'S TONES ALREADY MEAN. DO NOT RE-READ THEM:\n" +
         lines.join("\n");
}

async function studioMaterialSpec(sharp, plan, metal, zones) {
  if (!sharp || !plan || !plan.faceBox) return null;
  const { px, w, h, n, face, blue } = plan;
  const cut = studioSpecCutMask(plan, zones);
  const bounded = studioBlueBoundedWhiteHoles(plan);
  const holes = new Uint8Array(n);
  let holePx = 0, facePx = 0, workPx = 0;
  /* BLUE IS A HOLE AT ANY WIDTH. A blue line is a thin slit cut clean
     through — the same instruction as a blue area, narrower. Without this
     term studioCutRegions calls it a "line", it falls through to POLISHED,
     and the white beside it gets punched instead. */
  for (let i = 0; i < n; i++) if (cut[i] || bounded[i] || blue[i]) holes[i] = 1;
  studioEnlargeTopHoopHole(plan, holes);
  for (let i = 0; i < n; i++) {
    if (holes[i]) holePx++;
    if (face[i]) facePx++;
  }
  if (!facePx || facePx < n * 0.005) return null;

  const red = studioRedMask(px, n, 3);
  /* `metal` is deliberately unused: this proof carries geometry, not colour. */
  const base = STUDIO_MASK_POLISHED, work = STUDIO_MASK_ENGRAVED;
  const out = Buffer.alloc(n * 3, 255);
  /* The worked pixels are recorded as they are painted, so the census can
     describe exactly what this image encodes rather than recomputing it. */
  const workMask = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    if (!face[i] || holes[i]) continue;
    const p = i * 3;
    out[p] = base[0]; out[p + 1] = base[1]; out[p + 2] = base[2];
    /* BLACK means engrave. RED means outline-only, whose boundary is engraved.
       Both are therefore already the same physical operation by the time the
       AI sees this proof. Blue is intentionally absent from the proof. */
    if (studioIsBlack(px, p) || red[i]) {
      out[p] = work[0]; out[p + 1] = work[1]; out[p + 2] = work[2];
      workMask[i] = 1; workPx++;
    }
  }
  const buf = await sharp(out, { raw: { width: w, height: h, channels: 3 } })
    .png().toBuffer();
  /* holeMask/workMask are for the census only. They describe THIS buffer, and
     they are handed out before studioRefineMask resamples it — refinement
     moves boundaries by sub-pixel amounts and never reclassifies, so region
     counts, centroids and area shares are unaffected. */
  return { buf, facePx, holePx, workPx, w, h, holeMask: holes, workMask };
}

/* the tinted copy that goes to the model — the drawing in Storage is untouched */
async function studioTintMetal(sharp, plan) {
  const { px, w, h, n, face, ink, cut } = plan;
  const out = Buffer.from(px);
  const inkWall = studioDilate(ink, w, h, 1);
  const [tr, tg, tb] = STUDIO_METAL_TINT;
  let filled = 0;
  for (let i = 0; i < n; i++) {
    if (!face[i] || inkWall[i] || cut[i]) continue;
    const p = i * 3;
    if (!studioIsBg(px, p)) continue;
    out[p] = tr; out[p + 1] = tg; out[p + 2] = tb;
    filled++;
  }
  const buf = await sharp(out, { raw: { width: w, height: h, channels: 3 } }).png().toBuffer();
  return { buf, filled };
}

/* ── THE PUNCH ────────────────────────────────────────────────────────────
   Returns the render unchanged plus a verdict whenever anything is uncertain.
   The three outcomes, in the order they are decided:

     undeclared_cut  the render removed metal nobody asked to remove. This is
                     the Image-1 failure, and it is NOT patchable — the metal
                     is gone. Reject so the render is retried.
     unaligned       the render's silhouette does not match the drawing's, so
                     no coordinate mapped from one to the other can be
                     trusted. Punching blind would be worse than not punching.
     punched         the declared cut-outs were missing and have been cut.
   ========================================================================= */
async function studioPunchCutouts(renderBuf, drawingBuf, plan) {
  const sharp = studioSharp();
  const report = { verified: false, reason: "", declaredCuts: 0, punchedPx: 0,
                   alignment: 0, openFrac: 0, regionsOk: 0, regionsBad: 0, worst: "" };
  if (!sharp) { report.reason = "sharp_unavailable"; return { buf: renderBuf, report }; }
  try {
    const d = plan;
    const r0 = await sharp(renderBuf).removeAlpha().raw().toBuffer({ resolveWithObject: true });
    const rw = r0.info.width, rh = r0.info.height, rpx = r0.data;
    const rInk = new Uint8Array(rw * rh);
    for (let i = 0; i < rw * rh; i++) if (!studioIsBg(rpx, i * 3)) rInk[i] = 1;
    const rFace = studioOuterFace(rInk, rw, rh);
    const rBox = studioBBox(rFace, rw, rh);
    if (!d.faceBox || !rBox) { report.reason = "no_subject"; return { buf: renderBuf, report }; }

    /* registration first: every region test below maps a drawing coordinate
       into the render through these two boxes, so if the silhouettes disagree
       there is nothing worth measuring and nothing safe to punch. */
    const N = 192;
    report.alignment = studioIoU(studioNormalise(d.face, d.w, d.h, d.faceBox, N),
                                 studioNormalise(rFace, rw, rh, rBox, N), N * N);
    if (report.alignment < 0.90) { report.reason = "unaligned"; return { buf: renderBuf, report }; }

    const toRender = (i) => {
      const x = i % d.w, y = (i / d.w) | 0;
      const u = (x - d.faceBox.x0) / d.faceBox.w, v = (y - d.faceBox.y0) / d.faceBox.h;
      const rx = Math.round(rBox.x0 + u * rBox.w), ry = Math.round(rBox.y0 + v * rBox.h);
      if (rx < 0 || ry < 0 || rx >= rw || ry >= rh) return -1;
      return ry * rw + rx;
    };

    /* ── EVERY REGION, NOT THE TOTAL ──────────────────────────────────────
       The old test compared total open AREA against total declared area with
       an 8-point allowance. Measured on a real failure — seven openings, 4.6%
       of the face, against three declared at 1% — that test passes: the two
       wrongly cut legs hide inside the allowance. Area cannot see WHERE a
       hole is. So each declared region is now interrogated on its own: a blue
       region must read open, and a black fill or a metal region must read
       closed. One region in the wrong state fails the render. */
    let bad = 0, ok = 0, worst = "";
    for (const reg of d.regions) {
      let seen = 0, open = 0;
      for (const i of reg.pts) {
        const j = toRender(i);
        if (j < 0) continue;
        seen++;
        if (studioIsBg(rpx, j * 3)) open++;
      }
      if (seen < 8) continue;
      const frac = open / seen;
      const good = reg.kind === "open" ? frac > 0.5 : frac < 0.35;
      if (good) ok++;
      else {
        bad++;
        if (!worst) worst = reg.kind === "open"
          ? `declared cut-out came back solid (${Math.round(frac * 100)}% open)`
          : `metal came back cut (${Math.round(frac * 100)}% open)`;
      }
    }
    report.regionsOk = ok; report.regionsBad = bad; report.worst = worst;
    report.declaredCuts = d.regions.filter((x) => x.kind === "open").length;

    let faceN = 0, openN = 0;
    for (let i = 0; i < rw * rh; i++) { if (!rFace[i]) continue; faceN++; if (studioIsBg(rpx, i * 3)) openN++; }
    report.openFrac = faceN ? openN / faceN : 0;

    /* A region the drawing declared as metal that came back open is the one
       failure compositing cannot undo — the metal is gone. Reject; never
       repair. A declared cut-out that came back solid IS repairable, and is
       repaired below, so it does not reject. */
    const cutIntoMetal = d.regions.some((reg, k) => {
      if (reg.kind !== "closed") return false;
      let seen = 0, open = 0;
      for (const i of reg.pts) { const j = toRender(i); if (j < 0) continue; seen++; if (studioIsBg(rpx, j * 3)) open++; }
      return seen >= 8 && open / seen >= 0.35;
    });
    if (cutIntoMetal) { report.reason = "undeclared_cut"; return { buf: renderBuf, report }; }

    if (!report.declaredCuts) { report.verified = true; report.reason = "no_cuts_declared"; return { buf: renderBuf, report }; }

    /* punch at FULL render resolution: the customer's charm is the artefact */
    const full = await sharp(renderBuf).removeAlpha().raw().toBuffer({ resolveWithObject: true });
    const fw = full.info.width, fh = full.info.height, fpx = full.data;
    const sx = fw / rw, sy = fh / rh;
    const fx0 = rBox.x0 * sx, fy0 = rBox.y0 * sy, fbw = rBox.w * sx, fbh = rBox.h * sy;
    const corners = [0, (fw - 1) * 3, (fh - 1) * fw * 3, ((fh - 1) * fw + fw - 1) * 3];
    const g0 = Math.round(corners.reduce((a, p) => a + fpx[p], 0) / 4);
    const g1 = Math.round(corners.reduce((a, p) => a + fpx[p + 1], 0) / 4);
    const g2 = Math.round(corners.reduce((a, p) => a + fpx[p + 2], 0) / 4);
    let punched = 0;
    for (let y = Math.max(0, Math.floor(fy0)); y < Math.min(fh, Math.ceil(fy0 + fbh)); y++) {
      const v = (y - fy0) / fbh;
      const dy = d.faceBox.y0 + Math.min(d.faceBox.h - 1, Math.floor(v * d.faceBox.h));
      if (dy < 0 || dy >= d.h) continue;
      for (let x = Math.max(0, Math.floor(fx0)); x < Math.min(fw, Math.ceil(fx0 + fbw)); x++) {
        const u = (x - fx0) / fbw;
        const dx = d.faceBox.x0 + Math.min(d.faceBox.w - 1, Math.floor(u * d.faceBox.w));
        if (!d.cut[dy * d.w + dx]) continue;
        const p = (y * fw + x) * 3;
        fpx[p] = g0; fpx[p + 1] = g1; fpx[p + 2] = g2;
        punched++;
      }
    }
    report.punchedPx = punched;
    report.verified = bad === 0;
    report.reason = punched ? "punched" : "nothing_to_punch";
    const out = await sharp(fpx, { raw: { width: fw, height: fh, channels: 3 } }).png().toBuffer();
    return { buf: out, report };
  } catch (err) {
    console.error("[studio] cut-out punch failed:", err?.message || err);
    report.reason = "punch_error";
    return { buf: renderBuf, report };
  }
}

/* ── WHAT A RE-RENDER IS TOLD ─────────────────────────────────────────────
   A retry is a FRESH generation, not a surgical edit. Image models cannot be
   handed a picture and told to change one region and nothing else — the whole
   frame is regenerated every time, which is precisely why the repairable
   failure (a declared opening that came back solid) is fixed in code by
   studioPunchCutouts instead of being asked for again.

   So this note is deliberately phrased against IMAGE 1, never against the
   previous attempt. The renderer is not shown that attempt and cannot
   preserve what it cannot see; telling it to "keep everything else the same"
   would be an instruction it has no way to follow, and an instruction that
   cannot be followed is one more thing competing with the ones that can.

   Only the two unrepairable verdicts reach here:
     undeclared_cut  metal that must be solid came back open
     unaligned       the silhouette drifted far enough that no coordinate in
                     one image maps into the other                          */
function studioRetryNote(report, attempt, builtInHoop) {
  const reason = String(report?.reason || "");
  const worst = studioCleanText(report?.worst || "");
  const lines = ["THIS IS A RE-RENDER. THE PREVIOUS ATTEMPT WAS REJECTED. Render IMAGE 1 again from scratch and correct exactly this:"];

  if (reason === "undeclared_cut") {
    lines.push("• IT REMOVED METAL THAT MUST BE SOLID. A region IMAGE 1 shows as metal came back open, showing the ground through a place where the charm is continuous sheet.");
    if (worst) lines.push(`• Measured on that attempt: ${worst}.`);
    lines.push("• Cut through ONLY where IMAGE 1 is white. Every grey pixel of IMAGE 1 — mid grey and dark grey alike — is solid metal with the ground hidden behind it. An engraved field is metal. A dark area is metal.");
  } else if (reason === "unaligned") {
    lines.push("• ITS SILHOUETTE DID NOT MATCH. The outer outline drifted from IMAGE 1 — reshaped, rescaled, recentred or cropped differently.");
    /* the same clause, the same flag: this note is appended to the render
       prompt, so asserting an integrated hoop here would contradict the
       sentence the prompt itself just swapped out */
    lines.push("• Reproduce IMAGE 1's outer silhouette, " +
               (builtInHoop === true ? "its hanging hardware exactly as it appears"
                                     : "its integrated top hoop") +
               " and its proportions exactly, at the same scale and centred the same way in the frame.");
  } else {
    lines.push("• It failed the geometry check against IMAGE 1. Reproduce IMAGE 1's silhouette, openings and worked regions exactly.");
  }

  lines.push("Everything else about this render is unchanged and is still governed by the instructions above: same alloy, same finish, same white ground, same single soft contact shadow, same framing. Do not compensate for the correction by altering anything else.");
  if (attempt >= 2) lines.push("This correction has already been asked for once. Follow IMAGE 1 literally rather than producing a more attractive charm.");
  return lines.join("\n");
}


/* ══════════════════════════════════════════════════════════════════════════
   THE OPENINGS ARE CUT BY CODE — a POST-PROCESS, not a prompt change
   ─────────────────────────────────────────────────────────────────────────
   Everything below runs AFTER the gold charm is in hand. It never touches
   the render prompt, the model, the attempt loop, the adjudicator or the cut
   check; it takes the finished image and the greyscale map the customer
   approved, and composites the declared through-cuts that the model did not
   make. It is bounded by a deadline and wrapped so that every failure path —
   no sharp, an unreadable map, a drifted silhouette, a thrown anything, an
   exhausted clock — hands the render back exactly as it arrived.

   Nothing here is tuned to one design. Every threshold is a share of the
   charm's own measured size, the tones are read from each map rather than
   assumed, and openings are found by connected components, so the shape, the
   size and the NUMBER of cut-outs are all discovered rather than configured.
   ═══════════════════════════════════════════════════════════════════════ */
/* ═══════════ THE OPENINGS ARE CUT BY CODE, NOT ASKED FOR ═══════════════════
   Measured on four renders of one charm: the grey map declared sixteen
   through-cuts covering 44.8% of the piece, and three of the four came back
   with exactly ONE of them — the hoop hole, 1.7% of the silhouette. The two
   large triangles, 39.5% of the charm between them, were solid metal in
   three renders out of four. Not drift; a whole instruction discarded.

   It cannot be fixed by asking harder. Google's image API documents no seed,
   no temperature and no mask parameter, so every render is an independent,
   unbounded sample and the prompt's "OUTPUT CUT-OUT MASK = IMAGE 1 WHITE
   MASK, exactly" is a request rather than a constraint. What CAN be relied
   on is measured too: the render's outer silhouette already matches the
   mask to about a pixel and a half. The model reproduces the outline and
   discards the interior topology — which is precisely the situation where
   you stop asking and start compositing.

   Nothing below touches the prompt or the model. It runs once, after the
   image is in hand, and it can only ever be skipped: every failure path
   returns the render untouched.

   ── THE RENDER IS NOT A RIGID COPY OF THE MASK ────────────────────────────
   A global fit on the silhouette reaches IoU 0.974, which reads as aligned
   and is not: the model does not transform the mask, it REDRAWS the charm
   with its own slightly different internal proportions. The openings want
   corrections that differ from each other by up to 8 px, and a weighted
   affine field through those corrections scored no better than no correction
   at all — 0.691 against 0.684. The distortion is local.

   Matching every opening independently is not the answer either: six
   identical fletching slots 36 px apart are a periodic pattern, and an
   unbounded search lands each one on its neighbour with a perfect score.

   So openings are matched as RIGID CLUSTERS — neighbours move together,
   which is what the object does and what keeps the spacing inside a row
   exactly as the mask drew it.

   ── AND THE SIGNAL HAS A SIGN ─────────────────────────────────────────────
   The first version matched each opening's boundary band against the
   render's DARKNESS, reasoning that a cut the model failed to make comes
   back as an engraved outline so the boundary is always there in ink. The
   boundary is; the score still had no penalty for sliding, because "mean
   darkness under a thin band" is maximised by moving that band into whatever
   is darkest nearby — and on a charm that is the engraved field the opening
   sits in. The fletching group slid 15 px into its own feather.

   Measured, the polarity runs the other way: a declared opening comes back
   BRIGHT, because the model renders the hole as raised polished metal rather
   than cutting it, by +46 to +80 luminance against the engraved ring around
   it. The score is that contrast, and it FALLS when the placement slides
   into the engraving. On the fletching cluster it moves the answer from
   dy+6 dx-15 at +31 to dy+5 dx+3 at +98.

   Contrast also says how much to trust each answer. Anything under the
   confidence line takes the consensus of the clusters that are sure, which
   is measurably right where two weak clusters' own readings were not.

   ── AN OPENING THAT WOULD SEVER THE CHARM IS NOT AN OPENING ───────────────
   One mask declared a 126 px ring around the hoop, 6 px wide at its widest.
   Cutting it drops the hoop off the body as a separate 10,575 px piece — a
   charm that leaves the machine in two parts. Tracing artefact, not
   instruction. Every declared opening is tested first and one whose removal
   disconnects the metal is refused outright.

   ── AND THE TONES ARE READ, NOT ASSUMED ───────────────────────────────────
   This began by testing each pixel against a hardcoded 176/136 pair, and the
   very next mask encoded engraving as 96: forty greys away, every engraved
   pixel failed the metal test, and the engraved line network came back as a
   274,000 px through-cut — 27.6% of that charm declared open. The fill law
   does not need the constants. White is empty; anything else inside the
   silhouette is metal, which is the same rule studioTopologyMask applies.  */

const SCO_MIN_AREA      = 150;    /* smaller than this is speckle, not design */
const SCO_BIG_AREA      = 5000;   /* at this size a feature is matched alone */
const SCO_CLUSTER_FRAC  = 0.040;  /* neighbours within this share of the charm move together */
const SCO_ALREADY_OPEN  = 0.40;   /* leave alone anything the render already cut this well */
/* ── AND "ALREADY CUT" HAS TO TOLERATE THE REGISTRATION IT IS MEASURED IN ─
   SCO_ALREADY_OPEN asks what share of an opening's own footprint the render
   has already cut. That is the right question and it was asked in a way a
   thin feature can never answer: a 12 px feather slot registered 6 px out
   overlaps its own rendered opening by half, so a hole the model cut
   perfectly well reads as 50% solid, fails the test, and gets a SECOND copy
   composited beside it. That is the double-cut with a sliver of gold down
   the middle — two versions of one hole, which is worse than either.

   So the footprint also asks a question that does not depend on landing
   dead-on: how far is the render's OWN nearest opening. Under a hole the
   model cut, that distance is a few pixels across the whole footprint; under
   metal the model never cut, the nearest opening is the next slot over — a
   whole feature-spacing away. The tolerance is bounded by the distance to
   the nearest OTHER declared opening, so it can never adopt a neighbour: the
   bound is geometry, not a guess.                                          */
/* ── THE ENGRAVING-FILL TEST — see scoEngraveFill ─────────────────────────
   Calibrated on ONE bad render against its own map, which is why the gate it
   feeds ships in "observe": it measures and files the numbers, and does not
   re-roll anything until this pair has been seen on real traffic. One word in
   config/customStudio (renderEngraveGate: "on") turns it into a re-roll.
   On the swallow: over = 0.087 at an allowance of 1.25, 0.050 at 1.50. A
   render that obeys its map cannot be thicker than its map, so a correct one
   sits near zero and the whole span between is margin.                     */
const SCO_ENG_EDGE_FRAC = 0.012;  /* start the census this far in from any metal edge */
/* WHERE THE POLISHED LEVEL IS READ FROM. p75 was the obvious choice and it
   goes blind on the worst renders: fill 70% of a charm and the 75th
   percentile of its surface IS the engraving, so the test measures
   engraving against engraving and reports a clean charm. Measured across
   p75/p80/p85/p90 on three pairs, p80 through p90 all give the same answer
   and p75 alone is wrong — so this sits in the middle of the plateau, not
   on the edge of the cliff. */
const SCO_ENG_POL_PCT   = 0.85;   /* this percentile of the core surface is polish */
const SCO_ENG_DROP      = 0.06;   /* darker than the polish by this share of it = engraved */
const SCO_ENG_ALLOW     = 1.35;   /* a stroke may be this much thicker than the map's thickest */
const SCO_ENG_FILL_MAX  = 0.05;   /* and this share of the engraving may exceed that */
/* ── AND HOW DARK AN ENGRAVED RECESS MAY BE ───────────────────────────────
   Measured as a bimodal split of the charm's own surface — the polished mode
   and the engraved mode — so it is a RATIO between two things in the same
   photograph and cannot be thrown off by exposure, metal or resolution.

     the customer-approved swallow   polished #F5DDA6  engraved #D4B87F  0.837
     the render they rejected        polished #F6E0AD  engraved #866B3D  0.488

   The base gold is the same in both to within two levels; only the recess
   moves, and it moves by a factor that is impossible to mistake. The target
   below is the approved charm's own number, and the floor sits between the
   two populations with room on either side. The prompt quotes the target in
   words, so the picture the renderer is shown and the sentence it is given
   say the same thing. */
const STUDIO_ENGRAVE_RATIO = 0.85;  /* engraved brightness ÷ polished brightness — the standard */
const SCO_ENG_TONE_MIN     = 0.72;  /* below this the recess reads as a hole or a second metal */
const SCO_NEAR_OPEN_FRAC = 0.70;  /* this share of a footprint within reach of a real opening */
const SCO_NEAR_TOL_FRAC  = 0.045; /* and "within reach" reaches this far, as a share of the charm */
const SCO_ERODE_FRAC    = 0.0037; /* keep the cut this far inside the render's own metal */
const SCO_RING_FRAC     = 0.026;  /* how wide a ring of surround the match reads */
const SCO_MIN_CONTRAST  = 6;      /* below this there is no evidence to move anything */
const SCO_SURE_CONTRAST = 60;     /* above this a cluster's own shift is trusted outright */
const SCO_SEVER_FRAC    = 0.0016; /* a cut leaving a loose piece this big is refused */
const SCO_RIM_FRAC      = 0.0032; /* width of the bright catch on the cut wall */
const SCO_SHADOW_FRAC   = 0.0152; /* reach of the shadow on the metal beside a cut */
/* ── A CATCH OF LIGHT ON GOLD IS STILL GOLD ───────────────────────────────
   The cut wall was brightened by mixing the metal toward WHITE — one lerp,
   38% of the way at the crest. That is the wrong operation for a metal, and
   the measurement says so: on (198,158,62) it lands (219,195,135), which is
   a 44% loss of saturation. Two or three pixels of pale, chalky, colourless
   metal ran all the way round every composited opening, and it read worst
   exactly where the surrounding gold was darkest — the shaded lower edge of
   a hole — because there the same 38% is a far bigger relative change. That
   is the "washed out around the hole" the eye keeps catching.

   Brightness and whiteness are not the same thing. A polished bevel catching
   a key light is BRIGHTER GOLD: every channel scales together, so the hue
   and the saturation come through untouched, and only the very crest of a
   specular highlight clips toward white. So the gain is multiplicative and
   the white is a separate, much smaller term with a squared falloff, which
   confines it to a single pixel at the peak instead of spreading it across
   the whole rim.                                                           */
const SCO_RIM_GAIN      = 0.30;   /* how much brighter the cut wall gets, chroma intact */
const SCO_RIM_WHITE     = 0.10;   /* and the specular crest on top of it, squared falloff */
const SCO_SHADOW_K      = 0.26;   /* how deep the shadow beside it goes */
const SCO_SEARCH_FRAC   = 0.42;   /* search radius, as a share of a cluster's own size */
const SCO_SEARCH_CAP    = 0.037;  /* and never more than this share of the charm */
const SCO_MATCH_SAMPLES = 5000;   /* pixels per mean in the match — see the note there */
const SCO_SHIFT_PAD_FRAC = 0.005; /* how far past its own radius an opening may be nudged */
const SCO_MATCH_MARGIN  = 6;      /* levels the best offset must beat standing still by */
/* ── the frame check: see scoFurniture ─────────────────────────────────────
   Measured, the biggest stray blob as a share of the charm's bounding box:
     a clean render          0.001 and 0.009
     a contact-sheet render  0.47
   The limit sits at 0.06 — six times the worst clean render and eight times
   under the failure — so neither population is anywhere near it.          */
const SCO_SHADOW_REACH  = 0.10;   /* how far a contact shadow may reach, of charm size */
const SCO_FURN_DEV      = 26;     /* levels from the ground before a pixel is not ground */
const SCO_FURN_SAT      = 36;     /* or this saturated, whatever its brightness */
const SCO_FURN_MIN_BLOB = 0.00035;/* smaller than this share of the charm is speckle */
const SCO_FURN_LIMIT    = 0.06;   /* one blob this big and the frame is not a product shot */
/* ── the alloy check: see scoAlloy ─────────────────────────────────────── */
const SCO_ALLOY_OPEN_MARGIN = 24; /* this close to the ground and neutral = an opening, not metal */
const SCO_ALLOY_OPEN_SAT    = 28;
const SCO_ALLOY_FRAC        = 0.35;/* below this share of the piece's own chroma is another metal */
const SCO_ALLOY_FLOOR       = 34; /* and never a looser test than this in absolute terms */
const SCO_ALLOY_LIMIT       = 0.12;/* this much of the metal off-alloy and the piece is two-tone */
/* the outline check: see scoBoundaryError. Percentages of the charm's size. */
/* ── AND THE TAIL TURNED OUT TO BE NOISE ──────────────────────────────────
   The p95 was kept because "one wrong shoulder moves the tail before it moves
   the average". True — but so does one nearly-closed coil, and a dragon has
   several. Two good dragons scored 3.16 and 17.98 on it while the heart that
   passed for a shield scored 9.83: the good and the bad populations OVERLAP,
   and on the second dragon the good one is the worst reading of the eight.
   A test that cannot order its own evidence is not a test, so it is gone.

   The mean still separates, but not by much, and that is worth stating
   plainly: good renders run 0.40 / 0.57 / 0.73 / 1.72 and bad ones 2.64 /
   2.94 / 5.43 / 6.06. The limit sits at 2.2 — 1.3x above the worst good and
   1.2x below the best bad. That is the thinnest margin of the four checks
   and the only one calibrated on four samples rather than a clean gap.

   It earns its place because it is the ONLY check that caught the heart
   drawn for a shield: that render passed IoU at 0.9119, passed the alloy
   test at 0.0862 and had no stray content at all. And it is safe to keep at
   a thin margin because it no longer blocks the composite — a false positive
   costs a re-roll, never the customer's cut-outs. */
const SCO_OUTLINE_MEAN      = 2.2; /* average distance between the two outlines */
const SCO_CMP_CLOSE         = 4;  /* both silhouettes are closed by this before comparing */

/* ── AND IoU IS INVERTED IN THE BAND THAT MATTERS ─────────────────────────
   THIS IS WHY A DRAGON SHIPS WITH ITS SCALES ENGRAVED. The composite has
   always been cancelled outright when the silhouette IoU fell under 0.90 —
   the reasoning being that without a fit, every placement below is a guess.
   The reasoning is right. The measurement is not.

   Ten pairs, good and bad, ranked by both numbers:

     GOOD dragon-1      IoU 0.9689   boundary 0.43
     GOOD dragon-2      IoU 0.9528   boundary 0.73
     GOOD dragon-4      IoU 0.9053   boundary 1.72
     BAD  heart/shield  IoU 0.9119   boundary 2.64
     BAD  dragon-3/dr4  IoU 0.7983   boundary 2.61
     BAD  dragon-3/dr   IoU 0.7628   boundary 2.94
     BAD  dragon-2/dr4  IoU 0.7905   boundary 3.25
     BAD  astronaut     IoU 0.7308   boundary 6.06
     BAD  p-pair        IoU 0.6678   boundary 12.02

   The worst GOOD IoU is 0.9053 and the best BAD is 0.9119. No threshold
   separates them; the order is wrong. The boundary distance separates them
   cleanly — 1.72 against 2.61 — because it is a DISTANCE and IoU is an AREA.
   A one-pixel boundary error costs a blob almost no overlap and costs a
   coiled dragon a great deal, since a dragon is nearly all perimeter. IoU
   therefore measures how thin the charm is at least as much as how wrong the
   render is, and the customer's most intricate designs are exactly the ones
   it punishes. A dragon at 0.89 lost EVERY declared opening — not a few
   scales, all of them — and shipped the model's engraving instead.

   So the cancel gate becomes a distance, and it sits far looser than the
   re-roll limit above, because the two ask different questions. 2.2 asks
   "is this worth another attempt?" — a false positive there costs one
   render. This one asks "does any coordinate mapping exist between these
   two pictures?" — a false positive here costs the customer their cut-outs,
   which is the expensive mistake and the one that has already been made.
   At 5.0 it cancels only the astronaut and the p-pair, where the model drew
   a different charm; the heart-for-shield still gets its openings cut, and
   the re-roll gate has already objected to it on its own account.

   The IoU floor stays as a backstop against a render that is not a charm at
   all, at 0.70 — below every bad sample here except the two the distance
   already catches, and 0.20 clear of the worst good one. */
const SCO_FIT_FAIL          = 5.0; /* boundary distance past which no placement is meaningful */
const SCO_FIT_IOU           = 0.70;/* and a floor for the case where there is no charm to trace */
/* ── AND THE ONE THE FIT ITSELF HIDES: A CHARM REDRAWN AT A DIFFERENT SHAPE ─
   Every placement in this file maps a mask coordinate through the two
   BOUNDING BOXES — kx = rb.w/mb.w, ky = rb.h/mb.h — and that pair is a free
   non-uniform scale. So a render that reproduces the outline but stretches
   it on one axis is normalised away before anything is measured: the fit
   reports a good IoU, the outline check passes, and every interior feature
   is then placed by a transform that squashes one axis by however much the
   model stretched it. Nothing downstream can see it, because it was removed
   before the measuring began.

   Measured, bounding-box anisotropy — (rb.w/mb.w) ÷ (rb.h/mb.h), folded so
   it is never below 1:

     swallow, the render the customer approved          1.079
     swallow, same map, the one rejected for tone       1.079   (identical: it
                                                                 is a property
                                                                 of the pair)
     bow and arrow, which fails on almost every render  1.208

   The bow's silhouette IoU is 0.812 and its outline distance passes; on
   every existing gate it is a good render. It is not: scaled to one height,
   its right limb sits 17% narrower than the map's, so the map's fletching
   slots land nowhere near the ones the model actually cut, the "already cut"
   test misses them, and a second set is composited beside the first.

   WHAT THIS DOES ABOUT IT IS REFUSE TO COMPOSITE, not re-roll. On a charm
   this far out no placement is trustworthy, and the two outcomes are not
   symmetrical: leaving the model's own openings alone gives a charm missing
   some holes, while placing ours gives a charm with holes in the wrong
   places AND the model's still there. Missing is recoverable by generating
   again; doubled is a disaster on the customer's screen.

   THE THRESHOLD IS CALIBRATED ON THREE PAIRS AND IS A CONFIG VALUE for that
   reason: renderAspectMax. Two good renders at 1.079 and one bad at 1.208
   is a real gap but a narrow one, and renderAspect is written to every
   version doc so the population can be watched before it is tightened. */
const SCO_ASPECT_MAX        = 1.15;/* bbox anisotropy past which no placement is trustworthy */

/* ── WHAT A HOLE LOOKS LIKE FROM THE INSIDE ────────────────────────────────
   A hole the model cuts is NOT the plain ground showing through: the metal
   shades the paper. Filling flat white was the whole reason a composited
   hole read differently from one the model cut — 36 levels of ground against
   33 on the metal side, where the two already agree.

   Making the shading a function of DEPTH was wrong in a way only a second
   sample shows. Fitted on a small hoop hole it gave a dip of 0.31 reaching
   14 px, and applied to the big triangles it washed them grey to the middle.
   Depth does not know that a small hole is close to metal in EVERY direction
   while a large one is close to it only near the rim.

   The quantity the two DO agree on is occlusion — how much metal surrounds
   the point. Blurred at a small sigma and read inside the opening, a 88 px
   triangle and a 33 px hole fall on one curve to within 1.3% of the ground:
       occ        0.05   0.10   0.20   0.30   0.40   0.50
       triangle   0.935  0.909  0.870  0.853  0.829  0.807
       hoop hole  0.924  0.903  0.870  0.860  0.845  0.815
   The fit reproduces both, and it goes to 1.0 as occlusion goes to 0 — so
   the middle of a large opening is plain ground, never a grey wash.

   AND THE BLUR SCALES WITH THE HOLE. One radius for the whole charm is
   right for a large opening and wrong for a small one, because occlusion is
   only meaningful relative to the hole it is measured in. At a single sigma
   of 4.1 px the triangles read 254 at their centres — plain ground, which is
   why they looked right — while every 5 px slot never fell below 0.22
   occlusion anywhere inside it and came out at 208-214. Grey, and visibly
   so. Each opening therefore gets a blur set by its OWN inscribed radius,
   which makes the shadow a fixed fraction of the hole rather than a fixed
   number of pixels: every opening then reads as ground through the middle
   with the shading confined to its rim, whatever its size.                 */
const SCO_OCC_CEIL  = 0.0094;   /* blur ceiling, as a share of the charm's size */
const SCO_OCC_FRAC  = 0.050;    /* blur as a share of the opening's inscribed radius */
const SCO_OCC_MIN   = 0.9;      /* px: the least blur any opening gets */
const SCO_OCC_POW   = 0.50;     /* shape of the curve, fitted across both samples */
const SCO_OCC_K     = 0.282;    /* its strength — refitted per render, see below */
const SCO_OCC_K_LO  = 0.20;     /* the refit is clamped to the band the samples span */
const SCO_OCC_K_HI  = 0.34;

/* ── local morphology, 8-connected, so the port matches its reference ───── */
function scoDilate8(mask, w, h, r) {
  let a = mask;
  for (let k = 0; k < r; k++) {
    const b = new Uint8Array(w * h);
    for (let y = 0; y < h; y++) {
      const y0 = Math.max(0, y - 1), y1 = Math.min(h - 1, y + 1);
      for (let x = 0; x < w; x++) {
        const x0 = Math.max(0, x - 1), x1 = Math.min(w - 1, x + 1);
        let on = 0;
        for (let yy = y0; yy <= y1 && !on; yy++) {
          for (let xx = x0; xx <= x1; xx++) if (a[yy * w + xx]) { on = 1; break; }
        }
        b[y * w + x] = on;
      }
    }
    a = b;
  }
  return a;
}
function scoErode8(mask, w, h, r) {
  let a = mask;
  for (let k = 0; k < r; k++) {
    const b = new Uint8Array(w * h);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        if (x === 0 || y === 0 || x === w - 1 || y === h - 1) { b[y * w + x] = 0; continue; }
        let on = 1;
        for (let yy = y - 1; yy <= y + 1 && on; yy++) {
          for (let xx = x - 1; xx <= x + 1; xx++) if (!a[yy * w + xx]) { on = 0; break; }
        }
        b[y * w + x] = on;
      }
    }
    a = b;
  }
  return a;
}
/* a square structuring element of side 2r+1, separably — the 9x9 closing the
   render's own segmentation needs would be 4 passes of 3x3 otherwise */
function scoBoxMorph(mask, w, h, r, grow) {
  const t = new Uint8Array(w * h), o = new Uint8Array(w * h);
  const want = grow ? 1 : 0;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let hit = grow ? 0 : 1;
      const x0 = Math.max(0, x - r), x1 = Math.min(w - 1, x + r);
      for (let xx = x0; xx <= x1; xx++) {
        if ((mask[y * w + xx] ? 1 : 0) === want) { hit = want; break; }
      }
      t[y * w + x] = hit;
    }
  }
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let hit = grow ? 0 : 1;
      const y0 = Math.max(0, y - r), y1 = Math.min(h - 1, y + r);
      for (let yy = y0; yy <= y1; yy++) {
        if ((t[yy * w + x] ? 1 : 0) === want) { hit = want; break; }
      }
      o[y * w + x] = hit;
    }
  }
  return o;
}
function scoClose(mask, w, h, r) {
  return scoBoxMorph(scoBoxMorph(mask, w, h, r, true), w, h, r, false);
}
/* everything the border cannot reach is interior */
function scoFillHoles(mask, w, h) {
  const out = new Uint8Array(w * h);
  const seen = new Uint8Array(w * h);
  const stack = new Int32Array(w * h);
  let top = 0;
  const push = (i) => { if (!mask[i] && !seen[i]) { seen[i] = 1; stack[top++] = i; } };
  for (let x = 0; x < w; x++) { push(x); push((h - 1) * w + x); }
  for (let y = 0; y < h; y++) { push(y * w); push(y * w + w - 1); }
  while (top) {
    const i = stack[--top], x = i % w, y = (i / w) | 0;
    if (x > 0) push(i - 1);
    if (x < w - 1) push(i + 1);
    if (y > 0) push(i - w);
    if (y < h - 1) push(i + w);
  }
  for (let i = 0; i < w * h; i++) out[i] = (mask[i] || !seen[i]) ? 1 : 0;
  return out;
}

/* THE CHARM IS NOT THE FRAME. A studio spec or render can carry furniture
   that touches the edge of the picture — a caption chip, a thin border, a
   neighbouring tile bleeding in — and any of it can be larger than the charm
   and win "largest component" outright. Measured on a mask with a caption
   strip: the silhouette came back as the whole 810x810 frame and every white
   pixel of the background was read as a declared opening.
   The charm floats: nothing that reaches the border is part of it. Dropped
   only when what remains is still substantial, so a legitimately edge-to-edge
   subject is never thrown away — that case is caught by the drift gate. */
function scoDropBorderTouching(mask, w, h) {
  const seen = new Uint8Array(w * h);
  const stack = new Int32Array(w * h);
  let top = 0;
  const push = (i) => { if (mask[i] && !seen[i]) { seen[i] = 1; stack[top++] = i; } };
  /* SEEDED FROM A MARGIN, NOT THE EDGE ITSELF. The furniture that caused
     this was a frame rule inset by one pixel — border-adjacent but not
     border-touching, so an edge-exact seed walked straight past it and the
     fill-holes that followed filled the entire picture. The margin is a
     share of the frame so it holds at any render size. */
  const m = Math.max(2, Math.round(0.006 * Math.max(w, h)));
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (x < m || y < m || x >= w - m || y >= h - m) push(y * w + x);
    }
  }
  while (top) {
    const i = stack[--top], x = i % w, y = (i / w) | 0;
    if (x > 0) push(i - 1);
    if (x < w - 1) push(i + 1);
    if (y > 0) push(i - w);
    if (y < h - 1) push(i + w);
  }
  let kept = 0, all = 0;
  const out = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) {
    if (mask[i]) all++;
    if (mask[i] && !seen[i]) { out[i] = 1; kept++; }
  }
  return kept >= all * 0.2 ? out : mask;
}

/* DILATION BY DISTANCE, not by iteration. A ring eleven pixels wide costs
   eleven full-image passes as repeated 4-connected growth and one linear
   pass as a distance field — and the field's ring is a true circle rather
   than a diamond, which is what "within eleven pixels" was always meant to
   say. */
function scoInvert(mask, w, h) {
  const inv = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) inv[i] = mask[i] ? 0 : 1;
  return inv;
}
function scoWithin(mask, w, h, r) {
  const d = studioEdt2d(scoInvert(mask, w, h), w, h);
  const out = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) out[i] = d[i] <= r ? 1 : 0;
  return out;
}

/* ── reading the two pictures ──────────────────────────────────────────── */
async function scoReadRaw(sharp, buf) {
  const { data, info } = await sharp(buf).removeAlpha().raw()
    .toBuffer({ resolveWithObject: true });
  return { px: data, w: info.width, h: info.height, ch: info.channels };
}

/* THE RENDER'S OWN METAL. Saturation, not luminance: gold is the only
   saturated thing in a white studio shot, and the contact shadow underneath
   it is grey — so a saturation cut separates metal from both the ground and
   its own shadow, which no brightness threshold does. */
function scoRenderParts(px, w, h, ch) {
  const n = w * h;
  const sat = new Uint8Array(n), lum = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const p = i * ch, r = px[p], g = px[p + 1], b = px[p + 2];
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
    sat[i] = mx ? (mx - mn) * 255 / mx > 32 ? 1 : 0 : 0;
    lum[i] = 0.299 * r + 0.587 * g + 0.114 * b;
  }
  const closed = scoClose(sat, w, h, 4);
  const outer = studioLargestComponent(
    scoFillHoles(scoDropBorderTouching(closed, w, h), w, h), w, h);
  const metal = new Uint8Array(n);
  for (let i = 0; i < n; i++) metal[i] = (closed[i] && outer[i]) ? 1 : 0;
  return { outer, metal, lum };
}

/* THE MASK, BY THE FILL LAW. White is empty; anything else inside the
   silhouette is metal. The polished tone is then whatever most of that metal
   is and engraving is whatever is meaningfully darker, both measured per
   mask — so a spec at 136 and a spec at 96 read the same way. */
function scoMaskParts(px, w, h, ch) {
  const n = w * h;
  const grey = new Uint8Array(n);
  for (let i = 0; i < n; i++) grey[i] = px[i * ch];
  const solid = new Uint8Array(n);
  for (let i = 0; i < n; i++) solid[i] = grey[i] < 240 ? 1 : 0;
  const closed = scoDilate8(solid, w, h, 1);
  const metal0 = scoDropBorderTouching(scoErode8(closed, w, h, 1), w, h);
  const outer = studioLargestComponent(scoFillHoles(metal0, w, h), w, h);
  const metal = new Uint8Array(n);
  for (let i = 0; i < n; i++) metal[i] = (metal0[i] && outer[i]) ? 1 : 0;

  const hist = new Float64Array(256);
  for (let i = 0; i < n; i++) if (metal[i]) hist[grey[i]]++;
  let polish = 176, best = -1;
  for (let v = 0; v < 256; v++) if (hist[v] > best) { best = hist[v]; polish = v; }
  const span = Math.max(1, 255 - polish);

  /* ── AND A SILHOUETTE BUILT THE SAME WAY THE RENDER'S IS ──────────────
     The two sides were segmented with different morphology: the render is
     closed by radius 4 to bridge the specular gaps a photograph of polished
     gold always has, the mask by radius 1 because a drawing has none. On a
     shape whose outline nearly touches itself — a dragon's coil — radius 4
     seals the gap and radius 1 does not, so one silhouette has a filled loop
     and the other has a hole in the same place. Measured on that dragon it
     was a 7,212 px blob, 8% of the charm, and it read to the outline check
     as a boundary a hundred pixels out of place.

     Nothing about the charm differed; the preprocessing did. A comparison
     between two silhouettes is only meaningful if both were made the same
     way, so this one is closed by the same radius. It is used ONLY for the
     fit and the outline check — `outer` above still decides where the metal
     is, what is a hole and where everything is placed. */
  const cmp = studioLargestComponent(
    scoFillHoles(scoDropBorderTouching(scoClose(solid, w, h, SCO_CMP_CLOSE), w, h), w, h), w, h);

  const holes = new Uint8Array(n), engraved = new Uint8Array(n);
  const alpha = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    if (!outer[i]) continue;
    if (!metal[i]) holes[i] = 1;
    if (grey[i] < polish - 20) engraved[i] = 1;
    const a = (grey[i] - polish) / span;
    alpha[i] = a < 0 ? 0 : a > 1 ? 1 : a;
  }
  return { outer, outerCmp: cmp, holes, alpha, engraved, polish };
}

/* ── THE GROUND, READ FROM THE GROUND ─────────────────────────────────────
   The ground colour used to be the mean of two 24 px corners. That is right
   for a product shot and catastrophic for anything else: a render that came
   back as a contact sheet had a BLACK inset panel occupying one of those
   corners, and every composited opening would have been filled with the
   average of white paper and that panel. A colour used to paint holes must
   not be readable off two arbitrary squares.

   So it is read from the whole border ring, and only from pixels that could
   plausibly BE ground — bright and unsaturated — taken as a median so a
   panel, a caption or a stray object cannot drag it. The old corner mean
   stays as the fallback for the case where the border holds no such pixels
   at all, because a wrong ground is still better than no render.           */
function scoGroundColour(px, w, h, ch, outer) {
  const band = Math.max(4, Math.round(0.03 * Math.max(w, h)));
  const rs = [], gs = [], bs = [];
  for (let y = 0; y < h; y++) {
    const edgeRow = y < band || y >= h - band;
    for (let x = 0; x < w; x++) {
      if (!edgeRow && x >= band && x < w - band) { x = w - band - 1; continue; }
      const i = y * w + x;
      if (outer && outer[i]) continue;
      const p = i * ch, r = px[p], g = px[p + 1], b = px[p + 2];
      const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
      if (mx < 170) continue;                       /* too dark to be paper */
      if (mx && (mx - mn) * 255 / mx > 26) continue; /* too coloured to be paper */
      rs.push(r); gs.push(g); bs.push(b);
    }
  }
  if (rs.length >= 64) {
    const med = (a) => { a.sort((p, q) => p - q); return a[a.length >> 1]; };
    return { r: med(rs), g: med(gs), b: med(bs), read: rs.length };
  }
  let cr = 0, cg = 0, cb = 0, cn = 0;
  const corner = 24;
  for (let y = 0; y < Math.min(corner, h); y++) {
    for (let x = 0; x < Math.min(corner, w); x++) {
      const p = (y * w + x) * ch; cr += px[p]; cg += px[p + 1]; cb += px[p + 2]; cn++;
    }
    for (let x = Math.max(0, w - corner); x < w; x++) {
      const p = (y * w + x) * ch; cr += px[p]; cg += px[p + 1]; cb += px[p + 2]; cn++;
    }
  }
  return { r: cr / (cn || 1), g: cg / (cn || 1), b: cb / (cn || 1), read: 0 };
}

/* ── WHAT ELSE IS IN THE PICTURE ──────────────────────────────────────────
   A product shot is the charm, its own contact shadow, and empty ground.
   Anything else in the frame — an inset panel, a caption, a border, a
   swatch, a second object — is furniture, and a render carrying furniture is
   not a photograph of a charm however good the charm in it looks.

   The shadow is the one thing that must not be mistaken for furniture, and
   it is distinguished by proximity rather than by colour: it lies under and
   beside the piece. Everything within reach of the silhouette is therefore
   excused, and the reach is a share of the charm's own size so it holds at
   any framing.                                                             */
function scoFurniture(px, w, h, ch, outer, rb, gnd) {
  const n = w * h;
  const reach = Math.max(12, SCO_SHADOW_REACH * Math.sqrt(Math.max(1, rb.w * rb.h)));
  const near = scoWithin(outer, w, h, reach);
  const dirty = new Uint8Array(n);
  let count = 0;
  for (let i = 0; i < n; i++) {
    if (outer[i] || near[i]) continue;
    const p = i * ch, r = px[p], g = px[p + 1], b = px[p + 2];
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
    const dev = Math.max(Math.abs(r - gnd.r), Math.abs(g - gnd.g), Math.abs(b - gnd.b));
    if (dev > SCO_FURN_DEV || (mx && (mx - mn) * 255 / mx > SCO_FURN_SAT)) { dirty[i] = 1; count++; }
  }
  const lab = studioLabel(dirty, w, h);
  const area = new Float64Array(lab.count + 1);
  for (let i = 0; i < n; i++) if (lab.labels[i]) area[lab.labels[i]]++;
  const charmArea = Math.max(1, rb.w * rb.h);
  const minBlob = Math.max(80, SCO_FURN_MIN_BLOB * charmArea);
  let blobs = 0, biggest = 0;
  for (let L = 1; L <= lab.count; L++) {
    if (area[L] >= minBlob) blobs++;
    if (area[L] > biggest) biggest = area[L];
  }
  return {
    frac: Math.round(count / n * 1e4) / 1e4,
    biggest: Math.round(biggest / charmArea * 1e4) / 1e4,
    blobs,
    dirty: biggest / charmArea > SCO_FURN_LIMIT,
  };
}

/* ── THE OUTLINE, NOT JUST THE MASS ───────────────────────────────────────
   IoU measures MASS, and two shapes of the same rough mass and extent score
   high however differently their outlines run. A HEART came back for a
   SHIELD and scored 0.9118 — over the line — because both are wide at the
   top, pointed at the bottom, symmetric, and fill the same box. What differs
   is convex lobes against concave shoulders, and an area measure cannot see
   it. Nine per cent of the area is the whole difference between two shapes
   nobody would confuse by eye.

   The boundary is what differs, so measure the boundary: for every edge
   pixel of one silhouette, the distance to the nearest edge pixel of the
   other, both directions, in units of the charm's own size so the number
   means the same at any resolution.

   Measured, as a percentage of charm size:
                              mean     p95
     good render               0.41     1.15
     good render               0.57     1.85
     the same at 512 / 1600px  0.61     1.87    (scale-invariant)
     a perfect synthetic       0.17     0.40
     ─────────────────────────────────────
     heart for a shield        2.64     9.83    ← IoU passed this
     two-tone bow              3.66     9.41
     wrong astronaut           6.06    15.06
   Two populations, four times apart, with nothing in between. The limits sit
   in the middle of that gap and the p95 is kept as well as the mean because
   a localised difference — one wrong shoulder on an otherwise right outline
   — moves the tail long before it moves the average.                       */
function scoOutlineEdge(m, w, h) {
  const e = new Uint8Array(w * h);
  for (let y = 1; y < h - 1; y++) {
    const row = y * w;
    for (let x = 1; x < w - 1; x++) {
      const i = row + x;
      if (!m[i]) continue;
      if (!m[i - 1] || !m[i + 1] || !m[i - w] || !m[i + w]) e[i] = 1;
    }
  }
  return e;
}
function scoBoundaryError(a, b, w, h, scale) {
  const ea = scoOutlineEdge(a, w, h), eb = scoOutlineEdge(b, w, h);
  const da = studioEdt2d(scoInvert(ea, w, h), w, h);
  const db = studioEdt2d(scoInvert(eb, w, h), w, h);
  const all = [];
  for (let i = 0; i < w * h; i++) {
    if (ea[i]) all.push(db[i]);
    if (eb[i]) all.push(da[i]);
  }
  if (all.length < 32 || !(scale > 0)) return { mean: 0, p95: 0, dirty: false };
  all.sort((p, q) => p - q);
  let sum = 0;
  for (let k = 0; k < all.length; k++) sum += all[k];
  const mean = sum / all.length / scale * 100;
  const p95 = all[Math.floor(all.length * 0.95)] / scale * 100;
  return {
    mean: Math.round(mean * 100) / 100,
    p95: Math.round(p95 * 100) / 100,
    dirty: mean > SCO_OUTLINE_MEAN,
  };
}

/* ── IS THE WHOLE PIECE ONE METAL? ────────────────────────────────────────
   A bow came back half gold and half gunmetal: the outer curve yellow, the
   bow's body and the arrow a flat dark grey, as though two alloys had been
   soldered together. The prompt names one alloy and calls colour leakage a
   hard fail, and it happened anyway — which is what "asking" is worth
   against an unseeded sampler.

   It is one number. A charm is one alloy, so its metal has ONE chroma; a
   render that is part gold and part grey is bimodal in saturation, and the
   grey half sits far below what the piece's own metal looks like. Measured
   on the raw model output, before anything is composited:
     good render      1.2% and 1.1% of the metal is off-alloy
     the grey bow     48.6%
   The reference is the piece's own upper-quartile saturation rather than a
   fixed number, so the test asks "is this all one metal" instead of "is this
   gold" — a question that stays meaningful if the alloy ever changes.

   Openings are excluded by brightness: ground showing through a cut is
   neutral too, and it is not metal.                                        */
/* ── DID THE RENDER FILL WHAT THE MAP DREW AS A LINE? ──────────────────────
   A different failure from a missing cut, and invisible to every check that
   counts things. Measured on a swallow whose map declares its engraving as a
   NETWORK OF STROKES — feather ribs, a body contour, a cheek circle, a beak:

                                    map      render
     engraved area, share of charm   17.6%    26.2%
     stroke half-width, median       1.0px    2.8px
     stroke half-width, p90          3.6px    8.5px
     engraved px in strokes thicker
       than 2% of the charm            1%      18%

   The render did not invent new decoration. It read each closed engraved
   OUTLINE as an instruction to recess everything the outline encloses, so
   the head, the flank under the wing and the tail band came back as broad
   sunken pockets where the map has plain polished metal inside a thin line.
   An area check barely moves on that — 17.6 to 26.2 — and a count of
   engraved regions does not move at all, because the regions are the same
   regions, only fatter. THICKNESS is what moves, and by eighteen times.

   So the test is thickness, and its ceiling comes from THIS MAP rather than
   from a constant: a map whose engraving is all hairlines permits only
   hairlines, and a map that genuinely declares a broad engraved field
   permits that field. Registration does not enter into it — both sides are
   measured in their own frame and compared as shares — so this cannot be
   thrown off by a fit that is a few pixels out.                            */
function scoEngraveFill(rp, rw, rh, mp, mw, mh, scaleR, m2r) {
  const out = { renderFrac: null, mapFrac: null, ceil: null, over: null, filled: false,
                toneRatio: null, tooDark: false, polLum: null, engLum: null };
  const rn = rw * rh, mn = mw * mh;
  let mEngN = 0, mOutN = 0;
  for (let i = 0; i < mn; i++) { if (mp.engraved[i]) mEngN++; if (mp.outer[i]) mOutN++; }
  /* A MAP THAT DECLARES NO ENGRAVING DECLARES NO CEILING. There is nothing
     to be thicker than, so this test has no opinion — the render's own
     invented engraving is the adjudicator's business, not this one's. */
  if (!mEngN || !mOutN) return out;
  const dM = studioEdt2d(mp.engraved, mw, mh);
  const histM = new Int32Array(512);
  for (let i = 0; i < mn; i++) if (mp.engraved[i]) histM[Math.min(511, Math.round(dM[i]))]++;
  let acc = 0, mP99 = 0;
  for (let r = 0; r < 512; r++) { acc += histM[r]; if (acc >= mEngN * 0.99) { mP99 = r; break; } }

  /* THE BEVEL IS NOT ENGRAVING. Every cut edge and every outer edge carries a
     wall of shaded gold, and it is darker than the polish by more than any
     engraving is. Reading it as engraving would report a filled charm on a
     render with no engraving at all, so the census starts a little way in
     from every edge the metal has. */
  const din = studioEdt2d(rp.metal, rw, rh);
  const edge = Math.max(2, SCO_ENG_EDGE_FRAC * scaleR);
  const core = new Uint8Array(rn);
  let coreN = 0;
  for (let i = 0; i < rn; i++) if (rp.metal[i] && din[i] > edge) { core[i] = 1; coreN++; }
  if (coreN < 600) return out;
  /* the polished level, read from this render rather than assumed: engraving
     is a minority of any charm even on a bad render, so a high percentile of
     the core IS polish — see SCO_ENG_POL_PCT for why it is not p75 */
  const histL = new Int32Array(256);
  for (let i = 0; i < rn; i++) if (core[i]) histL[Math.max(0, Math.min(255, Math.round(rp.lum[i])))]++;
  let a2 = 0, pol = 255;
  for (let v = 0; v < 256; v++) { a2 += histL[v]; if (a2 >= coreN * SCO_ENG_POL_PCT) { pol = v; break; } }

  /* ── HOW DARK THE RECESSES ARE, AS A RATIO OF THE POLISH BESIDE THEM ────
     The same histogram, asked a different question. A charm's surface is two
     populations — polished and engraved — and the gap between their peaks is
     the only thing this needs; both are read off the SAME photograph, so
     exposure, alloy and resolution all cancel. A percentile cannot do it: at
     one engraved region a percentile lands in the polish and at forty it
     lands in the engraving, and the answer has to mean the same thing in
     both cases. Peaks do not care how much of the surface each covers. */
  {
    const sm = new Float64Array(256);
    for (let v = 0; v < 256; v++) {
      let acc = 0, wt = 0;
      for (let k = -3; k <= 3; k++) {
        const u = v + k; if (u < 0 || u > 255) continue;
        const w = 1 / (1 + k * k); acc += histL[u] * w; wt += w;
      }
      sm[v] = wt ? acc / wt : 0;
    }
    let top = 0;
    for (let v = 0; v < 256; v++) if (sm[v] > top) top = sm[v];
    const peaks = [];
    for (let v = 1; v < 255; v++) {
      if (sm[v] >= sm[v - 1] && sm[v] > sm[v + 1] && sm[v] >= top * 0.08) {
        /* keep peaks at least 12 levels apart, tallest first */
        if (!peaks.some((p) => Math.abs(p - v) < 12)) peaks.push(v);
      }
    }
    peaks.sort((x, y) => sm[y] - sm[x]);
    if (peaks.length >= 2) {
      const two = peaks.slice(0, 2).sort((x, y) => x - y);
      const engL = two[0], polL = two[1];
      if (polL > 0) {
        out.engLum = engL; out.polLum = polL;
        out.toneRatio = Math.round((engL / polL) * 1e3) / 1e3;
        out.tooDark = out.toneRatio < SCO_ENG_TONE_MIN;
      }
    }
  }
  const drop = Math.max(6, SCO_ENG_DROP * pol);
  const rEng = new Uint8Array(rn);
  let rEngN = 0;
  for (let i = 0; i < rn; i++) if (core[i] && rp.lum[i] < pol - drop) { rEng[i] = 1; rEngN++; }
  let rOutN = 0;
  for (let i = 0; i < rn; i++) if (rp.outer[i]) rOutN++;
  out.mapFrac = Math.round(mEngN / mOutN * 1e4) / 1e4;
  out.renderFrac = rOutN ? Math.round(rEngN / rOutN * 1e4) / 1e4 : null;
  if (rEngN < 400) { out.over = 0; return out; }
  const dR = studioEdt2d(rEng, rw, rh);
  const ceil = mP99 * m2r * SCO_ENG_ALLOW + 1;
  let over = 0;
  for (let i = 0; i < rn; i++) if (rEng[i] && dR[i] > ceil) over++;
  out.ceil = Math.round(ceil * 10) / 10;
  out.over = Math.round(over / rEngN * 1e4) / 1e4;
  /* BOTH, OR NEITHER. Thickness alone can be a legitimately bolder stroke on
     a map drawn thin; area alone is the 17.6-to-26.2 that a filled charm
     barely registers on. Together they are the fill and nothing else. */
  out.filled = out.over > SCO_ENG_FILL_MAX &&
               out.renderFrac != null && out.renderFrac > out.mapFrac * 1.15;
  return out;
}

function scoAlloy(px, w, h, ch, outer, gnd) {
  const n = w * h;
  const gl = 0.299 * gnd.r + 0.587 * gnd.g + 0.114 * gnd.b;
  const sats = [];
  const keep = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    if (!outer[i]) continue;
    const p = i * ch, r = px[p], g = px[p + 1], b = px[p + 2];
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
    const sat = mx ? (mx - mn) * 255 / mx : 0;
    const lum = 0.299 * r + 0.587 * g + 0.114 * b;
    /* the ground seen through a cut-out is not metal and has no alloy */
    if (lum > gl - SCO_ALLOY_OPEN_MARGIN && sat < SCO_ALLOY_OPEN_SAT) continue;
    keep[i] = 1;
    sats.push(sat);
  }
  if (sats.length < 500) return { offAlloy: 0, chroma: 0, dirty: false };
  sats.sort((a, b) => a - b);
  const p75 = sats[Math.floor(sats.length * 0.75)];
  const floor = Math.min(SCO_ALLOY_FLOOR, p75 * SCO_ALLOY_FRAC);
  let off = 0, all = 0;
  for (let i = 0; i < n; i++) {
    if (!keep[i]) continue;
    all++;
    const p = i * ch, r = px[p], g = px[p + 1], b = px[p + 2];
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
    if ((mx ? (mx - mn) * 255 / mx : 0) < floor) off++;
  }
  const frac = all ? off / all : 0;
  return {
    offAlloy: Math.round(frac * 1e4) / 1e4,
    chroma: Math.round(p75),
    dirty: frac > SCO_ALLOY_LIMIT,
  };
}

/* ── placing a mask-space field into the render's frame ─────────────────── */
/* BILINEAR, not a windowed sinc: the scale here is within a per cent of 1:1,
   so the operation is almost pure sub-pixel translation and a sharper filter
   would only ring along an edge that is already correct. */
/* ── AND IT LANDS ON A FRACTION OF A PIXEL ────────────────────────────────
   This used to crop, resample to a whole number of pixels, and stamp the
   result at a ROUNDED origin — so every opening carried up to half a pixel
   of placement error in each axis, always in the same direction for the
   whole cluster, and the error showed as the cut edge sitting a touch inside
   the metal on one side and a touch outside it on the other.

   The inverse map removes the rounding rather than correcting for it: each
   OUTPUT pixel asks where it falls in the mask and reads that point, so a
   target origin of 412.4 is sampled at 412.4 instead of 412. It also drops
   the intermediate crop and resample buffers, so it is cheaper than what it
   replaces. With an integer origin it is arithmetically identical to the old
   path — the sampling convention below is studioBilinearField's own. */
function scoPlace(field, mw, mh, box, mb, rb, sxN, syN, dx, dy, out, ow, oh, take) {
  /* mask pixels to render pixels: the two bounding boxes give the base
     scale, the fit's sx/sy correct it */
  const kx = (rb.x1 - rb.x0 + 1) / (mb.x1 - mb.x0 + 1) * sxN;
  const ky = (rb.y1 - rb.y0 + 1) / (mb.y1 - mb.y0 + 1) * syN;
  const cw = box.x1 - box.x0 + 1, chh = box.y1 - box.y0 + 1;
  const tw = Math.max(2, Math.round(cw * kx)), th = Math.max(2, Math.round(chh * ky));
  /* WHERE THE CROP SITS INSIDE THE MASK'S OWN BOX, scaled — not at the
     render box's origin. Dropping this term put every opening at the top
     left corner of the charm, where none of them are. Kept fractional. */
  const txf = (box.x0 - mb.x0) * kx + rb.x0 + dx;
  const tyf = (box.y0 - mb.y0) * ky + rb.y0 + dy;
  const sxs = cw / tw, sys = chh / th;
  /* the rectangle actually written, so a caller can read back only what it
     changed instead of walking the whole frame per opening */
  const hit = {
    x0: Math.max(0, Math.floor(txf)), y0: Math.max(0, Math.floor(tyf)),
    x1: Math.min(ow - 1, Math.ceil(txf + tw - 1)),
    y1: Math.min(oh - 1, Math.ceil(tyf + th - 1)),
  };
  for (let oy = hit.y0; oy <= hit.y1; oy++) {
    const cyr = oy - tyf;
    if (cyr < -0.5 || cyr > th - 0.5) continue;
    let fy = (cyr + 0.5) * sys - 0.5;
    if (fy < 0) fy = 0; else if (fy > chh - 1) fy = chh - 1;
    const y0 = Math.floor(fy), y1 = y0 + 1 < chh ? y0 + 1 : chh - 1, wy = fy - y0;
    const r0 = (y0 + box.y0) * mw + box.x0, r1 = (y1 + box.y0) * mw + box.x0;
    const row = oy * ow;
    for (let ox = hit.x0; ox <= hit.x1; ox++) {
      const cxr = ox - txf;
      if (cxr < -0.5 || cxr > tw - 0.5) continue;
      let fx = (cxr + 0.5) * sxs - 0.5;
      if (fx < 0) fx = 0; else if (fx > cw - 1) fx = cw - 1;
      const x0 = Math.floor(fx), x1 = x0 + 1 < cw ? x0 + 1 : cw - 1, wx = fx - x0;
      const a = field[r0 + x0], b = field[r0 + x1];
      const c = field[r1 + x0], e = field[r1 + x1];
      const v = (a * (1 - wx) + b * wx) * (1 - wy) + (c * (1 - wx) + e * wx) * wy;
      if (take === "max") { if (v > out[row + ox]) out[row + ox] = v; }
      else out[row + ox] = v;
    }
  }
  return hit;
}

/* ── THE GLOBAL FIT ────────────────────────────────────────────────────────
   Registration in two stages, because one transform cannot do the job and
   pretending otherwise is what put the first version's cuts a few pixels off
   everywhere. This is the coarse half: scale in x and y plus a translation,
   fitted on the outer silhouette alone, which the model reproduces well.

   It runs on a downsampled pair. The fine half — per-cluster, on contrast —
   works in full-resolution pixels and is what actually lands each opening,
   so the only thing asked of this stage is to get within the clusters' own
   search radius. Doing it at 1:1 would cost a hundred times as much for a
   correction the next stage makes anyway.                                  */
function scoGlobalFit(maskOuter, mw, mh, mb, renderOuter, rw, rh, rb) {
  const SIDE = 224;
  const shrink = (mask, w, h, box) => {
    const bw = box.x1 - box.x0 + 1, bh = box.y1 - box.y0 + 1;
    const f = new Float32Array(bw * bh);
    for (let y = 0; y < bh; y++) {
      for (let x = 0; x < bw; x++) f[y * bw + x] = mask[(y + box.y0) * w + (x + box.x0)] ? 1 : 0;
    }
    return { f, bw, bh };
  };
  const M = shrink(maskOuter, mw, mh, mb);
  const R = shrink(renderOuter, rw, rh, rb);
  /* both cropped to their own bounding box, then to one common grid: the
     bounding-box map is the identity in this frame, so the search below is
     purely the correction to it */
  const rSmall = studioBilinearField(R.f, R.bw, R.bh, SIDE, SIDE);
  /* THE SET PIXELS, AS A LIST. The score only ever asks questions about the
     render's own silhouette and about totals, so walking all 50,176 cells of
     the grid 1,234 times to look at the same 25,000 of them is most of this
     step's cost for none of its answer. */
  const aX = [], aY = [];
  for (let y = 0; y < SIDE; y++) {
    for (let x = 0; x < SIDE; x++) if (rSmall[y * SIDE + x] > 0.5) { aX.push(x); aY.push(y); }
  }
  const ax = Int32Array.from(aX), ay = Int32Array.from(aY), aCount = ax.length;

  /* THE RESAMPLE DEPENDS ON THE SCALE, NOT THE SHIFT. Rebuilding it inside
     the translation loop cost 1,225 resamples where 25 were needed, and was
     four fifths of the whole step's time. */
  const cache = new Map();
  const scaled = (sx, sy) => {
    const key = sx.toFixed(3) + "," + sy.toFixed(3);
    let v = cache.get(key);
    if (!v) {
      const tw = Math.max(4, Math.round(SIDE * sx)), th = Math.max(4, Math.round(SIDE * sy));
      const m = studioBilinearField(M.f, M.bw, M.bh, tw, th);
      const bin = new Uint8Array(tw * th);
      /* an integral image of the mask side, so "how many of its pixels are
         inside the window at this shift" is four lookups instead of a scan —
         which is the only other term the union needs */
      const sum = new Int32Array((tw + 1) * (th + 1));
      for (let y = 0; y < th; y++) {
        let run = 0;
        for (let x = 0; x < tw; x++) {
          const on = m[y * tw + x] > 0.5 ? 1 : 0;
          bin[y * tw + x] = on;
          run += on;
          sum[(y + 1) * (tw + 1) + (x + 1)] = sum[y * (tw + 1) + (x + 1)] + run;
        }
      }
      v = { bin, sum, tw, th };
      cache.set(key, v);
    }
    return v;
  };
  const scoreAt = (sx, sy, dx, dy) => {
    const { bin, sum, tw, th } = scaled(sx, sy);
    let inter = 0;
    for (let k = 0; k < aCount; k++) {
      const my = ay[k] - dy;
      if (my < 0 || my >= th) continue;
      const mx = ax[k] - dx;
      if (mx < 0 || mx >= tw) continue;
      inter += bin[my * tw + mx];
    }
    /* mask pixels visible in the window: the rectangle [x0,x1) x [y0,y1) of
       mask coordinates that maps inside the SIDE-square grid */
    const mx0 = Math.max(0, -dx), mx1 = Math.min(tw, SIDE - dx);
    const my0 = Math.max(0, -dy), my1 = Math.min(th, SIDE - dy);
    let bVis = 0;
    if (mx1 > mx0 && my1 > my0) {
      const S = tw + 1;
      bVis = sum[my1 * S + mx1] - sum[my0 * S + mx1] - sum[my1 * S + mx0] + sum[my0 * S + mx0];
    }
    const uni = aCount + bVis - inter;
    return uni ? inter / uni : 0;
  };
  let best = { iou: -1, sx: 1, sy: 1, dx: 0, dy: 0 };
  for (let sx = 0.975; sx <= 1.0301; sx += 0.011) {
    for (let sy = 0.975; sy <= 1.0301; sy += 0.011) {
      for (let dx = -6; dx <= 6; dx += 2) {
        for (let dy = -6; dy <= 6; dy += 2) {
          const v = scoreAt(sx, sy, dx, dy);
          if (v > best.iou) best = { iou: v, sx, sy, dx, dy };
        }
      }
    }
  }
  for (let dx = best.dx - 1; dx <= best.dx + 1; dx++) {
    for (let dy = best.dy - 1; dy <= best.dy + 1; dy++) {
      const v = scoreAt(best.sx, best.sy, dx, dy);
      if (v > best.iou) best = { iou: v, sx: best.sx, sy: best.sy, dx, dy };
    }
  }
  /* back into render pixels: the search grid is SIDE wide, the render's own
     bounding box is not */
  const kx = (rb.x1 - rb.x0 + 1) / SIDE, ky = (rb.y1 - rb.y0 + 1) / SIDE;
  return {
    iou: best.iou,
    sx: best.sx, sy: best.sy,
    dx: Math.round(best.dx * kx), dy: Math.round(best.dy * ky),
  };
}

/* ══════════════════════════════════════════════════════════════════════════
   THE COMPOSITOR

   Returns { buf, report }. `buf` is the render untouched on every failure
   path — a missing sharp, an unreadable mask, a drifted design, a thrown
   anything. This step may improve a render and may decline to; it may never
   cost one.                                                                */
async function studioCompositeOpenings(renderBuf, specBuf, opts) {
  const sharp = studioSharp();
  const o = opts || {};
  const t0 = Date.now();
  const deadline = t0 + Math.max(2000, Number(o.budgetMs) || 25000);
  const report = {
    ran: false, why: "", ms: 0,
    declared: 0, refused: 0, composited: 0, leftAlone: 0, leftAloneNear: 0,
    iou: null, aspect: null, openFrac: null, declaredFrac: null, shadeK: null, clusters: 0,
    maxShift: 0, localFit: true,
    furniture: { frac: 0, biggest: 0, blobs: 0, dirty: false },
    alloy: { offAlloy: 0, chroma: 0, dirty: false },
    outline: { mean: 0, p95: 0, dirty: false },
    engrave: { renderFrac: null, mapFrac: null, ceil: null, over: null, filled: false,
               toneRatio: null, tooDark: false, polLum: null, engLum: null },
  };
  if (!sharp || !renderBuf?.length || !specBuf?.length) {
    report.why = "no_inputs";
    return { buf: renderBuf, report };
  }
  try {
    const R = await scoReadRaw(sharp, renderBuf);
    const M = await scoReadRaw(sharp, specBuf);
    const rn = R.w * R.h, mn = M.w * M.h;

    const rp = scoRenderParts(R.px, R.w, R.h, R.ch);
    const mp = scoMaskParts(M.px, M.w, M.h, M.ch);
    const rb = studioBBox(rp.outer, R.w, R.h);
    const mb = studioBBox(mp.outer, M.w, M.h);
    if (!rb || !mb || !rb.w || !mb.w) {
      report.why = "no_silhouette";
      return { buf: renderBuf, report };
    }
    /* ── THE DISTORTION THE BOUNDING-BOX MAP IS ABOUT TO ABSORB ───────────
       Measured HERE, before kx and ky are used for anything, because using
       them is what makes it invisible. See SCO_ASPECT_MAX. */
    {
      const kx = (rb.x1 - rb.x0 + 1) / (mb.x1 - mb.x0 + 1);
      const ky = (rb.y1 - rb.y0 + 1) / (mb.y1 - mb.y0 + 1);
      const k = (kx > 0 && ky > 0) ? Math.max(kx / ky, ky / kx) : null;
      report.aspect = k == null ? null : Math.round(k * 1e3) / 1e3;
    }

    /* ── IS THERE ANYTHING IN THIS FRAME BUT THE CHARM? ───────────────────
       A render came back as a CONTACT SHEET: the finished charm in the
       middle, and beside it the model's own two input maps redrawn as inset
       panels, complete with borders and with the words "IMAGE 1", "IMAGE 2"
       and "YOUR CHARM" lettered in. Nothing upstream could see it. The
       silhouette gate passes — the charm in the middle is a charm — the
       adjudicator is parked, and the composite happily cut openings into a
       picture that was never a product shot.

       It is trivially measurable, because a product shot has a defining
       property: outside the charm and its own contact shadow, the frame is
       empty ground. So the ground is sampled, everything meaningfully
       different from it is found, whatever lies within reach of the charm is
       excused as its shadow, and what remains is FURNITURE — panels, text,
       borders, swatches, a second object, anything at all.

       Measured, the two populations are two orders of magnitude apart:
         clean renders   biggest stray blob   0.1% and 0.9% of the charm's box
         the contact sheet                    47%
       so the line can sit anywhere between and never be near either. */
    const gnd = scoGroundColour(R.px, R.w, R.h, R.ch, rp.outer);
    report.furniture = scoFurniture(R.px, R.w, R.h, R.ch, rp.outer, rb, gnd);
    report.alloy = scoAlloy(R.px, R.w, R.h, R.ch, rp.outer, gnd);
    /* one number for the whole charm, so every threshold below is a share of
       the object rather than a pixel count that only suits one resolution */
    let roCount = 0;
    for (let i = 0; i < rn; i++) if (rp.outer[i]) roCount++;
    const scale = Math.sqrt(Math.max(1, roCount));
    const px = (frac, min) => Math.max(min == null ? 1 : min, frac * scale);

    /* ── the declared openings, and the ones that are not openings ──────── */
    const lab = studioLabel(mp.holes, M.w, M.h);
    const area = new Float64Array(lab.count + 1);
    for (let i = 0; i < mn; i++) if (lab.labels[i]) area[lab.labels[i]]++;
    /* ── THE FLOOR WAS SET IN PIXELS, AND PIXELS ARE NOT A SIZE ──────────
       A dragon's map declared thirty-seven openings and six of them — 35, 30,
       18, 12, 12 and 9 px — fell under the floor and were silently dropped.
       On a 353 px charm a 35 px region is about six pixels across, which on a
       20 mm piece is a third of a millimetre: small, and entirely
       manufacturable. It was excluded because the absolute term, 60, is a
       count rather than a proportion — the same feature on the same charm
       photographed at 2048 px would have sailed through at four times the
       pixel count.
       Both terms come down: the share of the charm to a figure that keeps a
       six-pixel detail on a 353 px piece, and the absolute floor to what is
       genuinely speckle at any size. */
    const minArea = Math.max(24, 0.00012 * mb.w * mb.h);
    const severMin = Math.max(120, SCO_SEVER_FRAC * mb.w * mb.h);
    /* one representative pixel and one bounding box per label, taken in the
       pass that was already walking every pixel */
    const seed = new Int32Array(lab.count + 1).fill(-1);
    const bx0 = new Int32Array(lab.count + 1).fill(1 << 29);
    const by0 = new Int32Array(lab.count + 1).fill(1 << 29);
    const bx1 = new Int32Array(lab.count + 1).fill(-1);
    const by1 = new Int32Array(lab.count + 1).fill(-1);
    for (let y = 0; y < M.h; y++) {
      for (let x = 0; x < M.w; x++) {
        const L = lab.labels[y * M.w + x];
        if (!L) continue;
        if (seed[L] < 0) seed[L] = y * M.w + x;
        if (x < bx0[L]) bx0[L] = x;
        if (x > bx1[L]) bx1[L] = x;
        if (y < by0[L]) by0[L] = y;
        if (y > by1[L]) by1[L] = y;
      }
    }
    const keep = [];
    const isKept = new Uint8Array(lab.count + 1);
    /* THE SEVER TEST IS EXACT BUT NOT UNIVERSAL. Labelling the whole charm
       once per opening is the most expensive thing here, and only a long
       thin opening can disconnect anything — a solid blob cannot, and every
       ordinary cut-out is a solid blob. So the cheap shape question is asked
       first and the exact one only of what could plausibly fail it: the
       hoop's phantom ring fills 10% of its own bounding box, a triangle
       fills 45%. */
    const holeDist = studioEdt2d(mp.holes, M.w, M.h);
    /* kept because the match below needs it: how far it is safe to move an
       opening is a question about the opening, and this is already measuring
       exactly that. */
    const rInL = new Float32Array(lab.count + 1);
    for (let L = 1; L <= lab.count; L++) {
      if (area[L] < minArea) continue;
      const bw = bx1[L] - bx0[L] + 1, bh = by1[L] - by0[L] + 1;
      let rIn = 0;
      for (let y = by0[L]; y <= by1[L]; y++) {
        for (let x = bx0[L]; x <= bx1[L]; x++) {
          const i = y * M.w + x;
          if (lab.labels[i] === L && holeDist[i] > rIn) rIn = holeDist[i];
        }
      }
      rInL[L] = rIn;
      if (area[L] < 0.35 * bw * bh && rIn < 0.12 * Math.max(bw, bh)) {
        const cut = new Uint8Array(mn);
        for (let i = 0; i < mn; i++) cut[i] = (mp.outer[i] && lab.labels[i] !== L) ? 1 : 0;
        const sub = studioLabel(cut, M.w, M.h);
        if (sub.count > 1) {
          const sz = new Float64Array(sub.count + 1);
          for (let i = 0; i < mn; i++) if (sub.labels[i]) sz[sub.labels[i]]++;
          const sorted = Array.from(sz.slice(1)).sort((a, b) => b - a);
          if (sorted.length > 1 && sorted[1] > severMin) { report.refused++; continue; }
        }
      }
      keep.push(L);
      isKept[L] = 1;
    }
    report.declared = keep.length;
    /* A CHARM WITH NO OPENINGS IS STILL A CHARM THAT CAN BE REDRAWN WRONG.
       The composite has nothing to do here and stops; the shape gate has the
       same question to answer as ever and must not be skipped just because
       this design happens to be solid. */
    if (!keep.length && !o.fitOnly) {
      report.why = "nothing_declared";
      report.ms = Date.now() - t0;
      return { buf: renderBuf, report };
    }
    let declaredPx = 0, moPx = 0;
    for (let i = 0; i < mn; i++) {
      if (isKept[lab.labels[i]]) declaredPx++;
      if (mp.outer[i]) moPx++;
    }
    report.declaredFrac = moPx ? declaredPx / moPx : null;

    /* ── coarse registration ────────────────────────────────────────────── */
    const mCmp = mp.outerCmp || mp.outer;
    const fit = scoGlobalFit(mCmp, M.w, M.h, mb, rp.outer, R.w, R.h, rb);
    report.iou = Math.round(fit.iou * 1e4) / 1e4;
    /* the RE-ROLL threshold, which the caller sets and which never cancels
       anything; the CANCEL thresholds are SCO_FIT_FAIL / SCO_FIT_IOU below
       and are deliberately not caller-tunable — see the note at their
       definition for why one number could not do both jobs. */
    const minIoU = Number(o.minIoU) || 0.80;
    /* THE OUTLINE, MEASURED WHERE THE FIT PUT IT. The mask's silhouette is
       carried into the render's frame by the transform just found, and the
       two boundaries are compared there — so this is asking "having lined
       these up as well as they can be lined up, do their edges run the same
       way", which is the question a heart passing for a shield exposed. */
    {
      const kx = rb.w / mb.w * fit.sx, ky = rb.h / mb.h * fit.sy;
      const warp = new Uint8Array(rn);
      for (let y = 0; y < R.h; y++) {
        const my = Math.round((y - rb.y0 - fit.dy) / ky) + mb.y0;
        if (my < 0 || my >= M.h) continue;
        const srow = my * M.w, drow = y * R.w;
        for (let x = 0; x < R.w; x++) {
          const mx = Math.round((x - rb.x0 - fit.dx) / kx) + mb.x0;
          if (mx < 0 || mx >= M.w) continue;
          if (mCmp[srow + mx]) warp[drow + x] = 1;
        }
      }
      report.outline = scoBoundaryError(rp.outer, warp, R.w, R.h, scale);
    }
    /* AND WHETHER THE ENGRAVING WAS TRACED OR FILLED. Same pass, same two
       segmentations, no model call and no credit — and, unlike everything
       else in this gate, no dependence on the fit: both sides are measured
       in their own frame. */
    try {
      report.engrave = scoEngraveFill(rp, R.w, R.h, mp, M.w, M.h, scale,
                                      (rb.x1 - rb.x0 + 1) / (mb.x1 - mb.x0 + 1));
    } catch (e) { /* a measurement is never a reason to fail a render */ }
    /* THE SHAPE GATE STOPS HERE. Everything above is what it takes to answer
       "is this the same charm?" — the two segmentations, the two silhouettes
       and the fit between them — and everything below is repair work that is
       pointless if the answer is no. The attempt loop asks the question once
       per render at about a third of the full cost, so a drifted render can
       be re-rolled instead of shipped. */
    if (o.fitOnly) {
      report.why = report.furniture.dirty ? "frame_furniture"
                 : report.alloy.dirty ? "two_tone_metal"
                 : fit.iou < minIoU ? "silhouette_drift"
                 /* REPORTED HERE, NOT ENFORCED. The composite refuses on this
                    unconditionally — that can only ever leave a render alone —
                    but making the shape gate RE-ROLL on it spends the
                    customer's clock on a threshold calibrated from three
                    pairs. Set renderAspectGate:"on" once renderAspect has
                    been watched across a real population. */
                 : (o.aspectGate && report.aspect != null &&
                    report.aspect > Math.max(1.0, Number(o.aspectMax) || SCO_ASPECT_MAX))
                     ? "aspect_drift"
                 : report.outline.dirty ? "outline_mismatch"
                 /* LAST of the objections, deliberately: a charm that is the
                    wrong shape has a more useful thing to be told than that
                    its engraving is too thick, and the note that goes back to
                    the renderer carries one correction, not four. */
                 : (o.engraveGate && report.engrave.filled) ? "engraving_filled"
                 : (o.engraveGate && report.engrave.tooDark) ? "engraving_too_dark"
                 : "fit_ok";
      report.ms = Date.now() - t0;
      return { buf: renderBuf, report };
    }
    if (report.furniture.dirty) {
      /* the same refusal the drift gate makes, for the same reason: what was
         identified as the charm in a page full of panels may not be one */
      report.why = "frame_furniture";
      report.ms = Date.now() - t0;
      return { buf: renderBuf, report };
    }
    /* ── A CHECK THAT BUYS A RE-ROLL IS NOT A CHECK THAT CANCELS THE CUT ──
       These two decisions were conflated and it cost a customer their
       cut-outs. A dragon whose map declared THIRTY-EIGHT openings shipped
       with none of them, because the outline check objected and the
       compositor took that as a reason to do nothing.

       They are different questions. The gate asks "is this worth another
       attempt?" — and the loop above spends one. The composite asks "can I
       improve the image that is going to ship?" — and by the time it runs,
       the attempts are over and this image IS shipping. Cutting the
       customer's declared openings into it is an improvement whatever the
       metal looks like or however the outline reads.

       Only two failures genuinely stop it, and both for the same reason:
       no coordinate maps between the two pictures. `silhouette_drift` means
       the fit itself failed, so every placement below would be a guess; and
       a contact sheet is not a product shot, so the thing identified as the
       charm may not be one. Everything else is reported and composited. */
    /* THE MODEL DREW A DIFFERENT CHARM. Nothing downstream rescues that, and
       cutting a mask's openings into someone else's silhouette makes it worse
       rather than better. Asked as a DISTANCE, not as an overlap: an overlap
       is an area, and on a shape that is nearly all perimeter — a coiled
       dragon — the same one-pixel accuracy scores far worse than it does on a
       blob. Measured, IoU put a good dragon at 0.9053 BELOW a bad heart at
       0.9119, so the old 0.90 floor cancelled the composite on the customer's
       most intricate designs and let a wrong shape through. See SCO_FIT_FAIL. */
    if (report.outline.mean > SCO_FIT_FAIL || fit.iou < SCO_FIT_IOU) {
      report.why = "silhouette_drift";
      report.ms = Date.now() - t0;
      return { buf: renderBuf, report };
    }
    /* ── AND THE SAME REFUSAL FOR A CHARM REDRAWN AT A DIFFERENT SHAPE ────
       Third and last thing that stops the composite, for the same reason as
       the other two: no coordinate maps between the two pictures. The
       difference is that this one passes every existing test — the bbox map
       normalises it away before the fit is measured — so it has to be asked
       before that map is trusted. Refusing leaves the model's own openings
       exactly as it cut them, which on a distorted render is the best
       available outcome. See SCO_ASPECT_MAX. */
    const aspectMax = Math.max(1.0, Number(o.aspectMax) || SCO_ASPECT_MAX);
    if (report.aspect != null && report.aspect > aspectMax) {
      report.why = "aspect_drift";
      report.ms = Date.now() - t0;
      return { buf: renderBuf, report };
    }

    /* ── clusters: large features alone, small ones with their neighbours ─ */
    const bigArea = Math.max(SCO_BIG_AREA, 0.028 * mb.w * mb.h);
    const smallMask = new Uint8Array(mn);
    for (let i = 0; i < mn; i++) {
      const L = lab.labels[i];
      if (L && isKept[L] && area[L] < bigArea) smallMask[i] = 1;
    }
    const clusterR = Math.max(4, SCO_CLUSTER_FRAC * Math.sqrt(mb.w * mb.h) / 2);
    const cl = studioLabel(scoWithin(smallMask, M.w, M.h, clusterR), M.w, M.h);
    const groups = new Map();
    for (const L of keep) {
      const key = area[L] >= bigArea ? "solo:" + L : "cl:" + cl.labels[seed[L]];
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(L);
    }
    report.clusters = groups.size;

    /* ── the fine half: each cluster, matched on contrast ─────────────────
       ONE SWITCH REMOVES IT. With localFit off every opening lands exactly
       where the global fit puts it — the map's own geometry, rigidly
       registered to the render's silhouette, with nothing downstream reading
       the render's interior at all. That is the most repeatable placement
       there is: identical inputs give identical output, and the position of
       any one opening cannot be influenced by what the model happened to draw
       anywhere else. It is also, on a render whose interior really has
       drifted, a few pixels less flattering than the match — which is why the
       match ships on. */
    const localFit = o.localFit !== false;
    const ringR = Math.max(3, px(SCO_RING_FRAC));
    const wants = [];
    for (const [key, members] of groups) {
      if (!localFit) { wants.push({ key, members, dy: 0, dx: 0, score: 0, cap: 0 }); continue; }
      if (Date.now() > deadline) throw new Error("budget");
      const inGroup = new Uint8Array(lab.count + 1);
      let gx0 = M.w, gy0 = M.h, gx1 = -1, gy1 = -1;
      for (const L of members) {
        inGroup[L] = 1;
        if (bx0[L] < gx0) gx0 = bx0[L];
        if (by0[L] < gy0) gy0 = by0[L];
        if (bx1[L] > gx1) gx1 = bx1[L];
        if (by1[L] > gy1) gy1 = by1[L];
      }
      /* EVERY MASK-SIDE OPERATION HERE IS BOUNDED BY THE CLUSTER'S OWN BOX
         plus the ring it reads. Run over the whole frame instead and a charm
         with a dozen clusters pays for a dozen full-image distance fields to
         answer a question about a twenty-pixel slot. */
      const pad = Math.ceil(ringR) + 3;
      const box = {
        x0: Math.max(0, gx0 - pad), y0: Math.max(0, gy0 - pad),
        x1: Math.min(M.w - 1, gx1 + pad), y1: Math.min(M.h - 1, gy1 + pad),
      };
      const bw = box.x1 - box.x0 + 1, bh = box.y1 - box.y0 + 1;
      const selB = new Uint8Array(bw * bh);
      for (let y = 0; y < bh; y++) {
        const src = (y + box.y0) * M.w + box.x0;
        for (let x = 0; x < bw; x++) if (inGroup[lab.labels[src + x]]) selB[y * bw + x] = 1;
      }
      const growB = scoWithin(selB, bw, bh, ringR);
      const innerB = scoErode8(selB, bw, bh, 1);
      const skinB = scoDilate8(selB, bw, bh, 1);
      const sel = new Uint8Array(mn), grow = new Uint8Array(mn);
      const inner = new Uint8Array(mn), skin = new Uint8Array(mn);
      for (let y = 0; y < bh; y++) {
        const dst = (y + box.y0) * M.w + box.x0, s = y * bw;
        for (let x = 0; x < bw; x++) {
          sel[dst + x] = selB[s + x]; grow[dst + x] = growB[s + x];
          inner[dst + x] = innerB[s + x]; skin[dst + x] = skinB[s + x];
        }
      }
      /* THE REFERENCE IS THE ENGRAVING, not whatever metal happens to be
         nearby: a binding slot sits in a narrow engraved band with bright
         polish either side, and including that polish dilutes the very
         contrast being measured. */
      let ringAll = 0, ringEng = 0;
      const ring = new Uint8Array(mn);
      for (let y = box.y0; y <= box.y1; y++) {
        const row = y * M.w;
        for (let x = box.x0; x <= box.x1; x++) {
          const i = row + x;
          if (grow[i] && !skin[i]) { ring[i] = 1; ringAll++; if (mp.engraved[i]) ringEng++; }
        }
      }
      if (ringEng >= 0.25 * ringAll) {
        for (let y = box.y0; y <= box.y1; y++) {
          const row = y * M.w;
          for (let x = box.x0; x <= box.x1; x++) {
            const i = row + x;
            if (ring[i] && !mp.engraved[i]) ring[i] = 0;
          }
        }
      }
      const gb = box;
      const innerF = new Float32Array(mn), ringF = new Float32Array(mn);
      for (let y = box.y0; y <= box.y1; y++) {
        const row = y * M.w;
        for (let x = box.x0; x <= box.x1; x++) { innerF[row + x] = inner[row + x]; ringF[row + x] = ring[row + x]; }
      }
      const canvasI = new Float32Array(rn), canvasR = new Float32Array(rn);
      const hitI = scoPlace(innerF, M.w, M.h, gb, mb, rb, fit.sx, fit.sy, fit.dx, fit.dy, canvasI, R.w, R.h, "set");
      const hitR = scoPlace(ringF, M.w, M.h, gb, mb, rb, fit.sx, fit.sy, fit.dx, fit.dy, canvasR, R.w, R.h, "set");

      /* only the rectangle the two fields were written into can hold a set
         pixel, so the census reads that instead of the whole frame */
      const scanX0 = Math.max(0, Math.min(hitI.x0, hitR.x0));
      const scanY0 = Math.max(0, Math.min(hitI.y0, hitR.y0));
      const scanX1 = Math.min(R.w - 1, Math.max(hitI.x1, hitR.x1));
      const scanY1 = Math.min(R.h - 1, Math.max(hitI.y1, hitR.y1));
      const idxIa = [], idxRa = [];
      for (let y = scanY0; y <= scanY1; y++) {
        const row = y * R.w;
        for (let x = scanX0; x <= scanX1; x++) {
          const i = row + x;
          if (canvasI[i] > 0.5) idxIa.push(i);
          else if (canvasR[i] > 0.5 && rp.metal[i]) idxRa.push(i);
        }
      }
      /* A MEAN DOES NOT NEED EVERY PIXEL. The search evaluates the same two
         means at up to 2,809 offsets, so a 30,000 px triangle costs 84
         million reads to answer a question a fixed, evenly spaced subsample
         answers to a fraction of a level. The subsample is the SAME set at
         every offset, so whatever it gets wrong it gets wrong identically
         across the search and cancels out of the comparison that picks the
         winner. */
      const thin = (a) => {
        if (a.length <= SCO_MATCH_SAMPLES) return Int32Array.from(a);
        const step = a.length / SCO_MATCH_SAMPLES;
        const out = new Int32Array(SCO_MATCH_SAMPLES);
        for (let k = 0; k < SCO_MATCH_SAMPLES; k++) out[k] = a[Math.floor(k * step)];
        return out;
      };
      const idxI = thin(idxIa), idxR = thin(idxRa);
      const lum = rp.lum;
      const gbw = Math.round((gb.x1 - gb.x0 + 1) * (rb.x1 - rb.x0 + 1) / (mb.x1 - mb.x0 + 1));
      const gbh = Math.round((gb.y1 - gb.y0 + 1) * (rb.y1 - rb.y0 + 1) / (mb.y1 - mb.y0 + 1));
      /* ── AN OPENING MAY NOT BE MOVED OFF ITSELF ────────────────────────
         Both existing bounds are about the CHARM — 0.42 of the cluster's box,
         0.037 of the whole piece — and on a real charm the second one binds
         every time: measured on the bow, every cluster got ±16 px whatever
         it contained, including one holding three slots five pixels wide. A
         search that wide is not a refinement of the global fit, it is an
         invitation to land somewhere else entirely, and it is how two 8 px
         circles on an astronaut's chest ended up sitting half off their own
         recesses.

         The third bound is about the OPENING: its own inscribed radius plus
         a small pad. A shift can then always be seen as a correction to the
         feature it belongs to, because the feature is still underneath it. */
      let rInMin = Infinity;
      for (const L of members) if (rInL[L] < rInMin) rInMin = rInL[L];
      const m2r = (rb.x1 - rb.x0 + 1) / (mb.x1 - mb.x0 + 1);
      const featureCap = Math.max(2, Math.round(rInMin * m2r + px(SCO_SHIFT_PAD_FRAC, 2)));
      const rad = Math.round(Math.min(
        Math.max(4, SCO_SEARCH_FRAC * Math.min(gbw, gbh)),
        Math.max(6, SCO_SEARCH_CAP * scale),
        featureCap
      ));
      const contrast = (ddy, ddx) => {
        if (idxI.length < 10 || idxR.length < 10) return -1e9;
        let si = 0, ni = 0, sr = 0, nr = 0;
        const off = ddy * R.w + ddx;
        for (let k = 0, K = idxI.length; k < K; k++) {
          const j = idxI[k] + off;
          if (j < 0 || j >= rn) continue;
          si += lum[j]; ni++;
        }
        for (let k = 0, K = idxR.length; k < K; k++) {
          const j = idxR[k] + off;
          if (j < 0 || j >= rn) continue;
          sr += lum[j]; nr++;
        }
        if (ni < 10 || nr < 10) return -1e9;
        return si / ni - sr / nr;
      };
      const base = contrast(0, 0);
      let bs = -1e9, by = 0, bx = 0;
      for (let ddy = -rad; ddy <= rad; ddy++) {
        for (let ddx = -rad; ddx <= rad; ddx++) {
          const v = contrast(ddy, ddx);
          if (v > bs) { bs = v; by = ddy; bx = ddx; }
        }
      }
      /* AND IT HAS TO BEAT STANDING STILL BY SOMETHING. The margin here was
         literally zero — a hundredth of a level bought a shift — so noise
         could move an opening whenever the surface under it was flat. */
      const ok = bs > base + SCO_MATCH_MARGIN && bs > SCO_MIN_CONTRAST;
      wants.push({ key, members, dy: ok ? by : 0, dx: ok ? bx : 0, score: bs, cap: featureCap });
    }

    /* ── A BORROWED ANSWER IS STILL SOMEBODY ELSE'S ───────────────────────
       Below the confidence line a cluster adopts the median shift of the
       clusters that are sure, and on the bow that is measurably right: three
       binding slots whose own readings were nonsense (-57 and -17 at rest)
       land correctly on the borrowed one.

       But it was adopted UNCONDITIONALLY and UNCLAMPED, and that is how two
       small circles on an astronaut's chest — different clusters, neither
       able to read its own feature — ended up displaced by the same amount
       off their own recesses. An identical offset on two unrelated clusters
       is the fingerprint of a borrowed answer rather than a measured one, and
       the borrowing has to earn its place:

         · THE LENDERS MUST AGREE. On the bow the sure clusters answered
           dy-1, dy-3 and dy-8 — five pixels apart across one charm, which is
           the whole reason this stage is per-cluster and not one affine
           field. Spread that wide and there is no single correction to lend.
         · AND IT MUST FIT THE BORROWER. A shift is a refinement of the
           global fit, so it may never be large enough to carry an opening
           off its own feature — the same bound its own search already obeys.

       Fail either test and the cluster holds at the global fit: a whole-charm
       registration measured on the silhouette at IoU 0.977, and the answer
       that does not depend on what the model happened to draw elsewhere. */
    const sure = wants.filter((w) => w.score >= SCO_SURE_CONTRAST);
    let cy = 0, cx = 0, agree = Infinity;
    if (sure.length >= 2) {
      const ys = sure.map((w) => w.dy).sort((a, b) => a - b);
      const xs = sure.map((w) => w.dx).sort((a, b) => a - b);
      cy = ys[(ys.length - 1) >> 1];
      cx = xs[(xs.length - 1) >> 1];
      agree = 0;
      for (const w of sure) {
        agree = Math.max(agree, Math.abs(w.dy - cy), Math.abs(w.dx - cx));
      }
    }
    for (const w of wants) {
      if (w.score >= SCO_SURE_CONTRAST) continue;
      const cap = w.cap;
      if (agree > cap) { w.dy = 0; w.dx = 0; continue; }
      w.dy = Math.max(-cap, Math.min(cap, cy));
      w.dx = Math.max(-cap, Math.min(cap, cx));
    }

    /* THE BIGGEST CORRECTION THIS RENDER TOOK, on the record. If an opening
       ever lands wrong again, this one number says immediately whether a
       local shift was involved or whether the global fit itself was off —
       which is the difference between two entirely different investigations,
       and it is not recoverable from the finished picture. */
    let maxShift = 0;
    for (const w of wants) maxShift = Math.max(maxShift, Math.abs(w.dy), Math.abs(w.dx));
    report.maxShift = maxShift;
    report.localFit = localFit;

    /* ── place each opening, skipping the ones already cut ──────────────── */
    const alpha = new Float32Array(rn);
    const theirs = new Uint8Array(rn);
    /* THE RENDER'S OWN OPENINGS, AND HOW FAR EVERY PIXEL IS FROM ONE.
       Interior only — the ground OUTSIDE the charm is open too, and counting
       it would excuse every opening near the rim. One field for the whole
       frame, read per footprint below; the alternative is re-walking each
       footprint at every candidate offset, which is the same answer for a
       few hundred times the work. */
    const rOpenIn = new Uint8Array(rn);
    for (let i = 0; i < rn; i++) rOpenIn[i] = (rp.outer[i] && !rp.metal[i]) ? 1 : 0;
    const dToOpen = studioEdt2d(scoInvert(rOpenIn, R.w, R.h), R.w, R.h);
    /* HOW FAR THE NEAREST OTHER DECLARED OPENING IS, per opening, in render
       pixels. This is what makes the tolerance above safe rather than
       generous: a slot may look for its own rendered hole as far away as it
       likes SHORT OF ITS NEIGHBOUR, and no further. Six identical fletching
       slots 34 px apart give each of them about 15 px of licence, which is
       more than any registration error measured on this pipeline and less
       than half the distance to the wrong answer. Centre-to-centre on the
       bounding boxes: exact spacing is not needed, only a bound. */
    const m2rN = (rb.x1 - rb.x0 + 1) / (mb.x1 - mb.x0 + 1);
    const sepL = new Float32Array(lab.count + 1).fill(Infinity);
    for (const A of keep) {
      const ax = (bx0[A] + bx1[A]) / 2, ay = (by0[A] + by1[A]) / 2;
      for (const B of keep) {
        if (B === A) continue;
        const dxc = ax - (bx0[B] + bx1[B]) / 2, dyc = ay - (by0[B] + by1[B]) / 2;
        const dd = Math.hypot(dxc, dyc);
        if (dd < sepL[A]) sepL[A] = dd;
      }
    }
    for (const w of wants) {
      if (Date.now() > deadline) throw new Error("budget");
      for (const L of w.members) {
        const ob = {
          x0: Math.max(0, bx0[L] - 2), y0: Math.max(0, by0[L] - 2),
          x1: Math.min(M.w - 1, bx1[L] + 2), y1: Math.min(M.h - 1, by1[L] + 2),
        };
        const ow2 = ob.x1 - ob.x0 + 1, oh2 = ob.y1 - ob.y0 + 1;
        const oneB = new Uint8Array(ow2 * oh2);
        for (let y = 0; y < oh2; y++) {
          const row = (y + ob.y0) * M.w + ob.x0;
          for (let x = 0; x < ow2; x++) if (lab.labels[row + x] === L) oneB[y * ow2 + x] = 1;
        }
        const skinB = scoDilate8(oneB, ow2, oh2, 1);
        const fld = new Float32Array(mn);
        for (let y = 0; y < oh2; y++) {
          const row = (y + ob.y0) * M.w + ob.x0;
          for (let x = 0; x < ow2; x++) if (skinB[y * ow2 + x]) fld[row + x] = mp.alpha[row + x];
        }
        const probe = new Float32Array(rn);
        const hit = scoPlace(fld, M.w, M.h, ob, mb, rb, fit.sx, fit.sy, fit.dx, fit.dy,
                             probe, R.w, R.h, "set");
        /* ── ASK ABOUT THE HOLE WHERE THE HOLE IS ACTUALLY GOING ──────────
           This census used to read rp.metal at `i` — the GLOBAL-fit position
           — and then paint at `i + off`, the global fit plus the cluster's
           local shift. The whole point of the local stage is that those two
           are not the same place, so the test was inspecting metal `off`
           pixels away from the opening it was about to cut. An opening the
           model rendered correctly, in a cluster that took any shift at all,
           was therefore judged solid and composited over the top of itself.
           Test where you paint. */
        const sdx = w.dx | 0, sdy = w.dy | 0;
        /* as (x,y), not as a linear offset: i + dy*W + dx wraps a row
           whenever dx carries a pixel past the frame edge, which silently
           moves an opening near the margin to the opposite side */
        const at = (x, y, ddx, ddy) => {
          const nx = x + ddx, ny = y + ddy;
          return (nx < 0 || ny < 0 || nx >= R.w || ny >= R.h) ? -1 : ny * R.w + nx;
        };
        /* HOW FAR OFF THE MODEL'S OWN OPENING MAY SIT and still be this
           opening. Not the cluster's shift bound — a cluster that could not
           read itself has a bound of zero, and zero tolerance is exactly
           what produced the double-cut. It is bounded by the geometry
           instead: short of the neighbour, and never beyond the largest
           correction this stage would ever make anyway. */
        const nearTol = Math.max(2, Math.min(
          0.45 * sepL[L] * m2rN,                 /* short of the neighbour: the safety bound */
          Math.max(6, SCO_NEAR_TOL_FRAC * scale) /* and no further than a real drift ever runs */
        ));
        let hard = 0, solid = 0, near = 0;
        for (let y = hit.y0; y <= hit.y1; y++) {
          const row = y * R.w;
          for (let x = hit.x0; x <= hit.x1; x++) {
            const i = row + x;
            if (probe[i] <= 0.5) continue;
            hard++;
            const j = at(x, y, sdx, sdy);
            if (j < 0) { solid++; continue; }
            if (rp.metal[j]) solid++;
            if (dToOpen[j] <= nearTol) near++;
          }
        }
        if (!hard) continue;
        /* EITHER answer means the model already cut this opening: the
           footprint is open where it lands, or — for a feature thinner than
           the registration it is measured in — the metal under the footprint
           is everywhere within a few pixels of the render's own opening. */
        const openFrac = 1 - solid / hard;
        const nearFrac = near / hard;
        if (openFrac >= SCO_ALREADY_OPEN || nearFrac >= SCO_NEAR_OPEN_FRAC) {
          report.leftAlone++;
          if (openFrac < SCO_ALREADY_OPEN) report.leftAloneNear++;
          for (let y = hit.y0; y <= hit.y1; y++) {
            const row = y * R.w;
            for (let x = hit.x0; x <= hit.x1; x++) {
              const i = row + x;
              if (probe[i] <= 0.5) continue;
              const j = at(x, y, sdx, sdy);
              if (j >= 0) theirs[j] = 1;
            }
          }
          continue;
        }
        report.composited++;
        for (let y = hit.y0; y <= hit.y1; y++) {
          const row = y * R.w;
          for (let x = hit.x0; x <= hit.x1; x++) {
            const i = row + x, v = probe[i];
            if (v <= 0) continue;
            const j = at(x, y, sdx, sdy);
            if (j < 0) continue;
            if (v > alpha[j]) alpha[j] = v;
          }
        }
      }
    }
    if (!report.composited) {
      report.why = report.leftAlone ? "already_cut" : "nothing_placed";
      report.ms = Date.now() - t0;
      return { buf: renderBuf, report };
    }

    /* THE SAFETY MARGIN IS A DISTANCE, NOT A BINARY MULTIPLY — a binary
       erosion stamps a hard staircase wherever it bites, and a staircase on
       a curve is the one thing that reads as pasted-on. */
    if (Date.now() > deadline) throw new Error("budget");
    const erode = px(SCO_ERODE_FRAC, 1.0);
    const dIn = studioEdt2d(rp.outer, R.w, R.h);
    for (let i = 0; i < rn; i++) {
      const room = dIn[i] - erode;
      const f = room <= 0 ? 0 : room >= 1 ? 1 : room;
      alpha[i] *= f;
    }

    /* the cut edge as a signed distance, so rim and shadow are smooth
       functions of it and neither can step */
    const hard = new Uint8Array(rn);
    for (let i = 0; i < rn; i++) hard[i] = alpha[i] > 0.5 ? 1 : 0;
    const sdf = studioSignedField(hard, R.w, R.h);
    const rimPx = px(SCO_RIM_FRAC, 1.2), shPx = px(SCO_SHADOW_FRAC, 3);

    /* ── the ground inside a hole, shaded by the metal around it ────────── */
    const cr = gnd.r, cg = gnd.g, cb = gnd.b;
    const plain = 0.299 * cr + 0.587 * cg + 0.114 * cb;

    const metalAfter = new Float32Array(rn);
    for (let i = 0; i < rn; i++) metalAfter[i] = (rp.outer[i] && !hard[i]) ? 1 : 0;
    const ceil = Math.max(1.5, SCO_OCC_CEIL * scale);

    /* EACH OPENING GETS A BLUR SET BY ITS OWN INSCRIBED RADIUS. One radius
       for the whole charm leaves a 5 px slot occluded through and through
       while a 88 px triangle reads plain ground at its centre — the same
       shading rule, opposite results, purely because of size. */
    if (Date.now() > deadline) throw new Error("budget");
    const olab = studioLabel(hard, R.w, R.h);
    const oIn = studioEdt2d(hard, R.w, R.h);
    const rIn = new Float64Array(olab.count + 1);
    for (let i = 0; i < rn; i++) {
      const L = olab.labels[i];
      if (L && oIn[i] > rIn[L]) rIn[L] = oIn[i];
    }
    const want = new Float32Array(rn);
    for (let i = 0; i < rn; i++) {
      const L = olab.labels[i];
      want[i] = L ? Math.min(ceil, Math.max(SCO_OCC_MIN, SCO_OCC_FRAC * rIn[L])) : 0;
    }
    /* carry each opening's own figure a little way onto the metal, so the
       soft edge of the alpha is shaded by the hole it belongs to */
    const spread = Math.max(2, Math.round(px(0.005, 2)));
    for (let pass = 0; pass < spread; pass++) {
      const nx = new Float32Array(rn);
      for (let y = 0; y < R.h; y++) {
        for (let x = 0; x < R.w; x++) {
          const i = y * R.w + x;
          let m = want[i];
          if (x > 0 && want[i - 1] > m) m = want[i - 1];
          if (x < R.w - 1 && want[i + 1] > m) m = want[i + 1];
          if (y > 0 && want[i - R.w] > m) m = want[i - R.w];
          if (y < R.h - 1 && want[i + R.w] > m) m = want[i + R.w];
          nx[i] = m;
        }
      }
      want.set(nx);
    }
    const bands = [];
    for (let i = 0; i < rn; i++) {
      if (!want[i]) continue;
      const q = Math.round(want[i] * 2) / 2;
      if (bands.indexOf(q) < 0) bands.push(q);
    }
    const occ = new Float32Array(rn);
    for (const bs of bands) {
      if (Date.now() > deadline) throw new Error("budget");
      const g = studioGaussField(metalAfter, R.w, R.h, Math.max(0.6, bs));
      for (let i = 0; i < rn; i++) if (Math.abs(want[i] - bs) < 0.26) occ[i] = g[i];
    }

    /* the strength is something the render can be ASKED rather than told:
       when it cut any opening itself, that opening is a sample of its own
       answer. Clamped narrowly on purpose — the fit is only as good as its
       sample, and a render whose one self-cut opening is small and deep
       reads darker than the curve expects. */
    if (Date.now() > deadline) throw new Error("budget");
    let shadeK = SCO_OCC_K;
    let theirsPx = 0;
    for (let i = 0; i < rn; i++) if (theirs[i]) theirsPx++;
    if (theirsPx >= Math.max(400, 0.0015 * roCount) && plain > 1) {
      let rT = 0;
      const tIn = studioEdt2d(theirs, R.w, R.h);
      for (let i = 0; i < rn; i++) if (tIn[i] > rT) rT = tIn[i];
      const sigT = Math.min(ceil, Math.max(SCO_OCC_MIN, SCO_OCC_FRAC * rT));
      const mT = new Float32Array(rn);
      for (let i = 0; i < rn; i++) mT[i] = (rp.outer[i] && !theirs[i]) ? 1 : 0;
      const gT = studioGaussField(mT, R.w, R.h, sigT);
      const est = [];
      for (let i = 0; i < rn; i++) {
        if (!theirs[i] || gT[i] <= 0.02) continue;
        est.push((1 - rp.lum[i] / plain) / Math.pow(gT[i], SCO_OCC_POW));
      }
      if (est.length > 400) {
        est.sort((a, b) => a - b);
        const med = est[est.length >> 1];
        shadeK = Math.min(SCO_OCC_K_HI, Math.max(SCO_OCC_K_LO, med));
      }
    }
    report.shadeK = Math.round(shadeK * 1e3) / 1e3;

    /* ── paint it ───────────────────────────────────────────────────────── */
    const out = Buffer.alloc(rn * 3);
    for (let i = 0; i < rn; i++) {
      const p = i * R.ch;
      let r = R.px[p], g = R.px[p + 1], b = R.px[p + 2];
      const d = sdf[i];                       /* negative inside the opening */
      if (d > -0.4 && d < shPx * 1.2) {
        const t = (d - 0.6) / rimPx;
        const rim = Math.exp(-t * t);
        const sh = d > 0 ? Math.pow(Math.max(0, 1 - d / shPx), 2) : 0;
        /* shadow and catch are both lighting, so they multiply — and both
           scale all three channels, which is what keeps the metal coloured */
        const k = (1 - SCO_SHADOW_K * sh) * (1 + SCO_RIM_GAIN * rim);
        r *= k; g *= k; b *= k;
        const spec = SCO_RIM_WHITE * rim * rim;
        r += (255 - r) * spec;
        g += (255 - g) * spec;
        b += (255 - b) * spec;
      }
      const a = alpha[i];
      if (a > 0) {
        const shade = Math.max(0, 1 - shadeK * Math.pow(Math.min(1, Math.max(0, occ[i])), SCO_OCC_POW));
        r = r * (1 - a) + cr * shade * a;
        g = g * (1 - a) + cg * shade * a;
        b = b * (1 - a) + cb * shade * a;
      }
      const q = i * 3;
      out[q] = r < 0 ? 0 : r > 255 ? 255 : r;
      out[q + 1] = g < 0 ? 0 : g > 255 ? 255 : g;
      out[q + 2] = b < 0 ? 0 : b > 255 ? 255 : b;
    }
    let openPx = 0;
    for (let i = 0; i < rn; i++) if (hard[i] || theirs[i]) openPx++;
    report.openFrac = roCount ? Math.round(openPx / roCount * 1e4) / 1e4 : null;

    const buf = await sharp(out, { raw: { width: R.w, height: R.h, channels: 3 } })
      .png().toBuffer();
    report.ran = true;
    report.ms = Date.now() - t0;
    return { buf, report };
  } catch (err) {
    report.why = String(err?.message || err).slice(0, 80);
    report.ms = Date.now() - t0;
    return { buf: renderBuf, report };
  }
}







/* ── kind: custom_charm_render ────────────────────────────────────────────
 * The approved drawing becomes the charm: the Charm Maker's gold→line-art
 * conversion run in reverse, with the drawing as structural truth. Costs one
 * credit like any generation, debited atomically before the upstream call and
 * refunded on failure. Progress and outcome are written to the SAME version
 * doc the drawing lives on — renderStatus/renderStage/renderURL — so the
 * onSnapshot listener the studio already holds open streams the render too,
 * and the drawing's own status:"done" is never disturbed. Invoked in the
 * background, so refusals decided before any work starts are written to the
 * doc as well: an HTTP status from a background invocation reaches nobody.
 * ===================================================================== */
async function studioFailRender(vRef, error, renderRunId) {
  try {
    await vRef.set({
      renderStatus: "failed", renderStage: "failed",
      renderRunId: String(renderRunId || ""),
      renderError: String(error).slice(0, 300),
    }, { merge: true });
  } catch (e) {
    console.error("[studio] could not record render failure:", e?.message || e);
  }
}

/* ── THE MASK IS BUILT WHEN THE DRAWING IS, NOT WHEN THE RENDER IS ────────
   The greyscale mask used to be produced inside handleStudioRender, which
   meant it only existed after a paid render — so the customer approved a
   drawing without ever seeing the thing the renderer would actually be shown.

   This builds and stores it the moment a drawing is filed, by both routes
   that file one (the model generator and the local composer), and writes
   specURL/specPath onto the version doc so the studio can show both pictures
   side by side before "See it in metal" is pressed.

   It can NEVER fail the step that calls it. A drawing that generated fine
   must not be lost because sharp was unavailable or Storage hiccupped — the
   render still builds its own mask exactly as before, so a miss here costs a
   preview, not a render. Every call site wraps it and ignores the result. */
/* ── ONE DEFINITION OF "STILL DESCRIBES THIS VERSION" ─────────────────────
   The greyscale map is a function of exactly three things: the drawing it
   was derived from, the customer's account of which areas are holes, and
   the resolution floor it was refined at. Both the place that BUILDS the
   map and the place that decides whether to REUSE it have to agree about
   that, byte for byte, or the reuse test can never match and the map is
   rebuilt on every press — which is what happened: this function filed its
   result as specURL/specPath and wrote no key at all, while the render
   looked for renderSpecKey. The two never met, so the very first press of
   Re-render threw away a map that was already correct, rebuilt it to the
   identical bytes, and re-uploaded it under a fresh download token — so the
   greyscale picture on screen visibly changed for no reason.

   Computed here, in one place, used by both. */
function studioSpecKey(drawingBuffer, zones, floorPx) {
  return require("crypto").createHash("sha256")
    .update(drawingBuffer)
    .update("\u0000" + JSON.stringify(studioZoneList(zones, "specKey")))
    .update("\u0000" + String(floorPx))
    .digest("hex").slice(0, 32);
}

async function studioStoreSpecForVersion({ uid, sessionId, n, metal, drawingBuffer, zones }) {
  const sharpMod = studioSharp();
  if (!sharpMod || !drawingBuffer?.length) return null;
  const cfg = await studioConfig();
  if (cfg.renderDeterministicSpec === false) return null;

  const planZones = studioZoneList(zones, "storeSpec");
  const plan = await studioDrawingPlan(sharpMod, drawingBuffer);
  if (!plan) return null;
  let spec = await studioMaterialSpec(sharpMod, plan, metal, planZones);
  if (!spec?.buf) return null;
  /* Same refinement the render applies, or the preview would show softer
     edges than the picture the model is handed — AND, now that the render
     reuses this map rather than rebuilding it, different bytes here would
     mean the model saw a different picture depending on which press it was.

     This call used to read `studioRefineMask(sharpMod, spec, cfg)`. The
     signature is (sharp, maskBuf, targetLong): it was handed the spec
     OBJECT where a buffer belongs and the whole config where a pixel count
     belongs, so sharp() threw on every call, the catch swallowed it, and
     the stored map was never once refined. It was invisible while the map
     was rebuilt at render time anyway; it is load-bearing now. */
  const floor = studioMaskMinPx(cfg);
  if (floor) {
    try {
      const refined = await studioRefineMask(sharpMod, spec.buf, floor);
      if (refined?.buf) {
        spec.buf = refined.buf;
        spec.w = refined.w; spec.h = refined.h;
      }
    } catch (e) { console.error("[studio] mask refine skipped:", e?.message || e); }
  }

  const specPath = `custom-studio/${uid}/uploads/designs/${sessionId}/v${n}-spec.png`;
  const bucket = getBucket();
  const token = newDownloadToken();
  await bucket.file(specPath).save(spec.buf, {
    resumable: false,
    contentType: "image/png",
    metadata: { metadata: { firebaseStorageDownloadTokens: token, uid, sessionId,
                            version: String(n), spec: "1" } },
  });
  return {
    specPath,
    specURL: tokenDownloadURLFor(bucket.name, specPath, token),
    /* what the render needs in order to recognise this map as current */
    specKey: studioSpecKey(drawingBuffer, planZones, floor),
    facePx: Number(spec.facePx) || 0,
    holePx: Number(spec.holePx) || 0,
    workPx: Number(spec.workPx) || 0,
  };
}

/* ── WHAT THE RENDER WOULD SEND — HANDLER REMOVED ─────────────────────────
   handleStudioPromptPreview lived here and answered custom_charm_prompt. It
   re-ran the render's own preparation — the drawing plan, the material spec,
   the census and the naming pass — purely so the studio's prompt lab could
   show the exact text a render would use, and returned the image-role labels
   beside it. It rendered nothing and debited nothing, but it was not cheap:
   it paid for sharp and a vision call on every open of the panel.

   The panel is gone, the render prompt is a fixed string, and the kind is
   dropped from STUDIO_KINDS here and from SYNC_KINDS in the kick. Anything
   still asking gets unknown_kind.                                         */

async function handleStudioRender({ body, event, origin }) {
  const uid = await requireStudioUser(event);
  const cfg = await studioConfig();
  const cost = Number(cfg.generateCost) || 1;
  const db = getDb();

  /* ── ONE RENDERER, AND body.quality IS NOT READ ───────────────────────────
     There was a tier here: "low" was Gemini at one credit, "high" routed the
     same drawing and prompt to OpenAI's image model for two, chosen by a
     Model toggle in the pair rail. The toggle is removed and the tier with
     it. `body.quality` is deliberately not read at all now — not sanitised,
     not downgraded, not refused — so an open tab or a replayed request from
     before the change cannot cost a customer double for something no screen
     offers. Every render is Gemini, and every render costs `cost`.

     cfg.renderHighCost and cfg.renderQualityTiers are likewise unread. A
     config document that still carries them changes nothing. */
  const quality = "low";
  const renderCost = cost;

  const sessionId = String(body?.sessionId || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 60);
  if (!sessionId) return studioJson(400, { ok: false, error: "missing_session" }, origin);
  const renderRunId = String(body?.renderRunId || ("rr_" + Date.now() + "_" + Math.random().toString(36).slice(2, 10)))
    .replace(/[^A-Za-z0-9_-]/g, "").slice(0, 80);

  /* Ownership first — a stranger gets the 403 and NOTHING written into the
     doc, exactly as in generate: a failure channel into someone else's
     design would be a way in. */
  const sRef = db.collection(STUDIO_SESSIONS_COLL).doc(sessionId);
  const sSnap = await sRef.get();
  if (!sSnap.exists || sSnap.data().uid !== uid) {
    return studioJson(403, { ok: false, error: "forbidden" }, origin);
  }
  const session = sSnap.data();

  const n = Number(body?.versionNumber) || Number(session.currentVersion) || 0;
  if (!n || n < 1) return studioJson(400, { ok: false, error: "missing_version" }, origin);
  const vRef = sRef.collection("versions").doc(String(n));
  const vSnap = await vRef.get();
  if (!vSnap.exists || vSnap.data().status !== "done") {
    return studioJson(409, { ok: false, error: "version_not_ready" }, origin);
  }

  /* ── PROVE THE RENDERER EXISTS BEFORE TAKING THE MONEY ───────────────────
     resolveImageModel throws on an unknown id and apiKeyForImageModel throws
     when the provider's key is not set. Discovering either AFTER the debit
     means the customer watches their balance drop, waits for a render that
     was never possible, and gets it back only via the refund path. Both are
     settled here, before a credit moves, and the refusal is written to the
     doc in words the studio can show. */
  let studioModelConfig = null;
  try {
    /* One id, not a branch on quality. cfg.renderHighModel is no longer
       consulted: there is no request that can reach the second renderer.
       The "render" step resolves studioRenderModel first — the gold charm
       has its own key so the drawing step can be moved without moving it. */
    studioModelConfig = resolveImageModel(studioImageModelId(cfg, "render"));
    apiKeyForImageModel(studioModelConfig);
  } catch (err) {
    console.error("[studio] render model unavailable:", err?.message || err);
    await studioFailRender(vRef, "render_unavailable", renderRunId);
    return studioJson(503, { ok: false, error: "render_unavailable" }, origin);
  }

  /* Renders share the generation budgets — a render IS a generation as far
     as the upstream model is concerned. */
  if (!(await studioGateOk(uid, event))) {
    await studioFailRender(vRef, "rate_limited", renderRunId);
    return studioJson(429, { ok: false, error: "rate_limited" }, origin);
  }

  try {
    await studioDebit(uid, renderCost, sessionId);
  } catch (err) {
    if (err?.status === 402) {
      await studioFailRender(vRef, "out_of_credits", renderRunId);
      return studioJson(402, { ok: false, error: "out_of_credits" }, origin);
    }
    throw err;
  }

  const metal = studioCleanText(body?.metal || session.metal || "gold");

  /* STUDIO_DEFAULT_CONFIG is merged in before this, so cfg.renderCutCheck is
     always set and a `|| "off"` fallback here would be dead code — which is
     exactly how a default of "punch" once kept running after the fallback was
     "reverted". The default above is the only place the mode is decided. */
  /* ⏸ paused: forced "off" regardless of config — see STUDIO_VERIFICATION_PAUSED */
  const cutMode = STUDIO_VERIFICATION_PAUSED
    ? "off"
    : String(cfg.renderCutCheck).trim().toLowerCase();
  /* cfg.renderDeterministicSpec is deliberately NOT read here. It used to
     gate the material-spec pass, on the understanding that switching it off
     dropped the render to the colour-coded drawing. With that fallback gone
     it would instead turn every render in the studio into a refunded
     failure, so the pass is mandatory and the key gates only the preview
     mask built at drawing time. */
  try {
    /* ── A NEW RUN STARTS WITH NO VERDICT ─────────────────────────────────
       Every write to this document is a merge, so the previous render's
       scores survived into the next one: press Re-render and the read-out
       went on showing the last run's table — the old attempt count, the old
       numbers — until a new verdict finally landed, and any field the new
       run did not happen to write stayed there for ever.

       So the score fields are CLEARED here, at the top of the run, in the
       same write that stamps this run's id. Between this moment and the new
       verdict the read-out shows nothing rather than something untrue, which
       is the only honest state for a judgement that has not been made yet.
       A Firestore merge has no way to delete a key, so they go to null and
       every reader treats null as absent. */
    /* every score field, from the one list — see STUDIO_SCORE_DOC_FIELDS */
    const clearedScore = studioClearedScore();
    await vRef.set(Object.assign({
      renderStatus: "rendering", renderStage: "planning", renderMetal: metal,
      renderQuality: quality, renderModel: studioModelConfig.id,
      renderCost, renderRunId, renderError: null,
    }, clearedScore), { merge: true });

    const bwPath = `custom-studio/${uid}/uploads/designs/${sessionId}/v${n}.png`;
    const bw = await storagePathToBuffer(bwPath);

    /* ── RE-RENDER RE-RENDERS. IT DOES NOT RE-DERIVE. ─────────────────────
       Everything between here and the model call resolves the approved
       drawing into the greyscale material map, and it did so on EVERY press:
       press Re-render twice with nothing changed and the map was built,
       refined, thresholded and re-uploaded from scratch both times, to
       arrive — deterministically — at the identical bytes. The customer
       asked for another cut of the metal and got the whole pipeline.

       So the map this version already has is reused when it still describes
       this version. "Still describes" is the whole of the care here: the map
       is a function of the drawing, of the customer's account of which areas
       are holes, and of the resolution floor it was refined at. Those three
       are fingerprinted with the map, and a change in any of them rebuilds
       it — so editing a fill and pressing Re-render is not quietly ignored,
       which would be a far worse fault than the slowness being fixed. */
    const vNow = vSnap.data() || {};
    const renderZones = studioZoneList(body?.zones, "render");
    /* the same three inputs, hashed by the same function the BUILDER uses —
       see studioSpecKey. Inlining the hash in two places is exactly what let
       the two drift apart and made reuse unreachable on the first press. */
    const specKey = studioSpecKey(bw.buffer, renderZones, studioMaskMinPx(cfg));
    let reusedSpec = null;
    if (vNow.renderSpecPath && String(vNow.renderSpecKey || "") === specKey) {
      try {
        const got = await storagePathToBuffer(vNow.renderSpecPath);
        if (got?.buffer?.length) {
          reusedSpec = { buf: got.buffer,
                         facePx: Number(vNow.renderSpecFacePx) || 0,
                         holePx: Number(vNow.renderSpecHolePx) || 0,
                         workPx: Number(vNow.renderSpecWorkPx) || 0 };
          console.log("[studio] re-render: reusing the greyscale map already on v" + n);
        }
      } catch (e) {
        /* the map is gone from Storage, or unreadable — build it again */
        console.warn("[studio] stored greyscale map unusable, rebuilding:", e?.message || e);
        reusedSpec = null;
      }
    }

    /* ── DETERMINISTIC SPECIFICATION → AI MATERIAL RENDER ──────────────────
       This is the boundary the render previously did not have. The approved
       drawing still contains BLUE/RED/BLACK because those colours are ideal
       production instructions for people and for the editor. The image model
       no longer receives that vocabulary on the normal path.

       Code resolves the drawing first into a flat material proof in which:
         polished metal is already one grey,
         engraved/outline work is already darker metal,
         and openings are already absent/white.

       The AI therefore has exactly one job: make that already-resolved object
       look like real jewellery. This used to fall back to the old
       colour-coded path when sharp was unavailable or the plan could not be
       built; it now fails the render instead — see THE GREY MAP, OR NOTHING
       below. The two `try`s here still swallow their errors so that the one
       refusal is made in one place, with one message, after the refine pass
       has had its chance. */
    const sharpMod = studioSharp();
    let studioPlan = null;
    if (sharpMod && !reusedSpec) {
      try { studioPlan = await studioDrawingPlan(sharpMod, bw.buffer); }
      catch (e) { console.error("[studio] drawing plan skipped:", e?.message || e); studioPlan = null; }
    } else if (!sharpMod) {
      console.error("[studio] sharp unavailable — no grey map can be built");
    }

    let materialSpec = reusedSpec;
    if (sharpMod && studioPlan && !materialSpec) {
      try { materialSpec = await studioMaterialSpec(sharpMod, studioPlan, metal, renderZones); }
      catch (e) {
        console.error("[studio] material spec skipped:", e?.message || e);
        materialSpec = null;
      }
    }
    /* Smoothed and resampled to the working resolution. Runs AFTER the
       cut/engrave/polish decisions, never before, so nothing is reclassified. */
    if (materialSpec && materialSpec.buf && !reusedSpec) {
      const floor = studioMaskMinPx(cfg);
      if (floor) {
        try {
          const t0 = Date.now();
          const refined = await studioRefineMask(sharpMod, materialSpec.buf, floor);
          materialSpec.buf = refined.buf;
          console.log("[studio] mask refined ->", refined.w + "x" + refined.h,
                      "(" + (Date.now() - t0) + "ms)");
          materialSpec.w = refined.w; materialSpec.h = refined.h;
        } catch (e) {
          console.error("[studio] mask refine skipped:", e?.message || e);
        }
      }
    }

    /* Build topology from the FINAL refined material map so IMAGE 1 and
       IMAGE 2 have identical dimensions and registration. This is a pure
       threshold pass: both grey metal classes become light grey; only white stays
       empty. No model and no second interpretation are involved. */
    let topologyMask = null;
    if (materialSpec?.buf) {
      try { topologyMask = await studioTopologyMask(sharpMod, materialSpec.buf); }
      catch (e) {
        console.error("[studio] topology mask skipped:", e?.message || e);
        topologyMask = null;
      }
    }

    /* ── THE TOPOLOGY + GREY MAPS, OR NOTHING ───────────────────────────
       There were two inputs and a switch between them: `renderInput:
       "drawing"` sent the colour-coded production drawing and let the model
       read the fill law itself, "mask" sent the greyscale spec where code
       has already resolved every cut, engraving and polished region. The
       Send toggle chose, with cfg.renderInput as the fallback.

       Both are gone. `body.renderInput` and `cfg.renderInput` are not read.
       The binary topology mask is handed over first and exclusively decides
       where metal exists. The grey map follows and can decide only whether
       that existing metal is smooth or engraved.

       AND THE COLOUR DRAWING IS NO LONGER A FALLBACK. It used to be sent
       automatically whenever the deterministic pass could not produce a
       spec — better a render than a failure, the reasoning went. It is the
       opposite: the prompt would then be describing an image the model was
       not given, and the customer pays a credit for a charm built from a
       vocabulary nobody resolved. So a missing mask FAILS the render, and
       the throw lands in the catch below, which refunds the credit before
       writing the failure to the version doc. */
    if (!materialSpec?.buf) {
      throw new Error("mask_unavailable");
    }
    /* ── THE TOPOLOGY MASK IS NO LONGER SENT ──────────────────────────────
       It is not an independent input. studioTopologyMask READS the material
       spec and collapses 136 to 176 — measured on a real map, the two images
       are IDENTICAL across 91.05% of their pixels and differ only where the
       engraved tone was flattened. It is derivable from the other by a
       threshold and carries nothing the other does not.

       What it did carry was weight. The request went out as TWO grey
       pictures of exactly the requested object and ONE gold photograph of a
       different object — and the model was told, in the prompt and in three
       separate role labels, to ignore the subject of the only gold one. An
       image model returns something that resembles its inputs; two thirds of
       these resembled a grey charm, and they were the two that matched the
       geometry being asked for. A white-and-grey dragon with gold edges is
       not the model hallucinating. It is the arithmetic of the request.

       Removing it halves the grey and costs no information. It also removes
       the reason it was added: the note above studioTopologyMask says it
       exists so "a learned symbol prior" cannot turn an enclosed light-grey
       island into a hole — and every opening is now cut deterministically by
       studioCompositeOpenings, whatever the model does with them. That job
       was taken over by arithmetic; the input kept the cost and lost the
       purpose.

       It is still COMPUTED, because its census is filed on the version doc
       and is a cheap check that the map is readable. It is simply not sent. */
    const specUsed = true;
    const images = [
      { buffer: materialSpec.buf, mime: "image/png", filename: "material-spec.png" },
    ];
    let renderStyleRef = null;
    try { renderStyleRef = await ensureStudioGoldStyleReference(); }
    catch (e) { console.error("[studio] gold style reference unavailable:", e?.message || e); renderStyleRef = null; }
    if (renderStyleRef?.buffer?.length) images.push({
      buffer: renderStyleRef.buffer,
      mime: renderStyleRef.mime || STUDIO_GOLD_STYLE_REFERENCE_MIME,
      filename: renderStyleRef.filename || STUDIO_GOLD_STYLE_REFERENCE_FILENAME,
    });
    console.log(`[studio] render input=topology+mask reference=${renderStyleRef?.buffer?.length ? "yes" : "no"}`);

    /* ── THE CENSUS AND THE NAMING PASS ARE PARKED ───────────────────────
       Both are still in the file and still correct. Neither runs.

       The prompt never appended the census, so the naming call — a vision
       call and several seconds of latency on every render — produced text
       nothing read. Paying a model to write something no one is shown is
       worse than not having it. The two locals that carried the empty result
       into the prompt builder are gone with the builder's arguments.

       The MASK is untouched and still essential: studioDrawingPlan and
       studioMaterialSpec run exactly as before, and their output IS the image
       the renderer receives. It is only the words about that image that stop. */

    /* ── THE PROMPT IS FIXED, AND CANNOT BE OVERRIDDEN ───────────────────
       `promptOverride` used to be honoured here: whatever text sat in the
       studio's prompt box replaced the built prompt verbatim for that one
       render, everything else unchanged, so a wording change could be told
       apart from a model's variance. It was the right instrument and it did
       its job — the text it converged on IS the prompt this file now ships.

       It is not read any more, and that closes the note I left last time:
       it accepted arbitrary text from a public storefront page, so anyone
       who found the endpoint could spend a credit driving the image model
       with a prompt of their own. Auth, ownership, the budget gate and the
       debit all still stood, but "an authenticated customer can put any
       text into our image model" is not a risk a fixed prompt carries at
       all. The field is ignored rather than rejected — an old tab that
       still sends it gets a normal render, not an error. */
    /* ── DOES THIS CHARM ALREADY HAVE ITS OWN HOOP? ────────────────────────
       Only a design that began life in our repository does, and only the
       storefront knows that — so it says so per request rather than the
       server guessing from the shape of the session. Read as a strict
       boolean: an older tab that sends nothing renders exactly as it did. */
    const builtInHoop = body?.builtInHoop === true;
    const effectivePrompt = buildMaterialSpecToCharmPrompt({ builtInHoop });
    console.log(`[studio] prompt fixed chars=${effectivePrompt.length}`);

    /* ── THE GREYSCALE MASK IS EVIDENCE, SO IT IS KEPT ───────────────────
       This proof records, without manufacturing-colour vocabulary, what is
       metal, what is worked and what is not there at all. The binary topology
       input is derived directly from it and carries no independent judgement. It was
       being built, sent and thrown away — so when a render came back wrong
       there was no way to tell a bad proof from a bad render, which are
       opposite problems with opposite fixes.

       It is filed beside its own pair, on the SAME "uploads" segment as the
       drawing and the charm for the same cart-thumbnail reason, and written
       to the version doc BEFORE the model is called: if the render then fails
       or times out, the proof for that attempt still exists to be looked at.

       It must never be able to fail a render. A proof that could not be
       stored is a missing picture; a render that dies because a picture could
       not be stored is a lost credit. */
    /* No `if (specUsed)` guard any more — the render has already thrown if
       there is no mask, so reaching here means there is one. */
    let renderSpecURL = "", renderSpecPath = "";
    if (reusedSpec) {
      /* the same bytes are already in Storage under the same path, with a
         download token the customer's browser is already using — writing
         them again would only change the token and cost a round trip */
      renderSpecURL = String(vNow.renderSpecURL || "");
      renderSpecPath = String(vNow.renderSpecPath || "");
    } else {
      try {
        renderSpecPath = `custom-studio/${uid}/uploads/designs/${sessionId}/v${n}-spec.png`;
        const specBucket = getBucket();
        const specToken = newDownloadToken();
        await specBucket.file(renderSpecPath).save(materialSpec.buf, {
          resumable: false,
          contentType: "image/png",
          metadata: { metadata: { firebaseStorageDownloadTokens: specToken, uid, sessionId,
                                  version: String(n), spec: "1" } },
        });
        renderSpecURL = tokenDownloadURLFor(specBucket.name, renderSpecPath, specToken);
      } catch (e) {
        console.error("[studio] greyscale mask not stored:", e?.message || e);
        renderSpecURL = ""; renderSpecPath = "";
      }
    }

    await vRef.set({
      renderStage: "rendering", renderRunId,
      renderSpecURL, renderSpecPath,
      /* what this map was derived FROM, so the next press can tell whether
         it still describes this version — see the note where it is read */
      renderSpecKey: renderSpecPath ? specKey : null,
      renderSpecReused: !!reusedSpec,
      renderSpecMode: "deterministic-material",
      renderSpecFacePx: materialSpec.facePx,
      renderSpecHolePx: materialSpec.holePx,
      renderSpecWorkPx: materialSpec.workPx,
      renderInput: "mask",
      renderTopologyMode: "binary-light-grey-metal",
      renderTopologyMetalPx: topologyMask ? topologyMask.metalPx : null,
      renderTopologyEmptyPx: topologyMask ? topologyMask.emptyPx : null,
      renderPromptText: effectivePrompt.slice(0, 40000),
      renderPromptChars: effectivePrompt.length,
      /* renderPromptOverridden is written as a constant false rather than
         dropped: a dashboard or a query reading version docs across the
         change keeps a field that means the same thing, and it is now the
         only answer the field can have. */
      renderPromptOverridden: false,
      /* on a reuse there is no fresh plan to read these from, and writing
         "unknown" over the values the map was actually built with would make
         the record of this version worse than it was */
      renderSpecRoiMode: studioPlan?.roiMode || (reusedSpec ? (vNow.renderSpecRoiMode || "unknown") : "unknown"),
      renderSpecRoiGuard: studioPlan?.roiGuard || (reusedSpec ? (vNow.renderSpecRoiGuard || "unknown") : "unknown"),
      renderSpecRoiSignalPx: Number(studioPlan?.roiSignalPx || (reusedSpec ? vNow.renderSpecRoiSignalPx : 0) || 0),
      renderSpecRoiBox: studioPlan?.roiBox || (reusedSpec ? (vNow.renderSpecRoiBox || null) : null),
      renderSpecSignalBox: studioPlan?.roiSignalBox || (reusedSpec ? (vNow.renderSpecSignalBox || null) : null),
      renderStyleRefPath: renderStyleRef?.storagePath || null,
      renderStyleRefSeeded: !!renderStyleRef?.seeded,
      renderStyleRefUsed: !!renderStyleRef?.buffer?.length,
    }, { merge: true });

    /* The renderer receives the derived topology mask, its deterministic
       material proof and the material reference. The geometry override is
       not appended: the exact hoop and
       silhouette already exist in IMAGE 1, and another prose description of
       where the hoop ought to be would reintroduce a second authority. */
    const renderOnce = (promptText) => callImageModelEdits({
      apiKey: apiKeyForImageModel(studioModelConfig),
      model: studioModelConfig.id,
      prompt: promptText,
      size: studioImageSizeString(studioRenderTier(cfg)),
      imageSizeTier: studioRenderTier(cfg),
      /* the pro model's own ceiling — see STUDIO_RENDER_TIMEOUT_MS */
      timeoutMs: STUDIO_RENDER_TIMEOUT_MS,
      quality: "high",
      output_format: "png",
      images,
      /* Three short labels keep the independent evidence channels from being
         blended or reversed: topology, surface treatment, then material.
         The role set is intentionally concise and adds no new design rules. */
      imageRoles: "material_spec_to_charm",
      /* null, not "flat_integrated_eyelet": that policy belonged to the
         colour-drawing fallback, which no longer exists. IMAGE 1 is the
         geometry. */
      charmGeometryPolicy: null,
      /* ── ONE VOICE ABOUT THE BACKGROUND ──────────────────────────────────
         backgroundPolicy: "solid_black" appends a block headed "BACKEND-
         ENFORCED, OVERRIDES EVERYTHING ABOVE" as the LITERAL LAST WORDS of
         the prompt — after STUDIO_RENDER_FINISH, which had already declared
         itself the final authority and asked for a white ground. Two blocks
         each claiming the last word, in opposition.

         It cost more than a background. That block also says holes "show
         pure black through them", and a black hole on a dark ground is
         indistinguishable from a deeply engraved area — so the one
         distinction the fill law exists to protect, hole versus engraving,
         collapsed, and every recess was pulled darker to match a scene the
         model believed was black. The studio render's presentation is
         defined ONCE — now by the fixed prompt's own IMAGE BACKGROUND line.
         Nothing overrides it. */
      backgroundPolicy: null,
    });

    /* ── ATTEMPT LOOP ─────────────────────────────────────────────────────
       One debit, up to 1 + renderRetries model calls. Only the two verdicts
       code cannot repair cause a retry; a declared opening that came back
       solid is composited in by studioPunchCutouts and accepted, because
       cutting those pixels is exact and asking a model again is not.

       The budget is the hard stop, not the attempt count: the browser's
       watcher gives up at 180s, and a render the customer was told had
       failed is worse than one imperfect region. A new attempt only starts
       if the elapsed time plus the LAST attempt's measured duration still
       fits, so a slow first render never buys a doomed second one. */
    const maxRetries = Math.max(0, Math.min(4, Number(cfg.renderRetries) || 0));

    /* ── THE COMPOSITOR'S SHARE OF THE CLOCK, TAKEN BEFORE IT IS SPENT ────
       The cut-out composite runs after the attempt loop, so if the loop is
       allowed to spend the whole budget the composite starts with nothing
       left and either overruns the client's cap or refuses itself on every
       slow render — which is precisely the render most in need of it.

       So its cost is RESERVED here rather than discovered afterwards. The
       retry loop is handed a budget short by that reserve, which means the
       decision it already makes — "does another attempt still fit?" — now
       accounts for the work that follows it. Measured at 2.6-2.9s on an
       824 px render and scaling with area, a 1600 px render lands near 10s;
       the reserve is set well above that so the composite is never the thing
       that runs out of clock, and it is a config value so it can be widened
       without a deploy. The composite's own deadline then keeps it honest:
       it aborts and returns the render untouched rather than overrunning.  */
    const compositeMode = String(cfg.renderComposite == null ? "on" : cfg.renderComposite)
      .trim().toLowerCase();                       /* "on" | "observe" | "off" */
    const compositing = compositeMode === "on" || compositeMode === "observe";
    /* ── AND THE GATE IN FRONT OF IT ──────────────────────────────────────
       Same measurement, asked earlier and for a different purpose: the
       composite REPAIRS a render, the gate REJECTS one. Both need sharp and
       both need the greyscale map; with neither available the gate simply
       does not arm, exactly as the composite does not run. */
    const shapeMode = String(cfg.renderShapeGate == null ? "on" : cfg.renderShapeGate)
      .trim().toLowerCase();
    const shapeGating = shapeMode === "on" && !!sharpMod;
    const engraveMode = String(cfg.renderEngraveGate == null ? "observe" : cfg.renderEngraveGate)
      .trim().toLowerCase();                       /* "on" | "observe" | "off" */
    const aspectMax = Math.max(1.0, Math.min(2.0, Number(cfg.renderAspectMax) || SCO_ASPECT_MAX));
    const aspectGating = String(cfg.renderAspectGate == null ? "off" : cfg.renderAspectGate)
      .trim().toLowerCase() === "on";
    const shapeMinIoU = Math.min(0.99, Math.max(0.5, Number(cfg.renderShapeMinIoU) || 0.80));
    const shapeRetries = Math.max(0, Math.min(3,
      Number(cfg.renderShapeRetries) === 0 ? 0 : (Number(cfg.renderShapeRetries) || 1)));
    const STUDIO_COMPOSITE_HARD_MS = Math.max(4000, Math.min(60000,
      Number(cfg.renderCompositeBudgetMs) || 30000));
    const rawRetryBudgetMs = Math.max(0, Number(cfg.renderRetryBudgetMs) || 0);
    const retryBudgetMs = rawRetryBudgetMs
      ? Math.max(30000, rawRetryBudgetMs - (compositing ? STUDIO_COMPOSITE_HARD_MS : 0))
      : 0;
    const RETRYABLE = new Set(["undeclared_cut", "unaligned"]);
    const doPunch = cutMode === "enforce" || cutMode === "punch";
    /* In "verify" nothing is repaired, so a repairable failure is not
       repaired — it is re-rendered. `verified` is false whenever any declared
       region read the wrong way, which is precisely the set that "punch"
       would have painted over. */
    const retryable = (rep) => RETRYABLE.has(rep.reason) ||
      (cutMode === "verify" && rep.reason !== "no_cuts_declared" && !rep.verified);
    const startedAt = Date.now();

    /* ── AND THE SECOND REASON TO ROLL AGAIN ──────────────────────────────
       The loop below now has two independent judges with two independent
       allowances. The cut check is geometric and repairs what it can; the
       adjudicator looks at the finished picture and scores it. Either may ask
       for another attempt, each is capped by its own retry count, and the
       wall-clock budget stops both. With renderAdjudicate:"off" every line
       added here is skipped and the loop behaves exactly as it did before. */
    /* ⏸ paused: forced "off" regardless of config — see STUDIO_VERIFICATION_PAUSED */
    const adjMode = STUDIO_VERIFICATION_PAUSED
      ? "off"
      : String(cfg.renderAdjudicate || "off").trim().toLowerCase();
    const adjudicating = adjMode === "observe" || adjMode === "enforce";
    const scoreRetries = adjMode === "enforce"
      ? Math.max(0, Math.min(4, Number(cfg.renderScoreRetries) === 0 ? 0 : (Number(cfg.renderScoreRetries) || 2)))
      : 0;
    /* undefined = not measured yet; null = measured and unmeasurable. The
       three states matter, because "we could not read the map" and "we have
       not looked at the map" mean different things to the audit. */
    let specTruth;
    /* what the judge tried and why it answered nothing — so a run with no
       verdict can still file a record the studio's readout can show */
    let judgeTriedModel = "", judgeFailWhy = "", judgeFailReply = "";
    /* and the same, per attempt — the two above are the run's LAST failure,
       which is all the "nothing could be scored" record needs, and is the
       wrong thing to print beside image #2 when image #1 scored fine */
    const judgeFailByAttempt = {};

    const loop = await studioRenderAttempts({
      renderOnce, basePrompt: effectivePrompt, cfg,
      /* the retry note is appended to basePrompt, so it has to know which
         hoop sentence that prompt already carries */
      builtInHoop,
      cutMode, maxRetries, retryable,
      /* ── THE SHAPE GATE, ONE NUMBER PER ATTEMPT ───────────────────────
         The compositor's own registration stage, stopped the moment it has
         answered — about a second against the twenty-odd the full composite
         takes, because everything after the fit is repair work that a
         drifted render does not want. Same code, same segmentation, same
         measurement, so the gate and the composite can never disagree about
         whether a render is the customer's charm.

         Written never to throw: a gate that cannot answer returns null and
         the loop treats that as no objection. */
      shapeFn: !shapeGating ? null : async (buf) => {
        const r = await studioCompositeOpenings(buf, materialSpec && materialSpec.buf,
          { fitOnly: true, budgetMs: 20000, minIoU: shapeMinIoU,
            engraveGate: engraveMode === "on",
            aspectMax, aspectGate: aspectGating });
        if (!r || !r.report || r.report.iou == null) return null;
        return {
          iou: r.report.iou,
          aspect: r.report.aspect,
          ok: r.report.why === "fit_ok",
          why: r.report.why,
          furniture: r.report.furniture,
          alloy: r.report.alloy,
          outline: r.report.outline,
          engrave: r.report.engrave,
          ms: r.report.ms,
        };
      },
      shapeRetries: shapeGating ? shapeRetries : null,
      shapeMinIoU,
      /* ── THE CUT CHECK NEEDS THE PLAN, AND REUSE SKIPS BUILDING IT ─────
         studioPlan is only derived when the greyscale map is being built
         from scratch, so on a reuse it is null — and studioPunchCutouts
         reads plan.faceBox on its second line. That is a TypeError into a
         catch that reports "punch_error" and hands the render back
         unpunched: first renders would keep their declared holes and every
         re-render would quietly lose them. It is invisible only because
         renderCutCheck ships "off"; turning it on would have shipped the
         bug. The plan is cheap and derived from the same drawing bytes, so
         it is built on demand here rather than made a reason not to reuse
         the map. */
      punchFn: async (buf) => {
        let plan = studioPlan;
        if (!plan && sharpMod) {
          try { plan = await studioDrawingPlan(sharpMod, bw.buffer); }
          catch (e) { console.error("[studio] cut-check plan skipped:", e?.message || e); }
        }
        if (!plan) {
          return { buf, report: { verified: false, reason: "no_plan", declaredCuts: 0,
                                  punchedPx: 0, alignment: 0, openFrac: 0,
                                  regionsOk: 0, regionsBad: 0, worst: "" } };
        }
        return studioPunchCutouts(buf, bw.buffer, plan);
      },
      adjMode, scoreRetries,
      judgeFn: async (buf, attemptNo) => {
        /* THE ANSWER SHEET, MEASURED ONCE. The map does not change between
           attempts, so neither does its census; measuring it per attempt
           would be the same numbers at three times the cost. */
        /* console.log, NOT log: `log` is a local of studioRenderAttempts and
           does not exist in this scope. mk28 wrote `log(...)` here, the first
           judged render threw ReferenceError, and — because the loop trusted
           judgeFn never to throw — the whole render died with "log is not
           defined". The judge crashing a render is the one outcome the
           adjudicator doctrine forbids; the loop is armoured now too. */
        if (specTruth === undefined) {
          specTruth = await studioSpecTruth(sharpMod, materialSpec.buf);
          if (specTruth) {
            console.log(`[studio] spec map contains ${specTruth.openings} opening(s) and ` +
                `${specTruth.engraved} engraved field(s) — the judge is marked against this`);
          }
        }
        let ans = await studioAdjudicateOnce(materialSpec.buf, buf, cfg, { builtInHoop });
        /* ── ONE RUNG DOWN BEFORE GIVING UP ─────────────────────────────
           mk29 pointed the judge's default at a text model — and in a
           deployment where that ID is not available, every call fails, the
           render ships unscored (correct), and the studio's readout simply
           vanishes (the reported symptom). A judge whose CALL failed is
           retried once — on the FLASH TEXT MODEL, not the image generator
           the rung used to reach for. The image model's verdict on the
           first live run was pure fabrication (invented counts arriving in
           a filled-in template), and mk31's other fix means an unreachable
           judge now files a record the panel reads out — so the choice is
           no longer "wrong numbers or silence", it is "a cheaper real
           judge, or an honest sentence saying nobody judged". A fabricated
           verdict lost its only selling point. Garbage ANSWERS
           ("unparsable") are not retried on a worse tool, and a missing
           API key is not retried on anything. */
        const UNREACHABLE = (a) => a.why && a.why !== "no_api_key" &&
              a.why !== "unparsable" && a.why !== "no_object" && a.why !== "incomplete";
        if (!ans.raw && UNREACHABLE(ans) && ans.model && ans.model !== DEFAULT_TEXT_MODEL) {
          console.warn(`[studio] adjudicator (${ans.model}) unreachable — ${ans.why}; ` +
                       `retrying once on ${DEFAULT_TEXT_MODEL}`);
          const cfg2 = Object.assign({}, cfg, { renderScoreModel: DEFAULT_TEXT_MODEL });
          ans = await studioAdjudicateOnce(materialSpec.buf, buf, cfg2, { builtInHoop });
        }

        let scored = studioScoreAudit(ans.raw, studioScoreVerdict(ans.raw, cfg), cfg,
                                      { truth: specTruth, model: ans.model });
        /* an object arrived and was still not a verdict — studioScoreVerdict
           refuses an answer missing any of the six, which is right, but the
           reason has to survive to the panel */
        if (!scored && ans.raw && !ans.why) ans = Object.assign({}, ans, { why: "incomplete" });

        /* ── A MALFORMED REPLY IS A TRANSIENT, NOT A VERDICT ──────────────
           The judge REACHED, answered, and the answer was not usable: no
           JSON object in it, or an object missing one of the six scores.
           The rung-down above deliberately does not fire for that — a
           cheaper model is no answer to a formatting slip, and mk31 was
           right that a fabricated verdict is worse than none.

           But "do not ask a WORSE model" was implemented as "do not ask
           again", and those are different things. This is a temperature-0
           call: the same request with nothing added would return the same
           malformed reply, so it is asked once more WITH THE SLIP NAMED,
           which is the ordinary repair and is how every other structured
           call in this file would be written if it had one.

           This is what shipped v9 unjudged. The first render of that
           version scored normally; the re-render's judge answered with
           something that carried no six scores, there was no second ask,
           and the panel could only say "unusable answer" — about a call
           that had cost sixty seconds and would very likely have answered
           correctly if asked twice. */
        if (!scored && (ans.why === "no_object" || ans.why === "unparsable" ||
                        ans.why === "incomplete")) {
          console.warn(`[studio] adjudicator (${ans.model}) answered but the answer ` +
                       `was not usable (${ans.why}) — asking the same model once more`);
          const retryAns = await studioAdjudicateOnce(materialSpec.buf, buf, cfg,
            { builtInHoop, repair: ans.why });
          const retryScored = studioScoreAudit(retryAns.raw, studioScoreVerdict(retryAns.raw, cfg),
                                               cfg, { truth: specTruth, model: retryAns.model });
          if (retryScored) { ans = retryAns; scored = retryScored; }
          else {
            /* keep the FIRST reply's text — it is the one worth reading, and
               the second is usually the same shape */
            ans = Object.assign({}, ans, { why: ans.why + "_twice" });
          }
        }

        if (scored) { scored.model = ans.model; scored.reply = String(ans.text || "").slice(0, 1200); }
        else {
          judgeTriedModel = ans.model || judgeTriedModel;
          judgeFailWhy = String(ans.why || (ans.text ? "unusable answer" : "no answer")).slice(0, 200);
          /* filed against THIS image, so a table row for an unscored attempt
             can say what happened to it instead of showing six blanks */
          if (attemptNo != null) judgeFailByAttempt[attemptNo] = judgeFailWhy;
          /* AND THE REPLY ITSELF. It was filed only when a verdict was
             produced — so on the one failure where anybody would want to
             read what the judge actually said, renderScoreReply was never
             written and the panel had nothing but an adjective. */
          judgeFailReply = String(ans.text || "").slice(0, 1200) || judgeFailReply;
          console.warn(`[studio] adjudicator (${ans.model}) gave no usable verdict` +
                       (ans.why ? ` — ${ans.why}` : "") +
                       (ans.text ? `; replied: ${ans.text.slice(0, 300)}` : ""));
        }
        return scored;
      },
      retryBudgetMs, startedAt,
      /* renderAttempts as well as renderAttempt: the counter on the storefront
         reads ONE field, and it has to tick while the run is still going
         rather than appear at the end. renderAttempt stays for the watcher's
         own liveness test, which has read it since before this existed. */
      onRetry: (n) => vRef.set({ renderStage: "rendering", renderAttempt: n,
                                 renderAttempts: n, renderRunId }, { merge: true }),
      /* best-effort, and never allowed to fail a render: this is a progress
         note, and a Firestore hiccup writing one must not cost a charm the
         customer has already paid for */
      onStage: async (stage, n) => {
        try {
          await vRef.set({ renderStage: stage, renderAttempt: n, renderRunId }, { merge: true });
        } catch (_e) {}
      },
    });
    let outBuf = loop.outBuf;
    let punch = loop.punch;
    const attempt = loop.attempts;
    /* ── HOW MANY IMAGES THIS RENDER COST, ON THE RECORD, ALWAYS ──────────
       renderAttempts was written in two places and both are parked: inside
       the cut check's block and inside the adjudicator's. With the pause on,
       a run that quietly made three images filed the number nowhere and the
       storefront had nothing to show. It is a fact about the run, not about
       either judge, so it is written here where neither can withhold it. */
    await studioStage(vRef, {
      renderAttempts: attempt,
      renderMaxAttempts: STUDIO_MAX_RENDER_ATTEMPTS,
      renderRunId,
    });
    /* THE GATE'S VERDICT ON THE IMAGE THAT SHIPPED, filed whether it passed
       or not. A render that reached the customer with the wrong outline
       because the clock ran out is exactly the run worth being able to find
       afterwards, and it is invisible unless the number is written down. */
    if (shapeGating && loop.shape && loop.shape.iou != null) {
      const s = loop.shape;
      if (!s.ok) {
        console.warn(`[studio] SHIPPING A RENDER THAT FAILED THE FRAME GATE (${s.why}) — ` +
          `silhouette IoU ${s.iou} vs ${shapeMinIoU}, stray content ` +
          `${s.furniture ? s.furniture.biggest : "?"} after ${attempt} attempt(s)`);
      }
      await studioStage(vRef, {
        renderShapeMode: shapeMode,
        renderShapeIoU: s.iou,
        renderShapeOk: !!s.ok,
        renderShapeMinIoU: shapeMinIoU,
        renderShapeWhy: s.why || "",
        /* the distortion every other measurement in this file normalises
           away before it looks. 1.0 is a faithful render; the bow that fails
           on almost every attempt reads 1.208. */
        renderAspect: s.aspect == null ? null : s.aspect,
        renderAspectMax: aspectMax,
        renderFrameStray: s.furniture ? s.furniture.biggest : null,
        renderFrameBlobs: s.furniture ? s.furniture.blobs : null,
        renderOffAlloy: s.alloy ? s.alloy.offAlloy : null,
        renderOutlineErr: s.outline ? s.outline.mean : null,
        renderOutlineP95: s.outline ? s.outline.p95 : null,
        /* the engraving-fill numbers, filed whether or not the gate is armed:
           this is the record that decides whether renderEngraveGate can be
           turned on, and it is not recoverable from the finished picture */
        renderEngraveMode: engraveMode,
        renderEngraveOver: s.engrave ? s.engrave.over : null,
        renderEngraveCeil: s.engrave ? s.engrave.ceil : null,
        renderEngraveRenderFrac: s.engrave ? s.engrave.renderFrac : null,
        renderEngraveMapFrac: s.engrave ? s.engrave.mapFrac : null,
        renderEngraveFilled: s.engrave ? !!s.engrave.filled : null,
        /* the recess-to-polish brightness ratio, against STUDIO_ENGRAVE_RATIO.
           The approved swallow is 0.837; the render the customer rejected for
           being too dark was 0.488. One number, no registration, no model. */
        renderEngraveTone: s.engrave ? s.engrave.toneRatio : null,
        renderEngraveTooDark: s.engrave ? !!s.engrave.tooDark : null,
        renderShapeSwapped: !!s.swapped,
        /* the storefront reads this to mark its counter: a render that failed
           every attempt is not the same thing as one that passed first time,
           and the customer paid the same credit for both */
        renderQualityFlag: s.ok ? "" : (s.why || "rejected"),
        renderRunId,
      });
    }
    const failedVerdicts = loop.failedVerdicts;
    const scoreLog = loop.scoreLog;
    const attemptLog = loop.attemptLog || [];
    const scoreBest = loop.scoreBest;

    if (scoreLog.length) {
      /* the verdict of the image the customer actually received — see
         `shipped` in studioRenderAttempts. It falls back to the best scored
         attempt only when the shipped render itself could not be judged,
         which is the one case where there is nothing truer to report. */
      const best = (loop.shipped && loop.shipped.scored) || scoreBest.scored;
      await vRef.set({
        renderScoreMode: adjMode,
        renderScore: best.total,
        renderScoreThreshold: best.threshold,
        renderScorePass: best.pass,
        renderScoreChosen: best.attempt,
        renderScoreCount: scoreLog.length,
        /* also written by the cut-check block, which does not run when that
           check is off — so the count of images actually generated is filed
           here too, and the studio's own read-out can always find it */
        renderAttempts: attempt,
        renderScoreFloorFails: best.floorFails,
        renderScoreFabricated: best.fabricated,
        renderScoreWorst: best.worst,
        /* WHO JUDGED, WHAT THEY SAW, AND WHETHER TO BELIEVE THEM.
           Without these three there is no way to tell a model that judged
           badly from one that never looked — which is the question the first
           run in the wild raised, and could not answer. */
        renderScoreJudgeModel: best.model || "",
        renderScoreSuspect: !!best.suspect,
        renderScoreSuspectWhy: best.suspectWhy || [],
        /* near-identical perfect scores: not disqualifying on its own, but
           always worth being able to see */
        renderScoreUniform: !!best.uniform,
        renderScoreCaps: best.caps || [],
        /* WHICH HALF OF THE PAPER THE JUDGE FAILED, AND WHAT THAT COST IT.
           A verdict that gated a render on one of the map's two questions
           has to be able to say which one, or the panel is back to numbers
           with nothing behind them. */
        renderScoreExamWrong: best.examWrong || [],
        renderScoreUnmarked: best.unmarked || [],
        renderScoreObservations: best.observations || null,
        /* WHAT THE MAP ACTUALLY CONTAINS, beside what the judge claimed it
           contains. Two numbers, and the whole argument about whether a
           verdict is worth anything can be settled by looking at them. */
        renderScoreSpecOpenings: best.truth ? best.truth.openings : null,
        renderScoreSpecEngraved: best.truth ? best.truth.engraved : null,
        renderScoreCorroborated: !!best.corroborated,
        renderScoreReply: best.reply || "",
        renderScoreGeometry: best.cats.geometry,
        renderScoreCutouts: best.cats.cutouts,
        renderScoreEngraving: best.cats.engraving,
        renderScoreFidelity: best.cats.fidelity,
        renderScoreTone: best.cats.tone,
        renderScorePresentation: best.cats.presentation,
        /* ── EVERY IMAGE MADE, IN ORDER, JUDGED OR NOT ────────────────────
           This mapped scoreLog, which holds only the attempts a judge
           answered on — so a run that made two images and scored one wrote
           a one-row table under a heading that said "2 images generated",
           and the second image was unreachable from the panel entirely.
           There was nothing wrong with the render; the record simply had no
           row to put it in.

           It maps attemptLog now, which the loop appends to on every pass
           whatever the judge did, and the score fields are merged in from
           scoreLog where one exists. `judged:false` is the flag the panel
           reads to print an honest "not scored" row rather than six blanks
           and a total of zero — an unmeasured render must not read as the
           worst one of the run.

           The two list fields are joined into strings rather than left as
           arrays: an array inside a map inside an array is legal in
           Firestore but reads badly in the console and buys nothing here. */
        renderScoreAttempts: attemptLog.map((a) => {
          const s = scoreLog.find((x) => x.attempt === a.n);
          const row = { n: a.n, ms: a.ms, judged: !!s, cut: a.cut || "" };
          if (!s) {
            /* why THIS image has no scores, attributed to it rather than to
               the run — the panel prints it in place of the numbers */
            row.unscoredWhy = judgeFailByAttempt[a.n] ||
                              (adjudicating ? "no usable verdict" : "not judged");
            return row;
          }
          return Object.assign(row, {
            total: s.total,
            floorFails: s.floorFails.join(","),
            fabricated: s.fabricated.join("; "),
            caps: (s.caps || []).join(","),
            unmarked: (s.unmarked || []).join(","),
            suspect: !!s.suspect,
            model: s.model || "",
            worst: s.worst,
          }, s.cats);
        }),
        renderRunId,
      }, { merge: true });
    } else if (adjudicating) {
      /* ── AN UNSCORED RUN STILL FILES A RECORD ──────────────────────────
         When no attempt could be judged, this used to write nothing at all —
         and the studio's readout, which paints only what the version doc
         carries, silently disappeared. That is how "the judge's model ID is
         wrong in this deployment" surfaced as "my little readout is gone"
         instead of as a sentence naming the problem. The record says how
         many images were made, that none was scored, which model was tried,
         and why it answered nothing — so the panel can come back and say so. */
      await vRef.set({
        renderScoreMode: adjMode,
        renderScoreCount: 0,
        renderAttempts: attempt,
        renderScoreJudgeModel: judgeTriedModel,
        renderScoreUnscoredWhy: judgeFailWhy ||
          (specTruth === undefined ? "the judge was never reached" : "no usable verdict"),
        /* WHAT IT ACTUALLY SAID, on the run where that is the only useful
           thing there is. This field was written only alongside a verdict,
           so the reply was thrown away in exactly the case worth reading. */
        renderScoreReply: judgeFailReply || "",
        /* AND A ROW PER IMAGE HERE TOO. This branch wrote a count and no
           table, so a run that made three images and scored none reported
           the number three with nothing to attach it to. Every row comes
           back `judged:false` with its own reason; the panel prints them
           under the warning instead of leaving the customer to take the
           count on trust. */
        renderScoreAttempts: attemptLog.map((a) => ({
          n: a.n, ms: a.ms, judged: false, cut: a.cut || "",
          unscoredWhy: judgeFailByAttempt[a.n] || judgeFailWhy || "no usable verdict",
        })),
        renderRunId,
      }, { merge: true });
    }

    await vRef.set({ renderStage: "polishing", renderRunId }, { merge: true });

    /* ── THE CUT CHECK IS PARKED ──────────────────────────────────────────
       The punch is correct on the cases it was proven against, but the fill
       identification behind it is still being corrected — and a check that is
       sometimes wrong is worse than no check, because it edits a charm the
       customer is paying for. So it ships OFF, and the customer sees exactly
       what they saw before it existed: no verdict, no rejected renders, no
       pixels touched.

       One value in config/customStudio, no deploy, three settings:
         "off"      what ships. The scan does not run.
         "observe"  the scan runs and files its numbers on the version doc,
                    but the image is returned untouched and nothing is ever
                    rejected. This is how the identification gets tuned
                    against real traffic without a customer ever paying for
                    it — turn it on when we start correcting the fills.
         "enforce"  punch declared cut-outs, reject undeclared ones. */
    /* ── "punch": HONOUR THE DECLARED CUT-OUTS, JUDGE NOTHING ─────────────
       The mask says a region is cut clean through; the model renders it as a
       shallow engraving anyway, and does so inconsistently — the same render
       cut the hoop and engraved the knife. That is not a wording problem. It
       is the one question the model keeps getting wrong, and it does not have
       to be asked: the openings are already known exactly, deterministically,
       before the render is ever requested.

       So this mode composites them and stops there. It never rejects a render
       and never charges a customer for a verdict:
         "off"      nothing runs (what shipped while identification was tuned)
         "punch"    declared cut-outs are cut into the render. Nothing else.
         "observe"  scan and file the numbers, image untouched
         "enforce"  punch AND reject undeclared cuts (the strict mode)
       Alignment still guards it — if the render's silhouette does not match
       the drawing's, no coordinate maps between them and studioPunchCutouts
       declines to punch rather than cutting blind. */
    if (punch) {
      if (doPunch) outBuf = punch.buf;
      /* Rejection is reserved for the one failure that survived every attempt
         AND cannot be repaired: metal removed that should be solid. An
         "unaligned" render is not damaged, only unjudgeable, so it ships
         unpunched rather than costing the customer their credit and their
         wait. */
      if (cutMode === "enforce" && punch.report.reason === "undeclared_cut") {
        const e = new Error("cut_check_undeclared");
        e.studioReport = punch.report;
        throw e;
      }
      await vRef.set({
        renderCutMode: cutMode,
        renderAttempts: attempt,
        /* one entry per attempt that failed the check, in order */
        renderAttemptVerdicts: failedVerdicts.slice(0, 5),
        renderCutsDeclared: punch.report.declaredCuts,
        renderCutsPunched: doPunch ? punch.report.punchedPx : 0,
        renderCutsWouldPunch: punch.report.punchedPx,
        renderAlignment: Math.round(punch.report.alignment * 1000) / 1000,
        renderOpenFraction: Math.round(punch.report.openFrac * 1000) / 1000,
        renderVerified: doPunch && !!punch.report.verified,
        renderRegionsOk: punch.report.regionsOk,
        renderRegionsBad: punch.report.regionsBad,
        renderWorstRegion: punch.report.worst || "",
        renderCheck: punch.report.reason,
        renderRunId,
      }, { merge: true });
    }

    /* ── THE CUT-OUTS, COMPOSITED ────────────────────────────────────────
       The last thing done to the image and the first thing skipped. It runs
       here, after the attempt loop has settled on a winner and BEFORE the
       PNG text chunks are spliced in, because embedPngTextMetadata writes
       raw iTXt chunks by hand and any later sharp re-encode would strip
       them. Everything it needs it already has: the finished render and the
       same greyscale map every other stage was measured against.

       It cannot fail a render. studioCompositeOpenings catches its own
       errors and returns the input buffer; this call is wrapped again on top
       of that, and the assignment only happens when a new buffer came back.

       The clock is real and shared. The stage write below is also what keeps
       the browser's silence watcher alive while the compositing runs — the
       render watcher gives up on a quiet document, not a long one. */
    if (compositing) {
      try {
        await vRef.set({ renderStage: "cutting", renderRunId }, { merge: true });
      } catch (e) { /* a stage write is narration; never a reason to stop */ }
      let comp = null;
      try {
        /* whichever runs out first: the composite's own cap, or what is left
           of the whole render's wall clock */
        const leftOfRun = rawRetryBudgetMs
          ? rawRetryBudgetMs - (Date.now() - startedAt)
          : STUDIO_COMPOSITE_HARD_MS;
        /* THE GREYSCALE MATERIAL SPEC, not the drawing. This is IMAGE 1 —
           the map the render was asked to obey and every other stage is
           measured against — on the 255/176/136 ladder. The line-art drawing
           carries the same geometry in a different vocabulary, and reading
           the wrong one would declare its ink as openings. */
        comp = await studioCompositeOpenings(outBuf, materialSpec && materialSpec.buf, {
          budgetMs: Math.max(2000, Math.min(STUDIO_COMPOSITE_HARD_MS, leftOfRun)),
          minIoU: Math.min(0.99, Math.max(0.5, Number(cfg.renderCompositeMinIoU) || 0.80)),
          aspectMax,
          localFit: String(cfg.renderCompositeLocalFit == null ? "on" : cfg.renderCompositeLocalFit)
            .trim().toLowerCase() !== "off",
        });
        if (comp && comp.buf && comp.buf.length && compositeMode === "on") outBuf = comp.buf;
        /* ── THE ALARM THAT WAS MISSING ────────────────────────────────
           A render where the compositor cut EVERY declared opening is not a
           compositor success, it is the generator having produced none of
           them — and the finished picture looks broadly right, so nobody
           notices. Three renders shipped that way after a prompt edit
           removed the only imperative telling the model white means cut
           through, and the fault was found by eye, from a customer, on the
           third one. It is one comparison off numbers already in hand. */
        if (comp.report.declared > 0 && comp.report.leftAlone === 0 &&
            comp.report.composited >= comp.report.declared) {
          console.warn(`[studio] THE MODEL CUT NOTHING — all ` +
            `${comp.report.declared} declared opening(s) were composited in by code. ` +
            `Every opening in this charm is deterministic. If this repeats across ` +
            `renders, suspect the render prompt rather than the compositor.`);
        }
        console.log(`[studio] cut-out composite: ran=${comp.report.ran} ` +
          `declared=${comp.report.declared} composited=${comp.report.composited} ` +
          `refused=${comp.report.refused} leftAlone=${comp.report.leftAlone} ` +
          `leftAloneNear=${comp.report.leftAloneNear} ` +
          `iou=${comp.report.iou} aspect=${comp.report.aspect} shift=${comp.report.maxShift}px ` +
          `${comp.report.why ? "why=" + comp.report.why + " " : ""}` +
          `${comp.report.ms}ms`);
      } catch (e) {
        console.error("[studio] cut-out composite skipped:", e?.message || e);
      }
      if (comp && comp.report) {
        try {
          await vRef.set({
            renderCompositeMode: compositeMode,
            renderCompositeRan: !!comp.report.ran,
            renderCompositeWhy: comp.report.why || "",
            renderCompositeMs: comp.report.ms,
            renderCompositeDeclared: comp.report.declared,
            renderCompositeRefused: comp.report.refused,
            renderCompositeApplied: comp.report.composited,
            renderCompositeLeftAlone: comp.report.leftAlone,
            /* of those, the ones left alone because the render's OWN opening
               was within reach rather than dead under the footprint. A thin
               feature registered a few pixels out lands here, and before
               this counter existed it was composited over instead. */
            renderCompositeLeftAloneNear: comp.report.leftAloneNear,
            /* ONE NUMBER FOR "DID THE GENERATOR CUT ANYTHING": the share of
               declared openings the model made itself. 1 is a clean render,
               0 means every hole in the picture was cut by code. Watch this
               across renders after any change to the render prompt — it is
               the field that would have caught the prompt edit that removed
               the cut instruction, on the first render instead of the third. */
            renderModelCutShare: comp.report.declared
              ? Math.round((comp.report.leftAlone / comp.report.declared) * 1e3) / 1e3
              : null,
            renderCompositeIoU: comp.report.iou,
            renderCompositeOpenFrac: comp.report.openFrac,
            renderCompositeDeclaredFrac: comp.report.declaredFrac == null
              ? null : Math.round(comp.report.declaredFrac * 1e4) / 1e4,
            renderCompositeShadeK: comp.report.shadeK,
            renderCompositeClusters: comp.report.clusters,
            /* the largest local correction any cluster took. If an opening
               ever lands wrong, this says in one number whether a shift was
               involved at all — which is the difference between two entirely
               different investigations, and is not recoverable afterwards
               from the finished picture. */
            renderCompositeMaxShift: comp.report.maxShift,
            renderCompositeStray: comp.report.furniture ? comp.report.furniture.biggest : null,
            renderCompositeLocalFit: !!comp.report.localFit,
            renderRunId,
          }, { merge: true });
        } catch (e) { /* the numbers are a record, not the product */ }
      }
    }

    outBuf = embedPngTextMetadata(outBuf, {
      Description: `Custom Charm Studio charm — rendered from approved drawing v${n} (${metal}).`,
      CharmTitle: `Custom charm v${n}`,
    });

    /* Same "uploads" segment as the drawing, for the same reason: both cart
       templates render any property URL containing uploads+extension as a
       clickable thumbnail, and BOTH halves of the pair go into the cart. */
    const renderPath = `custom-studio/${uid}/uploads/designs/${sessionId}/v${n}-charm.png`;
    const bucket = getBucket();
    const token = newDownloadToken();
    await bucket.file(renderPath).save(outBuf, {
      resumable: false,
      contentType: "image/png",
      metadata: { metadata: { firebaseStorageDownloadTokens: token, uid, sessionId, version: String(n), render: "1" } },
    });
    const renderURL = tokenDownloadURLFor(bucket.name, renderPath, token);

    await vRef.set({
      renderStatus: "done", renderStage: "done", renderRunId,
      renderURL, renderPath, renderMetal: metal,
      renderSpecURL, renderSpecPath,
      renderQuality: quality, renderModel: studioModelConfig.id, renderCost,
      /* ── A RENDER IS THE UNDO FOR A GOLD EDIT ─────────────────────────
         The storefront has always said so — "Re-render puts the charm back
         to what the drawing says" — and cleared these two on its own copy
         of the version, claiming in a comment that the server cleared them
         "in the same breath". It did not: this file had never heard of a
         gold edit. So a customer who edited the gold, re-rendered, then
         reopened the design from another device still found the charm
         flagged as diverged from a drawing it now matched exactly. */
      goldEdited: false,
      goldEditCount: 0,
      renderedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });

    return studioJson(200, { ok: true, n, renderURL, renderPath, renderMetal: metal,
                             renderSpecURL, renderSpecPath,
                             renderQuality: quality, renderModel: studioModelConfig.id,
                             renderCost, renderRunId,
                             /* the browser watches the version doc, so this is
                                belt and braces for the poll path */
                             renderAttempts: attempt,
                             renderScore: scoreBest ? scoreBest.scored.total : null,
                             renderScoreMode: adjudicating ? adjMode : "off" }, origin);
  } catch (err) {
    // A failed render must never cost a credit — including a double-priced one.
    await studioRefund(uid, renderCost, sessionId);
    await studioFailRender(vRef, String(err?.message || err), renderRunId);
    console.error("[studio] render failed:", err?.message || err);
    return studioJson(500, { ok: false, error: "render_failed" }, origin);
  }
}

/* ═══════════ THE GOLD EDIT ════════════════════════════════════════════════
   "Make the wings a little longer", typed while looking at a finished charm.

   THIS IS NOT A RENDER, AND MUST NOT BEHAVE LIKE ONE. A render descends from
   the greyscale map: it asks the model to realise a specification, and every
   pixel is up for negotiation because none of them existed yet. A gold edit
   descends from a PHOTOGRAPH THE CUSTOMER HAS ALREADY ACCEPTED. Ninety-nine
   percent of it is finished work they did not ask about, and the only
   acceptable outcome is that picture again with one thing different.

   So the greyscale map is not sent, the drawing is not regenerated and the
   mask is not rebuilt. One image goes up — the charm as it stands — with one
   sentence, and the prompt spends most of its length saying what must NOT
   change. The version keeps its drawing and its mask, and is stamped
   goldEdited so the stage can tell the customer the two halves of the pair
   have diverged. Re-render is the way back.

   IT IS ALSO NOT ADJUDICATED. The scoring pass compares a render against the
   greyscale map, and after an edit the map deliberately no longer describes
   the charm — the customer asked for the difference. Scoring it would mark
   down exactly the change that was paid for. See the note at the debit.
   ═══════════════════════════════════════════════════════════════════════ */
const STUDIO_GOLD_EDIT_PROMPT_HEAD =
`SURGICAL EDIT OF AN EXISTING PHOTOGRAPH — PRESERVATION IS THE PRIMARY TASK.

The supplied image is a finished photograph of a real 14K gold charm that the
customer has already accepted. You are not designing a charm and you are not
rendering one. You are making ONE requested alteration to this exact
photograph and returning it otherwise unchanged.

Treat everything not named in the request as FIXED and already correct.`;

const STUDIO_GOLD_EDIT_PROMPT_TAIL =
`WHAT MUST SURVIVE THE EDIT, PIXEL FOR PIXEL WHERE THE REQUEST DOES NOT REACH:
• The silhouette and proportions of every part of the charm the request does
  not name. If the request is about the wings, the hoop, the body, the base
  and every engraved line stay exactly as they are — same size, same position,
  same shape, same spacing.
• The hanging hoop: same place, same diameter, same wall thickness\${HOOP_RULE}.
• EVERY OPENING. Each hole cut through the metal stays open, the same shape
  and in the same place, with the same bright inner cut edge. Do not fill one,
  do not add one, do not turn one into an engraved recess.
• EVERY ENGRAVED AREA: same placement, same coverage, same shallow depth, same
  satin finish against the polish around it.
• The material: one alloy, warm yellow 14K gold, the same colour, the same
  polish, the same warmth. No second metal, no inlay, no enamel, no patina.
• The photograph itself: the same camera angle, the same framing, the same
  scale within the frame, the same single soft key light from the upper left,
  the same plain pure white seamless ground, and the same single soft contact
  shadow beneath the piece with every opening showing through it as clean
  white.

ABSOLUTELY FORBIDDEN, whatever the request says:
• Re-composing, re-cropping, re-lighting, rotating or re-staging the charm.
• Redrawing the charm "in the same style" — this is an edit of THIS picture,
  not a new picture of the same subject.
• More than one charm in the frame. No second view, no before-and-after, no
  split panel, no duplicate, no inset, no comparison.
• Any label, caption, watermark, letter, number, arrow, callout or border.
• Any chain, hand, prop, packaging, backdrop or surface other than the plain
  white ground.
• Any ornament, gemstone, texture or engraved line that is not already in the
  picture and was not asked for.

HOW TO APPLY THE CHANGE:
• Make the smallest alteration that honestly satisfies the request. If a
  request could be read as small or large, read it small.
• Blend it into the surrounding metal so the edited region is the same
  material under the same light — the seam must not be findable.
• Where the request would disturb something in the preserved list above,
  favour the request only in the region it actually concerns and leave the
  rest alone.
• If the request is impossible or you cannot tell what it refers to, return
  the photograph UNCHANGED rather than guessing. An unchanged charm is a
  recoverable outcome; a redesigned one is not.

FINAL CHECK BEFORE YOU ANSWER: place your result beside the original. A person
who was not told what was asked for should be able to spot exactly one
difference, and it should be the one the customer requested.`;

/* ── THE CAPTION ON ONE OF OUR OWN PHOTOGRAPHS ────────────────────────────
   Every catalogue product image carries "Charm Only" in handwritten script
   above the piece. It is a listing caption, not jewellery, and it must not
   survive into a charm the customer is buying.

   IT IS REMOVED HERE RATHER THAN CROPPED OFF EARLIER. Cropping worked — the
   caption is achromatic and the charm is not, so it separates cleanly — but
   it throws pixels away before the customer has asked for anything, and the
   model is about to redraw this piece regardless. One clause in a prompt
   that is already editing the charm costs nothing extra.

   IT IS ALSO THE ONE THING THAT OVERRIDES THE PRESERVATION RULES BELOW,
   which is why it is stated as an exception rather than added to the list:
   those rules demand the same framing and the same scale in the frame, and
   removing a caption from above the charm means the charm no longer sits
   where it did. Both are suspended, for this one purpose, and nothing else
   about the piece may move with them. */
const STUDIO_GOLD_EDIT_CAPTION =
`BEFORE ANYTHING ELSE — REMOVE THE CAPTION. The supplied photograph is a
catalogue listing image and carries handwritten text reading "Charm Only"
above the charm. That text is a caption on a web page. It is not part of the
jewellery, it is not engraved on anything, and it must NOT appear anywhere in
your output.

• Delete it completely. Leave clean, seamless, pure white in its place — no
  ghost, no smudge, no faint remnant, no blurred patch where it was.
• Reproduce NO text of any kind: not this caption, not a replacement, not a
  watermark, not a signature, not lettering engraved onto the charm.
• With the caption gone, CENTRE THE CHARM in the square frame at a size that
  fills it comfortably, with even white margin on all four sides.

THIS PARAGRAPH IS THE ONE EXCEPTION to the preservation rules further down.
Those rules require the same framing and the same scale within the frame;
removing text from above the charm makes both impossible, so for this purpose
only, both are suspended. Everything else they protect — the silhouette, the
hoop, every opening, every engraved area, the alloy, the light, the white
ground and the single contact shadow — is preserved exactly as written.`;

/* ── THE CUSTOMER POINTING AT THEIR OWN CHARM ─────────────────────────────
   A charm adopted from our catalogue has no production drawing, so marks made
   on it cannot send the arrow back to a design step — there is no drawing to
   redraw. The studio therefore keeps them on the gold edit, and this is the
   half of that which the model sees.

   IT IS A LOCATOR, NOT A BRIEF, and every line here exists to keep it one.
   The design step's markup contract is a rich grammar — a ring means a
   cut-out, a pen line means engrave this — because there the customer IS
   designing. Here they are not: they have a finished charm and a sentence,
   and the marks answer only "where". Importing that grammar would hand a
   surgical edit a licence to re-cut the piece, which is precisely what the
   customer asked this path never to do.

   The notes still travel with their anchors, because "make this bigger" is
   not an instruction until you know what `this` is. */
function buildGoldEditMarkupBlock(markupNotes, markupMode) {
  const notes = (Array.isArray(markupNotes) ? markupNotes : [])
    .map((nRaw) => {
      const o = nRaw && typeof nRaw === "object" ? nRaw : { text: nRaw };
      const t = studioCleanText(o.text);
      if (!t) return null;
      const x = Number(o.x), y = Number(o.y);
      const where = Number.isFinite(x) && Number.isFinite(y) ? markupRegion(x, y) : null;
      return { text: t, where, lettering: o.kind === "lettering" };
    })
    .filter(Boolean).slice(0, 12);
  const plain = notes.filter((nn) => !nn.lettering);
  const letters = notes.filter((nn) => nn.lettering);
  const exact = String(markupMode || "") === "exact";

  const lines = [
`THE CUSTOMER HAS MARKED THE CHARM TO SHOW YOU WHERE.

A second image is supplied: it is the SAME photograph of this charm with the
customer's own marks drawn on top of it. Read it for ONE thing only — the
place on the charm their request refers to.

• The marks are a pointing finger. A circle, a highlight, a scribble or an
  arrow means "the part of the charm underneath or ahead of this", and
  nothing more. A circle drawn around the hoop is not a request for a circle.
• NO MARK EVER BECOMES METAL. Not as ink, not as an engraved line, not as a
  cut-out, not as a raised edge, not as a change of finish. The output must
  look as though the marks were never made — because the customer's finger
  was never part of the jewellery.
• The marks do NOT enlarge the request. They say where the sentence below
  applies; the sentence still says what to do, and it is still the only
  change being made. If the marks appear to ask for more than the sentence
  does, follow the sentence.
• If a mark and the sentence disagree about WHERE, the mark wins — it is the
  more precise of the two, which is why the customer drew it.`,
  ];
  if (exact) {
    lines.push(
`The customer set their marks to EXACT, which here means only that they have
placed them carefully: read the boundary of each mark as the true extent of
the region they mean, rather than as a rough gesture near it. It does not
mean reproduce the marks, and it does not licence a change the sentence
below did not ask for.`);
  }
  if (plain.length) {
    lines.push(
`THEIR NOTES, EACH PINNED TO THE PART OF THE CHARM IT IS ABOUT:
${plain.map((nn, i) => `${i + 1}. ${nn.where ? `(pinned at ${nn.where} of the charm) ` : ""}"${nn.text}"`).join("\n")}

These are instructions ABOUT the charm. Not one word of them is to be
engraved, printed or otherwise written onto the metal.`);
  }
  if (letters.length) {
    lines.push(
`TEXT THE CUSTOMER PLACED ON THE CHARM — this, unlike their notes, IS to be
engraved, at the position shown, in the same shallow satin engraving as the
rest of the piece:
${letters.map((nn) => `• "${nn.text}"${nn.where ? ` — at ${nn.where} of the charm` : ""}`).join("\n")}`);
  }
  return lines.join("\n\n");
}

function buildGoldEditPrompt(instruction, metal, opts) {
  const clean = studioCleanText(instruction).slice(0, STUDIO_MAX_INSTRUCTION);
  const parts = [STUDIO_GOLD_EDIT_PROMPT_HEAD];
  /* First, so it is read before the preservation rules it overrides. */
  if (opts && opts.stripCaption) parts.push(STUDIO_GOLD_EDIT_CAPTION);
  parts.push(
`THE ONE CHANGE THE CUSTOMER ASKED FOR — this, and nothing else:
"${clean}"`);
  /* AFTER the request and BEFORE the preservation rules: it qualifies the
     sentence above by locating it, and it is itself outranked by the list
     of what must survive — a mark can move the edit, never widen it. */
  if (opts && opts.markupMode !== undefined && opts.markupMode !== null) {
    parts.push(buildGoldEditMarkupBlock(opts.markupNotes, opts.markupMode));
  }
  if (metal) {
    parts.push(`The metal is ${studioCleanText(metal)} and does not change.`);
  }
  /* ── THE HOOP CLAUSE, ON THIS PIPELINE TOO ──────────────────────────
     The render's hoop sentence is swapped per request on `builtInHoop`, and
     this tail carried the un-swapped doctrine — "still part of the same flat
     sheet rather than an attached jump ring" — on every edit. So the very
     first edit of a repository charm re-asserted, in the list of things that
     must survive PIXEL FOR PIXEL, the one thing the render had just been
     told was false of it: a real jump ring would be re-formed into a flat
     integrated hoop while the model believed it was preserving the piece.

     Same flag, same strict true, same one-clause swap. */
  parts.push(STUDIO_GOLD_EDIT_PROMPT_TAIL.replace("${HOOP_RULE}",
    (opts && opts.builtInHoop === true)
      ? ", and still the hanging hardware the piece arrived with rather than " +
        "re-formed into a hoop cut from the same sheet"
      : ", and still part of the same flat sheet rather than an attached jump ring"));
  return parts.join("\n\n");
}

async function handleStudioGoldEdit({ body, event, origin }) {
  const uid = await requireStudioUser(event);
  const cfg = await studioConfig();
  const cost = Number(cfg.generateCost) || 1;
  const db = getDb();

  const sessionId = String(body?.sessionId || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 60);
  if (!sessionId) return studioJson(400, { ok: false, error: "missing_session" }, origin);
  const renderRunId = String(body?.renderRunId || ("ge_" + Date.now()))
    .replace(/[^A-Za-z0-9_-]/g, "").slice(0, 80);

  /* Ownership before anything is written, exactly as in render: a failure
     channel into somebody else's design would be a way in. */
  const sRef = db.collection(STUDIO_SESSIONS_COLL).doc(sessionId);
  const sSnap = await sRef.get();
  if (!sSnap.exists || sSnap.data().uid !== uid) {
    return studioJson(403, { ok: false, error: "forbidden" }, origin);
  }
  const session = sSnap.data();

  const n = Number(body?.versionNumber) || Number(session.currentVersion) || 0;
  if (!n || n < 1) return studioJson(400, { ok: false, error: "missing_version" }, origin);
  const vRef = sRef.collection("versions").doc(String(n));
  const vSnap = await vRef.get();
  if (!vSnap.exists) return studioJson(409, { ok: false, error: "version_not_ready" }, origin);
  const version = vSnap.data();

  /* THE THING BEING EDITED HAS TO EXIST. The browser has its own copy of
     this check, but a stale tab can still ask, and "no_gold_yet" is a word
     the storefront already has a sentence for. */
  const goldPath = String(version.renderPath || "");
  if (!goldPath) return studioJson(409, { ok: false, error: "no_gold_yet" }, origin);

  const instruction = studioCleanText(body?.instruction || "").slice(0, STUDIO_MAX_INSTRUCTION);
  if (!instruction) return studioJson(400, { ok: false, error: "missing_instruction" }, origin);

  const metal = studioCleanText(body?.metal || version.renderMetal || session.metal || "gold");

  /* Prove the renderer exists before taking the money — same order as
     handleStudioRender, for the same reason. Same "goldedit" step key too,
     which resolves the same studioRenderModel: an edited gold charm and a
     freshly rendered one must come off the same model or the customer sees
     the metal change when they touch it. */
  let studioModelConfig = null;
  try {
    studioModelConfig = resolveImageModel(studioImageModelId(cfg, "goldedit"));
    apiKeyForImageModel(studioModelConfig);
  } catch (err) {
    console.error("[studio] gold edit model unavailable:", err?.message || err);
    await studioFailRender(vRef, "render_unavailable", renderRunId);
    return studioJson(503, { ok: false, error: "render_unavailable" }, origin);
  }

  if (!(await studioGateOk(uid, event))) {
    await studioFailRender(vRef, "rate_limited", renderRunId);
    return studioJson(429, { ok: false, error: "rate_limited" }, origin);
  }

  try {
    await studioDebit(uid, cost, sessionId);
  } catch (err) {
    if (err?.status === 402) {
      await studioFailRender(vRef, "out_of_credits", renderRunId);
      return studioJson(402, { ok: false, error: "out_of_credits" }, origin);
    }
    throw err;
  }

  try {
    /* The stage names match GOLD_EDIT_STAGES in the storefront, so the bar
       moves through the words the customer is reading rather than jumping. */
    await vRef.set({
      renderStatus: "rendering", renderStage: "planning", renderRunId,
      renderMetal: metal, renderModel: studioModelConfig.id, renderCost: cost,
      renderError: null,
      goldEditInstruction: instruction.slice(0, 400),
      /* NO SCORE FIELDS ARE WRITTEN AND THE OLD ONES ARE CLEARED. The
         adjudicator scores a charm against the greyscale map, and this
         charm is deliberately no longer the one the map describes — the
         customer paid for the difference. A stale verdict left on the doc
         would be read by the studio's own read-out as a judgement of the
         edited picture, which it is not. */
      ...studioClearedScore(),
    }, { merge: true });

    const gold = await storagePathToBuffer(goldPath);
    if (!gold?.buffer?.length) throw new Error("gold_missing");

    /* ── THE EDIT COMES BACK THE SIZE IT WENT UP ──────────────────────────
       A render sizes itself from studioRenderTier, and that is right for a
       render: it is making a picture that does not exist yet. An edit is
       making the SAME picture again, so taking its size from a config value
       is a quiet way to lose half the customer's charm — set the tier to 1K
       after a charm was rendered at 2K and every subsequent edit silently
       returns a quarter of the pixels, permanently, over the same file.

       And it compounds. Each edit re-encodes the previous edit's output, so
       resolution only ever ratchets DOWN; there is no pass that puts detail
       back. So the source decides, measured from the actual bytes, and the
       config tier is only the fallback for when it cannot be read. */
    let editSize = studioImageSizeString(studioRenderTier(cfg));
    let editTier = studioRenderTier(cfg);
    try {
      const sh = studioSharp();
      if (sh) {
        const meta = await sh(gold.buffer).metadata();
        const long = Math.max(Number(meta.width) || 0, Number(meta.height) || 0);
        if (long >= 3072)      { editSize = "4096x4096"; editTier = "4K"; }
        else if (long >= 1536) { editSize = "2048x2048"; editTier = "2K"; }
        else if (long > 0)     { editSize = "1024x1024"; editTier = "1K"; }
        if (long) console.log(`[studio] gold edit source is ${meta.width}x${meta.height} — ` +
                              `editing at ${editSize} (config tier would have been ` +
                              `${studioRenderTier(cfg)})`);
      }
    } catch (e) {
      console.error("[studio] could not measure the charm, falling back to the config tier:",
                    e?.message || e);
    }

    await vRef.set({ renderStage: "rendering", renderRunId }, { merge: true });

    /* A charm adopted from the catalogue still carries its listing caption
       until an edit has taken it off. captionStripped is set on the version
       the first time one succeeds, so the clause is sent exactly while it is
       needed and not on every edit thereafter. */
    const stripCaption = version.source === "catalog" && !version.captionStripped;

    /* THE CHARM IS ALWAYS FIRST AND ALWAYS ALONE UNLESS THE CUSTOMER DREW.
       Nothing else may ever join it — see the note at the call below. */
    const editImages = [{ buffer: gold.buffer, mime: gold.mime || "image/png",
                          filename: `v${n}-charm.png` }];

    /* ── THE MARKS, IF THE CUSTOMER MADE ANY ──────────────────────────────
       Accepted on exactly the terms the design step accepts them on: a data
       URL of a known type, decoded, size-capped, and MODE IS SET ONLY IF THE
       IMAGE ITSELF WAS ACCEPTED. That last part is the whole guard — notes
       describing an image that never arrived would tell the model to read a
       second picture that is not there, and a model told to look at a
       missing image invents one. If anything about the payload is wrong the
       edit proceeds as the plain sentence it has always been. */
    let markupNotes = null;
    let markupMode = null;
    if (typeof body?.markupImage === "string") {
      const mm = /^data:image\/(png|jpeg);base64,([A-Za-z0-9+/=]+)$/.exec(body.markupImage.trim());
      if (mm) {
        const mbuf = Buffer.from(mm[2], "base64");
        if (mbuf.length > 0 && mbuf.length <= 1.5 * 1024 * 1024) {
          editImages.push({ buffer: mbuf, mime: "image/" + mm[1],
                            filename: "markup." + (mm[1] === "png" ? "png" : "jpg") });
          markupNotes = Array.isArray(body.markupNotes) ? body.markupNotes : [];
          markupMode = String(body.markupMode) === "exact" ? "exact" : "interpret";
        }
      }
    }

    /* the same per-request flag the render reads, so an edit cannot contradict
       the charm the render was told to make — see buildGoldEditPrompt's tail */
    const builtInHoop = body?.builtInHoop === true;
    const prompt = buildGoldEditPrompt(instruction, metal,
                                       { stripCaption, markupNotes, markupMode, builtInHoop });
    console.log(`[studio] gold edit v${n} "${instruction.slice(0, 60)}" ` +
                `prompt=${prompt.length} chars model=${studioModelConfig.id}` +
                (stripCaption ? " (+ caption removal)" : "") +
                (markupMode ? ` (+ marks, ${markupMode}, ` +
                              `${(markupNotes || []).length} note(s))` : ""));

    /* ONE PICTURE OF THE CHARM GOES UP: the charm as it stands. Not the grey
       map, not the topology mask, not the style reference — every one of
       those is an instruction to build a charm from a specification, and
       sending them alongside "change the wings" is how a surgical request
       turns into a re-render. The picture being edited is the only authority
       here, AND THE GREYSCALE MAP IN PARTICULAR IS NEVER SENT.

       The only thing that may ever accompany it is the customer's own marks
       ON that same picture, which are not a second charm and not a
       specification — they are where the customer pointed. gold_edit_markup
       says so in the labels the model reads, and the block in the prompt
       says it again in words. */
    let outBuf = await callImageModelEdits({
      apiKey: apiKeyForImageModel(studioModelConfig),
      model: studioModelConfig.id,
      /* the gold edit moved to the pro model with the render — same ceiling */
      timeoutMs: STUDIO_RENDER_TIMEOUT_MS,
      prompt,
      size: editSize,
      imageSizeTier: editTier,
      quality: "high",
      output_format: "png",
      /* ── ONE IMAGE IN, ONE IMAGE OUT, ONE CALL ─────────────────────────
         There is no attempt loop here and there must never be one. A render
         may roll again because it is sampling for a specification and a
         second sample is a fair attempt at the same brief. An edit is not
         sampling: the customer is looking at a specific charm, and rolling
         again does not produce a better version of that charm — it produces
         a DIFFERENT one, with everything the second roll happened to change
         along the way. One call, whatever comes back, and Re-render is the
         way out if it comes back wrong. */
      images: editImages,
      /* null means "fall back to the `edit` labels", which crown a second
         image DESIGN TRUTH — exactly wrong for a sheet of arrows. With marks
         present the role set has to say what they are; without them the old
         behaviour is kept byte for byte. */
      imageRoles: markupMode ? "gold_edit_markup" : null,
      charmGeometryPolicy: null,
      backgroundPolicy: null,
    });

    await vRef.set({ renderStage: "polishing", renderRunId }, { merge: true });

    outBuf = embedPngTextMetadata(outBuf, {
      Description: `Custom Charm Studio charm — v${n} (${metal}), edited: ${instruction.slice(0, 120)}`,
      CharmTitle: `Custom charm v${n}`,
    });

    /* THE SAME PATH THE RENDER USES. The pair in the cart, the thumbnail in
       My designs and the version strip all point at v{n}-charm.png, so an
       edit that wrote somewhere else would leave every one of them showing
       the charm as it was before the customer changed it. A fresh download
       token is minted so caches cannot serve the old bytes. */
    const bucket = getBucket();
    const token = newDownloadToken();
    await bucket.file(goldPath).save(outBuf, {
      resumable: false,
      contentType: "image/png",
      metadata: { metadata: { firebaseStorageDownloadTokens: token, uid, sessionId,
                              version: String(n), render: "1", goldEdit: "1" } },
    });
    const renderURL = tokenDownloadURLFor(bucket.name, goldPath, token);

    await vRef.set({
      renderStatus: "done", renderStage: "done", renderRunId,
      renderURL, renderPath: goldPath, renderMetal: metal,
      renderModel: studioModelConfig.id, renderCost: cost,
      /* THE PAIR HAS DIVERGED, AND THE STAGE SAYS SO. The drawing and the
         greyscale map on this version still describe the charm as it was
         BEFORE this change — deliberately, because rebuilding them is the
         design step's job and not this one's. */
      goldEdited: true,
      goldEditCount: (Number(version.goldEditCount) || 0) + 1,
      /* what it was actually edited at, so a charm that has lost resolution
         over a chain of edits can be seen to have done so */
      goldEditTier: editTier,
      /* whether this change was pointed at as well as described — a charm
         that came back wrong is a different investigation depending */
      goldEditMarked: !!markupMode,
      captionStripped: version.captionStripped || stripCaption,
      goldEditedAt: admin.firestore.FieldValue.serverTimestamp(),
      renderedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });

    return studioJson(200, { ok: true, n, renderURL, renderPath: goldPath,
                             renderMetal: metal, renderModel: studioModelConfig.id,
                             renderCost: cost, renderRunId,
                             goldEdited: true }, origin);
  } catch (err) {
    /* A change that did not happen must never cost a credit. */
    await studioRefund(uid, cost, sessionId);
    await studioFailRender(vRef, String(err?.message || err), renderRunId);
    console.error("[studio] gold edit failed:", err?.message || err);
    return studioJson(500, { ok: false, error: "gold_edit_failed" }, origin);
  }
}

/* ═══════════ THE GREYSCALE MAP, DERIVED BACKWARDS FROM THE GOLD ══════════
   Every other version in this studio gets its greyscale map for free: the
   production drawing exists first, and studioMaterialSpec resolves it into
   the three tones deterministically. A charm chosen from the catalogue has
   no drawing. It is a photograph, and the map has to be recovered from it.

   HALF OF THAT IS FREE AND HALF OF IT IS NOT, and it is worth writing down
   which is which, because it decides the whole shape of this.

   Measured on a real charm photograph:
     · METAL vs GROUND separates at a Fisher ratio of 3.89, with 0.75% of
       pixels ambiguous. Gold is chromatic; the white ground and its grey
       contact shadow are not. The silhouette and every hole fall straight
       out of the saturation channel, exactly, for nothing.
     · ENGRAVED vs POLISHED does not separate at all. Luminance, local
       contrast, texture, high-pass and gradient were all tried; the best
       scored 0.037 where ~0.15 is the floor for two distinguishable
       clusters. Polished gold's specular variation is louder than the
       engraving is. No code gets this out of a photograph.

   So the engraving comes from a LINE DRAWING instead — the Charm Maker's
   gold-to-line-art conversion, whose prompt classifies every engraving
   before inking it and whose output is unambiguous: black is engraved
   metal, white is polished. That drawing has its own blind spot, and it is
   the mirror image of the photograph's: a hole and a polished area enclosed
   by an outlined engraving are BOTH white, and nothing in the drawing tells
   them apart.

   Neither source can produce this map alone. Together they are complete:

       photograph ──chroma──→ silhouette + every hole      (exact)
       drawing    ──ink─────→ engraved vs polished         (one model call)
       both       ──code────→ 255 / 176 / 136

   Validated against an authored ground truth at 99.42% pixel agreement,
   with holes kept open 99.82% of the time and the polished interior of an
   outlined engraving kept polished 97.87% of the time. That number measures
   the ARITHMETIC, not the model: given a correct drawing the map is
   correct, and a drawing that misses an engraving produces a map that
   misses it too.
   ═══════════════════════════════════════════════════════════════════════ */

/* The Charm Maker's own line-art style sample, in the same bucket. It is a
   STYLE reference only — the prompt below forbids its subject appearing —
   and the newest file in the folder wins, so replacing the sample is a
   drag-and-drop rather than a deploy. `listing-generator-1/Charm_Maker/` is
   already on storagePathToBuffer's allowlist. */
function asMsServer(v) {
  if (!v) return 0;
  if (typeof v === "number") return v;
  if (typeof v.toMillis === "function") { try { return v.toMillis(); } catch (e) { return 0; } }
  if (typeof v.seconds === "number") return v.seconds * 1000;
  if (typeof v.toDate === "function") { try { return v.toDate().getTime(); } catch (e) { return 0; } }
  return 0;
}

const STUDIO_LINEART_REF_PREFIX = "listing-generator-1/Charm_Maker/Reference_Line_Art_Image/";
let _lineArtRef = null, _lineArtRefAt = 0;

async function ensureStudioLineArtReference() {
  if (_lineArtRef && Date.now() - _lineArtRefAt < 600000) return _lineArtRef;
  try {
    const bucket = getBucket();
    const [files] = await bucket.getFiles({ prefix: STUDIO_LINEART_REF_PREFIX, maxResults: 50 });
    const usable = (files || []).filter((f) => /\.(png|jpe?g|webp)$/i.test(f.name || ""));
    if (!usable.length) {
      console.warn("[studio] no line-art style sample in " + STUDIO_LINEART_REF_PREFIX +
                   " — the drawing will be made from the written rules alone");
      _lineArtRef = null; _lineArtRefAt = Date.now();
      return null;
    }
    usable.sort((a, b) => {
      const ta = Date.parse(a.metadata?.updated || a.metadata?.timeCreated || 0) || 0;
      const tb = Date.parse(b.metadata?.updated || b.metadata?.timeCreated || 0) || 0;
      return tb - ta;
    });
    const pick = usable[0];
    const got = await storagePathToBuffer(pick.name);
    _lineArtRef = {
      buffer: Buffer.from(got.buffer || Buffer.alloc(0)),
      mime: String(got.mime || "image/png"),
      filename: pick.name.split("/").pop() || "line-art-style.png",
      storagePath: pick.name,
    };
    _lineArtRefAt = Date.now();
    console.log("[studio] line-art style sample: " + pick.name);
    return _lineArtRef;
  } catch (e) {
    console.error("[studio] line-art style sample unavailable:", e?.message || e);
    _lineArtRef = null; _lineArtRefAt = Date.now();
    return null;
  }
}

/* Ported verbatim in substance from the Charm Maker's promptStrBW, which is
   the version that has been producing these drawings reliably. The engraving
   fill rule is the whole value of it and is reproduced rule for rule: black
   maps 1:1 to engraved metal, an outlined engraving keeps a white interior,
   solid black is reserved for areas recessed all the way across, and holes
   stay white. Changing any of that changes what the map means. */
/* ── TRACE, NOT ILLUSTRATE ────────────────────────────────────────────────
   An armadillo charm — flat, geometric, a separate jump ring, a tail of
   discrete segments — came back as a cartoon armadillo: a smiling face the
   metal does not have, a thick sticker border round the whole piece, the
   tail restyled as a taper, the ring turned into an integrated loop. The
   drawing's silhouette scores IoU 0.376 against the photograph it was traced
   from; their bounding boxes do not even share an aspect ratio.

   The prompt this replaces was 4,139 characters and did not contain the
   sentence that would have stopped it. It said "100% STRUCTURAL MATCH" —
   which is about geometry — while the model's failure was one of SUBJECT: it
   recognised an armadillo and drew the armadillo it knows. Meanwhile the
   style-reference rule was stated four separate times (twice here, and twice
   more in the role labels the model receives as its own parts), and the
   engraving fill rule ran to five numbered cases and two hard fails for one
   idea. That is the shape of a prompt that has been added to after every bad
   result, and it is the same shape buildMaterialSpecToCharmPrompt was in
   before it was cut back — see the note there for why length works against
   this rather than for it.

   So: every rule once, positively, and the recognition failure named. The
   guarantee is not here — it is studioLineArtIoU, which measures whether the
   drawing lies over the photograph and spends a re-roll when it does not. */
const STUDIO_LINEART_PROMPT =
`Trace the charm in the FIRST image as flat black-and-white line art. This is a manufacturing drawing of one specific object that already exists — not an illustration of what that object depicts.

TRACE, DO NOT REDRAW. Keep the outline, the proportions and every internal line exactly as the photograph shows them, in the same place in the frame and at the same size, so the drawing can be laid straight over the photograph. If you recognise the subject, draw the piece you were given rather than the friendlier or more familiar version of that thing: add no face, expression, border, pattern, texture or detail the metal does not have, and simplify away none that it does. Draw the charm and nothing else — no caption, watermark, signature or listing text, and no mark where any of those were.

BLACK IS ENGRAVED METAL; EVERYTHING ELSE IS WHITE. An engraving that reads as a LINE in the photograph is drawn as a line, and whatever that line encloses stays white — polished metal is white, and a hole cut clean through the piece is white. Fill an area solid black only when its whole interior is visibly recessed in the photograph.

LINE WEIGHT: every stroke, the outer perimeter included, about 1/30th of the charm's own width — fine enough that two neighbouring lines stay separate.

HANGING HARDWARE: the photograph shows a separate JUMP RING threaded through the charm — an added ring that opens and closes. It is not part of the piece: leave it out completely, and close the drawing cleanly where it was. The charm's OWN hoop, cut from the same flat sheet and continuous with the body, IS part of the piece and is traced exactly as it appears.

Flat 2D only: no shading, no 3D, no grey, no colour. Solid pure white (#FFFFFF) background, no transparency.`;

/* ── the morphology the combine needs ─────────────────────────────────────
   Small, explicit and separable rather than a dependency: each is a couple
   of passes over a bit-per-pixel Uint8Array, which is faster than anything
   general-purpose would be at these sizes and leaves nothing to interpret. */
function mmErode(src, w, h, r) {
  if (!r) return src;
  const tmp = new Uint8Array(w * h), out = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    let keep = 1;
    for (let dx = -r; dx <= r && keep; dx++) {
      const nx = x + dx;
      if (nx < 0 || nx >= w || !src[y * w + nx]) keep = 0;
    }
    tmp[y * w + x] = keep;
  }
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    let keep = 1;
    for (let dy = -r; dy <= r && keep; dy++) {
      const ny = y + dy;
      if (ny < 0 || ny >= h || !tmp[ny * w + x]) keep = 0;
    }
    out[y * w + x] = keep;
  }
  return out;
}
function mmDilate(src, w, h, r) {
  if (!r) return src;
  const tmp = new Uint8Array(w * h), out = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    let hit = 0;
    for (let dx = -r; dx <= r && !hit; dx++) {
      const nx = x + dx;
      if (nx >= 0 && nx < w && src[y * w + nx]) hit = 1;
    }
    tmp[y * w + x] = hit;
  }
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    let hit = 0;
    for (let dy = -r; dy <= r && !hit; dy++) {
      const ny = y + dy;
      if (ny >= 0 && ny < h && tmp[ny * w + x]) hit = 1;
    }
    out[y * w + x] = hit;
  }
  return out;
}
const mmOpen  = (s, w, h, r) => mmDilate(mmErode(s, w, h, r), w, h, r);
const mmClose = (s, w, h, r) => mmErode(mmDilate(s, w, h, r), w, h, r);

/* Everything NOT reachable from the border is enclosed. Iterative scanline
   flood rather than a recursive one: a 2048² charm would blow the stack. */
function mmFillHoles(src, w, h) {
  const n = w * h;
  const outside = new Uint8Array(n);
  const stack = new Int32Array(n);
  let sp = 0;
  const push = (i) => { if (!src[i] && !outside[i]) { outside[i] = 1; stack[sp++] = i; } };
  for (let x = 0; x < w; x++) { push(x); push((h - 1) * w + x); }
  for (let y = 0; y < h; y++) { push(y * w); push(y * w + w - 1); }
  while (sp > 0) {
    const i = stack[--sp], x = i % w, y = (i - x) / w;
    if (x > 0) push(i - 1);
    if (x < w - 1) push(i + 1);
    if (y > 0) push(i - w);
    if (y < h - 1) push(i + w);
  }
  const filled = new Uint8Array(n);
  for (let i = 0; i < n; i++) filled[i] = src[i] || !outside[i] ? 1 : 0;
  return { filled, outside };
}
function mmBBox(src, w, h) {
  let x0 = w, y0 = h, x1 = -1, y1 = -1;
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) if (src[y * w + x]) {
    if (x < x0) x0 = x; if (x > x1) x1 = x;
    if (y < y0) y0 = y; if (y > y1) y1 = y;
  }
  return x1 < 0 ? null : { x0, y0, x1, y1, w: x1 - x0 + 1, h: y1 - y0 + 1 };
}

const STUDIO_SPEC_SAT_MIN = 0.16;     /* metal is chromatic; ground and shadow are not */
const STUDIO_SPEC_INK_MAX = 128;      /* the drawing is pure black on pure white */
const STUDIO_SPEC_EDGE_R = 4;         /* the perimeter stroke is not an engraving */
const STUDIO_SPEC_MIN_IOU = 0.86;
/* the shoulder: the first row down at which the piece reaches this share of
   its own widest. Everything above it is hanging hardware — see the note in
   studioLineArtIoU for why neither side may be scored on it. */
const STUDIO_SPEC_SHOULDER = 0.35;     /* below this the drawing does not describe this charm */

/**
 * gold photograph + line drawing → the three-tone map.
 * Pure arithmetic. No model, no network, same inputs → same bytes.
 */
/* ── DOES THIS DRAWING DESCRIBE THIS CHARM? ───────────────────────────────
   The reference-line-art step had a retry loop whose only rejection was an
   empty buffer, so "the model returned SOMETHING" was the whole test. An
   armadillo charm came back as a different armadillo — cartoon proportions
   instead of the piece's flat geometry, a smiling face the metal does not
   have, a striped tail where the charm has separate segments, a thick
   sticker border round the whole thing, and the hoop moved from a separate
   jump ring to an integrated loop. Measured against the photograph it was
   drawn from, its silhouette scores IoU 0.376. Their bounding boxes do not
   even share an aspect ratio — 1.353 against 1.482.

   The map-from-gold step next door has scored exactly this since it was
   written, and refuses at 0.86. There was never a reason for the two to
   differ: both ask a model to trace one photograph, and one number answers
   "did it". So the measurement moves out here where both can call it.

   It is the same arithmetic studioSpecFromGold performs on its way to the
   three-tone map — chroma for the metal, a threshold for the ink, both
   silhouettes filled, the drawing scaled and shifted onto the photograph's
   bounding box, then intersection over union. No model, no network, same
   inputs → same number.                                                    */
async function studioLineArtIoU(sharp, goldBuf, lineBuf, size) {
  const S = Math.max(256, Math.min(2048, Number(size) || 768));
  const n = S * S;
  const read = async (buf, grey) => {
    let q = sharp(buf).resize(S, S, { fit: "fill" }).flatten({ background: "#ffffff" });
    if (grey) q = q.greyscale();
    return q.removeAlpha().raw().toBuffer({ resolveWithObject: true });
  };
  const g = await read(goldBuf, false);
  const gd = g.data, gch = g.info.channels;
  let metal = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    const p = i * gch, r = gd[p], gg = gd[p + 1], b = gd[p + 2];
    const mx = Math.max(r, gg, b), mn = Math.min(r, gg, b);
    metal[i] = mx > 0 && (mx - mn) / mx > STUDIO_SPEC_SAT_MIN ? 1 : 0;
  }
  metal = mmClose(mmOpen(metal, S, S, 1), S, S, 1);
  const body = mmFillHoles(metal, S, S).filled;
  let facePx = 0;
  for (let i = 0; i < n; i++) if (metal[i]) facePx++;
  if (facePx < n * 0.01) return { iou: 0, aligned: false, why: "no_charm_in_photo" };

  const l = await read(lineBuf, true);
  const ld = l.data, lch = l.info.channels;
  let ink = new Uint8Array(n);
  for (let i = 0; i < n; i++) ink[i] = ld[i * lch] < STUDIO_SPEC_INK_MAX ? 1 : 0;
  const inkBody = mmFillHoles(mmClose(ink, S, S, 1), S, S).filled;

  /* ── NEITHER SIDE IS SCORED ON ITS HANGING HARDWARE ───────────────────
     The drawing is asked to leave the catalogue jump ring out, and a
     bounding-box registration punishes it savagely for obeying: losing the
     ring costs only 2.8% of the charm's area, but it shortens the box, so
     the whole drawing is stretched ~11% taller to fit and every feature
     slides out of place. Measured on the armadillo, dropping the ring took
     a perfect tracing from 1.000 to 0.853 — under the line. The gate would
     have rejected every drawing that did what the prompt asks.

     The body has a landmark the hardware cannot move: the highest row at
     which the silhouette is a real share of its own widest. Above it is
     hoop and ring; below it is the charm. Both sides are cut there, then
     registered and scored, so hardware differences leave the measurement
     entirely — and what remains is the question actually being asked, which
     is whether this is the same object.

     Measured: a correct tracing 0.93 with the ring and 0.93 without it; the
     cartoon redraw 0.50. The line at 0.86 sits clear of both. */
  const shoulder = (mask) => {
    const bb0 = mmBBox(mask, S, S);
    if (!bb0) return null;
    let widest = 0;
    const rowW = new Int32Array(S);
    for (let y = bb0.y0; y <= bb0.y1; y++) {
      let lo = -1, hi = -1;
      for (let x = bb0.x0; x <= bb0.x1; x++) if (mask[y * S + x]) { if (lo < 0) lo = x; hi = x; }
      rowW[y] = hi < 0 ? 0 : hi - lo + 1;
      if (rowW[y] > widest) widest = rowW[y];
    }
    for (let y = bb0.y0; y <= bb0.y1; y++) {
      if (rowW[y] >= widest * STUDIO_SPEC_SHOULDER) return y;
    }
    return bb0.y0;
  };
  const trim = (mask, y0) => {
    const o = new Uint8Array(n);
    for (let y = y0; y < S; y++) for (let x = 0; x < S; x++) o[y * S + x] = mask[y * S + x];
    return o;
  };
  const sg = shoulder(body), sl = shoulder(inkBody);
  if (sg == null || sl == null) return { iou: 0, aligned: false, why: "no_silhouette" };
  const gTrim = trim(body, sg), lTrim = trim(inkBody, sl);

  const ba = mmBBox(gTrim, S, S), bb = mmBBox(lTrim, S, S);
  if (!ba || !bb) return { iou: 0, aligned: false, why: "no_silhouette" };
  const sx = bb.w / ba.w, sy = bb.h / ba.h;
  let inter = 0, uni = 0;
  for (let y = 0; y < S; y++) {
    const syy = Math.round(bb.y0 + (y - ba.y0) * sy);
    for (let x = 0; x < S; x++) {
      const a = gTrim[y * S + x];
      const sxx = Math.round(bb.x0 + (x - ba.x0) * sx);
      const b2 = (sxx >= 0 && sxx < S && syy >= 0 && syy < S && lTrim[syy * S + sxx]) ? 1 : 0;
      if (a && b2) inter++;
      if (a || b2) uni++;
    }
  }
  const iou = uni ? inter / uni : 0;
  return { iou, aligned: iou >= STUDIO_SPEC_MIN_IOU, why: "" };
}

async function studioSpecFromGold(sharp, goldBuf, lineBuf, size) {
  const S = Math.max(512, Math.min(4096, Number(size) || 2048));
  const HOLE = 255, POLISH = STUDIO_MASK_POLISHED[0], ENGRAVE = STUDIO_MASK_ENGRAVED[0];
  const n = S * S;

  /* ── the photograph: what is metal, and what is a hole ────────────────── */
  const g = await sharp(goldBuf).resize(S, S, { fit: "fill" })
    .flatten({ background: "#ffffff" }).removeAlpha().raw()
    .toBuffer({ resolveWithObject: true });
  const gd = g.data, gch = g.info.channels;
  let metal = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    const p = i * gch, r = gd[p], gg = gd[p + 1], b = gd[p + 2];
    const mx = Math.max(r, gg, b), mn = Math.min(r, gg, b);
    metal[i] = mx > 0 && (mx - mn) / mx > STUDIO_SPEC_SAT_MIN ? 1 : 0;
  }
  metal = mmClose(mmOpen(metal, S, S, 1), S, S, 1);
  const { filled: body } = mmFillHoles(metal, S, S);
  let facePx = 0, holePx = 0;
  for (let i = 0; i < n; i++) { if (metal[i]) facePx++; else if (body[i]) holePx++; }
  if (facePx < n * 0.01) throw new Error("no_charm_found");

  /* ── the drawing: what is ink ─────────────────────────────────────────── */
  const l = await sharp(lineBuf).resize(S, S, { fit: "fill" })
    .flatten({ background: "#ffffff" }).greyscale().removeAlpha().raw()
    .toBuffer({ resolveWithObject: true });
  const ld = l.data, lch = l.info.channels;
  let ink = new Uint8Array(n);
  for (let i = 0; i < n; i++) ink[i] = ld[i * lch] < STUDIO_SPEC_INK_MAX ? 1 : 0;

  /* ── put the drawing over the photograph ──────────────────────────────
     The prompt asks for the object in the same place at the same size, and
     mostly gets it, but "mostly" is not registration. Both silhouettes are
     known, so the drawing is scaled and shifted onto the photograph's
     bounding box before a single pixel is read from it — and if the two
     still do not agree afterwards, the drawing is not of this charm and
     nothing is derived from it. */
  const inkBody = mmFillHoles(mmClose(ink, S, S, 1), S, S).filled;
  const ba = mmBBox(body, S, S), bb = mmBBox(inkBody, S, S);
  if (!ba || !bb) throw new Error("no_charm_found");
  if (bb.w !== ba.w || bb.h !== ba.h || bb.x0 !== ba.x0 || bb.y0 !== ba.y0) {
    const sx = bb.w / ba.w, sy = bb.h / ba.h;
    const moved = new Uint8Array(n);
    for (let y = 0; y < S; y++) {
      const syy = Math.round(bb.y0 + (y - ba.y0) * sy);
      if (syy < 0 || syy >= S) continue;
      for (let x = 0; x < S; x++) {
        const sxx = Math.round(bb.x0 + (x - ba.x0) * sx);
        if (sxx < 0 || sxx >= S) continue;
        moved[y * S + x] = ink[syy * S + sxx];
      }
    }
    ink = moved;
  }
  const alignedBody = mmFillHoles(mmClose(ink, S, S, 1), S, S).filled;
  let inter = 0, uni = 0;
  for (let i = 0; i < n; i++) {
    const a = body[i], b2 = alignedBody[i];
    if (a && b2) inter++;
    if (a || b2) uni++;
  }
  const iou = uni ? inter / uni : 0;

  /* ── the combine ──────────────────────────────────────────────────────
     The perimeter stroke and every hole outline are ink, and neither is an
     engraving — inked straight in, the charm grows a black rim around
     itself and around each of its openings. So ink is only read well inside
     the metal, and the stroke width the erosion cost is given back after. */
  const inner = mmErode(metal, S, S, STUDIO_SPEC_EDGE_R);
  let engraved = new Uint8Array(n);
  for (let i = 0; i < n; i++) engraved[i] = metal[i] && ink[i] && inner[i] ? 1 : 0;
  engraved = mmOpen(engraved, S, S, 1);
  engraved = mmDilate(engraved, S, S, 1);
  let workPx = 0;
  const out = Buffer.alloc(n * 3, HOLE);
  for (let i = 0; i < n; i++) {
    if (!metal[i]) continue;                      /* ground and holes: 255 */
    const v = engraved[i] && metal[i] ? ENGRAVE : POLISH;
    if (v === ENGRAVE) workPx++;
    out[i * 3] = out[i * 3 + 1] = out[i * 3 + 2] = v;
  }
  const buf = await sharp(out, { raw: { width: S, height: S, channels: 3 } }).png().toBuffer();
  return { buf, w: S, h: S, iou, facePx, holePx, workPx,
           aligned: iou >= STUDIO_SPEC_MIN_IOU };
}


/* ── the job itself ───────────────────────────────────────────────────────
   Fired when a design is APPROVED, not when it is made. A customer choosing
   a catalogue charm and then changing the gold five times would otherwise
   pay for five drawings and five maps, four of which describe charms nobody
   is going to make. Only the approved one gets a map.

   IT IS NOT ON ANYBODY'S CRITICAL PATH. The browser fires it and walks to
   checkout; the map lands on the version document whenever it lands. So the
   one thing that must never happen is a silent failure — an order exists,
   and the thing production needs does not. specStatus says which of those
   is true at any moment, and nothing ever leaves it unset:

     "pending"  the job is running (or has just been queued)
     "done"     the map is on the doc and its URL is beside it
     "failed"   every attempt was used; specError says what went wrong and
                specAttempts says how many times it was tried

   NO CREDIT. The customer paid for the gold; this is the workshop's own
   record of what they bought. */
const STUDIO_SPEC_MAX_ATTEMPTS = 3;
const STUDIO_SPEC_STALE_MS = 5 * 60 * 1000;

async function studioSpecFail(vRef, why, attempts) {
  try {
    await vRef.set({
      specStatus: "failed",
      specError: String(why).slice(0, 300),
      specAttempts: attempts,
      specFailedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });
  } catch (e) {
    console.error("[studio] could not record spec failure:", e?.message || e);
  }
}

/* ═══════════ THE REFERENCE, AS A DRAWING ═════════════════════════════════
   A charm chosen from our own catalogue arrives as a PHOTOGRAPH: gold, lit,
   shadowed, and carrying "Charm Only" in script above it. A photograph is a
   fine thing to look at and a poor thing to edit — there is nothing in it to
   take hold of, and every tool on the mark-up rail is built for line work.

   So the moment the customer commits to a reference by pressing Next, this
   turns that photograph into the black line drawing of the same charm, and
   THAT becomes the reference from then on. The customer gets a drawing they
   can actually work on; the workshop gets geometry rather than a picture.

   IT REUSES THE PIPELINE THAT ALREADY WORKS. This is the same model call,
   the same prompt and the same style sample that handleStudioSpecFromGold
   uses to derive a greyscale map at approval — the one the customer told us
   works flawlessly. The only differences are what it is pointed at (a
   catalogue URL rather than a filed render) and where the answer is written
   (the session, because there is no version yet).

   ONCE PER REFERENCE DESIGN. The result is keyed on the product, so choosing
   the same charm again — or pressing Next twice — costs nothing. A drawing
   already made is simply returned.                                          */
const STUDIO_REF_CAPTION_CLAUSE =
`THE CAPTION IS NOT PART OF THE CHARM. This photograph is a catalogue listing
image and carries handwritten text reading "Charm Only" above the piece. It is
a caption on a web page. Do not draw it, do not outline it, do not ink it as
an engraving, and do not leave any mark where it was — that area is plain
white paper. Draw the charm and nothing else.`;

/* ── A LISTING PHOTOGRAPH IS SHOT WITH ROOM AROUND THE PIECE ───────────────
   and every pixel of that room is a pixel the model does not spend on the
   charm. The margin is measured on a small copy — a 4096-pixel photograph
   does not have to be read at full size to find where the white stops — and
   then cut from the original, leaving a thin border so the outer perimeter
   is never flush against the frame.

   Everything here fails soft and hands the photograph back untouched. A
   tighter frame is an improvement, never a requirement, and a charm that is
   genuinely pale must not be cropped down to nothing on the strength of a
   threshold. */
async function studioTrimToSubject(sharpMod, buf, marginPct) {
  try {
    const meta = await sharpMod(buf).metadata();
    const W = meta.width || 0, H = meta.height || 0;
    if (!W || !H) return buf;
    const P = 512;
    const sc = Math.min(P / W, P / H, 1);
    const w2 = Math.max(1, Math.round(W * sc)), h2 = Math.max(1, Math.round(H * sc));
    const { data } = await sharpMod(buf)
      .flatten({ background: "#ffffff" })
      .resize(w2, h2, { fit: "fill" })
      .greyscale().raw().toBuffer({ resolveWithObject: true });
    let x0 = w2, y0 = h2, x1 = -1, y1 = -1;
    for (let y = 0; y < h2; y++) {
      const row = y * w2;
      for (let x = 0; x < w2; x++) {
        if (data[row + x] < 244) {
          if (x < x0) x0 = x;
          if (x > x1) x1 = x;
          if (y < y0) y0 = y;
          if (y > y1) y1 = y;
        }
      }
    }
    if (x1 < x0 || y1 < y0) return buf;                 /* an entirely blank sheet */
    const cw = (x1 - x0 + 1) / w2, chh = (y1 - y0 + 1) / h2;
    if (cw > 0.97 && chh > 0.97) return buf;            /* already tight */
    if (cw < 0.02 || chh < 0.02) return buf;            /* a speck, not a charm */
    const m = marginPct == null ? 0.03 : Number(marginPct);
    const px = Math.round(W * m), py = Math.round(H * m);
    const left = Math.max(0, Math.round((x0 / w2) * W) - px);
    const top = Math.max(0, Math.round((y0 / h2) * H) - py);
    const right = Math.min(W, Math.round(((x1 + 1) / w2) * W) + px);
    const bottom = Math.min(H, Math.round(((y1 + 1) / h2) * H) + py);
    const width = right - left, height = bottom - top;
    if (width < 8 || height < 8) return buf;
    return await sharpMod(buf).extract({ left, top, width, height }).png().toBuffer();
  } catch (e) {
    return buf;
  }
}

/* the drawing pipeline's own version — see the cache gate below. 1 was the
   raw model output; 2 added orientation matching and the first thinning;
   3 is the greyscale-erosion thinning, the canvas-relative floor and the
   tier check. */
/* 4: the prompt was rewritten and a silhouette gate added, so every drawing
   cached under 3 was made by a version that could not tell a tracing from an
   illustration. They are re-made on next sight rather than trusted. */
const STUDIO_LINEART_REV = 5;

async function handleStudioRefLineArt({ body, event, origin }) {
  const uid = await requireStudioUser(event);
  const cfg = await studioConfig();
  const db = getDb();

  const sessionId = String(body?.sessionId || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 60);
  if (!sessionId) return studioJson(400, { ok: false, error: "missing_session" }, origin);
  const sRef = db.collection(STUDIO_SESSIONS_COLL).doc(sessionId);
  let sSnap = await sRef.get();
  /* ── A BRAND-NEW PROJECT'S DOCUMENT MAY NOT EXIST YET ────────────────
     The browser writes the session and queues this in the same breath, and
     this runs in the background — refusing on !exists turned a race nobody
     could see into a 403 nobody could see, and the customer's drawing
     simply never happened. An absent document is CREATED here, stamped
     with the caller's own uid; a document that exists and belongs to
     someone else is refused exactly as before. Session ids are random
     client-generated strings, so first-writer-wins is the same trust model
     the browser's own create already has. */
  if (!sSnap.exists) {
    await sRef.set({ uid, id: sessionId, createdAt: Date.now(), updatedAt: Date.now() },
                   { merge: true });
    sSnap = await sRef.get();
  }
  if (!sSnap.exists || sSnap.data().uid !== uid) {
    return studioJson(403, { ok: false, error: "forbidden" }, origin);
  }
  const session = sSnap.data();

  const gid = String(body?.productGid || body?.imageUrl || "").slice(0, 200);
  const title = studioCleanText(body?.title || "").slice(0, 140);

  /* ONCE — per charm AND per pipeline. The cache used to check only the
     charm, which made it a trap that fired exactly when the pipeline
     improved: a drawing made before a deploy was handed straight back after
     it, on every visit, for ever. The orientation fix, the weight fix and
     the anti-aliasing all shipped and the customer kept receiving the
     drawing from before any of them — "the fix did not get applied", when
     the fix was deployed and running and never given the chance. So the
     drawing now remembers which pipeline made it, and a drawing made by an
     older one is simply stale: the next request redraws it. Bump the rev
     whenever the drawing pipeline changes what it produces. */
  if (!body?.force && session.refLineArtStatus === "done" &&
      session.refLineArtURL && String(session.refLineArtGid || "") === gid &&
      Number(session.refLineArtRev || 0) === STUDIO_LINEART_REV) {
    return studioJson(200, { ok: true, cached: true, url: session.refLineArtURL,
                             path: session.refLineArtPath || "" }, origin);
  }
  /* and a run already in flight is left to finish rather than raced */
  const started = asMsServer(session.refLineArtStartedAt);
  if (!body?.force && session.refLineArtStatus === "pending" &&
      started && Date.now() - started < STUDIO_SPEC_STALE_MS) {
    return studioJson(200, { ok: true, pending: true }, origin);
  }

  await sRef.set({
    refLineArtStatus: "pending", refLineArtGid: gid, refLineArtTitle: title,
    refLineArtError: null,
    refLineArtStartedAt: admin.firestore.FieldValue.serverTimestamp(),
    updatedAt: Date.now(),
  }, { merge: true });

  const fail = async (why) => {
    console.error("[studio] ref line art:", why);
    await sRef.set({ refLineArtStatus: "failed", refLineArtError: String(why).slice(0, 200),
                     updatedAt: Date.now() }, { merge: true });
    return studioJson(500, { ok: false, error: String(why) }, origin);
  };

  let src;
  try { src = await studioFetchCatalogImage(body?.imageUrl); }
  catch (err) { return fail(err?.message || "bad_image_url"); }

  let studioModelConfig;
  try {
    studioModelConfig = resolveImageModel(studioImageModelId(cfg, "lineart"));
    apiKeyForImageModel(studioModelConfig);
  } catch (err) { return fail("render_unavailable"); }

  /* ── THIS DRAWING IS THE INPUT SIDE, NOT THE OUTPUT SIDE ─────────────────
     It borrowed studioRenderTier, which is 1K, and the config block that
     defines these two tiers says in as many words why that is the wrong one:
     the RENDER tier is the finished metal the customer looks at, where
     "nothing downstream measures it, so the extra tier buys presentation
     only". This drawing is measured by everything. It becomes the reference,
     it is what the mark-up sheet opens on, and it is taken apart stroke by
     stroke into editable layers — every pixel of it is read twice.

     The borrowed tier cost real fidelity, and the arithmetic is not close. A
     charm is a tall narrow object photographed on white: the baseball bat
     measures 111 x 546 in its listing image, so letterboxed into a 1024
     square it is 194 pixels wide and holds 18% of the frame. Each stitch on
     it is then about five pixels across — under what a vision encoder can
     resolve — so the model stopped replicating the stitching that is there
     and started drawing a generic one from memory, and lost the engraved
     shield altogether. At 2K the same charm is 388 pixels wide and a stitch
     is eleven. That is also simply what the Charm Maker has always run at:
     callGeminiGenerateContentImage gives every caller 2K and only the studio
     ever asked it for less. */
  const tier = studioDrawingTier(cfg);

  /* normalised the same way an adopted charm is, so the drawing is made from
     the same bytes the customer is looking at — but framed on the charm
     first, because the listing's white margin is model attention spent on
     nothing */
  let goldBuf = src.buffer;
  try {
    const sharpMod = studioSharp();
    if (sharpMod) {
      const S = studioTierPx(tier);
      const framed = await studioTrimToSubject(sharpMod, src.buffer, 0.03);
      goldBuf = await sharpMod(framed).flatten({ background: "#ffffff" })
        .resize(S, S, { fit: "contain", background: "#ffffff" }).png().toBuffer();
    }
  } catch (e) { /* the raw bytes will do */ }

  const styleRef = await ensureStudioLineArtReference();
  const images = [{ buffer: goldBuf, mime: "image/png", filename: "reference-charm.png" }];
  if (styleRef && styleRef.buffer && styleRef.buffer.length) {
    images.push({ buffer: styleRef.buffer, mime: styleRef.mime, filename: styleRef.filename });
  }
  /* STUDIO_REF_CAPTION_CLAUSE is no longer appended: it was 389 characters
     describing one particular catalogue caption ("Charm Only"), and the
     prompt's own "no caption, watermark, signature or listing text, and no
     mark where any of those were" covers it and every other one. The
     constant is kept for the moment in case a specific listing needs naming
     again. */
  const prompt = STUDIO_LINEART_PROMPT;

  let lineBuf = null, lastErr = null;
  /* the fit score of the drawing that ships, and the best near-miss to fall
     back on when no attempt clears the line */
  let lineIoU = null, bestIoU = -1, bestBuf = null, attemptsMade = 0;
  for (let attempt = 1; attempt <= STUDIO_SPEC_MAX_ATTEMPTS; attempt++) {
    attemptsMade = attempt;
    try {
      lineBuf = await callImageModelEdits({
        apiKey: apiKeyForImageModel(studioModelConfig),
        model: studioModelConfig.id,
        prompt,
        size: studioImageSizeString(tier),
        imageSizeTier: tier,
        quality: "high",
        output_format: "png",
        images,
        imageRoles: "line_art_style",
        charmGeometryPolicy: null,
        backgroundPolicy: null,
      });
      if (!lineBuf || !lineBuf.length) { lastErr = new Error("empty_drawing"); continue; }
      /* ── AND IS IT THIS CHARM? ────────────────────────────────────────
         "The model returned something" was the entire test on this path.
         It is the same question the map-from-gold step has scored since it
         was written, so it gets the same answer and the same threshold. A
         drawing that does not lie over the photograph is not a drawing of
         this charm, and every deterministic step below it — the orientation
         match, the stroke thinning — would then be polishing the wrong
         object very carefully.

         Never allowed to fail the STEP, only an attempt: if the last try
         still misses, the closest one ships. A customer looking at an
         imperfect tracing is in a better position than one looking at an
         error, and they can redraw it themselves. */
      let fitOk = true;
      try {
        const sharpFit = studioSharp();
        if (sharpFit) {
          const m = await studioLineArtIoU(sharpFit, goldBuf, lineBuf, 768);
          lineIoU = m.iou;
          fitOk = m.aligned;
          if (!fitOk) {
            console.warn(`[studio] ref line art attempt ${attempt}: not this charm ` +
                         `(IoU ${m.iou.toFixed(3)} < ${STUDIO_SPEC_MIN_IOU}${m.why ? " " + m.why : ""})`);
            if (m.iou > bestIoU) { bestIoU = m.iou; bestBuf = lineBuf; }
            lastErr = new Error("unaligned_drawing_iou_" + m.iou.toFixed(3));
            lineBuf = null;
            continue;
          }
          console.log(`[studio] ref line art attempt ${attempt}: traced this charm (IoU ${m.iou.toFixed(3)})`);
        }
      } catch (e) {
        /* a gate that cannot answer raises no objection */
        console.error("[studio] ref line art fit check skipped:", e?.message || e);
      }
      if (lineBuf && lineBuf.length) break;
    } catch (err) {
      lastErr = err;
      console.warn(`[studio] ref line art attempt ${attempt}:`, err?.message || err);
    }
  }
  /* every attempt missed: the closest tracing ships rather than an error */
  if ((!lineBuf || !lineBuf.length) && bestBuf) {
    console.warn(`[studio] ref line art: no attempt matched — shipping the closest ` +
                 `(IoU ${bestIoU.toFixed(3)})`);
    lineBuf = bestBuf;
    lineIoU = bestIoU;
  }
  if (!lineBuf || !lineBuf.length) return fail(lastErr?.message || "lineart_failed");

  /* THE MODEL'S FRAMING IS NOT THE LAST WORD. See studioMatchOrientation:
     the prompt asks for the charm to stay where it was and the model turns
     it anyway, so the turn is measured against the photograph it was drawn
     from and undone. Never allowed to fail the step. */
  let orient = null, thin = null, gotPx = null;
  try {
    const sharpMod = studioSharp();
    if (sharpMod) {
      const fixed = await studioMatchOrientation(sharpMod, lineBuf, goldBuf);
      orient = fixed.report;
      if (fixed.buf && fixed.buf.length) lineBuf = fixed.buf;
      /* AFTER the turn, never before: the stroke weight is measured against
         the charm's own short side, and that is a different number before
         the drawing has been squared up */
      /* ── AND IT MUST BE BIG ENOUGH TO HOLD THE DETAIL ────────────────
         2K is ASKED FOR — studioDrawingTier, and the block above says why —
         but asking is not the same as receiving, and an image model is free
         to hand back a smaller frame than the one it was told to draw. The
         drawing that came with the report measured 103 px across the charm,
         which is a 1K frame, not the 2K one that was requested. Nothing
         downstream noticed, because nothing downstream was looking.

         So the frame is checked and brought up to the tier before anything
         measures or cuts it. That does not create detail the model did not
         draw — nothing can — but it does three real things: it stops the
         reference being the narrowest point in a pipeline that reads it
         twice, it gives the cut below a finer grid to place an edge on, and
         it puts the number on the record so "the model shortchanged us" and
         "we asked for too little" stop looking the same. */
      try {
        const meta = await sharpMod(lineBuf).metadata();
        const want = studioTierPx(tier);
        if (meta && meta.width && meta.width < want) {
          lineBuf = await sharpMod(lineBuf)
            .resize(want, want, { fit: "contain", background: "#ffffff",
                                  kernel: "lanczos3" })
            .png({ compressionLevel: 9 }).toBuffer();
          gotPx = { from: meta.width, to: want };
        } else if (meta && meta.width) {
          gotPx = { from: meta.width, to: meta.width };
        }
      } catch (e) { /* the frame it came in is the frame it keeps */ }
      const fine = await studioThinLineArt(sharpMod, lineBuf, cfg);
      thin = fine.report;
      if (fine.buf && fine.buf.length) lineBuf = fine.buf;
    } else {
      /* SAY SO. Without sharp there is no correction at all, and the only
         symptom is a drawing that arrives lying on its side — which looks
         exactly like the correction being wrong rather than absent. One
         field on the session tells the two apart without a bisect. */
      orient = { applied: false, deg: 0, why: "no_sharp" };
      thin = { applied: false, why: "no_sharp" };
      console.warn("[studio] sharp unavailable — line art cannot be squared to its reference");
    }
  } catch (e) {
    orient = { applied: false, deg: 0, why: "error" };
    console.error("[studio] orientation match skipped:", e?.message || e);
  }

  let outBuf = lineBuf;
  try {
    outBuf = embedPngTextMetadata(lineBuf, {
      Description: `Custom Charm Studio — production drawing of ${title || "a catalogue charm"}.`,
      CharmTitle: title || "Reference drawing",
    });
  } catch (e) { /* metadata is a nicety */ }

  try {
    const bucket = getBucket();
    const path = `custom-studio/${uid}/uploads/refs/${sessionId}/reference-lineart.png`;
    const token = newDownloadToken();
    await bucket.file(path).save(outBuf, {
      resumable: false, contentType: "image/png",
      metadata: { metadata: { firebaseStorageDownloadTokens: token, uid, sessionId,
                              refLineArt: "1" } },
    });
    const url = tokenDownloadURLFor(bucket.name, path, token);
    await sRef.set({
      refLineArtStatus: "done", refLineArtURL: url, refLineArtPath: path,
      refLineArtGid: gid, refLineArtTitle: title, refLineArtError: null,
      refLineArtTurnedDeg: orient && orient.applied ? orient.deg : 0,
      refLineArtOrientWhy: (orient && orient.why) || "",
      refLineArtStrokeFrom: (thin && thin.from) || 0,
      refLineArtStrokeTo: (thin && thin.to) || 0,
      refLineArtStrokeWhy: (thin && thin.why) || "",
      refLineArtPxFrom: (gotPx && gotPx.from) || 0,
      refLineArtPx: (gotPx && gotPx.to) || 0,
      /* how closely the drawing lies over the photograph it was traced from,
         and whether it cleared the line. A drawing that ships below the line
         is the run worth being able to find afterwards, and it is invisible
         from the picture alone. */
      refLineArtIoU: lineIoU == null ? null : Math.round(lineIoU * 1000) / 1000,
      refLineArtAligned: lineIoU == null ? null : lineIoU >= STUDIO_SPEC_MIN_IOU,
      refLineArtAttempts: attemptsMade,
      refLineArtRev: STUDIO_LINEART_REV,
      refLineArtAt: admin.firestore.FieldValue.serverTimestamp(),
      updatedAt: Date.now(),
    }, { merge: true });
    console.log(`[studio] ref line art ready for ${title || gid} → ${path}`);
    return studioJson(200, { ok: true, url, path }, origin);
  } catch (err) { return fail(err?.message || "save_failed"); }
}

/* ═══════════ AND IT MUST COME BACK FINE ENOUGH TO READ ══════════════════
   Measured on a real drawing the studio produced: the charm was 103 px wide
   and every black line was 11 px across — the bat was NINE STROKES WIDE. At
   that weight the stitching, the seam and the engraved shield are finer than
   the pen drawing them, so they merge into their neighbours or disappear.
   "The lines are too thick and we are losing fine details" is one fault.

   The prompt asked for "2px thick", which is the wrong unit twice over: an
   absolute pixel count on a canvas whose size is a config value, describing
   a charm that occupies a fifth of it. It now asks for a weight relative to
   the CHARM. But an instruction the model may decline to follow is not a
   mechanism — see studioMatchOrientation for the same lesson — so the weight
   is also brought down here, in arithmetic.

   THINNING A DRAWING IS HOW YOU DESTROY A DRAWING, so this cannot be a plain
   erosion: eroding four pixels from every side removes every stroke thinner
   than eight, which is precisely the detail being rescued. Two things make
   it safe:

     · the target is set from the MEDIAN stroke width, which a solid engraved
       region cannot drag upwards the way a mean would, so the estimate
       describes the linework rather than the blobs
     · the skeleton is unioned back in, so every stroke keeps its spine. A
       thick line loses its shoulders; a line already at the target keeps
       every pixel it had; nothing can be erased, and the topology of the
       drawing is the topology it arrived with.

   A happy side effect: two lines the model had merged are pushed apart, so
   detail can come BACK rather than merely survive. */

/* ── HOW FAR IS THIS PIXEL FROM WHITE ────────────────────────────────────
   Felzenszwalb & Huttenlocher: the EXACT Euclidean distance transform, in
   two linear passes over the parabolic lower envelope. It replaces a chamfer
   approximation, and the reason is not accuracy for its own sake — this
   field is what an EDGE IS PLACED ON below. A chamfer field's level set is
   faintly octagonal and quantised to steps of 0.41, so an edge drawn on it
   inherits both: a curve comes back with flats on it and stairs along it,
   which is precisely the "much more aliasing than before" in the report.
   The exact field is isotropic and continuous, so the same edge is smooth.

   AND IT WAS ALREADY IN THIS FILE. studioEdt2d has been here all along,
   serving the pixel plan. Writing a second copy of it — which is what the
   first attempt at this did — did not merely duplicate code: two top-level
   `function studioEdt1d` declarations in one module mean the LAST one wins
   for every caller, so a private helper with a different signature silently
   replaced the one studioEdt2d calls, and every mask measurement in the
   pixel plan would have thrown on a buffer nobody passed it. `node --check`
   is perfectly happy with that, which is why verify-guards.sh now refuses a
   duplicate top-level name in either source file.

   The half-pixel matters too. The transform measures centre to centre, so a
   pixel touching white reads 1 while the boundary it is touching is half a
   pixel away. Everything downstream — the width estimate, the cut, the
   anti-aliased ramp — works in distance-to-the-EDGE, so the half is taken
   off here, once, rather than being forgotten in three places. */
function studioInkDistance(ink, w, h) {
  const dist = studioEdt2d(ink, w, h);
  for (let i = 0; i < dist.length; i++) {
    dist[i] = ink[i] ? Math.max(0, dist[i] - 0.5) : 0;
  }
  return dist;
}

/* the ridge: ink no lower than any of its eight neighbours. Not a true
   one-pixel skeleton and it does not need to be — it only has to be a
   connected subset that survives the erosion, which is what stops a stroke
   being rubbed out entirely. */
function studioInkRidge(d, ink, w, h) {
  const keep = new Uint8Array(w * h);
  for (let y = 1; y < h - 1; y++) {
    for (let x = 1; x < w - 1; x++) {
      const i = y * w + x;
      if (!ink[i]) continue;
      const v = d[i];
      /* A PLATEAU IS NOT A RIDGE. "No neighbour is higher" alone keeps every
         flat region, and the inside of a thick curve — the bail of a charm,
         say — is a broad plateau several pixels across. Keeping all of it
         put the stroke back to sixteen pixels after asking for five. A true
         ridge has at least one neighbour BELOW it; the flat interior of a
         heavy stroke does not, and does not need to be rescued either
         because the cut leaves its middle standing anyway.

         The exception is a stroke so fine its whole cross-section is one
         value — a one or two pixel line has no lower neighbour to point at,
         and it is exactly the detail this is all for. */
      let higher = false, lower = false;
      for (let dy = -1; dy <= 1 && !higher; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (!dx && !dy) continue;
          const u = d[i + dy * w + dx];
          if (u > v + 1e-9) { higher = true; break; }
          if (u < v - 1e-9) lower = true;
        }
      }
      if (!higher && (lower || v <= 1.5)) keep[i] = 1;
    }
  }
  return keep;
}

/* ── HOW HEAVY IS RIGHT ──────────────────────────────────────────────────
   3.2 was the first answer and it was one notch too far: "the lines are now
   just a little bit too thin". The two ends of the range are both measured
   rather than guessed — the drawing that started this ran at 10.9 per cent
   of the charm's own width and was unreadable, the 3.2 setting landed at
   3.9 and was thin — so the setting sits between them and nearer the fine
   end, where a lost detail is recoverable and a merged one is not. */
const STUDIO_LINE_PCT_FALLBACK = 3.3;   /* per cent of the charm's short side */
/* ── AND A PROPORTIONAL TRIM, BECAUSE THE CAP ALONE MISSES WIDE CHARMS ──
   The cap is a percentage of the charm's SHORT side, and on a wide, squat
   charm the short side is its height — enormous — so the model's own weight
   sails in under the cap and the thinner never engages. The customer then
   measured that untouched output at exactly a third too heavy. So every
   drawing is now trimmed by this ratio relative to what the model actually
   drew, unless the absolute cap already demands more or the canvas floor
   forbids less. 1.33 IS the customer's number: "the generated black lines
   are too thick, by 33%". Config lineArtTrimRatio overrides; 1 disables. */
const STUDIO_LINE_TRIM_FALLBACK = 1.33;
/* and a floor in absolute pixels, expressed against the CANVAS rather than
   fixed at 2: two pixels is a hairline on a 1K frame and a thread on a 4K
   one, and the same drawing must not get finer just because it got bigger */
const STUDIO_LINE_MIN_FRAC = 1 / 512;
const STUDIO_LINE_MIN_PX = 2;           /* below this a line stops being a line */

async function studioThinLineArt(sharp, buf, cfg) {
  const report = { applied: false, from: 0, to: 0, target: 0, why: "" };
  if (!sharp || !buf?.length) { report.why = "no_input"; return { buf, report }; }
  try {
    const pct = Math.max(1, Math.min(12, Number(cfg && cfg.lineArtStrokePct) ||
                                        STUDIO_LINE_PCT_FALLBACK));
    const { data, info } = await sharp(buf).flatten({ background: "#ffffff" })
      .greyscale().raw().toBuffer({ resolveWithObject: true });
    const w = info.width, h = info.height, n = w * h;
    const ink = new Uint8Array(n);
    let count = 0, x0 = w, y0 = h, x1 = -1, y1 = -1;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        if (data[y * w + x] < 128) {
          ink[y * w + x] = 1; count++;
          if (x < x0) x0 = x; if (x > x1) x1 = x;
          if (y < y0) y0 = y; if (y > y1) y1 = y;
        }
      }
    }
    if (count < 64 || x1 < 0) { report.why = "no_ink"; return { buf, report }; }

    const d = studioInkDistance(ink, w, h);
    const ridge = studioInkRidge(d, ink, w, h);
    /* ── MEASURED ON THE SPINE, NOT ON THE INK ─────────────────────────
       Along the middle of a stroke the distance to white is exactly half its
       width, so the median distance over RIDGE pixels doubles straight into
       a stroke width with no fitted constant and no bias.

       Taken over all the ink instead it is neither. It carries a systematic
       error of about two pixels — the distance across a stroke runs 0.5, 1.5,
       … so its median is not a quarter of the width — and, worse, a solid
       engraved region has far more pixels than the lines around it, so the
       median simply lands INSIDE the blob: a six-pixel linework beside one
       solid rectangle measured sixty. Every line in that drawing would then
       have been thinned to nothing. A blob's spine is short and a line's is
       long, so on the ridge the linework is what the median describes. */
    const spine = [];
    for (let i = 0; i < n; i++) if (ridge[i]) spine.push(d[i]);
    if (!spine.length) { report.why = "no_spine"; return { buf, report }; }
    spine.sort((a, b) => a - b);
    const halfNow = spine[spine.length >> 1];
    const from = halfNow * 2;
    const short = Math.min(x1 - x0 + 1, y1 - y0 + 1);
    const floor = Math.max(STUDIO_LINE_MIN_PX, Math.max(w, h) * STUDIO_LINE_MIN_FRAC);
    const trim = Math.max(1, Number(cfg && cfg.lineArtTrimRatio) || STUDIO_LINE_TRIM_FALLBACK);
    const target = Math.max(floor, Math.min((short * pct) / 100, from / trim));
    report.from = Math.round(from * 10) / 10;
    report.target = Math.round(target * 10) / 10;
    report.charmShort = short;
    if (from <= target * 1.25) {
      report.why = "already_fine"; report.to = report.from;
      return { buf, report };
    }
    /* How much comes off each side. A stroke of width W keeps the band where
       the distance exceeds `cut`, which is W - 2*cut wide, so the cut for a
       target T is simply (W - T)/2.

       The cap is against the DEEPEST point of a stroke, not the median one:
       halfNow is the median distance over the ink, which for an even stroke
       is a QUARTER of its width rather than a half. Capping against it took
       barely half the intended cut — a 12px line came out at 8px when 3px
       was asked for — and the fault was invisible because the direction was
       right. Ink that the cut would take entirely is caught by the ridge
       below, so the only job left for a cap is to stop a runaway. */
    const cut = Math.min((from - target) / 2, halfNow - 0.6);
    if (cut <= 0.35) { report.why = "nothing_to_cut"; report.to = report.from; return { buf, report }; }

    /* ── AND IT MUST NOT COME BACK WITH STAIRS ON IT ──────────────────
       The first version wrote pure black or pure white per pixel. That is
       the whole of the second half of the report — "you really lost a lot of
       quality on the aliasing, the previous thicker lines had much higher
       quality curves" — and it was not a side effect, it was the output
       format: every intermediate tone the model had drawn to make a curve
       read as a curve was thrown away, and the new edge was drawn on a
       staircase of whole pixels.

       The distance field already knows where the edge is to a fraction of a
       pixel, so the edge is drawn there. A pixel one full pixel inside the
       level set is solid, one outside is paper, and in between it takes the
       coverage its distance implies — which is what a rasteriser does and
       what the model itself did.

       Two rules keep it honest. Nothing is ever drawn DARKER than the model
       drew it, so no ink is invented; and a spine pixel keeps its original
       tone whatever the ramp says, so no stroke can be rubbed out. */
    /* ── DO IT ON THE TONES, NOT ON THE BITS ──────────────────────────
       "Keep the band where the distance exceeds `cut`" and "erode by a disc
       of radius `cut`" are the same sentence — {x : d(x) > R} IS the erosion
       of the shape by a disc of radius R. The first form has to be evaluated
       on a BINARY mask, so the new edge can only land on a level set of a
       field computed from whole pixels, and lands within about a third of a
       pixel of where it should. Down a near-vertical curve that error is
       fresh on every row, and it reads as exactly what the report says:
       stairs on a line that was smooth when the model drew it.

       The second form has no such limit. Greyscale erosion — the minimum
       over a disc — works on the tones themselves, so wherever the model
       drew a soft edge, the eroded edge is the same soft edge moved inward.
       Sub-pixel position, curvature and smoothness are all inherited rather
       than re-derived. A fractional radius is the blend of the two whole
       radii either side of it, which keeps the weight continuous in `cut`
       instead of jumping a pixel at a time.

       And it is anti-extensive by construction: a minimum over a set that
       includes the pixel itself can never exceed the pixel itself, so "never
       darker than the model drew it" is not a rule that has to be enforced.

       The spine is unioned back at its ORIGINAL tone, so a stroke finer than
       the cut keeps every tone it had rather than being rescued as a hard
       black thread — the rescue must not be its own aliasing. */
    const rad = Math.max(0, cut);
    const rOut = Math.ceil(rad), rIn = Math.floor(rad), frac = rad - rIn;
    const disc = [];
    for (let dy = -rOut; dy <= rOut; dy++) {
      for (let dx = -rOut; dx <= rOut; dx++) {
        const rr = dx * dx + dy * dy;
        if (rr <= rOut * rOut) disc.push([dx, dy, rr]);
      }
    }
    disc.sort((a, b) => a[2] - b[2]);
    const inSq = rIn * rIn;
    const out = Buffer.alloc(n * 3, 255);
    let kept = 0;
    for (let i = 0; i < n; i++) {
      const a0 = (255 - data[i]) / 255;
      if (a0 <= 0) continue;
      const x = i % w, y = (i / w) | 0;
      let mIn = a0, mOut = a0;
      for (let k = 0; k < disc.length; k++) {
        const nx = x + disc[k][0], ny = y + disc[k][1];
        const v = (nx < 0 || ny < 0 || nx >= w || ny >= h) ? 0 : (255 - data[ny * w + nx]) / 255;
        if (disc[k][2] <= inSq && v < mIn) mIn = v;
        if (v < mOut) mOut = v;
        if (mOut <= 0 && (disc[k][2] > inSq || mIn <= 0)) break;
      }
      let al = mIn * (1 - frac) + mOut * frac;
      if (ridge[i] && a0 > al) al = a0;
      if (al <= 0) continue;
      const g = Math.round(255 * (1 - al));
      out[i * 3] = g; out[i * 3 + 1] = g; out[i * 3 + 2] = g;
      if (al >= 0.5) kept++;
    }
    if (!kept) { report.why = "would_erase"; report.to = report.from; return { buf, report }; }

    /* measure what actually came out, rather than what was asked for */
    const ink2 = new Uint8Array(n);
    /* the same threshold the measurement used going in — reading only PURE
       black would now skip every anti-aliased edge and report the result
       thinner than it is */
    for (let i = 0; i < n; i++) if (out[i * 3] < 128) ink2[i] = 1;
    const d2 = studioInkDistance(ink2, w, h);
    const r2 = studioInkRidge(d2, ink2, w, h);
    const v2 = [];
    for (let i = 0; i < n; i++) if (r2[i]) v2.push(d2[i]);
    v2.sort((a, b) => a - b);
    report.to = v2.length ? Math.round(v2[v2.length >> 1] * 20) / 10 : 0;

    const png = await sharp(out, { raw: { width: w, height: h, channels: 3 } })
      .png({ compressionLevel: 9 }).toBuffer();
    report.applied = true;
    console.log(`[studio] line art was ${report.from}px on a ${short}px charm — thinned to ` +
                `${report.to}px (target ${report.target}px)`);
    return { buf: png, report };
  } catch (e) {
    report.why = "error:" + String(e?.message || e).slice(0, 80);
    return { buf, report };
  }
}

/* ═══════════ THE DRAWING MUST COME BACK THE WAY IT WENT IN ═══════════════
   The line-art prompt says it plainly — "do not move, rescale, re-centre or
   re-crop the object; it must sit in the same place in the frame, at the
   same size, so the drawing can be laid directly over the photograph" — and
   the model turns it anyway. A charm photographed upright comes back lying
   at forty-five degrees across the frame. Everything downstream then
   inherits it: the customer's first sight of their own charm is a drawing
   nobody drew that way, the alignment check has nothing to align, and every
   part the trace produces is filed at the wrong angle.

   An instruction the model declines to follow is not a mechanism. This is
   the mechanism: the orientation of a shape is a property of its pixels, so
   it is measured on both pictures and the difference is simply undone.

   WHAT IS AND IS NOT CORRECTED. The principal axis is undirected — it says
   which way a shape is long, not which end is the top — so a drawing that
   came back upside down is NOT flipped, because nothing here can tell an
   upside-down bat from a right-way-up one. Only the turn is undone, and only
   within a quarter turn either way. A charm too round to have a long axis is
   left alone entirely: on a disc the axis is noise, and rotating by noise
   would be worse than the fault being fixed. */

/* Second moments of the ink. Returns the principal angle in radians (-π/2,
   π/2], the eccentricity 0..1, and how much ink there was to measure — all
   from one pass over a grayscale buffer, so it costs nothing worth naming. */
function studioInkAxis(gray, w, h) {
  let n = 0, sx = 0, sy = 0;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (gray[y * w + x] < 128) { n++; sx += x; sy += y; }
    }
  }
  if (n < 32) return null;
  const cx = sx / n, cy = sy / n;
  let mxx = 0, myy = 0, mxy = 0;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (gray[y * w + x] >= 128) continue;
      const dx = x - cx, dy = y - cy;
      mxx += dx * dx; myy += dy * dy; mxy += dx * dy;
    }
  }
  mxx /= n; myy /= n; mxy /= n;
  /* the major axis of the covariance ellipse */
  const angle = 0.5 * Math.atan2(2 * mxy, mxx - myy);
  const t = Math.sqrt((mxx - myy) * (mxx - myy) + 4 * mxy * mxy);
  const l1 = (mxx + myy + t) / 2, l2 = (mxx + myy - t) / 2;
  const ecc = l1 > 1e-9 ? Math.sqrt(Math.max(0, 1 - l2 / l1)) : 0;
  return { angle, ecc, n, cx, cy };
}

/* the smallest turn that brings axis `from` onto axis `to`, in (-π/2, π/2] —
   an axis has no head or tail, so half a turn is no turn at all */
function studioAxisDelta(from, to) {
  let d = to - from;
  while (d <= -Math.PI / 2) d += Math.PI;
  while (d > Math.PI / 2) d -= Math.PI;
  return d;
}

const STUDIO_ORIENT_MIN_ECC = 0.62;   /* below this a shape has no long axis */
const STUDIO_ORIENT_MIN_DEG = 4;      /* below this, leave it alone */

/* Never throws and never fails the step: a drawing that arrived is worth
   more than a drawing that is perfectly square. */
async function studioMatchOrientation(sharp, drawingBuf, referenceBuf) {
  const report = { applied: false, deg: 0, why: "" };
  if (!sharp || !drawingBuf?.length || !referenceBuf?.length) {
    report.why = "no_input"; return { buf: drawingBuf, report };
  }
  try {
    const W = 320;
    const read = async (buf) => {
      const { data, info } = await sharp(buf)
        .flatten({ background: "#ffffff" }).greyscale()
        .resize(W, W, { fit: "contain", background: "#ffffff" })
        .raw().toBuffer({ resolveWithObject: true });
      return studioInkAxis(data, info.width, info.height);
    };
    const a = await read(referenceBuf);
    const b = await read(drawingBuf);
    if (!a || !b) { report.why = "no_ink"; return { buf: drawingBuf, report }; }
    report.refEcc = Math.round(a.ecc * 100) / 100;
    report.outEcc = Math.round(b.ecc * 100) / 100;
    if (a.ecc < STUDIO_ORIENT_MIN_ECC || b.ecc < STUDIO_ORIENT_MIN_ECC) {
      report.why = "too_round"; return { buf: drawingBuf, report };
    }
    const d = studioAxisDelta(b.angle, a.angle);
    const deg = d * 180 / Math.PI;
    report.deg = Math.round(deg * 10) / 10;
    if (Math.abs(deg) < STUDIO_ORIENT_MIN_DEG) {
      report.why = "already_upright"; return { buf: drawingBuf, report };
    }
    /* rotate onto the reference's axis, on white, then put it back in a
       square frame the same way the drawing arrived in one */
    const meta = await sharp(drawingBuf).metadata();
    const S = Math.max(meta.width || 1024, meta.height || 1024);
    const turned = await sharp(drawingBuf)
      .flatten({ background: "#ffffff" })
      .rotate(deg, { background: "#ffffff" })
      .png().toBuffer();
    const framed = await studioTrimToSubject(sharp, turned, 0.03);
    const out = await sharp(framed)
      .flatten({ background: "#ffffff" })
      .resize(S, S, { fit: "contain", background: "#ffffff" })
      .png().toBuffer();
    report.applied = true;
    console.log(`[studio] line art was ${report.deg}° off the reference's axis — turned back`);
    return { buf: out, report };
  } catch (e) {
    report.why = "error:" + String(e?.message || e).slice(0, 80);
    return { buf: drawingBuf, report };
  }
}

async function handleStudioSpecFromGold({ body, event, origin }) {
  const uid = await requireStudioUser(event);
  const cfg = await studioConfig();
  const db = getDb();

  const sessionId = String(body?.sessionId || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 60);
  if (!sessionId) return studioJson(400, { ok: false, error: "missing_session" }, origin);

  const sRef = db.collection(STUDIO_SESSIONS_COLL).doc(sessionId);
  const sSnap = await sRef.get();
  if (!sSnap.exists || sSnap.data().uid !== uid) {
    return studioJson(403, { ok: false, error: "forbidden" }, origin);
  }
  const session = sSnap.data();

  const n = Number(body?.versionNumber) || Number(session.currentVersion) || 0;
  if (!n || n < 1) return studioJson(400, { ok: false, error: "missing_version" }, origin);
  const vRef = sRef.collection("versions").doc(String(n));
  const vSnap = await vRef.get();
  if (!vSnap.exists) return studioJson(409, { ok: false, error: "version_not_ready" }, origin);
  const version = vSnap.data();

  const goldPath = String(version.renderPath || "");
  if (!goldPath) return studioJson(409, { ok: false, error: "no_gold_yet" }, origin);

  /* ── DOING IT TWICE IS THE EXPENSIVE MISTAKE ──────────────────────────
     Approve can be pressed twice, a checkout can be retried, and a sweep
     for stalled jobs will re-fire this by design. The map already on the
     doc is only stale if the GOLD it was made from has changed since, so
     that — not a flag — is what decides. A run already in flight is left
     alone unless it has been in flight long enough to be dead. */
  const force = body?.force === true;
  /* ── A MAP THE DRAWING PIPELINE ALREADY BUILT IS THE BETTER MAP ────────
     The dedupe below only recognises maps this handler made itself
     (specStatus / specSource are its own fields). A design that went
     through the markup studio arrives with a map built DETERMINISTICALLY
     from the drawing — renderSpecKey and renderSpecPath, no specStatus —
     and deriving a second one from the gold is not only a duplicate, it is
     a WORSE copy: a model's reading of a photograph, replacing arithmetic
     on the customer's own instructions. So a drawing-derived map ends this
     request here, and specStatus is stamped so a watcher already waiting
     on the doc settles instead of timing out. */
  if (!force && version.renderSpecURL && version.renderSpecPath && version.renderSpecKey) {
    await vRef.set({ specStatus: "done", specSource: "drawing-pipeline",
                     specError: null }, { merge: true });
    return studioJson(200, { ok: true, n, skipped: "drawing_map",
                             renderSpecURL: version.renderSpecURL }, origin);
  }
  const sourceKey = goldPath + "|" + String(version.renderRunId || "") +
                    "|" + String(version.goldEditCount || 0);
  if (!force && version.specStatus === "done" && version.specSource === sourceKey && version.renderSpecURL) {
    return studioJson(200, { ok: true, n, skipped: "already_done",
                             renderSpecURL: version.renderSpecURL }, origin);
  }
  if (!force && version.specStatus === "pending") {
    const started = asMsServer(version.specStartedAt);
    if (started && Date.now() - started < STUDIO_SPEC_STALE_MS) {
      return studioJson(200, { ok: true, n, skipped: "already_running" }, origin);
    }
  }

  const attemptsSoFar = Number(version.specAttempts) || 0;
  await vRef.set({
    specStatus: "pending",
    specSource: sourceKey,
    specStartedAt: admin.firestore.FieldValue.serverTimestamp(),
    specError: null,
  }, { merge: true });

  const sharpMod = studioSharp();
  if (!sharpMod) {
    await studioSpecFail(vRef, "sharp_unavailable", attemptsSoFar);
    return studioJson(503, { ok: false, error: "sharp_unavailable" }, origin);
  }

  let studioModelConfig = null;
  try {
    studioModelConfig = resolveImageModel(studioImageModelId(cfg, "specgold"));
    apiKeyForImageModel(studioModelConfig);
  } catch (err) {
    await studioSpecFail(vRef, "render_unavailable", attemptsSoFar);
    return studioJson(503, { ok: false, error: "render_unavailable" }, origin);
  }

  let gold;
  try {
    gold = await storagePathToBuffer(goldPath);
    if (!gold?.buffer?.length) throw new Error("gold_missing");
  } catch (err) {
    await studioSpecFail(vRef, String(err?.message || err), attemptsSoFar);
    return studioJson(500, { ok: false, error: "gold_missing" }, origin);
  }

  const styleRef = await ensureStudioLineArtReference();
  const images = [{ buffer: gold.buffer, mime: gold.mime || "image/png", filename: `v${n}-charm.png` }];
  if (styleRef?.buffer?.length) {
    images.push({ buffer: styleRef.buffer, mime: styleRef.mime, filename: styleRef.filename });
  }

  /* ── RETRIED HERE, NOT SOMEWHERE ELSE ─────────────────────────────────
     Nobody is watching this run, so an attempt that dies has nothing to
     tell and nowhere to tell it. The cheapest correct place to try again
     is immediately, inside the invocation that already has the gold in
     memory and the model resolved. Only the two failures worth retrying
     are retried: the model call itself, and a drawing that came back
     unusable. A missing file or a bad configuration will fail the same way
     every time and is recorded at once. */
  let attempt = 0, lastErr = null, saved = null;
  while (attempt < STUDIO_SPEC_MAX_ATTEMPTS) {
    attempt++;
    try {
      const lineBuf = await callImageModelEdits({
        apiKey: apiKeyForImageModel(studioModelConfig),
        model: studioModelConfig.id,
        prompt: STUDIO_LINEART_PROMPT,
        size: studioImageSizeString(studioRenderTier(cfg)),
        imageSizeTier: studioRenderTier(cfg),
        quality: "high",
        output_format: "png",
        images,
        imageRoles: "line_art_style",
        charmGeometryPolicy: null,
        backgroundPolicy: null,
      });

      const spec = await studioSpecFromGold(sharpMod, gold.buffer, lineBuf, studioMaskMinPx(cfg));
      if (!spec.aligned) {
        /* The drawing does not lie over this charm, so reading engraving out
           of it would be reading it off the wrong pixels. Worth one more
           attempt — this is usually a model that re-cropped. */
        lastErr = new Error("unaligned_drawing_iou_" + spec.iou.toFixed(3));
        console.warn(`[studio] spec attempt ${attempt}: drawing does not align (IoU ${spec.iou.toFixed(3)})`);
        continue;
      }

      const bucket = getBucket();
      const base = `custom-studio/${uid}/uploads/designs/${sessionId}/v${n}`;
      const lineToken = newDownloadToken(), specToken = newDownloadToken();
      /* the drawing is kept as evidence for the same reason the mask always
         has been: when a map looks wrong, the only way to tell a bad drawing
         from a bad combine is to have both */
      await bucket.file(base + "-lineart.png").save(lineBuf, {
        resumable: false, contentType: "image/png",
        metadata: { metadata: { firebaseStorageDownloadTokens: lineToken, uid, sessionId,
                                version: String(n), lineart: "1" } },
      });
      await bucket.file(base + "-spec.png").save(spec.buf, {
        resumable: false, contentType: "image/png",
        metadata: { metadata: { firebaseStorageDownloadTokens: specToken, uid, sessionId,
                                version: String(n), spec: "1" } },
      });
      saved = {
        lineArtURL: tokenDownloadURLFor(bucket.name, base + "-lineart.png", lineToken),
        lineArtPath: base + "-lineart.png",
        renderSpecURL: tokenDownloadURLFor(bucket.name, base + "-spec.png", specToken),
        renderSpecPath: base + "-spec.png",
        spec,
      };
      break;
    } catch (err) {
      lastErr = err;
      console.error(`[studio] spec attempt ${attempt} failed:`, err?.message || err);
    }
  }

  if (!saved) {
    await studioSpecFail(vRef, lastErr?.message || "spec_failed", attemptsSoFar + attempt);
    return studioJson(500, { ok: false, error: "spec_failed",
                             detail: String(lastErr?.message || "").slice(0, 200) }, origin);
  }

  await vRef.set({
    specStatus: "done",
    specAttempts: attemptsSoFar + attempt,
    specError: null,
    specSource: sourceKey,
    specDoneAt: admin.firestore.FieldValue.serverTimestamp(),
    renderSpecURL: saved.renderSpecURL,
    renderSpecPath: saved.renderSpecPath,
    renderSpecMode: "derived-from-gold",
    renderSpecFacePx: saved.spec.facePx,
    renderSpecHolePx: saved.spec.holePx,
    renderSpecWorkPx: saved.spec.workPx,
    specLineArtURL: saved.lineArtURL,
    specLineArtPath: saved.lineArtPath,
    specAlignIoU: Math.round(saved.spec.iou * 1000) / 1000,
    specModel: studioModelConfig.id,
    specStyleRef: styleRef?.storagePath || "",
  }, { merge: true });

  console.log(`[studio] spec derived for v${n} in ${attempt} attempt(s) — ` +
              `IoU ${saved.spec.iou.toFixed(3)}, ${saved.spec.workPx}px engraved`);
  return studioJson(200, { ok: true, n, renderSpecURL: saved.renderSpecURL,
                           renderSpecPath: saved.renderSpecPath,
                           specAlignIoU: saved.spec.iou, attempts: attempt }, origin);
}

/* ═══════════ ADOPTING A CHARM FROM THE CATALOGUE ═════════════════════════
   "From our designs" used to run the same pipeline as everything else: the
   product photograph became a REFERENCE, the model drew a production
   drawing from it, and the drawing was rendered back into metal. Three
   model calls and two credits to arrive at an approximation of a charm the
   workshop already makes, photographs of which were sitting in the
   catalogue the whole time.

   So it does not do that any more. The catalogue photograph IS the charm:
   it is filed as version 1's gold, no model runs, nothing is charged, and
   the arrow's surgical gold edit is the only thing that ever changes it.

   THE DRAWING AND THE MAP ARE SIMPLY ABSENT, and that is deliberate rather
   than missing. A version adopted this way has no production drawing,
   because none was ever made and inventing one would be inventing a claim
   about a charm the workshop already knows how to cut. The greyscale map
   arrives later, derived backwards from whatever gold the customer finally
   approves — see handleStudioSpecFromGold.

   THE IMAGE IS FETCHED HERE, NOT POSTED. The browser has the URL and could
   have sent the bytes, but reading a Shopify CDN image from a page is a
   CORS gamble that fails silently on some stores, and a browser that cannot
   read it cannot tell anyone why. The server has no such problem — and to
   keep that from becoming a way to make this function fetch anything at
   all, the host is checked against a fixed list before a request is made. */
function studioTierPx(tier) {
  return tier === "1K" ? 1024 : tier === "4K" ? 4096 : 2048;
}

const STUDIO_ADOPT_HOSTS = [
  "cdn.shopify.com",
  "britesjewelry.com",
  "www.britesjewelry.com",
  "brites-jewelry.myshopify.com",
  "firebasestorage.googleapis.com",
];
const STUDIO_ADOPT_MAX_BYTES = 12 * 1024 * 1024;

/* The storefront normalises this before sending it, and this resolves the
   same three shapes again anyway — a path, a protocol-relative URL and an
   absolute one — because the browser is not the only thing that can call
   this and a fixable input should not be a refusal.

   AND THE REFUSAL NAMES WHAT IT SAW. The first version answered a bare
   "bad_image_url", which is true of a relative path, an http URL, a data
   URL and a typo alike; the log said the adopt failed and nothing else, and
   the actual cause — predictive search returning "/cdn/shop/..." rather
   than a URL — took a code read to find. Every branch below says which
   thing was wrong now. */
async function studioFetchCatalogImage(rawUrl) {
  let raw = String(rawUrl || "").trim();
  if (!raw) throw new Error("image_url_empty");
  if (raw.startsWith("//")) raw = "https:" + raw;
  let u;
  try { u = new URL(raw, "https://britesjewelry.com"); }
  catch (e) { throw new Error("image_url_unparsable"); }
  if (u.protocol !== "https:") throw new Error("image_url_not_https_" + u.protocol.replace(":", ""));
  if (!STUDIO_ADOPT_HOSTS.includes(u.hostname)) {
    throw new Error("image_host_not_allowed_" + u.hostname);
  }
  const resp = await fetch(u.toString(), { redirect: "follow" });
  if (!resp.ok) throw new Error("image_fetch_" + resp.status);
  const type = String(resp.headers.get("content-type") || "").split(";")[0].trim().toLowerCase();
  if (!/^image\//.test(type)) throw new Error("not_an_image");
  const ab = await resp.arrayBuffer();
  if (!ab.byteLength) throw new Error("empty_image");
  if (ab.byteLength > STUDIO_ADOPT_MAX_BYTES) throw new Error("image_too_large");
  return { buffer: Buffer.from(ab), mime: type };
}

async function handleStudioAdopt({ body, event, origin }) {
  const uid = await requireStudioUser(event);
  const db = getDb();

  const sessionId = String(body?.sessionId || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 60);
  if (!sessionId) return studioJson(400, { ok: false, error: "missing_session" }, origin);

  const sRef = db.collection(STUDIO_SESSIONS_COLL).doc(sessionId);
  const sSnap = await sRef.get();
  if (!sSnap.exists || sSnap.data().uid !== uid) {
    return studioJson(403, { ok: false, error: "forbidden" }, origin);
  }
  const session = sSnap.data();

  const n = Number(body?.versionNumber) || (Number(session.currentVersion) || 0) + 1;
  if (!n || n < 1 || n > 400) return studioJson(400, { ok: false, error: "bad_version" }, origin);
  const vRef = sRef.collection("versions").doc(String(n));

  const metal = studioCleanText(body?.metal || session.metal || "gold");
  const title = studioCleanText(body?.title || "").slice(0, 140);
  const productGid = String(body?.productGid || "").slice(0, 120);

  let img;
  try { img = await studioFetchCatalogImage(body?.imageUrl); }
  catch (err) {
    console.error("[studio] catalogue image:", err?.message || err);
    return studioJson(400, { ok: false, error: String(err?.message || "bad_image_url") }, origin);
  }

  /* Normalised to PNG on a white ground at the render tier, so a catalogue
     photograph and a rendered charm are the same kind of object downstream:
     the gold edit reads its size from these bytes, and the map derived at
     approval reads its chroma from them. A JPEG with a transparent-looking
     white or an odd aspect would make both of those subtly wrong. */
  let outBuf;
  try {
    const sharpMod = studioSharp();
    if (!sharpMod) throw new Error("sharp_unavailable");
    const cfg = await studioConfig();
    const S = studioTierPx(studioRenderTier(cfg));
    /* ── THE PHOTOGRAPH IS KEPT WHOLE ─────────────────────────────────────
       An earlier version cropped the "Charm Only" caption off here, finding
       the charm by chroma and squaring around it. It worked, and it is the
       wrong place to do it: cropping throws away pixels before the customer
       has asked for anything, and the model is about to redraw this charm
       anyway. So the caption is removed as part of the FIRST gold edit,
       where it is one clause in a prompt that is already redrawing the
       piece — see buildGoldEditPrompt. Nothing is discarded here. */
    outBuf = await sharpMod(img.buffer)
      .flatten({ background: "#ffffff" })
      .resize(S, S, { fit: "contain", background: "#ffffff", kernel: "lanczos3" })
      .png().toBuffer();
  } catch (err) {
    console.error("[studio] catalogue image could not be normalised:", err?.message || err);
    return studioJson(500, { ok: false, error: "image_unreadable" }, origin);
  }

  outBuf = embedPngTextMetadata(outBuf, {
    Description: `Custom Charm Studio — ${title || "catalogue charm"} adopted as v${n} (${metal}).`,
    CharmTitle: title || `Custom charm v${n}`,
  });

  const renderPath = `custom-studio/${uid}/uploads/designs/${sessionId}/v${n}-charm.png`;
  const bucket = getBucket();
  const token = newDownloadToken();
  await bucket.file(renderPath).save(outBuf, {
    resumable: false, contentType: "image/png",
    metadata: { metadata: { firebaseStorageDownloadTokens: token, uid, sessionId,
                            version: String(n), render: "1", adopted: "1" } },
  });
  const renderURL = tokenDownloadURLFor(bucket.name, renderPath, token);

  await vRef.set({
    n, status: "done", stage: "done",
    /* NO `url`. There is no production drawing and there is not going to be
       one; the studio reads the absence and does not offer the Drawing tab. */
    url: "", storagePath: "",
    source: "catalog", catalogTitle: title, catalogProductGid: productGid,
    renderStatus: "done", renderStage: "done",
    renderURL, renderPath, renderMetal: metal,
    renderRunId: String(body?.renderRunId || ("ad_" + Date.now())).replace(/[^A-Za-z0-9_-]/g, "").slice(0, 80),
    renderCost: 0,
    goldEdited: false, goldEditCount: 0,
    /* the map is owed, and saying so now means a sweep can find a design
       whose map never arrived without having to guess whether one was due */
    specStatus: "not_started",
    createdAt: admin.firestore.FieldValue.serverTimestamp(),
  }, { merge: true });

  await sRef.set({ currentVersion: n, updatedAt: Date.now() }, { merge: true });

  return studioJson(200, { ok: true, n, renderURL, renderPath, renderMetal: metal,
                           source: "catalog" }, origin);
}

async function handleStudioSessionStatus({ body, event, origin }) {
  const uid = await requireStudioUser(event);
  const db = getDb();
  const sessionId = String(body?.sessionId || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 60);
  const n = String(Number(body?.versionNumber) || 1);
  const sRef = db.collection(STUDIO_SESSIONS_COLL).doc(sessionId);
  const sSnap = await sRef.get();
  if (!sSnap.exists || sSnap.data().uid !== uid) {
    return studioJson(403, { ok: false, error: "forbidden" }, origin);
  }
  const v = await sRef.collection("versions").doc(n).get();
  const sd = sSnap.data();
  return studioJson(200, {
    ok: true,
    currentVersion: sd.currentVersion || 0,
    version: v.exists ? Object.assign({ n: Number(n) }, v.data()) : null,
    /* the reference drawing's progress lives on the SESSION doc, and the
       browser's snapshot listener can be refused by the security rules in
       the first seconds of a brand-new project — this read, made with admin
       credentials and answered only to the owner, is the channel no rule
       can refuse */
    session: {
      refLineArtStatus: sd.refLineArtStatus || "",
      refLineArtURL: sd.refLineArtURL || "",
      refLineArtPath: sd.refLineArtPath || "",
      refLineArtError: sd.refLineArtError || "",
    },
  }, origin);
}

/* ═══════════ FILING A DRAWING THE STUDIO MADE ITSELF ═════════════════════
   In "exactly as drawn" the browser composes the production drawing from the
   customer's own vector items — no model is called and nothing is
   interpreted. But the render step does not accept a picture: it reads a
   FIXED Storage path, `.../designs/<session>/v<n>.png`, and refuses any
   version whose Firestore doc is not marked done. A composed drawing that
   lived anywhere else was therefore invisible to it — the render answered
   409 version_not_ready and the customer watched a progress bar to its
   timeout with no reason given.

   So the composed PNG is filed exactly where a generated one is filed, and
   its version doc is written in the same shape. Everything downstream — the
   render, the cart thumbnail, My designs, the order webhook — then treats it
   as what it is: version n of this design.

   IT COSTS NO GENERATION CREDIT. No model ran, so there is nothing to
   charge for; the upload allowance the browser already spent is the whole
   price. The rate limits still apply, because writing megabytes into
   Storage is worth bounding whoever asks for it. */
async function handleStudioCompose({ body, event, origin }) {
  const uid = await requireStudioUser(event);
  const db = getDb();

  const sessionId = String(body?.sessionId || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 60);
  if (!sessionId) return studioJson(400, { ok: false, error: "missing_session" }, origin);

  const sRef = db.collection(STUDIO_SESSIONS_COLL).doc(sessionId);
  const sSnap = await sRef.get();
  if (!sSnap.exists || sSnap.data().uid !== uid) {
    return studioJson(403, { ok: false, error: "forbidden" }, origin);
  }
  const session = sSnap.data();

  const n = Number(body?.versionNumber) || (Number(session.currentVersion) || 0) + 1;
  if (!n || n < 1 || n > 400) return studioJson(400, { ok: false, error: "bad_version" }, origin);
  const vRef = sRef.collection("versions").doc(String(n));

  /* ── NO CEILING HERE, EVER, WHATEVER THE CEILINGS ARE SET TO ───────────
     This was the wrong gate on the wrong door, and it is the one that was
     actually refusing work. A compose calls NO model, spends NO credit and
     costs nothing upstream — the browser painted the picture itself and this
     is where it gets filed. It was nevertheless counted against the same
     hourly generation budget as a Gemini render, so filing your own drawing
     used up the allowance for making new ones, and the studio answered a
     purely local operation with `rate_limited`.

     The controls that matter are still every one of them above: a verified
     ID token, a session this caller owns, a bounded version number, and the
     5.5 MB body cap the kick enforces before this function is even loaded.
     A ceiling here protects nothing that those do not already protect. */

  let img;
  try {
    img = dataUrlToBuffer(String(body?.dataUrl || ""));
  } catch (_e) {
    return studioJson(400, { ok: false, error: "bad_image" }, origin);
  }
  if (!/^image\/png$/i.test(img.mime)) return studioJson(400, { ok: false, error: "png_only" }, origin);
  if (!img.buffer.length || img.buffer.length > 12 * 1024 * 1024) {
    return studioJson(413, { ok: false, error: "image_too_large" }, origin);
  }

  try {
    /* the same path the generator writes, "uploads" segment included: the
       cart template keys its thumbnail off that word */
    const storagePath = `custom-studio/${uid}/uploads/designs/${sessionId}/v${n}.png`;
    const bucket = getBucket();
    const token = newDownloadToken();
    await bucket.file(storagePath).save(img.buffer, {
      resumable: false,
      contentType: "image/png",
      metadata: { metadata: { firebaseStorageDownloadTokens: token, uid, sessionId,
                              version: String(n), composed: "1" } },
    });
    const downloadURL = tokenDownloadURLFor(bucket.name, storagePath, token);

    /* Build the Greyscale Mask now, so the customer sees both pictures before
       paying for a render. Never allowed to fail this step. */
    let specURL = "", specPath = "", specReuse = null;
    try {
      const sp = await studioStoreSpecForVersion({
        uid, sessionId, n, metal: session.metal || "gold",
        drawingBuffer: img.buffer, zones: body?.zones,
      });
      if (sp) {
        specURL = sp.specURL; specPath = sp.specPath;
        specReuse = {
          renderSpecURL: sp.specURL, renderSpecPath: sp.specPath,
          renderSpecKey: sp.specKey, renderSpecMode: "deterministic-material",
          renderSpecFacePx: sp.facePx, renderSpecHolePx: sp.holePx,
          renderSpecWorkPx: sp.workPx,
        };
      }
    } catch (e) { console.error("[studio] greyscale mask at generation skipped:", e?.message || e); }

    await studioStage(vRef, Object.assign({
      status: "done", stage: "done", storagePath, downloadURL,
      specURL, specPath,
      composed: true,
      model: "studio-composer",
      prompt: "Composed locally from the customer's own vector items — exactly as drawn.",
      doneAt: admin.firestore.FieldValue.serverTimestamp(),
    }, specReuse || {}));
    try {
      await sRef.set({
        currentVersion: n,
        updatedAtServer: admin.firestore.FieldValue.serverTimestamp(),
      }, { merge: true });
    } catch (_e) {}

    return studioJson(200, { ok: true, n, storagePath, downloadURL }, origin);
  } catch (err) {
    console.error("[studio] compose file:", err);
    return studioJson(500, { ok: false, error: "server_error" }, origin);
  }
}

async function handleStudioKind({ kind, body, event }) {
  const origin = (event?.headers && (event.headers.origin || event.headers.Origin)) || "";
  try {
    if (kind === "custom_charm_precheck") return await handleStudioPrecheck({ body, event, origin });
    if (kind === "custom_charm_generate" || kind === "custom_charm_refine") {
      return await handleStudioGenerate({ kind, body, event, origin });
    }
    if (kind === "custom_charm_compose") return await handleStudioCompose({ body, event, origin });
    if (kind === "custom_charm_render") return await handleStudioRender({ body, event, origin });
    if (kind === "custom_charm_gold_edit") return await handleStudioGoldEdit({ body, event, origin });
    if (kind === "custom_charm_spec_from_gold") return await handleStudioSpecFromGold({ body, event, origin });
    if (kind === "custom_charm_ref_lineart") return await handleStudioRefLineArt({ body, event, origin });
    if (kind === "custom_charm_adopt") return await handleStudioAdopt({ body, event, origin });
    /* custom_charm_prompt is gone — see STUDIO_KINDS. A tab left open from
       before the prompt lab was removed falls to unknown_kind below, which
       is the right answer: there is nothing to preview. */
    if (kind === "custom_session_status") return await handleStudioSessionStatus({ body, event, origin });
    return studioJson(400, { ok: false, error: "unknown_kind" }, origin);
  } catch (err) {
    if (err?.status) return studioJson(err.status, { ok: false, error: err.message }, origin);
    console.error("[studio]", kind, err);
    return studioJson(500, { ok: false, error: "server_error" }, origin);
  }
}

exports.handler = async (event) => {
  // Top-level safety net. Any error inside the handler that isn't
  // caught by the inner try/catch blocks would otherwise bubble up to
  // Netlify and surface as an opaque "Internal Error. ID: xxx" 500
  // with no useful message. This wrapper guarantees we always return
  // a JSON response with the actual error text so the browser can
  // display it. Crucial for debugging large batch submissions where
  // Netlify's function logs aren't always visible.
  try {
    return await _handlerImpl(event);
  } catch (err) {
    console.error("[handler] unhandled error:", err);
    return {
      statusCode: 500,
      headers: {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*",
      },
      body: JSON.stringify({
        ok: false,
        error: {
          message: String(err?.message || err),
          stack: String(err?.stack || "").split("\n").slice(0, 5).join(" | "),
          kind: (() => { try { return JSON.parse(event?.body || "{}")?.kind; } catch { return null; } })(),
        },
      }),
    };
  }
};

async function _handlerImpl(event) {
  if (event.httpMethod === "OPTIONS") return json(200, { ok: true });
  if (event.httpMethod !== "POST") return json(405, { error: { message: "Method not allowed" } });

  const body = parseJsonBody(event);
  if (!body) return json(400, { error: { message: "Invalid JSON body" } });

  // ---------------------------------------------------------------------
  // Custom Charm Studio (storefront, customer-facing). Dispatched before
  // every existing kind and before the destructure below, because these
  // requests are authenticated with a Firebase ID token, answer a
  // storefront-locked CORS origin rather than "*", and share none of the
  // Listing Generator's body contract. No existing kind is affected.
  // ---------------------------------------------------------------------
  if (STUDIO_KINDS.has(body.kind)) {
    return await handleStudioKind({ kind: body.kind, body, event });
  }

  const {
    jobId,
    runId,
    slotIndex,
    kind = "edits",
    model: _clientModel,
    prompt,
    size = "2048x2048",
    quality = "high",
    output_format = "png",
    input_storage_path,
    input_image,
    input_charm_storage_path,
    input_charm_image,
    remove_prompt,
    postprocess,
    base_storage_path,
    base_image,
    activeCategory,
    output_base_path,
    source_storage_path,
    manifest,
    concept_count,
    background_policy,
    // Charm geometry contract, enforced as the backend's FINAL word after all
    // role labels: "flat_integrated_eyelet" (base charm — flat sheet with one
    // fused eyelet, no jump rings) or "flat_no_attachment" (earring twin —
    // flat sheet with no attachment hardware at all).
    charm_geometry_policy,
    // Optional edit-intent declaration (e.g. "remove_jump_ring_only") used by
    // the text-only prompt preflight to scope a repair to the attachment
    // hardware while preserving the charm design 100%.
    charm_edit_intent,
    // Optional {keyword: text} map written into the output PNG as iTXt
    // chunks (e.g. the Charm Maker's tailored per-image design description).
    embed_metadata,
    // "edit" (default) | "style_reference"
    //
    // The role labels this function injects around the inline image parts are
    // written for the listing compositor: IMAGE 1 is a locked template canvas,
    // IMAGE 2 is design truth whose exact silhouette must be reused, and the
    // final lock says "edit IMAGE 1 in place". They are appended AFTER the
    // caller's prompt, so they win any disagreement with it.
    //
    // That is correct for compositing a known charm onto a known template. It
    // is exactly wrong for the Charm Maker, which passes a reference charm and
    // asks for a NEW design: the labels instruct the model to reproduce the
    // silhouette it was supposed to depart from, which is why derivatives came
    // back as near-copies no matter how the prompt was worded.
    //
    // "style_reference" swaps in labels that scope the reference to material,
    // finish, lighting, background and engraving language, and make reusing its
    // subject or silhouette an explicit failure. Default is unchanged, so every
    // existing caller behaves byte-for-byte as before.
    image_roles,
  } = body || {};

  // ---------------------------------------------------------------------
  // kind: "capabilities" — a cheap, side-effect-free probe.
  //
  // The Charm Maker's design mode depends on this file supporting
  // image_roles: "style_reference". An older deployment simply IGNORES an
  // unknown image_roles and appends "IMAGE 1 — EDIT TARGET. Apply only the
  // requested edit and preserve all unrelated pixels", which silently turns
  // every derivative back into a near-copy of its reference with no error
  // anywhere. That silent failure is unacceptable, so the client probes for
  // this endpoint and refuses to use the image-conditioned path unless it
  // answers. An old deployment falls through to the edits branch and 400s,
  // which is itself a clear answer.
  // ---------------------------------------------------------------------
  if (kind === "capabilities") {
    // Every flag below is a live description of this file's behaviour — the
    // Listing Generator refuses to run the Charm Maker against a backend
    // whose answers don't match the contract it was built for.
    return json(200, {
      ok: true,
      proxy: "geminiImageProxy-background",
      // 13: adds the Custom Charm Studio kinds and the customer_reference
      // role vocabulary. Every key below 13 is unchanged — the Listing
      // Generator hard-gates on them.
      capabilitiesVersion: 13,
      roleModes: Object.keys(IMAGE_ROLE_LABELS),
      supportsStyleReference: Object.prototype.hasOwnProperty.call(IMAGE_ROLE_LABELS, "style_reference"),
      supportsCharmConceptPlanning: true,
      supportsCharmBatchOrchestration: true,
      supportsCharmBatchRecovery: true,
      supportsBatchSweep: true,
      // charm_geometry_policy is appended by the backend AFTER all role
      // labels, as the request's final word (charmPolicyFinalText).
      supportsBackendFinalGeometryOverride: true,
      charmGeometryPolicies: Object.keys(CHARM_GEOMETRY_OVERRIDES),
      // Text-only prompt audit by an independent agent, run once BEFORE the
      // single image generation. It can never produce an image.
      supportsCharmPromptPreflight: true,
      promptPreflightMode: "text_only_before_image_generation",
      usesIndependentPromptAuditAgent: true,
      promptAuditProducesImages: false,
      // The manual jump-ring repair is an ordinary single edits request: it
      // runs on the client-selected image model, generates exactly one image,
      // and its preflight contract preserves the charm design 100%.
      supportsManualJumpRingRepair: true,
      manualRepairUsesSelectedModel: true,
      manualRepairMaxImageGenerations: 1,
      manualRepairPreservesCharmDesign: true,
      // One generation per request. What the model returns is what the
      // operator reviews — no automatic retake, no post-generation image QA.
      maxImageGenerationsPerRequest: 1,
      automaticImageRegeneration: false,
      postGenerationImageQA: false,
      // Background policy is enforced natively (generation prompt + text
      // preflight). The old frame-connected flood fill is retired: it could
      // eat bright engraving detail near the frame.
      backgroundEnforcement: "native_generation_prompt_preflight_only",
      destructiveBackgroundFloodFill: false,
      usesBackgroundMasking: false,
      backgroundPolicies: ["solid_black"],
      supportsGenerations: true,
      imageModels: Object.keys(IMAGE_MODEL_CONFIG),
      defaultImageModel: DEFAULT_IMAGE_MODEL,
      defaultCharmRenderModel: preferredCharmRenderModelId(),
      // Custom Charm Studio (storefront). Firebase-ID-token authenticated,
      // storefront-locked CORS, server-side wallet with refund on failure.
      supportsCustomCharmStudio: true,
      customStudioKinds: Array.from(STUDIO_KINDS),
      customStudioAuth: "firebase_id_token",
      customStudioReusesCharmDoctrine: true,
      supportsCustomerReferenceRole: Object.prototype.hasOwnProperty.call(IMAGE_ROLE_LABELS, "customer_reference"),
    });
  }

  if (kind === "charm_concept_plan") {
    try {
      const sourcePath = String(input_storage_path || source_storage_path || "").trim();
      if (!sourcePath) {
        return json(400, { ok: false, error: { message: "input_storage_path is required" } });
      }
      const plan = await planComplementaryCharmConcepts({
        sourceStoragePath: sourcePath,
        count: concept_count,
      });
      return json(200, { ok: true, plan });
    } catch (err) {
      console.error("[charm_concept_plan] failed", safeErr(err));
      return json(502, { ok: false, error: safeErr(err) });
    }
  }

  let modelConfig;
  try {
    modelConfig = resolveImageModel(effectiveRequestImageModel(kind, _clientModel));
  } catch (err) {
    return json(400, { ok: false, error: safeErr(err) });
  }
  const model = modelConfig.id;

  // ============================================================
  // CHARM BATCH ORCHESTRATION — fully server-side, tab-independent.
  // ------------------------------------------------------------
  // One request from the browser hands over the ENTIRE job: the charm
  // list, derivatives count and model. This background function then does
  // everything the browser used to do — per-charm concept planning,
  // per-set folder/snapshot/manifest creation, prompt + embedded-metadata
  // building (via the *Server mirror builders), and dense batch_submit
  // chunks — persisting progress to Firestore as it goes. If the work
  // exceeds one background invocation's budget it SELF-CHAINS: it POSTs
  // itself a resume request and returns. Collection is handled by
  // batch_sweep (fired by charmBatchSweepCron), so neither submission nor
  // collection ever depends on a browser being open.
  // ============================================================
  if (kind === "charm_batch_orchestrate") {
    const db = getDb();
    const bucket = admin.storage().bucket();
    const ORCH_BUDGET_MS = 10.5 * 60 * 1000;
    const ORCH_CHUNK_SETS = 25;
    const startedAtMs = Date.now();

    const inProcess = async (payload) => {
      const res = await module.exports.handler({
        httpMethod: "POST",
        headers: {},
        body: JSON.stringify(payload),
      });
      let parsed = null;
      try { parsed = res && res.body ? JSON.parse(res.body) : null; } catch (_) {}
      return { statusCode: res?.statusCode || 0, body: parsed };
    };

    const selfChain = async (orchestrationId) => {
      const origin = (process.env.URL || process.env.DEPLOY_PRIME_URL || process.env.DEPLOY_URL || "").replace(/\/+$/, "");
      if (!origin) { console.warn("[orchestrate] no site origin env — sweep cron will resume instead"); return; }
      try {
        await fetch(`${origin}/.netlify/functions/geminiImageProxy-background`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ kind: "charm_batch_orchestrate", orchestrationId, resume: true }),
        });
      } catch (e) {
        console.warn("[orchestrate] self-chain failed — sweep cron will resume:", e?.message || e);
      }
    };

    const latestUnderPrefix = async (prefix) => {
      try {
        const [files] = await bucket.getFiles({ prefix, maxResults: 500 });
        let best = null, bestMs = -1;
        for (const f of files) {
          if (f.name.endsWith("/")) continue;
          const ms = Date.parse(f.metadata?.updated || f.metadata?.timeCreated || "") || 0;
          if (ms > bestMs) { bestMs = ms; best = f.name; }
        }
        return best;
      } catch (_) { return null; }
    };

    try {
      let orchRef, orch;
      if (body?.resume && body?.orchestrationId) {
        orchRef = db.collection(ORCH_COLL).doc(String(body.orchestrationId));
        const snap = await orchRef.get();
        if (!snap.exists) return json(404, { ok: false, error: { message: "orchestration not found" } });
        orch = snap.data();
        if (orch.status !== "running") return json(200, { ok: true, orchestrationId: orchRef.id, status: orch.status, note: "already final" });
      } else {
        const charms = Array.isArray(body?.charms)
          ? body.charms
              .map((c) => ({ fullPath: String(c?.fullPath || "").trim(), name: String(c?.name || "").trim() }))
              .filter((c) => c.fullPath)
          : [];
        if (!charms.length) return json(400, { ok: false, error: { message: "charms must be a non-empty array" } });
        const derivCount = Math.max(1, Math.min(8, Number(body?.derivCount) || 1));
        if (charms.length * derivCount > 1000) {
          return json(400, { ok: false, error: { message: "Per-orchestration limit is 1000 sets." } });
        }
        // Resolve the shared refs the manifests record, once per orchestration.
        const earringRef = await latestUnderPrefix("listing-generator-1/Charm_Maker/New_Charms_Earrings/");
        const lineArtRef = await latestUnderPrefix("listing-generator-1/Charm_Maker/Reference_Line_Art_Image/");
        orchRef = db.collection(ORCH_COLL).doc(`orch_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`);
        orch = {
          orchestrationId: orchRef.id,
          sessionId: String(body?.sessionId || orchRef.id),
          model,
          derivCount,
          charms,
          earringRef: earringRef || null,
          lineArtRef: lineArtRef || null,
          cursor: 0,
          setsPlanned: charms.length * derivCount,
          setsPrepared: 0,
          chunksSubmitted: 0,
          batchNames: [],
          prepSkipped: [],
          chunkErrors: [],
          status: "running",
          createdAt: admin.firestore.FieldValue.serverTimestamp(),
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        };
        await firestoreRetry(() => orchRef.set(orch), "orch.create");
      }

      const persist = async (patch) => {
        Object.assign(orch, patch);
        await firestoreRetry(
          () => orchRef.set({ ...patch, updatedAt: admin.firestore.FieldValue.serverTimestamp() }, { merge: true }),
          "orch.update"
        );
      };

      let pendingSets = [];
      let lastStamp = 0;

      const submitPending = async () => {
        if (!pendingSets.length) return;
        const chunk = pendingSets;
        pendingSets = [];
        const partN = (orch.chunksSubmitted || 0) + 1;
        const dn = `cm-charms-${String(orch.sessionId).slice(-8)}-part${partN}`;
        let resp = await inProcess({
          kind: "batch_submit", model: orch.model, sets: chunk,
          imageSize: "2K", displayName: dn, sessionId: orch.sessionId,
        });
        if (!(resp.body && resp.body.ok)) {
          console.warn(`[orchestrate] chunk ${dn} submit failed — retrying once`, resp.body?.error);
          await sleep(8000);
          resp = await inProcess({
            kind: "batch_submit", model: orch.model, sets: chunk,
            imageSize: "2K", displayName: dn, sessionId: orch.sessionId,
          });
        }
        if (resp.body && resp.body.ok) {
          await persist({
            chunksSubmitted: partN,
            batchNames: [...(orch.batchNames || []), resp.body.batchName].filter(Boolean),
          });
        } else {
          await persist({
            chunksSubmitted: partN,
            chunkErrors: [...(orch.chunkErrors || []), { part: partN, sets: chunk.length, error: String(resp.body?.error?.message || `HTTP ${resp.statusCode}`).slice(0, 300) }].slice(0, 40),
          });
        }
        await sleep(2000); // Files API stagger
      };

      while (orch.cursor < orch.charms.length && (Date.now() - startedAtMs) < ORCH_BUDGET_MS) {
        const charm = orch.charms[orch.cursor];
        let plan = null;
        try {
          plan = await planComplementaryCharmConcepts({ sourceStoragePath: charm.fullPath, count: orch.derivCount });
        } catch (planErr) {
          console.warn(`[orchestrate] planning failed for ${charm.name} — skipping`, planErr?.message || planErr);
          await persist({
            cursor: orch.cursor + 1,
            prepSkipped: [...(orch.prepSkipped || []), { charm: charm.name, error: String(planErr?.message || planErr).slice(0, 200) }].slice(0, 60),
          });
          continue;
        }
        const planMeta = {
          version: Number(plan?.version) || 1,
          referenceSubject: cmCleanText(plan?.referenceSubject),
          buyerProfile: cmCleanText(plan?.buyerProfile),
          purchaseSignals: Array.isArray(plan?.purchaseSignals) ? plan.purchaseSignals.slice(0, 6) : [],
        };

        for (let d = 0; d < orch.derivCount; d++) {
          const concept = plan.concepts[d] || plan.concepts[plan.concepts.length - 1];
          let stamp = Date.now() + Math.floor(Math.random() * 10000);
          if (stamp <= lastStamp) stamp = lastStamp + 1;
          lastStamp = stamp;
          const folderId = `Deriv_${stamp}`;
          const outputBase = `listing-generator-1/Charm_Maker/Generated_Charm_Sets/${folderId}`;

          // Reference snapshot (mirror of snapshot_charm_reference, inline).
          let sourceSnapshot = null;
          try {
            const srcFile = bucket.file(charm.fullPath);
            const [exists] = await srcFile.exists();
            if (exists) {
              let mime = "image/png";
              try { const [m] = await srcFile.getMetadata(); mime = String(m?.contentType || mime).toLowerCase(); } catch (_) {}
              const ext = mime.includes("jpeg") || mime.includes("jpg") ? "jpg" : mime.includes("webp") ? "webp" : "png";
              const dst = `${outputBase}/Source_Ref.${ext}`;
              await srcFile.copy(bucket.file(dst));
              try {
                await bucket.file(dst).setMetadata({ metadata: { firebaseStorageDownloadTokens: newDownloadToken() } });
              } catch (_) {}
              sourceSnapshot = dst;
            }
          } catch (snapErr) {
            console.warn(`[orchestrate] snapshot failed for ${folderId}`, snapErr?.message || snapErr);
          }

          const manifest = {
            sourceCharm: charm.fullPath,
            sourceSnapshot,
            sourceEarring: orch.earringRef || null,
            lineArtRef: orch.lineArtRef || null,
            charmConceptPlan: planMeta,
            charmConcept: concept,
            imageDescriptions: {
              necklace: buildCharmImageDescriptionServer(concept, planMeta, "necklace"),
              earring: buildCharmImageDescriptionServer(concept, planMeta, "earring"),
            },
            model: orch.model,
            batchQueued: true,
            orchestrationId: orchRef.id,
            timestamp: new Date().toISOString(),
          };
          try {
            await bucket.file(`${outputBase}/manifest.json`).save(
              Buffer.from(JSON.stringify(manifest, null, 2), "utf8"),
              { contentType: "application/json", resumable: false }
            );
          } catch (mErr) {
            console.warn(`[orchestrate] manifest write failed for ${folderId} — skipping set`, mErr?.message || mErr);
            continue;
          }

          pendingSets.push({
            category: "Charms",
            outputBasePath: outputBase,
            setN: stamp,
            setKind: "charm_maker",
            manifest,
            tasks: [{
              type: "edits",
              slotIndex: 0,
              input_storage_path: charm.fullPath,
              prompt: buildCharmDesignPromptServer(concept, planMeta),
              image_roles: "style_reference",
              background_policy: "solid_black",
              charm_geometry_policy: "flat_integrated_eyelet",
              embed_metadata: buildCharmEmbedMetadataServer(concept, planMeta, "necklace"),
            }],
          });
          orch.setsPrepared = (orch.setsPrepared || 0) + 1;
        }

        await persist({ cursor: orch.cursor + 1, setsPrepared: orch.setsPrepared });
        if (pendingSets.length >= ORCH_CHUNK_SETS) await submitPending();
      }

      // Never carry unsubmitted sets across invocations — flush now.
      await submitPending();

      if (orch.cursor < orch.charms.length) {
        await persist({ status: "running" });
        await selfChain(orchRef.id);
        return json(200, {
          ok: true, orchestrationId: orchRef.id, status: "running",
          progress: { cursor: orch.cursor, of: orch.charms.length, setsPrepared: orch.setsPrepared, chunksSubmitted: orch.chunksSubmitted },
          chained: true,
        });
      }

      await persist({ status: "submitted", finishedAt: admin.firestore.FieldValue.serverTimestamp() });
      return json(200, {
        ok: true, orchestrationId: orchRef.id, status: "submitted",
        setsPrepared: orch.setsPrepared, chunksSubmitted: orch.chunksSubmitted,
        prepSkipped: (orch.prepSkipped || []).length, chunkErrors: orch.chunkErrors || [],
      });
    } catch (err) {
      console.error("[charm_batch_orchestrate] failed", safeErr(err));
      return json(502, { ok: false, error: safeErr(err) });
    }
  }

  // ============================================================
  // CHARM BATCH RECOVERY — resubmit sets that never got images.
  // ------------------------------------------------------------
  // When a submission dies mid-run (browser sleep, deploy, crash), the
  // affected Deriv_ folders are left with a manifest.json + Source_Ref
  // snapshot but NO Slot_1.png. Every expensive artifact — the planned
  // concept, buyer analysis, tailored descriptions — is already in that
  // manifest, so recovery rebuilds each set's slot-0 task FROM the
  // manifest (zero re-planning cost) and resubmits in dense chunks.
  //
  // Safety rails:
  //   • a set whose Slot_1.png exists is finished — skipped;
  //   • a set referenced by an UNCOLLECTED, non-failed batch is already
  //     in flight at Gemini — skipped (no double spend);
  //   • a set with no manifest.charmConcept (pre-concept legacy) is
  //     counted and skipped rather than guessed at.
  // Runs on the background function, self-chains across invocations via
  // a lexicographic folder-name cursor, and reports progress through the
  // same orchestration records the panel already displays.
  // ============================================================
  if (kind === "charm_batch_recover") {
    const db = getDb();
    const bucket = admin.storage().bucket();
    const REC_BUDGET_MS = 10.5 * 60 * 1000;
    const REC_CHUNK_SETS = 25;
    const SETS_PREFIX = "listing-generator-1/Charm_Maker/Generated_Charm_Sets/";
    const startedAtMs = Date.now();

    const inProcess = async (payload) => {
      const res = await module.exports.handler({ httpMethod: "POST", headers: {}, body: JSON.stringify(payload) });
      let parsed = null;
      try { parsed = res && res.body ? JSON.parse(res.body) : null; } catch (_) {}
      return { statusCode: res?.statusCode || 0, body: parsed };
    };
    const selfChain = async (orchestrationId) => {
      const origin = (process.env.URL || process.env.DEPLOY_PRIME_URL || process.env.DEPLOY_URL || "").replace(/\/+$/, "");
      if (!origin) return;
      try {
        await fetch(`${origin}/.netlify/functions/geminiImageProxy-background`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ kind: "charm_batch_recover", orchestrationId, resume: true }),
        });
      } catch (e) { console.warn("[recover] self-chain failed — sweep will resume:", e?.message || e); }
    };

    try {
      let orchRef, orch;
      if (body?.resume && body?.orchestrationId) {
        orchRef = db.collection(ORCH_COLL).doc(String(body.orchestrationId));
        const snap = await orchRef.get();
        if (!snap.exists) return json(404, { ok: false, error: { message: "recovery run not found" } });
        orch = snap.data();
        if (orch.status !== "running") return json(200, { ok: true, orchestrationId: orchRef.id, status: orch.status });
      } else {
        orchRef = db.collection(ORCH_COLL).doc(`rec_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`);
        orch = {
          orchestrationId: orchRef.id,
          sessionId: String(body?.sessionId || orchRef.id),
          type: "recovery",
          model,
          cursorName: "",
          scanned: 0,
          resubmitted: 0,
          alreadyDone: 0,
          inFlightSkipped: 0,
          missingManifest: 0,
          setsPlanned: 0,
          setsPrepared: 0,
          chunksSubmitted: 0,
          batchNames: [],
          chunkErrors: [],
          status: "running",
          createdAt: admin.firestore.FieldValue.serverTimestamp(),
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        };
        await firestoreRetry(() => orchRef.set(orch), "recover.create");
      }

      const persist = async (patch) => {
        Object.assign(orch, patch);
        await firestoreRetry(
          () => orchRef.set({ ...patch, updatedAt: admin.firestore.FieldValue.serverTimestamp() }, { merge: true }),
          "recover.update"
        );
      };

      // Exclusion set: outputBasePaths already sitting in an uncollected,
      // non-failed Gemini batch (submitted, pending, running, or succeeded
      // and awaiting the sweep's collection).
      const normSt = (x) => String(x || "").startsWith("BATCH_STATE_") ? "JOB_STATE_" + String(x).slice(12) : String(x || "");
      const finalFailed = (st) => ["JOB_STATE_FAILED", "JOB_STATE_CANCELLED", "JOB_STATE_EXPIRED"].includes(normSt(st));
      const inFlight = new Set();
      const openSnap = await db.collection(BATCHES_COLL).where("collected", "==", false).limit(500).get();
      openSnap.forEach((d) => {
        const b = d.data();
        if (finalFailed(b.state)) return; // that batch is dead — its sets ARE recoverable
        for (const s of (b.sets || [])) if (s?.outputBasePath) inFlight.add(s.outputBasePath);
      });

      let pendingSets = [];
      const submitPending = async () => {
        if (!pendingSets.length) return;
        const chunk = pendingSets;
        pendingSets = [];
        const partN = (orch.chunksSubmitted || 0) + 1;
        const dn = `cm-recover-${String(orch.sessionId).slice(-8)}-part${partN}`;
        let resp = await inProcess({ kind: "batch_submit", model: orch.model, sets: chunk, imageSize: "2K", displayName: dn, sessionId: orch.sessionId });
        if (!(resp.body && resp.body.ok)) {
          await sleep(8000);
          resp = await inProcess({ kind: "batch_submit", model: orch.model, sets: chunk, imageSize: "2K", displayName: dn, sessionId: orch.sessionId });
        }
        if (resp.body && resp.body.ok) {
          await persist({ chunksSubmitted: partN, resubmitted: (orch.resubmitted || 0), batchNames: [...(orch.batchNames || []), resp.body.batchName].filter(Boolean) });
        } else {
          await persist({ chunksSubmitted: partN, chunkErrors: [...(orch.chunkErrors || []), { part: partN, sets: chunk.length, error: String(resp.body?.error?.message || `HTTP ${resp.statusCode}`).slice(0, 300) }].slice(0, 40) });
        }
        await sleep(2000);
      };

      // Page through set folders lexicographically, resuming past cursorName.
      let query = {
        prefix: SETS_PREFIX,
        delimiter: "/",
        autoPaginate: false,
        maxResults: 500,
      };
      if (orch.cursorName) query.startOffset = SETS_PREFIX + orch.cursorName;
      let exhausted = false;

      while (!exhausted && (Date.now() - startedAtMs) < REC_BUDGET_MS) {
        const [files, nextQuery, apiResp] = await bucket.getFiles(query);
        const prefixes = (apiResp && apiResp.prefixes) || [];
        for (const p of prefixes) {
          if ((Date.now() - startedAtMs) >= REC_BUDGET_MS) break;
          const folderName = p.slice(SETS_PREFIX.length).replace(/\/$/, "");
          if (!folderName.startsWith("Deriv_")) continue;
          if (orch.cursorName && folderName <= orch.cursorName) continue; // startOffset is inclusive
          orch.scanned = (orch.scanned || 0) + 1;

          const base = SETS_PREFIX + folderName;
          try {
            const [slotExists] = await bucket.file(`${base}/Slot_1.png`).exists();
            if (slotExists) { orch.alreadyDone = (orch.alreadyDone || 0) + 1; orch.cursorName = folderName; continue; }
            if (inFlight.has(base)) { orch.inFlightSkipped = (orch.inFlightSkipped || 0) + 1; orch.cursorName = folderName; continue; }

            let manifest = null;
            try {
              const [buf] = await bucket.file(`${base}/manifest.json`).download();
              manifest = JSON.parse(buf.toString("utf8"));
            } catch (_) {}
            if (!manifest || !manifest.charmConcept || !manifest.sourceCharm) {
              orch.missingManifest = (orch.missingManifest || 0) + 1;
              orch.cursorName = folderName;
              continue;
            }

            const concept = manifest.charmConcept;
            const planMeta = manifest.charmConceptPlan || null;
            const inputPath = manifest.sourceSnapshot || manifest.sourceCharm;
            pendingSets.push({
              category: "Charms",
              outputBasePath: base,
              setN: Number((folderName.match(/Deriv_(\d+)/) || [])[1] || 0),
              setKind: "charm_maker",
              manifest,
              tasks: [{
                type: "edits",
                slotIndex: 0,
                input_storage_path: inputPath,
                prompt: buildCharmDesignPromptServer(concept, planMeta),
                image_roles: "style_reference",
                background_policy: "solid_black",
                charm_geometry_policy: "flat_integrated_eyelet",
                embed_metadata: buildCharmEmbedMetadataServer(concept, planMeta, "necklace"),
              }],
            });
            orch.resubmitted = (orch.resubmitted || 0) + 1;
            orch.setsPrepared = orch.resubmitted;
            orch.setsPlanned = orch.resubmitted;
            orch.cursorName = folderName;
            if (pendingSets.length >= REC_CHUNK_SETS) {
              await persist({
                cursorName: orch.cursorName, scanned: orch.scanned, resubmitted: orch.resubmitted,
                alreadyDone: orch.alreadyDone, inFlightSkipped: orch.inFlightSkipped,
                missingManifest: orch.missingManifest, setsPrepared: orch.setsPrepared, setsPlanned: orch.setsPlanned,
              });
              await submitPending();
            }
          } catch (folderErr) {
            console.warn(`[recover] folder ${folderName} failed — skipping`, folderErr?.message || folderErr);
            orch.cursorName = folderName;
          }
        }
        await persist({
          cursorName: orch.cursorName, scanned: orch.scanned, resubmitted: orch.resubmitted,
          alreadyDone: orch.alreadyDone, inFlightSkipped: orch.inFlightSkipped,
          missingManifest: orch.missingManifest, setsPrepared: orch.setsPrepared, setsPlanned: orch.setsPlanned,
        });
        if (nextQuery) { query = nextQuery; } else { exhausted = true; }
      }

      await submitPending();

      if (!exhausted) {
        await persist({ status: "running" });
        await selfChain(orchRef.id);
        return json(200, {
          ok: true, orchestrationId: orchRef.id, status: "running", chained: true,
          progress: { scanned: orch.scanned, resubmitted: orch.resubmitted, alreadyDone: orch.alreadyDone },
        });
      }

      await persist({ status: "submitted", finishedAt: admin.firestore.FieldValue.serverTimestamp() });
      return json(200, {
        ok: true, orchestrationId: orchRef.id, status: "submitted",
        scanned: orch.scanned, resubmitted: orch.resubmitted, alreadyDone: orch.alreadyDone,
        inFlightSkipped: orch.inFlightSkipped, missingManifest: orch.missingManifest,
        chunksSubmitted: orch.chunksSubmitted, chunkErrors: orch.chunkErrors || [],
      });
    } catch (err) {
      console.error("[charm_batch_recover] failed", safeErr(err));
      return json(502, { ok: false, error: safeErr(err) });
    }
  }

  // Lightweight progress read for the Charm Maker panel. Inline-safe.
  if (kind === "charm_batch_status") {
    try {
      const db = getDb();
      const snap = await db.collection(ORCH_COLL).orderBy("createdAt", "desc").limit(20).get();
      const orchestrations = [];
      snap.forEach((doc) => {
        const o = doc.data();
        if (body?.sessionId && o.sessionId !== body.sessionId) return;
        orchestrations.push({
          orchestrationId: o.orchestrationId || doc.id,
          sessionId: o.sessionId || null,
          type: o.type || "orchestration",
          status: o.status || "unknown",
          model: o.model || null,
          scanned: o.scanned || 0,
          resubmitted: o.resubmitted || 0,
          alreadyDone: o.alreadyDone || 0,
          inFlightSkipped: o.inFlightSkipped || 0,
          missingManifest: o.missingManifest || 0,
          charmsTotal: Array.isArray(o.charms) ? o.charms.length : 0,
          cursor: o.cursor || 0,
          setsPlanned: o.setsPlanned || 0,
          setsPrepared: o.setsPrepared || 0,
          chunksSubmitted: o.chunksSubmitted || 0,
          batchNames: (o.batchNames || []).length,
          prepSkipped: (o.prepSkipped || []).length,
          chunkErrors: (o.chunkErrors || []).length,
          createdAt: o.createdAt?.toMillis?.() || null,
          updatedAt: o.updatedAt?.toMillis?.() || null,
        });
      });
      return json(200, { ok: true, orchestrations });
    } catch (err) {
      return json(502, { ok: false, error: safeErr(err) });
    }
  }

  // ============================================================
  // BATCH SWEEP — server-side status refresh + auto-collect + stall
  // recovery. Fired by charmBatchSweepCron every few minutes, so batch
  // results are downloaded into Firebase even when no browser is open.
  // Also resumes orchestrations whose self-chain was dropped.
  // ============================================================
  if (kind === "batch_sweep") {
    const db = getDb();
    const SWEEP_BUDGET_MS = 11 * 60 * 1000;
    const sweepStart = Date.now();
    const guardRef = db.collection("LG1_Config").doc("batchSweep");

    const inProcess = async (payload) => {
      const res = await module.exports.handler({ httpMethod: "POST", headers: {}, body: JSON.stringify(payload) });
      let parsed = null;
      try { parsed = res && res.body ? JSON.parse(res.body) : null; } catch (_) {}
      return parsed;
    };

    try {
      // Overlap guard: skip if another sweep started < 12 minutes ago.
      const guard = await guardRef.get();
      const runningSince = guard.exists ? (guard.data().runningSince?.toMillis?.() || 0) : 0;
      if (runningSince && Date.now() - runningSince < 12 * 60 * 1000) {
        return json(200, { ok: true, skipped: "sweep already running" });
      }
      await guardRef.set({ runningSince: admin.firestore.FieldValue.serverTimestamp() }, { merge: true });

      const normState = (st) => {
        const x = String(st || "");
        return x.startsWith("BATCH_STATE_") ? "JOB_STATE_" + x.slice(12) : x;
      };
      const isFinal = (st) => ["JOB_STATE_FAILED", "JOB_STATE_CANCELLED", "JOB_STATE_EXPIRED"].includes(normState(st));
      const isSucceeded = (st) => normState(st) === "JOB_STATE_SUCCEEDED";

      let statusChecked = 0, collected = 0, collectErrors = 0, resumed = 0;

      const openSnap = await db.collection(BATCHES_COLL).where("collected", "==", false).limit(250).get();
      const open = [];
      openSnap.forEach((d) => open.push(d.data()));
      // Oldest first so long-waiting batches are served before fresh ones.
      open.sort((a, b) => (a.createdAt?.toMillis?.() || 0) - (b.createdAt?.toMillis?.() || 0));

      for (const b of open) {
        if (Date.now() - sweepStart > SWEEP_BUDGET_MS) break;
        if (!b.batchName || isFinal(b.state)) continue;
        let state = b.state;
        if (!isSucceeded(state)) {
          const st = await inProcess({ kind: "batch_status", batchName: b.batchName });
          statusChecked++;
          state = st?.state || state;
        }
        if (isSucceeded(state)) {
          const col = await inProcess({ kind: "batch_collect", batchName: b.batchName });
          if (col?.ok) collected++; else collectErrors++;
        }
      }

      // Resume orchestrations whose self-chain got dropped (no update in 20m).
      const orchSnap = await db.collection(ORCH_COLL).where("status", "==", "running").limit(20).get();
      const origin = (process.env.URL || process.env.DEPLOY_PRIME_URL || process.env.DEPLOY_URL || "").replace(/\/+$/, "");
      const stale = [];
      orchSnap.forEach((d) => {
        const o = d.data();
        const upd = o.updatedAt?.toMillis?.() || 0;
        if (Date.now() - upd > 20 * 60 * 1000) stale.push(o.orchestrationId || d.id);
      });
      for (const id of stale) {
        if (!origin) break;
        try {
          await fetch(`${origin}/.netlify/functions/geminiImageProxy-background`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ kind: "charm_batch_orchestrate", orchestrationId: id, resume: true }),
          });
          resumed++;
        } catch (e) { console.warn("[batch_sweep] orchestration resume failed:", id, e?.message || e); }
      }

      await guardRef.set({
        runningSince: null,
        lastSweepAt: admin.firestore.FieldValue.serverTimestamp(),
        lastResult: { statusChecked, collected, collectErrors, resumed },
      }, { merge: true });
      return json(200, { ok: true, statusChecked, collected, collectErrors, resumed, openBatches: open.length });
    } catch (err) {
      try { await guardRef.set({ runningSince: null }, { merge: true }); } catch (_) {}
      console.error("[batch_sweep] failed", safeErr(err));
      return json(502, { ok: false, error: safeErr(err) });
    }
  }

  // ---------- NEW: non-job operations (no jobId required) ----------
  try {
    if (kind === "alloc_set") {
      const { setN, outputBasePath } = await allocNextSet(activeCategory);
      return json(200, { ok: true, setN, outputBasePath });
    }

    // ============================================================
    // SCAN EMPTY SETS — for partial-failure recovery
    // ------------------------------------------------------------
    // After a batch submission, some Set_N folders may end up empty
    // (allocated by alloc_set but never populated with slot images
    // because the underlying batch failed or never collected). This
    // kind enumerates them so the frontend can offer a "Resume" flow
    // that re-submits batches for just the empty ones, leaving the
    // populated ones untouched.
    //
    // Algorithm:
    //   1. Read the Firestore set counter for the category — gives us
    //      the highest setN that's ever been issued.
    //   2. List every file under Ready_To_List/ in one bucket call.
    //   3. Bucket the files by Set_N. A set with at least one
    //      Slot_*.png file counts as "has content"; everything else
    //      (no files at all, or only a stale manifest) counts as
    //      "empty".
    //   4. Return a sorted list of {setN, outputBasePath} for empty
    //      slots in [1, highestN]. Populated slots are NOT returned.
    // ============================================================
    if (kind === "scan_empty_sets") {
      const cat = normalizeCategory(activeCategory);
      if (!GENERATABLE_CATEGORIES.has(cat)) {
        return json(400, { error: { message: "activeCategory not generatable" } });
      }

      const db = getDb();
      const counterSnap = await db.collection(SET_COUNTERS_COLL).doc(cat).get();
      const highestN = counterSnap.exists ? Number(counterSnap.data()?.nextSetN || 0) : 0;
      if (highestN <= 0) {
        return json(200, { ok: true, highestN, empty: [], populated: [], message: "No sets allocated yet for this category." });
      }

      const bucket = admin.storage().bucket();
      const prefix = `listing-generator-1/${cat}/Ready_To_List/`;
      const [files] = await bucket.getFiles({ prefix });

      // Bucket file names by setN. Track whether each setN has at least
      // one Slot_*.png file (the gating signal for "has content"). A
      // manifest.json alone does not count — alloc_set never writes
      // files, so a folder with only a stale manifest is still "empty"
      // by our definition (the manifest typically arrives only after
      // batch_collect, which also writes slot images).
      const hasSlots = new Set();
      const re = /\/Set_(\d+)\/(Slot_\d+\.png|.+)$/;
      for (const f of files) {
        const m = f.name.match(re);
        if (!m) continue;
        const setN = Number(m[1]);
        const filename = m[2];
        if (/^Slot_\d+\.png$/i.test(filename)) {
          hasSlots.add(setN);
        }
      }

      // Identify already-approved sets so we don't classify them as
      // "empty" and accidentally regenerate them when the user clicks
      // Resume Empty Sets. The approval flow moves files from
      // Ready_To_List/Set_N/ to Completed_Listing_Sets/{cat}_Set_N/,
      // leaving Ready_To_List/Set_N/ empty (no slot images). Without
      // this filter, every approved set would look like a gap and get
      // re-filled with brand-new charms — destroying the user's
      // approved work.
      const approvedSetNs = new Set();
      const completedPrefix = `listing-generator-1/Generated_Listing_Sets/Completed_Listing_Sets/${cat}_Set_`;
      try {
        const [completedFiles] = await bucket.getFiles({ prefix: completedPrefix });
        for (const f of completedFiles) {
          // Path looks like ".../Completed_Listing_Sets/{cat}_Set_42/..."
          const idx = f.name.indexOf(`/${cat}_Set_`);
          if (idx === -1) continue;
          const tail = f.name.slice(idx + `/${cat}_Set_`.length);
          const numStr = tail.split("/")[0];
          const num = Number(numStr);
          if (Number.isFinite(num) && num > 0) approvedSetNs.add(num);
        }
      } catch (e) {
        console.warn("[scan_empty_sets] could not enumerate Completed_Listing_Sets:", e?.message || e);
      }

      const empty = [];
      const populated = [];
      const skippedApproved = [];
      for (let n = 1; n <= highestN; n++) {
        if (approvedSetNs.has(n)) {
          skippedApproved.push(n);
          continue;
        }
        const outputBasePath = `listing-generator-1/${cat}/Ready_To_List/Set_${n}`;
        if (hasSlots.has(n)) {
          populated.push({ setN: n, outputBasePath });
        } else {
          empty.push({ setN: n, outputBasePath });
        }
      }

      return json(200, {
        ok: true,
        highestN,
        emptyCount: empty.length,
        populatedCount: populated.length,
        approvedCount: skippedApproved.length,
        empty,
        // populated and skippedApproved returned only as counts to keep
        // the response payload small for large counters.
      });
    }

    // ============================================================
    // CHARM POOL — pick & release for batch mode
    // ------------------------------------------------------------
    // Each generated set must use a UNIQUE charm from the shared pool,
    // and we must avoid duplicate picks across concurrent submissions.
    //
    // Pick algorithm:
    //   1. List all charms in the active pool (necklace or earring).
    //   2. Enumerate every uncollected batch's `sets[].tasks[].input_charm_storage_path`
    //      to find currently-reserved charms.
    //   3. Subtract: available = pool - reserved.
    //   4. Return the first `count` available paths.
    //
    // Atomicity: the pick step doesn't write anything — the
    // reservation happens implicitly when the caller subsequently
    // submits a batch with these paths in its tasks. There's a small
    // race window (two clients pick same charms simultaneously then
    // both submit), which we accept because:
    //   - The window is sub-second in practice
    //   - The user-visible result is just one charm getting reused
    //     once across two concurrent submissions
    //   - The full atomicity solution (Firestore-tracked reservations
    //     with ttl) adds significant complexity for a problem that
    //     basically only manifests if you submit two batches within
    //     the same second
    // ============================================================
    if (kind === "charm_pool_pick") {
      const isEarring = !!body?.isEarring;
      const want = Math.max(1, Number(body?.count || 1));

      const bucket = admin.storage().bucket();
      const poolPrefix = isEarring
        ? "listing-generator-1/Charm_Maker/New_Charms_Earrings/"
        : "listing-generator-1/Charm_Maker/New_Charms/";

      // Step 1: list pool. Skip pseudo-folders (paths ending with "/").
      const [poolFiles] = await bucket.getFiles({ prefix: poolPrefix });
      const poolPaths = poolFiles
        .map((f) => f.name)
        .filter((n) => !n.endsWith("/") && /\.(png|jpg|jpeg|webp)$/i.test(n));

      if (poolPaths.length === 0) {
        return json(200, { ok: true, charms: [], poolSize: 0, reservedCount: 0 });
      }

      // Step 2: enumerate reservations from uncollected batches.
      const db = getDb();
      const reservedSet = new Set();
      try {
        const snap = await db.collection(BATCHES_COLL)
          .where("collected", "==", false).get();
        snap.forEach((doc) => {
          const sets = Array.isArray(doc.data()?.sets) ? doc.data().sets : [];
          for (const s of sets) {
            for (const t of (s.tasks || [])) {
              const p = t?.input_charm_storage_path;
              if (p) reservedSet.add(p);
            }
          }
        });
      } catch (e) {
        console.warn("charm_pool_pick: failed to enumerate reservations", e?.message || e);
      }

      // Step 3: filter and return.
      const available = poolPaths.filter((p) => !reservedSet.has(p));

      // Shuffle so concurrent submissions don't all start from the
      // same position. Fisher-Yates.
      for (let i = available.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [available[i], available[j]] = [available[j], available[i]];
      }

      const picked = available.slice(0, want);
      return json(200, {
        ok: true,
        charms: picked,
        poolSize: poolPaths.length,
        reservedCount: reservedSet.size,
        availableCount: available.length,
      });
    }

    // ------------------------------------------------------------
    // charm_restore — put a charm back into the active pool.
    //
    // The regenerate flow relocates its charm into the Used pool
    // (New_Charms_Earrings → Used_Earring_Charm_Pool) as soon as the
    // charm is claimed, which is correct when the generation lands but
    // burns the charm when the generation fails: it can never be picked
    // again by charm_pool_pick, even though nothing was produced from
    // it. This is the rollback for that case — call it from the
    // failure branch of a regenerate/generate attempt.
    //
    // Mirror image of the move in batch_collect: copy + delete (Firebase
    // Storage has no native rename), a fresh download token on the
    // destination so any UI expecting one can render it, and per-charm
    // error isolation so one bad path doesn't sink the rest.
    //
    // Idempotent by design. Restoring a charm that is already back in
    // the pool, or whose source object no longer exists, is reported
    // under `skipped` rather than as an error, so a retried failure
    // handler never double-moves or throws.
    //
    // Body: { kind: "charm_restore",
    //         charm_storage_path: "…/Used_Earring_Charm_Pool/x.png" }
    //   or   { kind: "charm_restore", charm_storage_paths: [ … ] }
    // ------------------------------------------------------------
    if (kind === "charm_restore") {
      const requested = Array.isArray(body?.charm_storage_paths)
        ? body.charm_storage_paths
        : (body?.charm_storage_path ? [body.charm_storage_path] : []);

      const paths = requested.map((p) => String(p || "").trim()).filter(Boolean);
      if (!paths.length) {
        return json(400, {
          error: { message: "charm_storage_path (or charm_storage_paths[]) is required" },
        });
      }
      if (paths.length > 500) {
        return json(400, { error: { message: "charm_storage_paths max length is 500" } });
      }

      const CHARM_RESTORE_MAP = [
        ["/Charm_Maker/Used_Earring_Charm_Pool/", "listing-generator-1/Charm_Maker/New_Charms_Earrings/"],
        ["/Charm_Maker/Used_Necklace_Charm_Pool/", "listing-generator-1/Charm_Maker/New_Charms/"],
      ];

      const bucket = getBucket();
      const restored = [];
      const skipped = [];
      const errors = [];

      // De-dupe so a caller passing the same charm twice does one move.
      for (const srcPath of Array.from(new Set(paths))) {
        try {
          const rule = CHARM_RESTORE_MAP.find(([usedPrefix]) => srcPath.includes(usedPrefix));

          if (!rule) {
            const alreadyActive =
              srcPath.includes("/Charm_Maker/New_Charms_Earrings/") ||
              srcPath.includes("/Charm_Maker/New_Charms/");
            skipped.push({
              charm: srcPath,
              reason: alreadyActive
                ? "already in the active pool"
                : "not a Charm_Maker used-pool path",
            });
            continue;
          }

          const filename = srcPath.split("/").pop();
          if (!filename) {
            skipped.push({ charm: srcPath, reason: "path has no filename" });
            continue;
          }
          const destPath = rule[1] + filename;

          const srcFile = bucket.file(srcPath);
          const [exists] = await srcFile.exists();
          if (!exists) {
            // Either an earlier restore already ran (dest exists) or the
            // path was wrong to begin with. Neither is worth failing on.
            const [destExists] = await bucket.file(destPath).exists();
            skipped.push({
              charm: srcPath,
              reason: destExists ? "already restored" : "source object not found",
            });
            continue;
          }

          await srcFile.copy(bucket.file(destPath));
          try {
            await bucket.file(destPath).setMetadata({
              metadata: { firebaseStorageDownloadTokens: newDownloadToken() },
            });
          } catch (_) {}
          await srcFile.delete();

          restored.push({ from: srcPath, to: destPath });
        } catch (e) {
          errors.push({ charm: srcPath, error: String(e?.message || e) });
        }
      }

      return json(200, {
        ok: errors.length === 0,
        restoredCount: restored.length,
        restored,
        skipped,
        errors: errors.slice(0, 50),
      });
    }

    // ============================================================
    // BATCH MODE — Listing Generator only (Charm Maker out of scope)
    //
    // Flow:
    //   1. Client calls batch_submit with an array of `sets`. Each
    //      `set` is { category, outputBasePath, setN, tasks: [...] }
    //      where tasks come from SLOT_MAP. Tasks of type "copy" run
    //      synchronously here (no Gemini call). Tasks of type "edits"
    //      become JSONL lines uploaded to Gemini Files API.
    //   2. Server builds the JSONL with explicit imageConfig.imageSize="2K"
    //      and submits to Gemini batchGenerateContent. The batch name
    //      ("batches/abc123") is persisted in Firestore alongside per-
    //      task routing metadata so we can later land each output in
    //      the correct Slot_N.png path.
    //   3. Client polls batch_status. When state=JOB_STATE_SUCCEEDED,
    //      client calls batch_collect. Server downloads result JSONL,
    //      decodes each base64 image, uploads to its destination, and
    //      writes per-set manifests.
    //
    // Constraint discovery: see `keyForTask()` for how we route results.
    // The Gemini Batch API echoes our per-line `key` in each response,
    // so we encode the routing tuple (setSeq, slotIndex) in the key.
    // ============================================================
    if (kind === "batch_submit") {
      // Memory profiling — log at every stage so we can see where the
      // OOM happens. process.memoryUsage() reports:
      //   rss        = total resident set (everything Node uses)
      //   heapUsed   = JS heap actively used
      //   heapTotal  = JS heap allocated
      //   external   = C++ buffers (file I/O, fetch bodies, etc.)
      //   arrayBuffers = TypedArray-backed buffers (subset of external)
      // The OOM in Netlify is "rss exceeds container limit". Watch rss.
      const memLog = (stage) => {
        try {
          const m = process.memoryUsage();
          const fmt = (n) => (n / 1024 / 1024).toFixed(1) + "MB";
          console.log(`[batch_submit:mem] ${stage} rss=${fmt(m.rss)} heap=${fmt(m.heapUsed)}/${fmt(m.heapTotal)} ext=${fmt(m.external)}`);
        } catch (_) {}
      };
      memLog("entry");

      if (modelConfig.provider !== "gemini" || !modelConfig.supportsBatch) {
        return json(400, {
          error: {
            message:
              "Batch mode is available for Gemini 3.1 Flash Image and Gemini 3 Pro Image. Use Standard mode for OpenAI GPT Image 2.",
          },
        });
      }
      let apiKey;
      try { apiKey = apiKeyForImageModel(modelConfig); }
      catch (err) { return json(400, { error: safeErr(err) }); }
      const batchModel = modelConfig.id;

      const sets = Array.isArray(body?.sets) ? body.sets : null;
      if (!sets || sets.length === 0) {
        return json(400, { error: { message: "sets must be a non-empty array" } });
      }
      // Sanity cap. Even at 200 sets * 8 tasks * ~1.2MB inline data ≈ 1.9GB,
      // we approach the Files API 2GB limit. 100 keeps headroom.
      if (sets.length > 100) {
        return json(400, { error: { message: "Per-batch limit is 100 sets. Split into multiple batches." } });
      }

      const displayName = String(body?.displayName || `lg1-batch-${Date.now()}`).slice(0, 100);
      const imageSize = String(body?.imageSize || "2K").toUpperCase();
      const bucket = admin.storage().bucket();

      // Validate every output_base_path up front so we fail fast.
      for (const s of sets) {
        const cat = normalizeCategory(s?.category);
        if (!GENERATABLE_CATEGORIES.has(cat)) {
          return json(400, { error: { message: `category not generatable: ${cat}` } });
        }
        try { assertAllowedOutputBase(s?.outputBasePath); }
        catch (e) {
          return json(400, { error: { message: `Invalid outputBasePath: ${e.message}` } });
        }
        if (!Array.isArray(s?.tasks) || s.tasks.length === 0) {
          return json(400, { error: { message: `set ${s?.outputBasePath} has no tasks` } });
        }
      }

      // Step A: Run all "copy" tasks synchronously. They don't go through
      // Gemini and shouldn't wait for batch turnaround. This mirrors what
      // copy_to_slot does, but inline so we don't double-network-trip.
      // We also do per-task storagePath validation here.
      let copiedCount = 0;
      let copyErrors = [];
      const copyPromises = [];
      for (const s of sets) {
        const base = s.outputBasePath;
        for (const t of s.tasks) {
          if (String(t?.type) !== "copy") continue;
          const slot = Number(t?.slotIndex);
          if (!Number.isFinite(slot) || slot < 0) continue;
          const src = String(t?.source_storage_path || "").trim();
          if (!src) {
            copyErrors.push({ outputBasePath: base, slotIndex: slot, error: "missing source_storage_path" });
            continue;
          }
          copyPromises.push((async () => {
            try {
              const dst = `${base}/Slot_${slot + 1}.png`;
              const dstFile = bucket.file(dst);
              await bucket.file(src).copy(dstFile);
              const token = newDownloadToken();
              await dstFile.setMetadata({ metadata: { firebaseStorageDownloadTokens: token } });
              copiedCount++;
            } catch (e) {
              copyErrors.push({ outputBasePath: base, slotIndex: slot, error: String(e?.message || e) });
            }
          })());
        }
      }
      await Promise.all(copyPromises);
      memLog("after copy step");

      // Step B: Build the JSONL for "edits" tasks. Each line carries a
      // routing key encoding setIndex and slotIndex so we can place
      // the result back in the right folder.
      //
      // MEMORY-CRITICAL DESIGN NOTE
      // ----------------------------
      // We never accumulate full line OBJECTS in memory. Instead:
      //   1. Worker fetches both reference images.
      //   2. Worker base64-encodes them into a single line object.
      //   3. Worker JSON.stringify's the line, encodes UTF-8 → Buffer.
      //   4. Worker pushes that Buffer into jsonlChunks[] and drops
      //      every other reference (line object, base64 strings, raw
      //      buffers) so GC can reclaim them immediately.
      //
      // This prevents the OOM that happened previously when we held
      // all 96 line objects (each ~1.6MB) alive simultaneously, then
      // doubled memory by serializing them into one giant string.
      // Per worker peak ≈ 5 MB; total peak ≈ jsonlChunks size + (10
      // workers × 5 MB).
      const jsonlChunks = []; // Buffer[] — each chunk is one JSONL line + "\n"
      const routes = []; // parallel array: routes[i] = { setIndex, slotIndex, outputBasePath }
      const fetchJobs = []; // { setIdx, slot, promptT, refPath, charmPath, outputBasePath }
      for (let setIdx = 0; setIdx < sets.length; setIdx++) {
        const s = sets[setIdx];
        for (const t of s.tasks) {
          if (String(t?.type) !== "edits") continue;
          const slot = Number(t?.slotIndex);
          if (!Number.isFinite(slot) || slot < 0) continue;
          const refPath = String(t?.input_storage_path || "").trim();
          const charmPath = String(t?.input_charm_storage_path || "").trim();
          const promptT = String(t?.prompt || "").trim();
          // charmPath is OPTIONAL for single-image tasks (Charm Maker base
          // charms use one style-reference image); the listing compositor
          // still sends both.
          if (!refPath || !promptT) continue;
          fetchJobs.push({
            setIdx, slot, promptT, refPath, charmPath,
            outputBasePath: s.outputBasePath,
            imageRoles: String(t?.image_roles || "").trim() || null,
            backgroundPolicy: String(t?.background_policy || "").trim() || null,
            geometryPolicy: String(t?.charm_geometry_policy || "").trim() || null,
          });
        }
      }

      // Routes need a fixed slot per fetchJob. Pre-populate so workers
      // can write into routes[index] without needing a mutex.
      for (let i = 0; i < fetchJobs.length; i++) {
        const j = fetchJobs[i];
        routes.push({ setIndex: j.setIdx, slotIndex: j.slot, outputBasePath: j.outputBasePath });
      }

      // Fetch + build with low concurrency. See memory note above.
      // Concurrency 10 means at most 10 base64 working sets exist at
      // once. Each working set ≈ 5 MB peak (raw + base64 + stringified
      // line + Buffer chunk). After the worker returns, only the
      // pushed Buffer chunk in jsonlChunks survives.
      const FETCH_CONCURRENCY = 10;
      memLog(`before fetch loop (${fetchJobs.length} jobs)`);
      let fetchCounter = 0;
      await runBoundedConcurrent(fetchJobs, FETCH_CONCURRENCY, async (j, idx) => {
        const [ref, charm] = await Promise.all([
          storagePathToBuffer(j.refPath),
          j.charmPath ? storagePathToBuffer(j.charmPath) : Promise.resolve(null),
        ]);
        const key = `s${j.setIdx}_slot${j.slot}`;

        // Build the line, stringify, encode to Buffer, then explicitly
        // null out big locals so V8 has a strong hint to free them
        // before the next worker iteration starts.
        let line = buildBatchJsonlLine(
          key, j.promptT,
          ref.mime, ref.buffer.toString("base64"),
          charm ? charm.mime : null, charm ? charm.buffer.toString("base64") : null,
          imageSize,
          { imageRoles: j.imageRoles, backgroundPolicy: j.backgroundPolicy, geometryPolicy: j.geometryPolicy }
        );
        let jsonStr = JSON.stringify(line) + "\n";
        line = null;
        const chunkBuf = Buffer.from(jsonStr, "utf8");
        jsonStr = null;

        // jsonlChunks order doesn't matter for correctness — the JSONL
        // routing key on each line tells Gemini which response is which.
        jsonlChunks.push(chunkBuf);
        // Periodic memory log so we see in-loop growth.
        const c = ++fetchCounter;
        if (c === 1 || c % 5 === 0 || c === fetchJobs.length) {
          memLog(`fetch ${c}/${fetchJobs.length}`);
        }
      });
      memLog(`after fetch loop`);

      if (jsonlChunks.length === 0) {
        // Edge case: all-copy batch (no Gemini calls needed). Write
        // manifests immediately and short-circuit. We emit slots in the
        // same shape as the gen-collect path so the Review tab renders
        // consistently regardless of which path produced the set.
        for (const s of sets) {
          const manifestPath = `${s.outputBasePath}/manifest.json`;
          const slotsOut = (s.tasks || [])
            .filter((t) => Number.isFinite(Number(t?.slotIndex)))
            .sort((a, b) => Number(a.slotIndex) - Number(b.slotIndex))
            .map((t) => {
              const slotIdx = Number(t.slotIndex);
              const slot = slotIdx + 1;
              const isCopy = String(t?.type) === "copy";
              return isCopy
                ? {
                    slot,
                    type: "copy",
                    source: t?.source_storage_path || null,
                    originalSource: t?.source_storage_path || null,
                    newCharm: null,
                    output: `${s.outputBasePath}/Slot_${slot}.png`,
                  }
                : {
                    slot,
                    type: "gen",
                    source: t?.input_storage_path || null,
                    originalSource: t?.input_storage_path || null,
                    newCharm: t?.input_charm_storage_path || null,
                    output: null, // not generated (no edits tasks)
                  };
            });
          const m = {
            category: s.category,
            setN: s.setN,
            outputBasePath: s.outputBasePath,
            // For consistency with the gen-collect path. Copy-only sets
            // usually have no gen tasks and therefore no charm, but if
            // there happens to be one task of type !=="copy" with a charm
            // path, we record it.
            sourceCharm: (() => {
              for (const t of (s.tasks || [])) {
                if (String(t?.type) !== "copy" && t?.input_charm_storage_path) {
                  return t.input_charm_storage_path;
                }
              }
              return null;
            })(),
            sourceCharmName: (() => {
              for (const t of (s.tasks || [])) {
                if (String(t?.type) !== "copy" && t?.input_charm_storage_path) {
                  return String(t.input_charm_storage_path).split("/").pop() || null;
                }
              }
              return null;
            })(),
            timestamp: new Date().toISOString(),
            model: batchModel,
            batchMode: false,
            copyOnly: true,
            slots: slotsOut,
          };
          await bucket.file(manifestPath).save(
            Buffer.from(JSON.stringify(m, null, 2), "utf8"),
            { contentType: "application/json", resumable: false }
          );
        }
        return json(200, {
          ok: true, batchName: null, copyOnly: true,
          copied: copiedCount, copyErrors, message: "All tasks were copy-only; no batch job needed."
        });
      }

      // Concat once into a single Buffer for upload. This is the only
      // moment when we hold the full JSONL in memory — and it's a
      // single contiguous Buffer, not a doubled UTF-16 string.
      memLog(`before Buffer.concat (${jsonlChunks.length} chunks)`);
      const jsonlBuffer = Buffer.concat(jsonlChunks);
      const jsonlBytes = jsonlBuffer.length;
      // Free chunk array — Buffer.concat copied them, originals can go.
      jsonlChunks.length = 0;
      memLog(`after Buffer.concat (${(jsonlBytes/1e6).toFixed(1)}MB JSONL)`);

      // Hard cap: Files API limit is 2GB. We reject early to avoid uploading.
      if (jsonlBytes > 1.9 * 1024 * 1024 * 1024) {
        return json(400, {
          error: { message: `JSONL too large (${(jsonlBytes / 1e9).toFixed(2)} GB). Reduce sets per batch.` }
        });
      }

      // Step C: Upload JSONL to Gemini Files API, then create the batch.
      const fileName = await uploadJsonlToGeminiFiles(apiKey, jsonlBuffer, displayName);
      memLog(`after Files API upload`);
      const { batchName, raw } = await createGeminiBatchJob(apiKey, batchModel, fileName, displayName);
      memLog(`after batch create`);

      // Step D: Persist routing data in Firestore. The doc id is a
      // sanitized batch name so the client can fetch it directly.
      const db = getDb();
      const docId = batchDocIdFromName(batchName);
      const persistDoc = {
        batchName,
        docId,
        displayName,
        sessionId: String(body?.sessionId || ""),
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        state: "JOB_STATE_PENDING",
        collected: false,
        model: batchModel,
        imageSize,
        inputFileName: fileName,
        inputJsonlBytes: jsonlBytes,
        // sets metadata (so we can route + write manifests later)
        sets: sets.map((s) => ({
          category: s.category,
          outputBasePath: s.outputBasePath,
          setN: s.setN,
          // "charm_maker" sets carry their own manifest (concept, plan,
          // sourceCharm, snapshot) written by the client at submit time;
          // batch_collect preserves it instead of composing the listing-
          // shaped manifest.
          setKind: String(s.setKind || "") || null,
          manifest: (s.manifest && typeof s.manifest === "object") ? s.manifest : null,
          tasks: s.tasks, // store the raw task list so we can write a faithful manifest later
        })),
        routes,
        copyStats: { copied: copiedCount, errors: copyErrors },
        rawCreate: raw || null,
      };
      await firestoreRetry(
        () => db.collection(BATCHES_COLL).doc(docId).set(persistDoc, { merge: true }),
        "batch.create"
      );

      return json(200, {
        ok: true,
        batchName,
        docId,
        requestCount: routes.length,
        setsCount: sets.length,
        copyStats: { copied: copiedCount, errors: copyErrors },
        inputJsonlBytes: jsonlBytes,
      });
    }

    if (kind === "batch_status") {
      let apiKey;
      try { apiKey = apiKeyForImageModel(modelConfig); }
      catch (err) { return json(400, { error: safeErr(err) }); }

      const batchName = String(body?.batchName || "").trim();
      if (!batchName.startsWith("batches/")) {
        return json(400, { error: { message: "batchName must start with batches/" } });
      }

      const data = await getGeminiBatchJob(apiKey, batchName);
      // Gemini wraps the batch info under .metadata for long-running ops.
      // Per the docs, .metadata.state and .response.responsesFile are
      // where progress and the result file land.
      const state = data?.metadata?.state || data?.state || "UNKNOWN";
      const stats = data?.metadata?.batchStats || data?.batchStats || null;
      const respFile = data?.response?.responsesFile || data?.dest?.fileName || null;

      // Mirror state into Firestore so the dashboard can show it without
      // the user having a tab open during the polling phase.
      try {
        const db = getDb();
        const docId = batchDocIdFromName(batchName);
        await firestoreRetry(
          () => db.collection(BATCHES_COLL).doc(docId).set({
            state, batchStats: stats || null, responsesFile: respFile || null,
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          }, { merge: true }),
          "batch.statusMirror"
        );
      } catch (_) { /* non-fatal */ }

      return json(200, {
        ok: true, batchName, state,
        batchStats: stats, responsesFile: respFile,
        done: state === "JOB_STATE_SUCCEEDED" || state === "JOB_STATE_FAILED" ||
              state === "JOB_STATE_CANCELLED" || state === "JOB_STATE_EXPIRED",
        succeeded: state === "JOB_STATE_SUCCEEDED",
      });
    }

    if (kind === "batch_collect") {
      const apiKey = process.env.GEMINI_API_KEY;
      if (!apiKey) return json(400, { error: { message: "Missing GEMINI_API_KEY env var" } });

      const batchName = String(body?.batchName || "").trim();
      if (!batchName.startsWith("batches/")) {
        return json(400, { error: { message: "batchName must start with batches/" } });
      }

      const db = getDb();
      const docId = batchDocIdFromName(batchName);
      const docSnap = await db.collection(BATCHES_COLL).doc(docId).get();
      if (!docSnap.exists) {
        return json(400, { error: { message: `No Firestore record for ${batchName}. Submit went through here?` } });
      }
      const docData = docSnap.data();

      if (docData.collected) {
        return json(200, { ok: true, alreadyCollected: true, batchName, results: docData.results || null });
      }

      const live = await getGeminiBatchJob(apiKey, batchName);
      const state = live?.metadata?.state || live?.state || "UNKNOWN";
      const forceMode = !!body?.force;

      // Standard download requires SUCCEEDED. Force download accepts any
      // state and pulls whatever responsesFile Google has produced —
      // useful when a job hangs, fails partway, or expires. Only failed
      // lines stay empty; successful ones still upload.
      if (!forceMode && state !== "JOB_STATE_SUCCEEDED") {
        return json(400, { error: { message: `Batch not succeeded; state=${state}. Use Force download to recover partial results.` } });
      }

      const respFileName = live?.response?.responsesFile || live?.dest?.fileName;
      if (!respFileName) {
        if (forceMode) {
          return json(400, { error: { message: `Force download: no result file available yet for state=${state}. Try again later or cancel.` } });
        }
        return json(500, { error: { message: "Succeeded batch has no responsesFile/fileName" } });
      }

      // STREAMING COLLECT
      // ------------------
      // We can't load the result JSONL into memory (potentially 2GB+) and
      // we can't queue every decoded image buffer either. Instead we
      // stream the JSONL line-by-line, decode each image inline, and
      // dispatch uploads through a bounded-concurrency worker pool.
      //
      // Concurrency limit (UPLOAD_CONCURRENCY) caps in-flight buffers,
      // keeping peak RAM at roughly UPLOAD_CONCURRENCY × ~3MB ≈ 60MB
      // even when collecting 100-set batches. Well under Netlify's
      // 1.5GB free-tier / 3GB Pro-tier function memory cap.
      const UPLOAD_CONCURRENCY = 20;

      const bucket = admin.storage().bucket();
      const routes = Array.isArray(docData.routes) ? docData.routes : [];
      const setsMeta = Array.isArray(docData.sets) ? docData.sets : [];

      const routeByKey = new Map();
      for (let i = 0; i < routes.length; i++) {
        const r = routes[i];
        routeByKey.set(`s${r.setIndex}_slot${r.slotIndex}`, r);
      }

      // Per-task PNG metadata (tailored design descriptions) recorded at
      // submit time — embedded into each result image before upload, exactly
      // like the synchronous edits path does.
      const embedByKey = new Map();
      for (let setIdx = 0; setIdx < setsMeta.length; setIdx++) {
        for (const t of (setsMeta[setIdx]?.tasks || [])) {
          const slot = Number(t?.slotIndex);
          if (!Number.isFinite(slot)) continue;
          if (t?.embed_metadata && typeof t.embed_metadata === "object") {
            embedByKey.set(`s${setIdx}_slot${slot}`, t.embed_metadata);
          }
        }
      }

      let succeededCount = 0;
      let failedCount = 0;
      const perSetSlotResults = new Map();
      const failures = [];

      // Producer: streams parsed lines from Google's result JSONL and
      // pushes upload tasks into a bounded queue. Consumers drain the
      // queue concurrently. We use a simple semaphore (slots[]) to
      // throttle in-flight uploads without buffering the whole list.
      const inFlight = new Set();
      const recordResult = (route, ok, storagePath, error) => {
        const arr = perSetSlotResults.get(route.setIndex) || [];
        if (ok) {
          succeededCount++;
          arr.push({ slotIndex: route.slotIndex, ok: true, storagePath });
        } else {
          failedCount++;
          failures.push({ key: `s${route.setIndex}_slot${route.slotIndex}`, error });
          arr.push({ slotIndex: route.slotIndex, ok: false, error });
        }
        perSetSlotResults.set(route.setIndex, arr);
      };

      const uploadOne = async (route, buffer, key) => {
        try {
          const embed = embedByKey.get(key);
          if (embed) buffer = embedPngTextMetadata(buffer, embed);
          const storagePath = `${route.outputBasePath}/Slot_${route.slotIndex + 1}.png`;
          const file = bucket.file(storagePath);
          const token = newDownloadToken();
          await file.save(buffer, {
            resumable: false,
            contentType: "image/png",
            metadata: { metadata: { firebaseStorageDownloadTokens: token } },
          });
          recordResult(route, true, storagePath);
        } catch (e) {
          recordResult(route, false, null, String(e?.message || e));
        }
        // Buffer drops out of scope once this fn returns; GC reclaims it.
      };

      // Drive the stream. For each line, parse → find route → decode b64
      // → spawn upload promise. If we hit the concurrency cap, wait for
      // the fastest one to finish before spawning the next. This keeps
      // memory bounded by UPLOAD_CONCURRENCY × per-image size.
      try {
        for await (const parsed of streamGeminiResultLines(apiKey, respFileName)) {
          const key = parsed?.key;
          const route = routeByKey.get(key);
          if (!route) {
            failures.push({ key: key || "(none)", error: "no route for key" });
            continue;
          }
          if (parsed?.error) {
            recordResult(route, false, null, parsed.error?.message || "batch error");
            continue;
          }
          const partsOut = parsed?.response?.candidates?.[0]?.content?.parts || [];
          const imgPart = partsOut.find((p) => p?.inline_data?.data) ||
                          partsOut.find((p) => p?.inlineData?.data) || null;
          const b64 = imgPart?.inline_data?.data || imgPart?.inlineData?.data;
          if (!b64) {
            recordResult(route, false, null, "no inline_data in response");
            continue;
          }

          // Decode + queue. Throttle once we hit the concurrency cap.
          const buffer = Buffer.from(b64, "base64");
          const p = uploadOne(route, buffer, key).finally(() => inFlight.delete(p));
          inFlight.add(p);
          if (inFlight.size >= UPLOAD_CONCURRENCY) {
            await Promise.race(inFlight);
          }
        }
        // Drain any remaining in-flight uploads.
        await Promise.all(inFlight);
      } catch (streamErr) {
        // If the stream itself fails, surface the partial state so the
        // user can see what was already uploaded before the break.
        await Promise.all(inFlight);
        failures.push({ key: "(stream)", error: String(streamErr?.message || streamErr) });
      }

      // Step: write a manifest per set, mirroring what Standard mode writes.
      // Manifest format intentionally matches the existing structure so the
      // Approved/Review tabs render batch results identically.
      //
      // The Review tab (loadSetImages → manifest.slots[].source) needs each
      // slot entry to carry its original `source` storage path so the UI
      // can display "Source: …". Standard mode also writes `newCharm` for
      // gen slots; we preserve that field here for cross-mode parity.
      for (let setIdx = 0; setIdx < setsMeta.length; setIdx++) {
        const s = setsMeta[setIdx];
        const slotResults = (perSetSlotResults.get(setIdx) || []).sort((a, b) => a.slotIndex - b.slotIndex);

        // Build a slotIndex → original-task lookup so we can pull source/newCharm.
        const taskBySlot = new Map();
        for (const t of (s.tasks || [])) {
          if (Number.isFinite(Number(t?.slotIndex))) taskBySlot.set(Number(t.slotIndex), t);
        }

        // Compose the slots array. We emit one entry per planned slot
        // (not just the ones that came back from Gemini), so the Review
        // tab can render every slot with its source label even if a
        // particular gen failed.
        const planSlotsByIndex = new Map();
        for (const t of (s.tasks || [])) {
          if (Number.isFinite(Number(t?.slotIndex))) planSlotsByIndex.set(Number(t.slotIndex), t);
        }
        const allSlotIndices = Array.from(planSlotsByIndex.keys()).sort((a, b) => a - b);

        const slotsOut = allSlotIndices.map((slotIdx) => {
          const t = planSlotsByIndex.get(slotIdx);
          // Look up generation result, if any (copies have no result entry — they
          // succeeded synchronously at submit time).
          const r = slotResults.find((x) => x.slotIndex === slotIdx);
          const isCopy = String(t?.type) === "copy";
          // For copy tasks, source == the synced source; output path is canonical.
          const slot = slotIdx + 1;
          if (isCopy) {
            return {
              slot,
              type: "copy",
              source: t?.source_storage_path || null,
              originalSource: t?.source_storage_path || null,
              newCharm: null,
              output: `${s.outputBasePath}/Slot_${slot}.png`,
            };
          }
          // Gen task. r may be undefined if Gemini didn't return this key
          // (e.g., upstream filtering); we still emit the slot for UI consistency.
          return {
            slot,
            type: r?.ok === false ? "error" : "gen",
            source: t?.input_storage_path || null,
            originalSource: t?.input_storage_path || null,
            newCharm: t?.input_charm_storage_path || null,
            output: (r?.ok && r?.storagePath) ? r.storagePath : null,
            error: r?.error || null,
          };
        });

        // Charm Maker sets: the client wrote a full charm-maker manifest
        // (sourceCharm, sourceSnapshot, charmConcept, charmConceptPlan, …)
        // at submit time and batch_submit persisted a copy. Preserve that
        // shape — the Charm Maker card UI, ref preview, concept summary and
        // Redo flow all read those fields — and just stamp the batch
        // metadata + slot results onto it.
        if (String(s.setKind || "") === "charm_maker") {
          const cmManifest = {
            ...((s.manifest && typeof s.manifest === "object") ? s.manifest : {}),
            batchMode: true,
            batchName,
            batchState: state,
            partial: forceMode && state !== "JOB_STATE_SUCCEEDED",
            imageSize: docData.imageSize || "2K",
            model: (s.manifest && s.manifest.model) || docData.model || preferredCharmRenderModelId(),
            batchSlots: slotsOut,
            collectedAt: new Date().toISOString(),
          };
          const cmManifestPath = `${s.outputBasePath}/manifest.json`;
          try {
            await bucket.file(cmManifestPath).save(
              Buffer.from(JSON.stringify(cmManifest, null, 2), "utf8"),
              { contentType: "application/json", resumable: false }
            );
          } catch (e) {
            failures.push({ key: `manifest:${s.outputBasePath}`, error: String(e?.message || e) });
          }
          continue;
        }

        const m = {
          category: s.category,
          setN: s.setN,
          outputBasePath: s.outputBasePath,
          // Lock the listing's charm into the manifest so the Review tab's
          // Redo flow can recover it even after batch_collect moves the
          // charm out of New_Charms/ into Used_*_Charm_Pool/. We pull
          // from the first gen task with an input_charm_storage_path; in
          // batch mode every gen task in a set shares the same charm
          // (one charm per listing).
          sourceCharm: (() => {
            for (const t of (s.tasks || [])) {
              if (String(t?.type) !== "copy" && t?.input_charm_storage_path) {
                return t.input_charm_storage_path;
              }
            }
            return null;
          })(),
          sourceCharmName: (() => {
            for (const t of (s.tasks || [])) {
              if (String(t?.type) !== "copy" && t?.input_charm_storage_path) {
                return String(t.input_charm_storage_path).split("/").pop() || null;
              }
            }
            return null;
          })(),
          timestamp: new Date().toISOString(),
          model: docData.model || preferredCharmRenderModelId(),
          batchMode: true,
          batchName,
          batchState: state,
          partial: forceMode && state !== "JOB_STATE_SUCCEEDED",
          imageSize: docData.imageSize || "2K",
          slots: slotsOut,
        };
        const manifestPath = `${s.outputBasePath}/manifest.json`;
        try {
          await bucket.file(manifestPath).save(
            Buffer.from(JSON.stringify(m, null, 2), "utf8"),
            { contentType: "application/json", resumable: false }
          );
        } catch (e) {
          failures.push({ key: `manifest:${s.outputBasePath}`, error: String(e?.message || e) });
        }
      }

      // Move used charms out of the active pool.
      // ---------------------------------------
      // After successful collection, every unique charm path referenced
      // in this batch's tasks is moved to the matching Used pool:
      //   New_Charms          → Used_Necklace_Charm_Pool
      //   New_Charms_Earrings → Used_Earring_Charm_Pool
      //
      // This ensures the same charm never gets picked again by a
      // future submission. Move happens AFTER images write so a
      // mid-collection failure doesn't strand the charm in the wrong
      // place. We use copy+delete (not rename, which Firebase Storage
      // doesn't support natively) and ignore per-charm errors so a
      // single flaky charm doesn't block the batch from being marked
      // collected.
      const charmsUsed = new Set();
      for (const s of setsMeta) {
        for (const t of (s.tasks || [])) {
          const p = t?.input_charm_storage_path;
          if (p) charmsUsed.add(p);
        }
      }
      const charmMoveErrors = [];
      let charmsMoved = 0;
      for (const srcPath of charmsUsed) {
        try {
          let destPrefix = null;
          if (srcPath.includes("/Charm_Maker/New_Charms_Earrings/")) {
            destPrefix = "listing-generator-1/Charm_Maker/Used_Earring_Charm_Pool/";
          } else if (srcPath.includes("/Charm_Maker/New_Charms/")) {
            destPrefix = "listing-generator-1/Charm_Maker/Used_Necklace_Charm_Pool/";
          } else {
            // Charm came from somewhere else — don't move it.
            continue;
          }
          const filename = srcPath.split("/").pop();
          if (!filename) continue;
          const destPath = destPrefix + filename;

          const srcFile = bucket.file(srcPath);
          const [exists] = await srcFile.exists();
          if (!exists) {
            // Already moved by an earlier collection of an overlapping
            // batch — not an error, just skip.
            continue;
          }
          await srcFile.copy(bucket.file(destPath));
          // Preserve a download token on the destination so it renders
          // in any UI that expects one.
          try {
            await bucket.file(destPath).setMetadata({
              metadata: { firebaseStorageDownloadTokens: newDownloadToken() },
            });
          } catch (_) {}
          await srcFile.delete();
          charmsMoved++;
        } catch (e) {
          charmMoveErrors.push({ charm: srcPath, error: String(e?.message || e) });
        }
      }

      // Mark Firestore record as collected.
      await firestoreRetry(
        () => db.collection(BATCHES_COLL).doc(docId).set({
          collected: true,
          collectedAt: admin.firestore.FieldValue.serverTimestamp(),
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          results: {
            succeededCount, failedCount, failures: failures.slice(0, 200),
            charmsMoved, charmMoveErrors: charmMoveErrors.slice(0, 50),
          },
        }, { merge: true }),
        "batch.markCollected"
      );

      return json(200, {
        ok: true, batchName, collected: true,
        succeededCount, failedCount,
        charmsMoved, charmMoveErrors: charmMoveErrors.slice(0, 20),
        failures: failures.slice(0, 50),
      });
    }

    if (kind === "batch_list") {
      const includeCollected = !!body?.includeCollected;
      // Ceiling raised from 200 → 1000 so the panel and the per-batch
      // collect-poll loop can find batches in submissions of up to 1000
      // sets. Default stays at 50 (cheap query for the common small case).
      const limit = clampNumber(body?.limit, 1, 1000, 50);
      const db = getDb();
      let q = db.collection(BATCHES_COLL).orderBy("createdAt", "desc").limit(limit);
      const snap = await q.get();
      const out = [];
      snap.forEach((doc) => {
        const d = doc.data();
        if (!includeCollected && d.collected) return;
        out.push({
          docId: doc.id,
          batchName: d.batchName,
          displayName: d.displayName,
          sessionId: d.sessionId || null,
          model: d.model || preferredCharmRenderModelId(),
          state: d.state,
          collected: !!d.collected,
          batchStats: d.batchStats || null,
          createdAt: d.createdAt?.toMillis ? d.createdAt.toMillis() : null,
          updatedAt: d.updatedAt?.toMillis ? d.updatedAt.toMillis() : null,
          collectedAt: d.collectedAt?.toMillis ? d.collectedAt.toMillis() : null,
          setsCount: Array.isArray(d.sets) ? d.sets.length : 0,
          requestCount: Array.isArray(d.routes) ? d.routes.length : 0,
          results: d.results || null,
        });
      });
      return json(200, { ok: true, batches: out });
    }

    if (kind === "batch_cancel") {
      const apiKey = process.env.GEMINI_API_KEY;
      if (!apiKey) return json(400, { error: { message: "Missing GEMINI_API_KEY env var" } });
      const batchName = String(body?.batchName || "").trim();
      if (!batchName.startsWith("batches/")) {
        return json(400, { error: { message: "batchName must start with batches/" } });
      }
      await cancelGeminiBatchJob(apiKey, batchName);
      try {
        const db = getDb();
        await firestoreRetry(
          () => db.collection(BATCHES_COLL).doc(batchDocIdFromName(batchName)).set({
            state: "JOB_STATE_CANCELLED",
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          }, { merge: true }),
          "batch.cancelMirror"
        );
      } catch (_) { /* non-fatal */ }
      return json(200, { ok: true, cancelled: true, batchName });
    }

    // ------------------------------------------------------------
    // files_cleanup
    //   Lists ALL files uploaded to the Gemini Files API for this API key
    //   and deletes them. Used to free the 20 GB cumulative
    //   file_storage_bytes quota that accumulates across batch_submit
    //   JSONL/reference uploads.
    //
    //   Optional body params:
    //     maxDelete  number  — cap deletion at N files this call (default:
    //                          no cap; use for chunked cleanup if you
    //                          have thousands of files and the function
    //                          might time out)
    //     prefix     string  — only delete files whose displayName starts
    //                          with this prefix (e.g., "lg1-Beady_Necklace-").
    //                          Useful if the same API key is shared with
    //                          other projects.
    //
    //   Returns:
    //     { ok, deleted, totalListed, candidateCount, bytesFreed,
    //       truncated, errors }
    //
    //   CAUTION: deleting Files API uploads breaks any in-flight batch
    //   jobs that still reference those input files. Caller is responsible
    //   for confirmation before invoking.
    // ------------------------------------------------------------
    if (kind === "files_cleanup") {
      const apiKey = process.env.GEMINI_API_KEY;
      if (!apiKey) return json(400, { error: { message: "Missing GEMINI_API_KEY env var" } });

      const maxDeleteRaw = Number(body?.maxDelete);
      const maxDelete = Number.isFinite(maxDeleteRaw) && maxDeleteRaw > 0 ? maxDeleteRaw : Infinity;
      const prefix = typeof body?.prefix === "string" && body.prefix.length > 0 ? body.prefix : null;

      const baseUrl = "https://generativelanguage.googleapis.com/v1beta";

      // 1) Paginate through all files. Hard guard against runaway
      //    pagination at 200 pages × 100/page = 20,000 files.
      const listed = [];
      let pageToken = null;
      let pages = 0;
      const MAX_PAGES = 200;
      do {
        const url = `${baseUrl}/files?key=${encodeURIComponent(apiKey)}&pageSize=100` +
                    (pageToken ? `&pageToken=${encodeURIComponent(pageToken)}` : "");
        const r = await fetch(url);
        if (!r.ok) {
          const errBody = await r.text().catch(() => "");
          return json(r.status, {
            error: { message: `Files API list failed: HTTP ${r.status}: ${errBody.slice(0, 300)}` },
          });
        }
        const data = await r.json();
        for (const f of (data.files || [])) listed.push(f);
        pageToken = data.nextPageToken || null;
        pages++;
      } while (pageToken && pages < MAX_PAGES);

      // 2) Optional displayName prefix filter
      const candidates = prefix
        ? listed.filter((f) => typeof f.displayName === "string" && f.displayName.startsWith(prefix))
        : listed.slice();

      // 3) Cap deletion count (for chunked cleanup if maxDelete supplied)
      const toDelete = maxDelete === Infinity
        ? candidates
        : candidates.slice(0, maxDelete);

      // 4) Delete with concurrency 10 — fast enough that even 1000s of
      //    files complete inside the 15-minute background-function budget,
      //    while not so parallel that we trigger our own rate-limit on
      //    the Files API delete endpoint.
      let deleted = 0;
      let bytesFreed = 0;
      const errors = [];
      let idx = 0;
      const CONC = 10;

      async function deleteWorker() {
        while (idx < toDelete.length) {
          const myIdx = idx++;
          const f = toDelete[myIdx];
          try {
            const delUrl = `${baseUrl}/${f.name}?key=${encodeURIComponent(apiKey)}`;
            const r = await fetch(delUrl, { method: "DELETE" });
            if (!r.ok) {
              const errBody = await r.text().catch(() => "");
              errors.push(`${f.name}: HTTP ${r.status} ${errBody.slice(0, 80)}`);
            } else {
              deleted++;
              bytesFreed += Number(f.sizeBytes || 0);
            }
          } catch (e) {
            errors.push(`${f.name}: ${e?.message || e}`);
          }
        }
      }

      const workers = [];
      for (let i = 0; i < CONC; i++) workers.push(deleteWorker());
      await Promise.all(workers);

      return json(200, {
        ok: true,
        deleted,
        totalListed: listed.length,
        candidateCount: candidates.length,
        bytesFreed,
        truncated: candidates.length > toDelete.length,
        errors: errors.slice(0, 20),
      });
    }

// ------------------------------------------------------------
    // NEW: run_set_async
    // - One request kicks off the whole set
    // - Server processes tasks ASYNCHRONOUSLY (Parallel)
    // - Enforces delayMs only on START times (staggered launch)
    // ------------------------------------------------------------
    if (kind === "run_set_async") {
      const cat = normalizeCategory(activeCategory);
      if (!GENERATABLE_CATEGORIES.has(cat)) {
        return json(400, { error: { message: "activeCategory not generatable" } });
      }

      const base = assertAllowedOutputBase(output_base_path);
      const delayMs = clampNumber(body?.delayMs ?? body?.delay_ms ?? 1000, 0, 10000, 1000);
      const tasks = Array.isArray(body?.tasks) ? body.tasks : null;
      if (!tasks || !tasks.length) {
        return json(400, { error: { message: "tasks must be a non-empty array" } });
      }
      if (tasks.length > 8) {
        return json(400, { error: { message: "tasks max length is 8" } });
      }

      let apiKey;
      try { apiKey = apiKeyForImageModel(modelConfig); }
      catch (err) { return json(400, { error: safeErr(err) }); }

      const runToken =
        globalThis.crypto?.randomUUID ? globalThis.crypto.randomUUID() : require("crypto").randomUUID();

      // ✅ FIX: Use Promise.all() to run tasks in parallel
      // We map the tasks to an array of promises, allowing them to execute concurrently.
      await Promise.all(tasks.map(async (t, i) => {
        const slot = Number(t?.slotIndex);
        if (!Number.isFinite(slot) || slot < 0) return;

        try {
          // ✅ STAGGERED START:
          // Instead of waiting for the previous task to *finish*, we only delay the *start*.
          // Task 0 starts at 0ms. Task 1 starts at 1500ms (if delayMs=1500).
          // They will all be processing simultaneously after the initial delay.
          const startDelay = i * delayMs;
          if (startDelay > 0) await sleep(startDelay);

          const bucket = admin.storage().bucket();

          // 1. Handle "Copy" tasks (instant)
          if (String(t?.type) === "copy") {
            const src = String(t?.source_storage_path || "").trim();
            if (!src) throw new Error("copy task missing source_storage_path");
            const dst = `${base}/Slot_${slot + 1}.png`;
            const dstFile = bucket.file(dst);
            
            await bucket.file(src).copy(dstFile);

            // Ensure browser previews can load: getDownloadURL() relies on firebaseStorageDownloadTokens.
            const token = newDownloadToken();
            await dstFile.setMetadata({ metadata: { firebaseStorageDownloadTokens: token } });
            return; // Done with this task
          }

          // 2. Handle image edit tasks with the selected provider.
          const basePath0 = String(t?.input_storage_path || "").trim();
          const basePath1 = String(t?.input_charm_storage_path || "").trim();
          const promptT = String(t?.prompt || "").trim();
          
          if (!basePath0 || !basePath1 || !promptT) {
               console.warn(`Skipping invalid task slot ${slot}`);
               return;
          }

          const img0 = await storagePathToBuffer(basePath0);
          const img1 = await storagePathToBuffer(basePath1);

          // Retry transient overload/rate-limit failures for either provider.
          let outBuf = await callImageWithRetry(async () => {
             return await callImageModelEdits({
              apiKey,
              model,
              prompt: promptT,
              size: String(t?.size || body?.size || "2048x2048"),
              quality: String(
                t?.quality ||
                body?.quality ||
                (modelConfig.provider === "openai" ? "medium" : "high")
              ),
              output_format: "png",
              images: [
                { buffer: img0.buffer, mime: img0.mime, filename: filenameForMime("image0", img0.mime) },
                { buffer: img1.buffer, mime: img1.mime, filename: filenameForMime("image1", img1.mime) },
              ],
            });
          }, `${modelConfig.provider}_slot_${slot}`);

          outBuf = await applyFinalFrameZoomIfNeeded(outBuf, t?.postprocess || body?.postprocess);
          
          // Upload result (Client polling will detect this file appearing)
          await uploadPngBufferToSetPath(outBuf, base, slot, null, runToken);

        } catch (err) {
          console.error(`[run_set_async] task failed at slot ${slot}`, safeErr(err));
          // We catch errors here so Promise.all() doesn't fail the entire set if one slot fails.
        }
      }));

      // Return successful completion (client received 202 long ago)
      return json(200, { ok: true, finished: true, runId: runToken });
    }

    if (kind === "snapshot_charm_reference") {
      const cat = normalizeCategory(activeCategory);
      if (cat !== "Charms") {
        return json(400, { error: { message: "snapshot_charm_reference is restricted to Charms" } });
      }
      const src = String(source_storage_path || "").trim();
      if (!src) return json(400, { error: { message: "source_storage_path is required" } });

      const allowedSource = [
        "listing-generator-1/Charm_Maker/",
        "listing-generator-1/Charms/",
      ].some((prefix) => src.startsWith(prefix));
      if (!allowedSource) {
        return json(400, { error: { message: "source_storage_path not allowed" } });
      }
      const base = assertAllowedOutputBase(output_base_path);
      const bucket = admin.storage().bucket();
      const sourceFile = bucket.file(src);
      const [exists] = await sourceFile.exists();
      if (!exists) return json(404, { error: { message: "source_storage_path not found" } });
      let mime = "image/png";
      try {
        const [meta] = await sourceFile.getMetadata();
        mime = String(meta?.contentType || mime).toLowerCase();
      } catch (_) {}
      const ext = mime.includes("jpeg") || mime.includes("jpg")
        ? "jpg"
        : mime.includes("webp")
          ? "webp"
          : "png";
      const dst = `${base}/Source_Ref.${ext}`;
      const dstFile = bucket.file(dst);
      await sourceFile.copy(dstFile);
      const token = newDownloadToken();
      await dstFile.setMetadata({ metadata: { firebaseStorageDownloadTokens: token } });
      return json(200, {
        ok: true,
        storagePath: dst,
        downloadURL: tokenDownloadURLFor(bucket.name, dst, token),
      });
    }

    if (kind === "copy_to_slot") {
      const cat = normalizeCategory(activeCategory);
      if (!GENERATABLE_CATEGORIES.has(cat)) return json(400, { error: { message: "activeCategory not generatable" } });

      const src = String(source_storage_path || "").trim();
      if (!src) return json(400, { error: { message: "source_storage_path is required" } });

      const base = assertAllowedOutputBase(output_base_path);
      const effectiveSlot = Number.isFinite(Number(slotIndex)) && Number(slotIndex) >= 0 ? Number(slotIndex) : 0;
      const dst = `${base}/Slot_${effectiveSlot + 1}.png`;

      const bucket = admin.storage().bucket();
       const dstFile = bucket.file(dst);
       await bucket.file(src).copy(dstFile);

       // Ensure a Firebase download token exists on the copied object.
       const token = newDownloadToken();
       await dstFile.setMetadata({ metadata: { firebaseStorageDownloadTokens: token } });
       const downloadURL = tokenDownloadURLFor(bucket.name, dst, token);
      return json(200, { ok: true, storagePath: dst, downloadURL });
    }

   if (kind === "edits") {
      const cat = normalizeCategory(activeCategory);
      if (!GENERATABLE_CATEGORIES.has(cat)) return json(400, { error: { message: "activeCategory not generatable" } });

      const basePath0 = String(input_storage_path || "").trim();
      const basePath1 = String(input_charm_storage_path || "").trim();
      if (!basePath0) return json(400, { error: { message: "input_storage_path is required" } });
      // input_charm_storage_path is OPTIONAL.
      //   • Two-image flow (regeneration / fresh composite): caller supplies
      //     both — image0 is the model/reference, image1 is the charm — and
      //     the selected image model composites them per the prompt.
      //   • One-image flow (in-place edit / Listing-Generator adjustment-mode
      //     redo): caller supplies only basePath0 and a prompt that describes
      //     the requested edit. We send a single image so the model does
      //     not search for differences between two identical inputs or try
      //     to composite them.

      let apiKey;
      try { apiKey = apiKeyForImageModel(modelConfig); }
      catch (err) { return json(400, { error: safeErr(err) }); }

      const outputBasePath = assertAllowedOutputBase(output_base_path);
      const effectiveSlot = Number.isFinite(Number(slotIndex)) && Number(slotIndex) >= 0 ? Number(slotIndex) : 0;

      const img0 = await storagePathToBuffer(basePath0);
      const img1 = basePath1 ? await storagePathToBuffer(basePath1) : null;

      const images = [
        { buffer: img0.buffer, mime: img0.mime, filename: filenameForMime("image0", img0.mime) },
      ];
      if (img1) {
        images.push({ buffer: img1.buffer, mime: img1.mime, filename: filenameForMime("image1", img1.mime) });
      }

      // ------------------------------------------------------------
      // Charm Maker pipeline (any request declaring a charm policy):
      //   1. TEXT-ONLY prompt preflight by an independent audit agent
      //      (best-effort — a failed audit never blocks generation);
      //   2. exactly ONE image generation, with the geometry/background
      //      policies appended by the backend as the request's final word;
      //   3. no post-generation image QA, no masking, no flood fill, no
      //      automatic second image — what the model returns is what the
      //      operator reviews.
      // ------------------------------------------------------------
      const isCharmPipeline = !!(background_policy || charm_geometry_policy || charm_edit_intent);
      let effectivePrompt = prompt;
      if (isCharmPipeline) {
        const audited = await auditCharmPromptPreflight({
          prompt,
          backgroundPolicy: background_policy,
          geometryPolicy: charm_geometry_policy,
          editIntent: charm_edit_intent,
          imageCount: images.length,
          imageRoles: image_roles,
        });
        if (audited) effectivePrompt = audited;
      }

      let outBuf = await callImageModelEdits({
        apiKey,
        model,
        prompt: effectivePrompt,
        size,
        quality,
        output_format,
        images,
        imageRoles: image_roles,
        charmGeometryPolicy: charm_geometry_policy,
        backgroundPolicy: background_policy,
      });

      outBuf = await applyFinalFrameZoomIfNeeded(outBuf, postprocess);

      // Write the caller-supplied design description into the PNG itself so
      // the description travels with the image through approvals, pool moves
      // and downloads.
      outBuf = embedPngTextMetadata(outBuf, embed_metadata);

      const saved = await uploadPngBufferToSetPath(outBuf, outputBasePath, effectiveSlot, null, null);
      return json(200, { ok: true, storagePath: saved.storagePath, downloadURL: saved.downloadURL });
    }

    if (kind === "write_manifest") {
      const cat = normalizeCategory(activeCategory);
      if (!GENERATABLE_CATEGORIES.has(cat)) return json(400, { error: { message: "activeCategory not generatable" } });

      const base = assertAllowedOutputBase(output_base_path);
      const bucket = admin.storage().bucket();
      const p = `${base}/manifest.json`;
      const buf = Buffer.from(JSON.stringify(manifest || {}, null, 2), "utf8");
      await bucket.file(p).save(buf, { contentType: "application/json", resumable: false });
      return json(200, { ok: true, storagePath: p });
    }

    // ============================================================
    // move_set_to_completed (v5.31)
    // ------------------------------------------------------------
    // Server-side replacement for the browser-driven
    // runBackgroundApproval flow in Listing_Generator_1.html.
    //
    // The old flow downloaded every PNG from Ready_To_List/Set_N
    // into the browser, re-uploaded it to Completed_Listing_Sets/
    // {cat}_Set_N, then deleted the source. That round-tripped 100%
    // of the bytes through the operator's bandwidth and Firebase
    // egress on every approval. For our typical 4–8 MB per slot ×
    // 4–6 slots per set × dozens of approvals/day, this was a
    // significant chunk of the monthly bandwidth bill — and worse,
    // it could leave files orphaned in Ready_To_List if any step
    // failed mid-loop because the UI hides the set immediately
    // (addHiddenSets) without retrying.
    //
    // This handler does the same work entirely server-side:
    //   • bucket.file(src).copy(dst) is a Google-internal byte
    //     transfer with no egress charge.
    //   • Manifest tidying for skipped slots happens here too, so
    //     the client doesn't need to know about manifest structure.
    //   • Per-file errors are collected and returned so the client
    //     can decide whether to surface them; the loop continues
    //     past failures (best-effort) so a single flaky file
    //     doesn't strand a 95%-complete approval.
    //
    // Body:
    //   {
    //     kind        : "move_set_to_completed",
    //     activeCategory: "Beady_Necklace" | ... (one of GENERATABLE_CATEGORIES),
    //     setName     : "Set_42",           // matches /^Set_\d+$/
    //     skippedSlots: ["Slot_3.png", ...] // optional; these get
    //                                       // deleted from src instead of moved
    //   }
    //
    // Response:
    //   { ok: true, moved: N, skippedDeleted: M, errors: [...] }
    //
    // The client should treat ANY non-2xx response or `ok:false` as
    // a signal to fall back to the legacy browser-mediated flow so
    // approvals never get stuck on a deploy lag.
    if (kind === "move_set_to_completed") {
      const cat = normalizeCategory(activeCategory);
      if (!GENERATABLE_CATEGORIES.has(cat)) {
        return json(400, { error: { message: "activeCategory not generatable" } });
      }
      const setName = String(body?.setName || "").trim();
      if (!/^Set_\d+$/.test(setName)) {
        return json(400, { error: { message: "setName must look like 'Set_<n>'" } });
      }
      const skippedSlots = Array.isArray(body?.skippedSlots)
        ? body.skippedSlots.filter((s) => typeof s === "string" && /^Slot_\d+\.png$/.test(s))
        : [];
      const skipSet = new Set(skippedSlots);

      const bucket = admin.storage().bucket();
      const srcPrefix = `listing-generator-1/${cat}/Ready_To_List/${setName}/`;
      const dstPrefix = `listing-generator-1/Generated_Listing_Sets/Completed_Listing_Sets/${cat}_${setName}/`;

      // Step 1: Enumerate source files. getFiles with a prefix is a
      // single-shot list — no pagination needed at this scale (a set
      // is at most ~10 files).
      let files;
      try {
        const [f] = await bucket.getFiles({ prefix: srcPrefix });
        files = f;
      } catch (e) {
        return json(500, { ok: false, error: { message: `getFiles failed: ${e?.message || e}` } });
      }
      if (!files.length) {
        // Nothing to do — set folder is already empty. Treat as success
        // so callers (and the optional fallback path on the client) can
        // proceed without surfacing a confusing "no files" error.
        return json(200, { ok: true, moved: 0, skippedDeleted: 0, errors: [], note: "source folder empty" });
      }

      // Step 2: If there are skipped slots and a manifest is present,
      // tidy the manifest before moving. We mirror the exact transform
      // the old browser code performed:
      //   slots[i] = { ...slots[i], skipped: true, output: null }
      //     for any slot whose Slot_<n>.png is in skipSet.
      // This keeps the manifest semantically truthful in its new home.
      const manifestFile = files.find((f) => f.name === srcPrefix + "manifest.json");
      let tidiedManifestBuf = null;
      if (manifestFile && skipSet.size > 0) {
        try {
          const [raw] = await manifestFile.download();
          const data = JSON.parse(raw.toString("utf8"));
          const tidied = {
            ...data,
            slots: (data.slots || []).map((s) =>
              s && typeof s.slot === "number" && skipSet.has(`Slot_${s.slot}.png`)
                ? { ...s, skipped: true, output: null }
                : s
            ),
          };
          tidiedManifestBuf = Buffer.from(JSON.stringify(tidied, null, 2), "utf8");
        } catch (e) {
          // Manifest unreadable — proceed without tidying. The original
          // manifest will be copied verbatim below, which mirrors the
          // browser code's fallback when its own manifest read fails.
          console.warn(`[move_set_to_completed] manifest read failed for ${srcPrefix}: ${e?.message || e}`);
        }
      }

      // Step 3: Walk files, mirroring the browser logic.
      let moved = 0;
      let skippedDeleted = 0;
      const errors = [];
      for (const f of files) {
        const filename = f.name.slice(srcPrefix.length);
        if (!filename) continue; // pseudo-folder entry

        try {
          if (skipSet.has(filename)) {
            // Skipped slot → delete from src, do not copy.
            await f.delete();
            skippedDeleted++;
          } else if (filename === "manifest.json" && tidiedManifestBuf) {
            // Manifest with tidying applied → write tidied version to
            // dst, then delete src.
            const dstFile = bucket.file(dstPrefix + filename);
            await dstFile.save(tidiedManifestBuf, {
              contentType: "application/json",
              resumable: false,
            });
            await f.delete();
            moved++;
          } else {
            // Default: server-side copy + delete.
            const dstFile = bucket.file(dstPrefix + filename);
            await f.copy(dstFile);
            await f.delete();
            moved++;
          }
        } catch (e) {
          // Per-file failure: log + continue. Returning the error list
          // lets the client decide whether to retry or fall back.
          errors.push({ file: filename, error: String(e?.message || e) });
        }
      }

      return json(200, {
        ok: errors.length === 0,
        moved,
        skippedDeleted,
        errors: errors.slice(0, 20),
        srcPrefix,
        dstPrefix,
      });
    }
  } catch (e) {
    return json(400, { ok: false, error: safeErr(e) });
  }

  // ---------- existing job-based operations (jobId required) ----------
  if (!jobId) return json(400, { error: { message: "jobId is required" } });

  const db = getDb();
  const jobRef = db.collection(JOBS_COLL).doc(jobId);

  try {
    await firestoreRetry(
      () =>
        jobRef.set(
          {
            status: "running",
            stage: "starting",
            runId: runId || null,
            slotIndex: typeof slotIndex === "number" ? slotIndex : null,
            kind,
            model,
            clientModel: _clientModel || null,
            activeCategory: activeCategory || null,
            outputBasePath: output_base_path || null,
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
            createdAt: admin.firestore.FieldValue.serverTimestamp(),
          },
          { merge: true }
        ),
      "jobRef.set"
    );

    const apiKey = apiKeyForImageModel(modelConfig);

    // -------------------------
    // SPECIAL: charm_postscale
    // -------------------------
    if (kind === "charm_postscale") {
      if (!input_storage_path && !input_image) {
        throw new Error("charm_postscale requires input_storage_path or input_image (Pass A output)");
      }

      await firestoreRetry(
        () =>
          jobRef.set(
            {
              stage: "downloading_inputs",
              updatedAt: admin.firestore.FieldValue.serverTimestamp(),
            },
            { merge: true }
          ),
        "jobRef.set"
      );

      const passA = input_storage_path
        ? await storagePathToBuffer(input_storage_path)
        : dataUrlToBuffer(input_image);

      await firestoreRetry(() => jobRef.set(
        { stage: "removing_charm", updatedAt: admin.firestore.FieldValue.serverTimestamp() },
        { merge: true }
      ), "jobRef.set");

      let rp = String(remove_prompt || "").trim();
      let baseNoCharmBuf;

      if (base_storage_path || base_image) {
        const base = base_storage_path
          ? await storagePathToBuffer(base_storage_path)
          : dataUrlToBuffer(base_image);

        const [mA, mB] = await Promise.all([
          sharp(passA.buffer).metadata(),
          sharp(base.buffer).metadata(),
        ]);

        if (mA?.width && mA?.height && (mA.width !== mB.width || mA.height !== mB.height)) {
          baseNoCharmBuf = await sharp(base.buffer)
            .resize(mA.width, mA.height, { kernel: "lanczos3" })
            .png()
            .toBuffer();
        } else {
          baseNoCharmBuf = base.buffer;
        }
      } else {
        rp = rp || "Remove the pendant charm + jump ring completely...";
        baseNoCharmBuf = await callImageModelEdits({
          apiKey,
          model,
          prompt: rp,
          size,
          quality,
          output_format,
          images: [{ buffer: passA.buffer, mime: passA.mime, filename: "passA.png" }],
        });
      }

      await firestoreRetry(() => jobRef.set(
        { stage: "postprocessing", updatedAt: admin.firestore.FieldValue.serverTimestamp() },
        { merge: true }
      ), "jobRef.set");

      let finalBuf = await postScaleCharmComposite({
        passABuf: passA.buffer,
        baseNoCharmBuf,
        targetPx: postprocess?.targetPx,
        scale: postprocess?.scale,
        shadowOpacity: postprocess?.shadowOpacity,
        shadowBlur: postprocess?.shadowBlur,
        diffThreshold: postprocess?.diffThreshold,
      });

      finalBuf = await applyFinalFrameZoomIfNeeded(finalBuf, postprocess);

      await firestoreRetry(() => jobRef.set(
        { stage: "uploading", updatedAt: admin.firestore.FieldValue.serverTimestamp() },
        { merge: true }
      ), "jobRef.set");

      const { storagePath, downloadURL, effectiveRunId, effectiveSlot } =
      await uploadPngBufferToSetPath(finalBuf, output_base_path, slotIndex, jobId, runId);

      await firestoreRetry(() => db.collection(IMAGES_COLL).add({
        runId: effectiveRunId,
        slotIndex: effectiveSlot,
        createdAt: new Date(),
        storagePath,
        downloadURL,
        model,
        prompt: rp,
        traits: body.traits || null,
        jobId,
        kind,
        postprocess: postprocess || null,
      }), "images.add");

      await firestoreRetry(
        () =>
          jobRef.set(
            {
              status: "done",
              stage: "done",
              storagePath,
              downloadURL,
              finishedAt: admin.firestore.FieldValue.serverTimestamp(),
              updatedAt: admin.firestore.FieldValue.serverTimestamp(),
            },
            { merge: true }
          ),
        "jobRef.set"
      );

      return json(202, { ok: true, jobId });
    }

    // -------------------------
    // DEFAULT: edits / generations behavior
    // -------------------------
    if (!prompt) return json(400, { error: { message: "prompt is required" } });

    if (kind !== "edits" && kind !== "generations") {
      return json(400, { error: { message: "kind must be 'edits', 'generations', or 'charm_postscale' (or use alloc_set/copy_to_slot/write_manifest)" } });
    }

    await firestoreRetry(
      () =>
        jobRef.set(
          {
            stage: "uploading",
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          },
          { merge: true }
        ),
      "jobRef.set"
    );

    let outBuf;

    if (kind === "generations") {
      outBuf = await callImageModelGenerations({
        apiKey,
        model,
        prompt,
        size,
        quality,
        output_format,
      });
    } else {
      // kind === "edits"
      if (!input_image && !input_storage_path) {
        return json(400, { error: { message: "Missing input_image or input_storage_path" } });
      }

      const ref = input_storage_path
        ? await storagePathToBuffer(input_storage_path)
        : dataUrlToBuffer(input_image);

      let charm = null;
      if (input_charm_storage_path || input_charm_image) {
        charm = input_charm_storage_path
          ? await storagePathToBuffer(input_charm_storage_path)
          : dataUrlToBuffer(input_charm_image);
      }

      const images = [{ buffer: ref.buffer, mime: ref.mime, filename: filenameForMime("reference", ref.mime) }];

      if (charm) {
        images.push({ buffer: charm.buffer, mime: charm.mime, filename: filenameForMime("charm_macro", charm.mime) });
      }

      // Same Charm Maker pipeline as the set-based edits branch: text-only
      // preflight audit, then exactly one generation with the policies as
      // the backend's final word. No pixel post-processing.
      let effectivePrompt = prompt;
      if (background_policy || charm_geometry_policy || charm_edit_intent) {
        const audited = await auditCharmPromptPreflight({
          prompt,
          backgroundPolicy: background_policy,
          geometryPolicy: charm_geometry_policy,
          editIntent: charm_edit_intent,
          imageCount: images.length,
          imageRoles: image_roles,
        });
        if (audited) effectivePrompt = audited;
      }

      outBuf = await callImageModelEdits({
        apiKey,
        model,
        prompt: effectivePrompt,
        size,
        quality,
        output_format,
        images,
        imageRoles: image_roles,
        charmGeometryPolicy: charm_geometry_policy,
        backgroundPolicy: background_policy,
      });
    }

    outBuf = await applyFinalFrameZoomIfNeeded(outBuf, postprocess);

    await firestoreRetry(
      () =>
        jobRef.set(
          {
            stage: "uploading",
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          },
          { merge: true }
        ),
      "jobRef.set"
    );

    const { storagePath, downloadURL, effectiveRunId, effectiveSlot } =
      await uploadPngBufferToSetPath(outBuf, output_base_path, slotIndex, jobId, runId);

    await firestoreRetry(() => db.collection(IMAGES_COLL).add({
      runId: effectiveRunId,
      slotIndex: effectiveSlot,
      createdAt: new Date(),
      storagePath,
      downloadURL,
      model,
      prompt,
      traits: body.traits || null,
      jobId,
      kind,
      activeCategory: activeCategory || null,
      outputBasePath: output_base_path || null,
    }), "images.add");

    await firestoreRetry(() => jobRef.set(
      {
        status: "done",
        stage: "done",
        storagePath,
        downloadURL,
        finishedAt: admin.firestore.FieldValue.serverTimestamp(),
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      },
      { merge: true }
    ), "jobRef.set");

    return json(202, { ok: true, jobId });
  } catch (err) {
    await firestoreRetry(
      () =>
        jobRef.set(
          {
            status: "error",
            stage: "error",
            error: safeErr(err),
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          },
          { merge: true }
        ),
      "jobRef.set"
    );

    return json(202, { ok: false, jobId, error: safeErr(err) });
  }
};
